export const pack11 = [
//Estraído de Provas
{id:3001, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Regência verbal e nominal", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:" Considerando as regras de regência verbal, assinalar a alternativa INCORRETA.", imagem:null, alternativas:["A) Esqueci do material em casa.", "B) A diarista aspirou todo o tapete.", "C) Meu irmão aspira ao cargo de chefe.", "D) Informei o ocorrido à direção."], resposta_correta:0, explicacao:"A alternativa correta é a A, pois apresenta a regência incorreta. O verbo 'esquecer', quando não é pronominal (esquecer-se), é transitivo direto e não exige preposição. O correto seria 'Esqueci o material em casa'. A forma 'Esqueci do material' é coloquial e gramaticalmente incorreta; a forma pronominal correta seria 'Esqueci-me do material'. As alternativas B, C e D estão corretas:'aspirar' no sentido de cheirar/sorver é transitivo direto ('aspirou o tapete'), 'aspirar' no sentido de almejar é transitivo indireto com preposição 'a' ('aspira ao cargo'), e 'informar' aceita a regência 'informar algo a alguém' ('informei o ocorrido à direção').", status:0, historico:0},
{id:3002, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Crase", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:" Em qual das alternativas o uso de crase está INCORRETO?", imagem:null, alternativas:["A) Dei um presente bem caro à ela.", "B) Não acredito que você não foi à aula!", "C) Pedi para marcar a consulta às 18h.", "D) Esse trabalho foi claramente feito às pressas."], resposta_correta:0, explicacao:"A alternativa correta é a A. A crase está incorreta porque não se usa crase antes de pronomes pessoais do caso reto ou oblíquo (como 'ela'), pois eles não admitem artigo definido feminino 'a'. O correto é 'Dei um presente bem caro a ela'. As outras alternativas estão corretas:'foi à aula' (verbo ir exige preposição 'a' + artigo 'a' antes de aula), 'às 18h' (crase obrigatória antes de indicação de horas exatas), e 'às pressas' (crase em locução adverbial feminina).", status:0, historico:0},
{id:3003, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Semântica", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"Assinalar a alternativa cujos termos são referentes ao termo sublinhado abaixo.\n\nA estátua áurea era imponente.", imagem:null, alternativas:["A) De cobre.", "B) De ferro.", "C) De bronze.", "D) De ouro."], resposta_correta:3, explicacao:"A alternativa correta é a D. O adjetivo 'áurea' é derivado do latim 'aurum', que significa ouro. Portanto, uma 'estátua áurea' é uma estátua de ouro. As outras alternativas não têm relação com a palavra 'áurea'.", status:0, historico:0},
{id:3004, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Período Simples e Composto", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:" A relação existente entre as orações abaixo é de:\n\nQuanto mais eu estudo, mais eu vejo que nada sei.", imagem:null, alternativas:["A) Proporção.", "B) Tempo.", "C) Condição.", "D) Concessão."], resposta_correta:0, explicacao:"A alternativa correta é a A. A expressão 'Quanto mais... mais...' estabelece uma relação de proporção entre as duas orações, indicando que a intensidade de uma ação (estudar) aumenta na mesma medida que a outra (perceber que nada sabe). Não há relação de tempo, condição ou concessão neste caso.", status:0, historico:0},
{id:3005, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Concordâncias nominal e verbal", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:" Em qual alternativa a concordância nominal está CORRETA?", imagem:null, alternativas:["A) Ela mesmo poderia ter feito a tarefa.", "B) Segue anexo a fatura do mês.", "C) Quero duzentos gramas de queijo, por favor.", "D) Minha tia é meia tímida às vezes."], resposta_correta:2, explicacao:"A alternativa correta é a C. A palavra 'grama', quando significa unidade de massa, é um substantivo masculino. Portanto, o numeral deve concordar no masculino:'duzentos gramas'. A alternativa A está incorreta porque 'mesmo', no sentido de 'própria', deve concordar com o pronome 'Ela' ('Ela mesma'). A alternativa B está incorreta porque 'anexo' deve concordar com o substantivo 'fatura' ('Segue anexa a fatura'). A alternativa D está incorreta porque 'meio', com função de advérbio (um pouco), é invariável ('Minha tia é meio tímida').", status:0, historico:0},
{id:3006, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Equações do 2º grau", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:" Assinalar a alternativa que corresponde ao produto das raízes da equação abaixo.\n\nx² - 3x - 10 = 0", imagem:null, alternativas:["A) -10", "B) 3", "C) 7", "D) 10"], resposta_correta:0, explicacao:"A alternativa correta é a A. De acordo com as Relações de Girard para equações do 2º grau da forma ax² + bx + c = 0, o produto das raízes (x₁ * x₂) é dado por c/a. Na equação dada, a = 1, b = -3 e c = -10. Portanto, o produto das raízes é -10 / 1 = -10. Não é necessário calcular as raízes individualmente.", status:0, historico:0},
{id:3007, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Frações", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:" Considerando-se a reta numérica abaixo, assinalar a alternativa que corresponde ao valor de x.", imagem:"3007.webp", alternativas:["A) 4,4", "B) 6/4", "C) 9/30", "D) 27/5"], resposta_correta:1, explicacao:"A alternativa correta é a B. Analisando a reta numérica, notamos que a distância entre as marcações é constante. Podemos converter todos os valores para decimais para facilitar a análise:19/5 = 3,8. As marcações conhecidas são 0,7, x, 3,8 e 5,2. A distância entre 3,8 e 5,2 é de 5,2 - 3,8 = 1,4. Como parece haver apenas um intervalo entre eles (assumindo que a imagem está em escala, embora o texto não diga, é a única forma de resolver), cada intervalo vale 1,4. A posição anterior a 3,8 seria 3,8 - 1,4 = 2,4. O ponto x está uma posição antes de 3,8? Não, se olharmos atentamente, as distâncias não são iguais. Vamos usar outra abordagem. \nA distância total entre 0,7 e 5,2 é de 5,2 - 0,7 = 4,5. Há 3 intervalos entre esses pontos. Assumindo que os intervalos são iguais, o tamanho de cada intervalo é 4,5 / 3 = 1,5. \nVamos verificar:0,7 + 1,5 = 2,2 (valor de x). O próximo seria 2,2 + 1,5 = 3,7. Isso está muito próximo de 19/5 = 3,8, indicando que os intervalos podem não ser iguais ou que há um pequeno erro na representação gráfica/valores. \nNo entanto, vamos reavaliar as alternativas em busca de algo que se aproxime do que encontramos. Se x fosse 2,2, em fração seria 22/10 = 11/5. Não temos essa alternativa. \nVamos verificar a alternativa B:6/4 = 1,5. Se x = 1,5, a distância de 0,7 a 1,5 é de 0,8. A distância de 1,5 a 3,8 (19/5) é de 2,3. Isso mostra que os intervalos não são regulares.\nVamos olhar para o gabarito fornecido pela imagem 'image_b983e2.png'. A resposta para a questão 12 é a alternativa B. A alternativa B é 6/4, que simplificada é 3/2 ou 1,5. Como não há informações adicionais no enunciado para calcular com certeza o valor de x (não sabemos a escala da reta), a resolução matemática exata é impossível sem assumir informações. A resposta é baseada no gabarito oficial.", status:0, historico:0},
{id:3008, categoria:"Conhecimentos Básicos", materia:"Matemática Financeira", assunto:"Juros simples", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"13) Maria Julia é uma investidora e aplicou R$ 5.000,00 em uma aplicação que rende 6% ao ano em juros simples. Qual será o montante acumulado após 4 anos?", imagem:null, alternativas:["A) R$ 6.200,00", "B) R$ 6.800,00", "C) R$ 7.200,00", "D) R$ 7.500,00"], resposta_correta:0, explicacao:"A alternativa correta é a A. Para calcular o montante em juros simples, usamos a fórmula M = C * (1 + i * t), onde M é o montante, C é o capital (R$ 5.000,00), i é a taxa de juros (6% ao ano = 0,06) e t é o tempo (4 anos). Calculando os juros primeiro:J = C * i * t = 5000 * 0,06 * 4 = 1200. O montante é o capital mais os juros:M = 5000 + 1200 = R$ 6.200,00.", status:0, historico:0},
{id:3009, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Regra de Três", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"14) Cinco caminhões são responsáveis pelo transporte de areia para um grande canteiro de obras. Juntos, eles conseguem transportar 750 toneladas de areia em 12 viagens. Se forem adicionados mais 3 caminhões à frota, quantas toneladas serão transportadas em 18 viagens?", imagem:null, alternativas:["A) 1.050", "B) 1.200", "C) 1.650", "D) 1.800"], resposta_correta:3, explicacao:"A alternativa correta é a D. Trata-se de um problema de Regra de Três Composta. Vamos montar a tabela:\nCaminhões | Viagens | Toneladas\n5         | 12      | 750\n8 (5+3)   | 18      | X\nAnalisando as grandezas em relação às 'Toneladas' (que queremos descobrir):\n- Mais caminhões transportarão mais toneladas (grandezas diretamente proporcionais).\n- Mais viagens transportarão mais toneladas (grandezas diretamente proporcionais).\nPortanto, a equação fica:750 / X = (5 / 8) * (12 / 18). Simplificando as frações:750 / X = (5/8) * (2/3). 750 / X = 10 / 24. Multiplicando em cruz:10 * X = 750 * 24. 10 * X = 18000. X = 18000 / 10. X = 1800 toneladas.", status:0, historico:0},
{id:3010, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Frações", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"15) Em uma fábrica, duas torneiras enchem um tanque de água. A primeira torneira, sozinha, consegue encher o tanque em 5 horas, enquanto a segunda torneira demora 8 horas para completar a mesma tarefa. Se ambas forem abertas ao mesmo tempo, em aproximadamente quanto tempo o tanque estará cheio?", imagem:null, alternativas:["A) 2 horas e 55 minutos.", "B) 3 horas e 5 minutos.", "C) 3 horas e 25 minutos.", "D) 6 horas e 30 minutos."], resposta_correta:1, explicacao:"A alternativa correta é a B. Este é um clássico 'problema das torneiras'. Calculamos qual fração do tanque cada torneira enche em 1 hora:A torneira 1 enche 1/5 do tanque por hora. A torneira 2 enche 1/8 do tanque por hora. Juntas, em 1 hora, elas enchem:(1/5) + (1/8) do tanque. O mínimo múltiplo comum (MMC) entre 5 e 8 é 40. Então, juntas enchem (8/40) + (5/40) = 13/40 do tanque por hora. O tempo total 'T' para encher o tanque inteiro (1) é o inverso dessa fração:T = 40/13 horas. Dividindo 40 por 13, obtemos aproximadamente 3,076 horas. Para converter a parte decimal em minutos, multiplicamos por 60:0,076 * 60 ≈ 4,6 minutos, que arredondamos para 5 minutos. Portanto, aproximadamente 3 horas e 5 minutos.", status:0, historico:0},
{id:3011, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Área e perímetro", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"16) Assinalar a alternativa que corresponde ao perímetro do retângulo abaixo, sabendo que os segmentos BC = 15cm e DC = 7cm.", imagem:"3011.webp", alternativas:["A) 32cm", "B) 44cm", "C) 98cm", "D) 105cm"], resposta_correta:1, explicacao:"A alternativa correta é a B. O perímetro de um retângulo é a soma de todos os seus lados. Em um retângulo, os lados opostos são iguais. Logo, se BC (base) = 15cm, o lado oposto AD também mede 15cm. Se DC (altura) = 7cm, o lado oposto AB também mede 7cm. O perímetro é:P = 15 + 15 + 7 + 7 = 30 + 14 = 44cm.", status:0, historico:0},
{id:3012, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Sistema Métrico e Grandezas", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"17) Mariana tem aula de dança às 18h00min. Ela saiu de casa às 17h20min e levou, no percurso de casa até o ponto de ônibus, 8 minutos. Se o ônibus demorou 15 minutos para chegar à escola de dança e se, ao sair do ônibus, Mariana gastou 5 minutos para ir da parada até a sala de aula, então Mariana chegou:", imagem:null, alternativas:["A) 12 minutos atrasada.", "B) Exatamente no horário.", "C) 5 minutos adiantada.", "D) 12 minutos adiantada."], resposta_correta:3, explicacao:"A alternativa correta é a D. Vamos somar o tempo que Mariana gastou no trajeto:8 minutos (caminhada até o ponto) + 15 minutos (ônibus) + 5 minutos (caminhada até a sala) = 28 minutos totais. Ela saiu de casa às 17h20min. Somando 28 minutos a esse horário, chegamos a 17h48min (17h20 + 28min). Como a aula começa às 18h00min e ela chegou às 17h48min, ela chegou 12 minutos antes da aula (18h00 - 17h48 = 12 minutos de adiantamento).", status:0, historico:0},
{id:3013, categoria:"Conhecimentos Básicos", materia:"Matemática Financeira", assunto:"Porcentagem", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"18) Guilherme comprou um sofá novo para sua casa e pagou R$ 1.936,00. Sabendo que o sofá estava com um desconto de 12%, assinalar a alternativa que apresenta o valor do desconto recebido por Guilherme.", imagem:null, alternativas:["A) R$ 232,00", "B) R$ 252,00", "C) R$ 264,00", "D) R$ 278,00"], resposta_correta:2, explicacao:"A alternativa correta é a C. O valor pago, R$ 1.936,00, representa o valor original do sofá menos o desconto. Se o desconto foi de 12%, Guilherme pagou 88% do valor original (100% - 12% = 88%). Podemos usar uma regra de três para descobrir o valor original (100%) ou diretamente o valor do desconto (12%). Vamos calcular o valor do desconto (X) correspondente a 12%:\n88% ---------- R$ 1.936,00\n12% ---------- X\nMultiplicando em cruz:88 * X = 1936 * 12. 88 * X = 23232. X = 23232 / 88. X = R$ 264,00. O valor do desconto foi R$ 264,00.", status:0, historico:0},
{id:3014, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Conceitos básicos", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"19) Os computadores utilizam diferentes tipos de dispositivos para permitir a comunicação entre o usuário e a máquina. Esses dispositivos podem ser classificados em entrada, saída ou entrada/saída. Com base nessa classificação, qual dos itens abaixo representa CORRETAMENTE um dispositivo de entrada?", imagem:null, alternativas:["A) Monitor", "B) Impressora", "C) Teclado", "D) Caixa de som"], resposta_correta:2, explicacao:"A alternativa correta é a C. O teclado é um dispositivo utilizado exclusivamente para inserir dados e comandos no computador, caracterizando-o como um dispositivo de entrada. O monitor (A) e a caixa de som (D) são dispositivos de saída, que mostram e emitem, respectivamente, informações processadas pelo computador ao usuário. A impressora (B) também é um dispositivo de saída, produzindo cópias físicas dos dados.", status:0, historico:0},
{id:3015, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Sistemas Operacionais", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"20) Qual função é desempenhada por um sistema operacional?", imagem:null, alternativas:["A) Converter código binário em linguagem de máquina.", "B) Criar redes de computadores.", "C) Desenvolver aplicações em linguagens de programação.", "D) Gerenciar recursos de hardware e fornecer interface para aplicativos."], resposta_correta:3, explicacao:"A alternativa correta é a D. A função principal de um sistema operacional (como Windows, Linux, macOS) é gerenciar os recursos de hardware do computador (como memória, processador, dispositivos de armazenamento) e fornecer uma plataforma e interface para que os aplicativos de software possam ser executados. A conversão de código (A) é função de compiladores ou interpretadores. Criar redes (B) envolve hardware específico e protocolos de rede. Desenvolver aplicações (C) é feito por meio de Ambientes de Desenvolvimento Integrado (IDEs) e linguagens de programação, não sendo a função do sistema operacional em si.", status:0, historico:0},
{id:3016, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Segurança Digital", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"21) Qual técnica de ataque usa e-mails falsos para induzir o usuário a revelar senhas?", imagem:null, alternativas:["A) Pharming", "B) Phishing", "C) Sniffing", "D) Spoofing"], resposta_correta:1, explicacao:"A alternativa correta é a B. 'Phishing' é uma técnica de engenharia social onde os atacantes se passam por entidades confiáveis (como bancos ou empresas conhecidas) enviando e-mails ou mensagens falsas para induzir as vítimas a fornecer informações confidenciais, como senhas e dados de cartão de crédito. 'Pharming' (A) redireciona o tráfego de um site legítimo para um falso, alterando o DNS. 'Sniffing' (C) é a interceptação e leitura do tráfego de rede. 'Spoofing' (D) é a falsificação de identidade para parecer outra pessoa ou sistema, sendo uma técnica frequentemente usada *dentro* de ataques de phishing, mas o ato específico descrito no enunciado caracteriza o phishing.", status:0, historico:0},
{id:3017, categoria:"Conhecimentos Específicos", materia:"Vigilância Epidemiológica", assunto:"Meio Ambiente", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"O desmatamento tem sido uma das principais causas de degradação ambiental, afetando a biodiversidade e o clima global. Assinalar a alternativa que apresenta uma das consequências para os ecossistemas.", imagem:null, alternativas:["A) Aumento da recarga de aquíferos, promovendo fortalecimento do ciclo hidrológico.","B) Aumento da poluição dos oceanos.","C) Expansão das zonas agrícolas para o cultivo de alimentos.","D) Diminuição da capacidade de captura de carbono pelas florestas."], resposta_correta:3, explicacao:"A alternativa D está correta. As florestas atuam como importantes 'sumidouros' de carbono, absorvendo CO2 da atmosfera através da fotossíntese. O desmatamento elimina essa cobertura vegetal, resultando na diminuição drástica da capacidade do ecossistema de reter o carbono, o que agrava as mudanças climáticas. O desmatamento diminui (e não aumenta) a recarga de aquíferos, e a expansão agrícola é frequentemente uma causa do desmatamento, não uma consequência ecológica dele.", status:0, historico:0 },
{id:3018, categoria:"Conhecimentos Específicos", materia:"Vigilância Epidemiológica", assunto:"Doenças epidêmicas", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"A malária é uma doença infecciosa transmitida por mosquitos do gênero Anopheles, que são picados por parasitas do gênero Plasmodium. Essa transmissão ocorre principalmente ao entardecer e ao amanhecer. No Brasil, a maioria dos casos de malária se concentra na região do(a):", imagem:null, alternativas:["A) Cerrado.","B) Pampa.","C) Amazônia.","D) Caatinga."], resposta_correta:2, explicacao:"A alternativa C está correta. No Brasil, mais de 99% dos casos autóctones (transmitidos localmente) de malária ocorrem na Região da Amazônia Legal. As condições climáticas (clima tropical úmido) e geográficas (densa floresta e grande bacia hidrográfica) dessa região fornecem o ambiente ideal para a proliferação do mosquito vetor (Anopheles).", status:0, historico:0 },
{id:3019, categoria:"Conhecimentos Gerais", materia:"Direito Administrativo", assunto:"Princípios administrativos", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"No serviço público, o nepotismo é uma prática ilegal, caracterizada como a:", imagem:null, alternativas:["A) Contratação de parentes para cargos públicos, sem critérios técnicos.","B) Realização de processos seletivos para contratação de servidores.","C) Criação de programas de inclusão para minorias no serviço público.","D) Promoção de servidores por competência."], resposta_correta:0, explicacao:"A alternativa A está correta. O nepotismo ocorre quando um agente público usa de sua posição de poder para nomear, contratar ou favorecer parentes (cônjuges, companheiros ou parentes em linha reta, colateral ou por afinidade, até o terceiro grau) para cargos em comissão ou de confiança, burlando o princípio do concurso público, da impessoalidade e da moralidade administrativa (Súmula Vinculante 13 do STF).", status:0, historico:0 },
{id:3020, categoria:"Conhecimentos Gerais", materia:"Direito Constitucional", assunto:"Poder Executivo", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"Sob a égide da Constituição Federal, os Ministros de Estado serão escolhidos dentre os brasileiros no exercício dos direitos políticos e maiores de:", imagem:null, alternativas:["A) Trinta anos.","B) Vinte anos.","C) Dezoito anos.","D) Vinte e um anos."], resposta_correta:3, explicacao:"A alternativa D está correta. A Constituição Federal de 1988 é muito clara em seu Artigo 87, definindo os requisitos para ocupar o cargo:'Os Ministros de Estado serão escolhidos dentre brasileiros maiores de vinte e um anos e no exercício dos direitos políticos'. O candidato deve memorizar essa idade, não confundindo com a maioridade civil de 18 anos.", status:0, historico:0 },
{id:3021, categoria:"Conhecimentos Gerais", materia:"Direito Administrativo", assunto:"Servidores Públicos", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"Em relação à estabilidade dos servidores, de acordo com a Lei Orgânica do Município, assinalar a alternativa que preenche a lacuna abaixo CORRETAMENTE.\nSão estáveis após ________ de efetivo exercício os servidores nomeados para cargo de provimento efetivo em virtude de concurso público.", imagem:null, alternativas:["A) um ano","B) três anos","C) dois anos","D) seis meses"], resposta_correta:1, explicacao:"A alternativa B está correta. Com a Emenda Constitucional nº 19 de 1998, o Art. 41 da Constituição Federal foi alterado, estipulando que são estáveis após 3 (três) anos de efetivo exercício os servidores nomeados para cargo de provimento efetivo em virtude de concurso público. As leis orgânicas e os estatutos municipais precisam obrigatoriamente espelhar essa regra constitucional.", status:0, historico:0 },
{id:3022, categoria:"Conhecimentos Específicos", materia:"Segurança da Informação", assunto:"Sistema de Gestão de Segurança da Informação", cargo:"Analista Censitário - Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Acerca das diretrizes, dos requisitos e das boas práticas estabelecidas pela norma ISO/IEC 27001 para a estruturação de um Sistema de Gestão de Segurança da Informação, assinale a alternativa correta.", imagem:null, alternativas:["A) A ISO/IEC 27001 estabelece uma lista rígida de controles técnicos obrigatórios, dispensando a análise do cenário organizacional e a avaliação formal dos riscos.","B) A ISO/IEC 27001 estabelece que a seleção dos controles deve decorrer do contexto organizacional e do processo de avaliação e tratamento de riscos.","C) A ISO/IEC 27001 restringe-se aos aspectos de infraestrutura tecnológica, tratando exclusivamente de redes corporativas, servidores físicos, sistemas operacionais e dispositivos lógicos conectados.","D) A ISO/IEC 27001 anula a necessidade de formulação de políticas internas, uma vez que o processo de auditoria externa atesta a conformidade do sistema de gestão, dispensando a manutenção de políticas internas.","E) A ISO/IEC 27001 preconiza que as ações de tratamento de riscos sejam deflagradas prioritariamente após a ocorrência de incidentes de segurança, mitigando o retrabalho no planejamento."], resposta_correta:1, explicacao:"A alternativa B está correta. Na norma ABNT NBR ISO/IEC 27001 (Seções 4 e 6), a estruturação do SGSI parte da compreensão do contexto da organização e das necessidades das partes interessadas, seguindo para o processo de avaliação e tratamento de riscos, a partir do qual são selecionados os controles necessários (documentados na Declaração de Aplicabilidade - SoA). Análise das incorretas: em A, o Anexo A da ISO 27001 não é uma lista rígida obrigatória sem análise de risco (os controles são selecionados conforme os riscos); em C, a norma abrange controles organizacionais, de pessoas, físicos e tecnológicos; em D, a Política de Segurança (Seção 5.2) é requisito obrigatório; em E, o tratamento de riscos é preventivo e planejado antes dos incidentes.", status:0, historico:0},
{id:3023, categoria:"Conhecimentos Específicos", materia:"Governança e gestão de TI", assunto:"PMBOK", cargo:"Analista Censitário - Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Sobre o gerenciamento da qualidade em projetos, segundo o PMI e o PMBOK®, assinale a alternativa correta.", imagem:null, alternativas:["A) O gerenciamento da qualidade busca ampliar entregas do projeto por meio da inclusão de requisitos adicionais ao escopo aprovado.","B) O gerenciamento da qualidade busca assegurar que entregas e processos atendam aos requisitos estabelecidos para o projeto.","C) O gerenciamento da qualidade busca substituir critérios técnicos por percepções dos usuários sobre o resultado entregue.","D) O gerenciamento da qualidade busca concentrar verificações no encerramento para reduzir controles durante o projeto.","E) O gerenciamento da qualidade busca priorizar velocidade de entrega quando houver restrições de custo e cronograma."], resposta_correta:1, explicacao:"A alternativa B está correta. Segundo o PMBOK®, o Gerenciamento da Qualidade do Projeto inclui os processos para incorporar a política de qualidade da organização com relação ao planejamento, gerenciamento e controle dos requisitos de qualidade do projeto e do produto, a fim de atender aos objetivos das partes interessadas (assegurando que tanto os processos quanto as entregas cumpram os requisitos estabelecidos). Pegadinha importante na alternativa A: incluir requisitos extras não aprovados no escopo chama-se 'Gold Plating' (ou 'Scope Creep'), uma prática condenada pelo PMI por gerar custos e riscos sem agregar valor acordado.", status:0, historico:0},
{id:3024, categoria:"Conhecimentos Específicos", materia:"Legislação", assunto:"Proteção de Dados", cargo:"Analista Censitário - Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Com base na Lei nº 13.709/2018 (Lei Geral de Proteção de Dados Pessoais - LGPD), acerca da figura do encarregado pelo tratamento de dados pessoais, assinale a alternativa correta.", imagem:null, alternativas:["A) O encarregado atua como canal de comunicação entre o controlador, os titulares dos dados pessoais e a Autoridade Nacional de Proteção de Dados, exercendo as atribuições previstas na LGPD.","B) O encarregado possui competência para autorizar, em caráter vinculante, o compartilhamento de dados pessoais entre controladores pertencentes ao mesmo grupo econômico ou conglomerado de empresas.","C) O encarregado responde solidariamente pelos danos civis e administrativos decorrentes de operações de tratamento realizadas pelo controlador, independentemente da demonstração de culpa no evento danoso.","D) O encarregado exerce função fiscalizatória de natureza correcional sobre a Autoridade Nacional de Proteção de Dados, detendo a prerrogativa de revisar os atos administrativos relacionados à proteção de dados.","E) O encarregado detém a prerrogativa de representação legal e compulsória dos titulares dos dados pessoais nos processos administrativos e sancionatórios instaurados perante a Autoridade Nacional de Proteção de Dados."], resposta_correta:0, explicacao:"A alternativa A está correta. Conforme o art. 5º, inciso VIII, e o art. 41, § 2º, da Lei nº 13.709/2018 (LGPD), o encarregado (DPO - Data Protection Officer) é a pessoa indicada pelo controlador e operador para atuar como canal de comunicação entre o controlador, os titulares dos dados e a Autoridade Nacional de Proteção de Dados (ANPD), cabendo-lhe aceitar reclamações dos titulares, receber comunicações da ANPD e orientar os funcionários sobre as práticas de proteção de dados. As demais alternativas inventam prerrogativas inexistentes: quem responde civilmente perante o titular (arts. 42 e 43) são os agentes de tratamento (controlador e operador), e não o encarregado.", status:0, historico:0},
{id:3025, categoria:"Conhecimentos Específicos", materia:"Segurança da Informação", assunto:"Segurança de Redes", cargo:"Analista Censitário - Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Acerca dos mecanismos, dos protocolos e das tecnologias empregados na arquitetura de segurança de redes de computadores, assinale a alternativa correta.", imagem:null, alternativas:["A) Um firewall de filtragem de pacotes realiza a inspeção completa das aplicações corporativas, permitindo identificar comandos maliciosos e bloquear ameaças avançadas.","B) Uma Rede Privada Virtual (VPN) tem como finalidade substituir mecanismos criptográficos por túneis lógicos, dispensando técnicas de autenticação dos dados.","C) Um Sistema de Detecção de Intrusão (IDS) atua predominantemente na identificação de atividades suspeitas ou maliciosas, produzindo alertas para subsidiar ações de resposta e investigação.","D) Um Sistema de Prevenção de Intrusão (IPS) caracteriza-se por operar de forma passiva na infraestrutura, limitando-se ao registro de eventos de segurança, sem capacidade de bloqueio imediato do tráfego.","E) A segmentação de redes por meio de VLANs estabelece canais criptográficos nativos para o tráfego lógico direcionado, assegurando o sigilo das comunicações entre diferentes domínios de broadcast."], resposta_correta:2, explicacao:"A alternativa C está correta. O IDS (Intrusion Detection System) monitora o tráfego de rede ou eventos de sistema em busca de assinaturas de ataques ou anomalias comportamentais, gerando alertas para a equipe de segurança ou SIEM. Análise das incorretas: em A, o filtro de pacotes clássico opera nas camadas 3 e 4 (cabeçalhos IP/TCP/UDP) e não faz inspeção profunda de camada de aplicação (papel de um NGFW ou WAF); em B, a VPN baseia-se justamente em criptografia e autenticação (como IPsec ou TLS) para proteger o túnel; em D, o IPS (Intrusion Prevention System) opera de forma ativa (inline), bloqueando/descartando pacotes maliciosos em tempo real; em E, VLANs (IEEE 802.1Q) apenas separam logicamente domínios de broadcast na camada 2, não provendo criptografia nativa.", status:0, historico:0},
{id:3026, categoria:"Conhecimentos Específicos", materia:"Saúde Pública", assunto:"Legislação do SUS", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"Baseando-se no Decreto nº 7.508/2011, os serviços de atendimento inicial à saúde do usuário no SUS se dão por meio de:", imagem:null, alternativas:["A) Protocolo Clínico.","B) Portas de Entrada.","C) Acesso Aberto.","D) Região de Saúde."], resposta_correta:1, explicacao:"A alternativa B está correta. De acordo com o glossário do Artigo 2º do Decreto 7.508/2011 (que regulamenta a Lei 8.080/90), as 'Portas de Entrada' são definidas exatamente como 'os serviços de atendimento inicial à saúde do usuário no SUS'. Elas incluem os serviços de Atenção Primária, Atenção de Urgência e Emergência, Atenção Psicossocial, e serviços especiais de acesso aberto.", status:0, historico:0 },
{id:3027, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Infrações Sanitárias", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"No âmbito da Lei nº 6.437/1977 — Infrações à Legislação Sanitária Federal, é considerada circunstância atenuante se o infrator:", imagem:null, alternativas:["A) For primário e a falta cometida for de natureza leve.","B) Coagir outro para a execução material da infração.","C) Ter agido com dolo, ainda que eventual fraude ou má fé.","D) Cometer a infração com consequências calamitosas à saúde pública."], resposta_correta:0, explicacao:"A alternativa A está correta. Na dosimetria das penas sanitárias (Art. 6º da Lei 6.437/77), ser primário e cometer uma infração de natureza leve atua em favor do infrator, configurando uma circunstância 'atenuante' (que diminui o rigor da punição). Todas as outras opções (agir com dolo/má-fé, coagir terceiros, ou gerar consequências calamitosas) são circunstâncias 'agravantes' graves.", status:0, historico:0 },
{id:3028, categoria:"Conhecimentos Específicos", materia:"Saúde Pública", assunto:"Saneamento Básico", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"De acordo com a Lei nº 11.445/2007 — Política Nacional de Saneamento Básico, NÃO faz parte do conjunto de serviços públicos que integram o saneamento básico:", imagem:null, alternativas:["A) Esgotamento sanitário.","B) Abastecimento de água potável.","C) Fornecimento de energia elétrica.","D) Drenagem e manejo de águas pluviais urbanas."], resposta_correta:2, explicacao:"A alternativa C está correta. A Política Nacional de Saneamento Básico (Lei 11.445/2007) define que o saneamento básico é composto por 4 (quatro) pilares fundamentais:1) Abastecimento de água potável, 2) Esgotamento sanitário, 3) Limpeza urbana e manejo de resíduos sólidos, e 4) Drenagem e manejo das águas pluviais urbanas. O 'fornecimento de energia elétrica' não compõe esse escopo legal.", status:0, historico:0 },
{id:3029, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Política Nacional de Resíduos Sólidos", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"Conforme alguns dos princípios elencados na Lei nº 12.305/2010 – Política Nacional de Resíduos Sólidos, analisar os itens.\nI. A responsabilidade compartilhada pelo ciclo de vida dos produtos.\nII. O reconhecimento do resíduo sólido reutilizável e reciclável como um bem econômico e de valor social, gerador de trabalho e renda e promotor de cidadania.\nIII. O direito da sociedade à informação e ao controle social.\nEstá CORRETO o que se afirma:", imagem:null, alternativas:["A) Apenas nos itens I e II.","B) Apenas nos itens I e III.","C) Apenas nos itens II e III.","D) Em todos os itens."], resposta_correta:3, explicacao:"A alternativa D está correta. Todos os itens listados estão perfeitamente alinhados com o texto da Lei nº 12.305/2010. A responsabilidade compartilhada impõe obrigações aos fabricantes, distribuidores e consumidores; o reconhecimento do valor econômico dos resíduos busca dignificar o trabalho de catadores e fortalecer a reciclagem; e o acesso à informação e o controle social garantem a transparência e participação popular na gestão ambiental.", status:0, historico:0 },
{id:3030, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Inspeção Industrial e Sanitária", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"Conforme o Decreto nº 9.013/2017 – RIISPOA, os estabelecimentos de produtos de origem animal que realizam comércio interestadual e internacional, sob a inspeção federal, NÃO serão classificados em:", imagem:null, alternativas:["A) Produtos não comestíveis.","B) Carnes e derivados.","C) Armazenagem.","D) Produtos de abelhas e derivados."], resposta_correta:0, explicacao:"A alternativa A está correta (é a exceção). O novo Regulamento da Inspeção Industrial e Sanitária de Produtos de Origem Animal (RIISPOA, Dec. 9.013/2017), em seu Artigo 18, classifica os estabelecimentos em:de carnes e derivados; de pescado; de ovos; de leite; de produtos de abelhas; e de armazenagem. A antiga categoria 'produtos não comestíveis' não figura mais como uma classe principal autônoma nesta listagem macro do artigo 18.", status:0, historico:0 },
{id:3031, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Inspeção Industrial e Sanitária", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"De acordo com o Decreto nº 9.013/2017 – RIISPOA, qual é o conceito de “desinfecção”?", imagem:null, alternativas:["A) Procedimento que consiste na execução de duas etapas distintas:limpeza e sanitização.","B) Procedimento que consiste na eliminação de agentes infecciosos por meio de tratamentos físicos ou agentes químicos.","C) Remoção física de resíduos orgânicos, inorgânicos ou de outro material indesejável das superfícies das instalações, dos equipamentos e dos utensílios.","D) Aplicação de métodos físicos nas superfícies das instalações para assegurar nível de higiene microbiologicamente aceitável."], resposta_correta:1, explicacao:"A alternativa B está correta. Segundo o glossário técnico de normas sanitárias e do RIISPOA, a Desinfecção é especificamente o combate e a eliminação de microrganismos patogênicos e agentes infecciosos, o que se alcança usando tratamentos químicos (desinfetantes) ou físicos (calor). A alternativa C descreve o processo primário de 'Limpeza' (que apenas remove a sujeira visível), e a alternativa A descreve o conceito amplo de 'Higienização'.", status:0, historico:0 },
{id:3032, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Inspeção Industrial e Sanitária", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"Sobre edificações, instalações, equipamentos, móveis e utensílios, considerando-se a Resolução-RDC nº 216/2004 − Regulamento técnico de boas práticas para serviços de alimentação, analisar a sentença.\nAs caixas de gordura e de esgoto devem possuir dimensão compatível ao volume de resíduos, devendo estar localizadas dentro da área de preparação e armazenamento de alimentos e apresentar adequado estado de conservação e funcionamento (1ª parte). A ventilação deve garantir a renovação do ar e a manutenção do ambiente livre de fungos, gases, fumaça, pós, partículas em suspensão, condensação de vapores dentre outros que possam comprometer a qualidade higiênico-sanitária do alimento (2ª parte).\nA sentença está:", imagem:null, alternativas:["A) Totalmente correta.","B) Correta somente em sua 1ª parte.","C) Correta somente em sua 2ª parte.","D) Totalmente incorreta."], resposta_correta:2, explicacao:"A alternativa C está correta. A primeira parte da sentença é perigosa e flagrantemente falsa, pois a RDC 216/2004 proíbe rigorosamente que caixas de gordura e esgoto fiquem DENTRO das áreas de preparação e armazenamento de alimentos, justamente para evitar a atração de pragas e a contaminação cruzada. A segunda parte da sentença, sobre a necessidade de renovação do ar e ventilação adequada para evitar fungos e fumaça, está perfeitamente correta.", status:0, historico:0 },
{id:3033, categoria:"Conhecimentos Específicos", materia:"Legislação", assunto:"Proteção de Dados", cargo:"Analista Censitário - Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"À luz da Lei nº 13.709/2018 (Lei Geral de Proteção de Dados Pessoais - LGPD), acerca do uso compartilhado de dados pessoais pelo Poder Público, assinale a alternativa correta.", imagem:null, alternativas:["A) O uso compartilhado de dados pessoais entre órgãos públicos depende de consentimento específico do titular, mesmo quando o tratamento decorrer da execução de política pública prevista em lei.","B) O uso compartilhado de dados pessoais entre entidades da Administração Pública exige, em caráter mandatório, autorização prévia e expressa da Autoridade Nacional de Proteção de Dados.","C) O uso compartilhado de dados pessoais entre órgãos públicos para a execução de políticas públicas previstas em leis ou regulamentos pode ocorrer com fundamento nas hipóteses legais de tratamento estabelecidas pela LGPD.","D) O uso compartilhado de dados pessoais no âmbito do Poder Público é condicionado à realização prévia do procedimento de pseudonimização dos dados pessoais objeto do compartilhamento.","E) O uso compartilhado de dados pessoais entre entidades estatais é juridicamente viabilizado mediante termo de autorização individual assinado por cada um dos titulares dos dados."], resposta_correta:2, explicacao:"A alternativa C está correta. Conforme os arts. 7º, inciso III, 23 e 26 da LGPD (Lei nº 13.709/2018), o tratamento e o uso compartilhado de dados pessoais pelo Poder Público devem atender à finalidade específica de execução de políticas públicas e atribuição legal pelos órgãos e pelas entidades públicas, respaldados nas hipóteses legais da LGPD, dispensando o consentimento individual do titular (o que invalida A e E) e não exigindo autorização prévia da ANPD (invalidando B) nem pseudonimização prévia obrigatória (invalidando D).", status:0, historico:0},
{id:3034, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Política Nacional de Resíduos Sólidos", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"Sobre o tratamento de resíduos degradáveis, no qual é comum se observar três fases, analisar os itens.\nI. Tratamento primário:crivagem mecânica e sedimentação de sólidos (que são queimados ou enterrados).\nII. Tratamento secundário:redução biológica da matéria orgânica.\nIII. Tratamento terciário ou avançado:remoção química de fosfatos, nitratos, materiais orgânicos e outros.\nEstá CORRETO o que se afirma.", imagem:null, alternativas:["A) Apenas no item I.","B) Apenas no item III.","C) Apenas nos itens I e II.","D) Em todos os itens."], resposta_correta:3, explicacao:"A alternativa D está correta. O sistema de tratamento de efluentes e resíduos orgânicos fluidos segue exatamente essas etapas fundamentais:1) Nível Primário usa a gravidade e barreiras físicas (grades, decantadores) para remover sólidos grossos; 2) Nível Secundário introduz bactérias e micro-organismos para consumir e degradar a matéria orgânica remanescente (biológico); e 3) Nível Terciário aplica polimento químico (como cloro, ozônio) para matar bactérias finais e precipitar nutrientes complexos (nitratos/fosfatos). Todas as etapas estão perfeitamente descritas.", status:0, historico:0 },
{id:3035, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Qualidade da Água", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2024", banca:"Objetiva Concursos", concurso:"Município de Guadalupe/PI", enunciado:"As exigências humanas quanto à qualidade da água crescem com o progresso humano e o da técnica. Justamente para evitar os perigos decorrentes da má qualidade da água, são estabelecidos padrões de potabilidade. Em relação às características de aceitação da água para consumo humano, analisar os itens.\nI. Deve ter aspecto agradável. A medida é pessoal.\nII. Deve ter gosto agradável ou ausência de gosto objetável. A medida do gosto é pessoal.\nIII. Deve ter odores desagradáveis ou ter odor objetável. A medida do odor não é pessoal.\nIV. A cor é determinada pela presença de substâncias em dissolução na água e não afeta sua transparência.\nV. A turbidez é devida à matéria em suspensão na água (argila, silte, matéria orgânica, etc.) e altera sua transparência.\nEstá CORRETO o que se afirma:", imagem:null, alternativas:["A) Apenas nos itens I, II e III.","B) Apenas nos itens I, II e V.","C) Apenas nos itens I, II, IV e V.","D) Em todos os itens."], resposta_correta:2, explicacao:"A alternativa C está correta. A leitura atenta do item III revela a sua absurdidade:afirma que a água potável 'deve ter odores desagradáveis'. A água tratada para consumo humano deve ser estritamente inodora. Os demais itens estão corretos:o gosto e aspecto são essenciais para a aceitação (I e II); a 'Cor Verdadeira' da água provém de sólidos dissolvidos, enquanto a turbidez provém de partículas finas em suspensão (barro, algas) que interferem na passagem da luz e afetam a transparência (IV e V).", status:0, historico:0 },
//ESTRAIDO DE PROVAS
{id:3036, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Interpretação e Produção de Textos", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n1) No texto acima, o autor explora, através do humor, a questão dos relacionamentos. Nesse sentido, de acordo com as ideias apresentadas, é correto afirmar que:", imagem:null, alternativas:["A) para o autor, a facilidade de abrir um relacionamento simplifica o tratamento com o outro.","B) o autor aponta para diferentes formas de abrir um relacionamento e ainda descreve um relacionamento fechado.","C) há um consenso, no mundo moderno, em relação à necessidade de abrir os relacionamentos.","D) o autor acredita que os relacionamentos abertos, invariavelmente, provocam infelicidade."], resposta_correta:1, explicacao:"A alternativa B está correta. Ao longo da crônica, o autor descreve, com muito humor, diversas modalidades de relacionamentos abertos (escancarado, entreaberto, sazonal, encostado) e também faz questão de descrever no penúltimo parágrafo o relacionamento fechado ('trancado a sete chaves e blindado'). A alternativa A é falsa, pois ele compara abrir um relacionamento a abrir uma embalagem de CD (tarefa difícil e arriscada). A alternativa C é falsa, pois não há menção a um consenso moderno. A alternativa D é uma extrapolação baseada na citação irônica de Tolstói no início do texto, não sendo uma crença absoluta do autor.", status:0, historico:0 },
{id:3037, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Coerência e Coesão", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n2) No quarto parágrafo, o autor emprega dois pronomes indefinidos em “tudo é possível e nada é passível de ciúme” e, por meio deles:", imagem:null, alternativas:["A) constrói uma ambiguidade.","B) indica a construção de um paradoxo.","C) aponta ideias que não são excludentes.","D) sinaliza uma incoerência nos relacionamentos."], resposta_correta:2, explicacao:"A alternativa C está correta. Embora os pronomes indefinidos 'tudo' e 'nada' sejam tradicionalmente antônimos, no contexto da frase eles se aplicam a esferas diferentes ('tudo' em relação às possibilidades de ação e 'nada' em relação ao sentimento de ciúme). Dessa forma, as ideias coexistem harmoniosamente para definir as regras da 'relação escancarada', provando que não são excludentes nem paradoxais neste cenário.", status:0, historico:0 },
{id:3038, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Semântica", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n3) No último parágrafo, o autor emprega a palavra “Crocs” que pode ser entendida como sandálias de plástico com furinhos. Apreendendo-se o sentido mais amplo que ele confere a esse termo, poderiam apresentar valor semântico equivalente todas as palavras abaixo, EXCETO:", imagem:null, alternativas:["A) CD","B) ostras","C) ombreiras","D) pochete"], resposta_correta:1, explicacao:"A alternativa B está correta. No texto, 'Crocs', 'CD', 'ombreiras' e 'pochete' pertencem a um mesmo campo semântico figurado:representam modismos, tendências passageiras que ficaram no passado, tornaram-se obsoletas ou são vistas com certa estranheza atualmente. A palavra 'ostras', por outro lado, foi utilizada no segundo parágrafo em uma metáfora para representar algo difícil de ser aberto e que traz risco, não possuindo qualquer relação semântica com itens fora de moda.", status:0, historico:0 },
{id:3039, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Conjunções", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n4) O emprego do termo “Aliás”, ao final do segundo parágrafo, introduz um sentido de:", imagem:null, alternativas:["A) conclusão","B) interrogação","C) confirmação","D) retificação"], resposta_correta:3, explicacao:"A alternativa D está correta. A conjunção/palavra denotativa 'aliás' é classicamente utilizada na língua portuguesa para retificar (corrigir/ajustar), expandir ou adicionar uma informação que reorienta o pensamento anterior. No trecho 'Nem gostava desse CD. Aliás, ninguém mais ouve CD', o autor retifica a sua afirmação particular expandindo-a para uma constatação geral, dando a entender que o fato de ele não gostar é irrelevante frente ao fato maior de que a tecnologia em si está morta.", status:0, historico:0 },
{id:3040, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Figuras de linguagem", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n5) A linguagem figurada foi empregada ao longo do texto para conferir a ele expressividade. Assinale a opção em que NÃO se percebe um exemplo desse tipo de linguagem.", imagem:null, alternativas:["A) “há grandes chances de você se perguntar:“Valia a pena tudo isso?” (2º§)","B) “os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os” (3º§)","C) “O relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:” (5º§)","D) “Há, é claro, o relacionamento trancado a sete chaves e blindado.” (8º§)"], resposta_correta:0, explicacao:"A alternativa A está correta. O trecho 'há grandes chances de você se perguntar:“Valia a pena tudo isso?”' está construído inteiramente em linguagem denotativa (literal e objetiva). Nas demais alternativas, notamos ricas linguagens figuradas:na B, uma comparação direta com ostras; na C, uma hipérbole ('mil maneiras'); e na D, o uso de metáforas e expressões idiomáticas cristalizadas ('trancado a sete chaves', 'blindado') aplicadas a relacionamentos.", status:0, historico:0 },
{id:3041, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Verbos", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n6) Em “Há, no entanto, quem defenda que os relacionamentos” (3º§), o modo pelo qual o verbo em destaque está conjugado sugere tratar-se de uma flexão do:", imagem:null, alternativas:["A) Presente do Indicativo","B) Imperativo afirmativo","C) Futuro do Presente do Indicativo","D) Presente do Subjuntivo"], resposta_correta:3, explicacao:"A alternativa D está correta. A forma verbal 'defenda' (do verbo defender) encontra-se conjugada no Presente do Subjuntivo (que eu defenda, que tu defendas, que ele defenda). Esse modo e tempo verbal são classicamente utilizados para expressar dúvida, desejo, possibilidade ou uma hipótese dependente na estrutura sintática, casando perfeitamente com a conjunção integrante 'que' subentendida ou explícita no contexto ('quem [que] defenda').", status:0, historico:0 },
{id:3042, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Sintaxe", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n7) Ao participarem da estrutura sintática dos textos, as orações estabelecem entre si relações de sentido. Desse modo, em “Há relacionamentos cuja abertura é sazonal” (6º§), a oração destacada cumpre o seguinte papel:", imagem:null, alternativas:["A) caracteriza um substantivo","B) completa o sentido de um verbo","C) indica circunstância, possui caráter adverbial","D) exerce a função de sujeito"], resposta_correta:0, explicacao:"A alternativa A está correta. A oração 'cuja abertura é sazonal' é classificada sintaticamente como uma Oração Subordinada Adjetiva Restritiva, introduzida pelo pronome relativo 'cuja'. O seu papel estrutural na frase é atuar como um imenso adjetivo, restringindo, especificando e caracterizando o substantivo antecedente 'relacionamentos'.", status:0, historico:0 },
{id:3043, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Interpretação e Produção de Textos", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n8) No oitavo parágrafo, ao afirmar “Parece que esse aí morreu.”, em sentido simbólico, o autor sugere uma crítica em relação:", imagem:null, alternativas:["A) às brigas.","B) à adolescência.","C) à fidelidade.","D) às regras."], resposta_correta:2, explicacao:"A alternativa C está correta. No trecho referenciado, o autor discorre sobre a situação extrema do relacionamento totalmente 'trancado a sete chaves' no qual, mesmo diante de uma oportunidade livre de consequências e descobertas (ninguém ficaria sabendo), o parceiro recusa por respeito irrestrito ao compromisso assumido. Ao concluir ironicamente 'Parece que esse aí morreu', o autor faz uma crítica bem-humorada atestando que a fidelidade cega e inabalável entrou em desuso na sociedade moderna.", status:0, historico:0 },
{id:3044, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Colocação Pronominal", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n9) Considerando a Norma Padrão, em “não se pode dizer que existe uma porta aberta” (4º§), o emprego, em próclise, do pronome oblíquo deve-se:", imagem:null, alternativas:["A) a um uso facultativo desse registro.","B) à presença de uma palavra atrativa.","C) a uma exigência do tempo verbal.","D) a uma reprodução do discurso oral."], resposta_correta:1, explicacao:"A alternativa B está correta. A gramática normativa estabelece regras rígidas para a colocação pronominal. A ocorrência da Próclise (pronome antes do verbo, 'se pode') no trecho fornecido é rigorosamente obrigatória devido à presença do advérbio de negação 'não', que atua como uma palavra atrativa, puxando o pronome oblíquo átono para perto de si.", status:0, historico:0 },
{id:3045, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Formação de Palavras", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"TEXTO I - O RELACIONAMENTO ABERTO\n(Por Gregorio Duvivier)\n\n“Todos os relacionamentos fechados se parecem”, diria Tolstói em “Anna Kariênina”. “Cada relacionamento aberto é infeliz à sua maneira.” Abrir um relacionamento pode se revelar uma tarefa mais difícil do que abrir uma embalagem de CD. Há grandes chances de você perder um dente. E, depois de aberto, há grandes chances de você se perguntar:“Valia a pena tudo isso? Nem gostava desse CD. Aliás, ninguém mais ouve CD”.\n\nHá, no entanto, quem defenda que os relacionamentos, assim como as ostras, merecem que a gente perca tempo abrindo-os — mesmo que, em ambos os casos, exista um forte risco de intoxicação.\n\nUma porta pode estar aberta, encostada, entreaberta, escancarada. Na relação escancarada, tudo é possível e nada é passível de ciúme (parece que esse fenômeno só aconteceu uma vez, e foi nos anos 1970). Há muitas relações escancaradas que, quando você vai ver de perto, são de fato escancaradas, mas não são relações:não se pode dizer que existe uma porta aberta porque não há sequer porta, já que tampouco há parede.\n\nO relacionamento entreaberto, no entanto, pode se entreabrir de mil maneiras:pode poder tudo desde que conte tudo pro outro ou desde que o outro não fique sabendo ou desde que não seja com amigos ou desde que seja com amigos ou desde que não se apaixone ou desde que seja por paixão.\n\nHá relacionamentos cuja abertura é sazonal:o namoro à distância internacional costuma ser como as cantinas de escola, que abrem nove meses por ano e fecham nas férias, enquanto o relacionamento intermunicipal costuma funcionar como os correios:abre em dia útil, fecha no final de semana.\n\nO relacionamento encostado parece que está trancado. Mas para amigos e vizinhos, é só empurrar o portão. E tem os namoros que, apesar de trancados, ninguém trocou a fechadura:o ex ainda tem a chave e entra quando quiser.\n\nHá, é claro, o relacionamento trancado a sete chaves e blindado. Aquele que se uma paixão de adolescência batesse na porta, e se por acaso vocês transassem, ninguém ficaria sabendo, mas mesmo assim você diz:“Não, não. Estou num relacionamento”. Parece que esse aí morreu. Talvez fique pra história como as ombreiras ou a pochete. Talvez volte com tudo em 2017, assim como as ombreiras e a pochete. Preparem-se. Não sei se estamos prontos pra essa loucura. A próxima coisa a voltar pode ser o Crocs.\n\n10) A partir do vocábulo “aberto”, formou-se “entreaberto” (5º§) pelo seguinte processo de formação:", imagem:null, alternativas:["A) sufixação","B) justaposição","C) aglutinação","D) prefixação"], resposta_correta:3, explicacao:"A alternativa D está correta. O vocábulo 'entreaberto' foi derivado a partir da raiz original 'aberto' com o acréscimo do elemento 'entre-' logo no início de sua estrutura morfológica. Quando acoplamos morfemas antes do radical da palavra, configuramos o clássico processo de derivação por prefixação.", status:0, historico:0 },
{id:3046, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Teoria dos Conjuntos", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"Numa academia 78 pessoas fazem musculação, 63 pessoas fazem ginástica, 27 fazem musculação e ginástica e 32 nenhum dos dois. O total de pessoas na academia é:", imagem:null, alternativas:["A) 141","B) 136","C) 146","D) 173"], resposta_correta:2, explicacao:"A alternativa C está correta. A resolução deste item exige a aplicação direta da teoria dos conjuntos através do Diagrama de Venn. A fórmula da união de dois conjuntos nos diz que:Total = n(A) + n(B) - n(A ∩ B) + Nenhum. Substituindo os valores extraídos do enunciado, temos:Total = 78 (musculação) + 63 (ginástica) - 27 (interseção contada duas vezes) + 32 (pessoas ociosas fora dos grupos). A operação resulta em:Total = 141 - 27 + 32 = 114 + 32 = 146 pessoas. Um erro comum induzido pela banca é o de somar todos os algarismos linearmente, ignorando as pessoas da intersecção.", status:0, historico:0 },
{id:3047, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Equações do 2º grau", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"Numa função polinomial do segundo grau o coeficiente de x² é 3, o coeficiente de x é 2 e o coeficiente independente é igual a 5. Desse modo, o valor da função para x = -1 é:", imagem:null, alternativas:["A) 5","B) 0","C) -3","D) 4"], resposta_correta:3, explicacao:"A questão original apresenta um provável erro material de formulação da banca que leva à inexistência de alternativa correta para a equação perfeitamente descrita no texto. Traduzindo o enunciado, montamos a função f(x) = 3x² + 2x + 5. Calculando o valor para x = -1, teríamos:f(-1) = 3(-1)² + 2(-1) + 5 = 3(1) - 2 + 5 = 6. O resultado matemático absoluto é 6, o qual não consta nas opções. Para que a alternativa D (4) estivesse correta, o coeficiente de x² deveria ser apenas 1. Para que a alternativa B (0) estivesse correta, o coeficiente de x² deveria carregar o sinal de negativo (-3). Assumiremos o preenchimento na alternativa D apenas por aproximação didática, alertando para a falha processual no certame.", status:0, historico:0 },
{id:3048, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Progressão Geométrica", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"O terceiro termo de uma PG(progressão geométrica) é igual a 12 e o quarto termo é igual a 4. Se a razão dessa PG é igual à razão da PA(progressão aritmética), cujo primeiro termo é igual a 2, então o sétimo termo dessa PA é igual a:", imagem:null, alternativas:["A) 3","B) 5","C) 6","D) 4"], resposta_correta:3, explicacao:"A alternativa D está correta. A mecânica exige descobrir primeiro a razão da PG e transportá-la para a PA. A razão 'q' da PG é definida pela divisão de um termo pelo seu antecessor. Assim, q = a4 / a3 = 4 / 12 = 1/3. O enunciado adverte que a razão 'r' da PA possui a mesmíssima magnitude da PG, portanto r = 1/3. Com o primeiro termo da PA sendo a1 = 2, aplicamos a fórmula do termo geral da PA para achar o sétimo termo:a7 = a1 + (n-1) * r -> a7 = 2 + (7-1) * (1/3) -> a7 = 2 + 6 * (1/3) -> a7 = 2 + 2 = 4. O termo final exigido totaliza 4.", status:0, historico:0 },
{id:3049, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Matrizes", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"O determinante da matriz formada pelos coeficientes das incógnitas do sistema linear\nx + 2y - z = 2\n2x + y + z = 4\n-x + y + 2z = 2\né igual a:", imagem:null, alternativas:["A) -12","B) -8","C) 4","D) -4"], resposta_correta:0, explicacao:"A alternativa A está correta. Montamos a matriz de ordem 3x3 alocando exclusivamente os coeficientes matemáticos puros (os números associados às letras):Linha 1 [1, 2, -1], Linha 2 [2, 1, 1] e Linha 3 [-1, 1, 2]. Aplicando o método da Regra de Sarrus, copiamos as duas primeiras colunas e multiplicamos cruzado. O somatório dos eixos principais resulta em:(1*1*2) + (2*1*-1) + (-1*2*1) = 2 - 2 - 2 = -2. O somatório dos eixos secundários invoca:(-1*1*-1) + (1*1*1) + (2*2*2) = 1 + 1 + 8 = 10. A equação final para apurar o determinante postula (Soma Primária - Soma Secundária):Det = -2 - 10 = -12.", status:0, historico:0 },
{id:3050, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Trigonometria", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"O total de soluções da equação cos x = 0 para 0 ≤ x ≤ 2π é:", imagem:null, alternativas:["A) 1","B) 2","C) 3","D) 0"], resposta_correta:1, explicacao:"A alternativa B está correta. A análise foca-se puramente na leitura espacial do ciclo trigonométrico base, varrendo o limite engessado da sua primeira volta completa [0, 2π]. O valor do cosseno reflete diretamente as medições do eixo das abscissas (eixo X horizontal). O cruzamento exato e pontual onde o valor da coordenada x zera (cos x = 0) materializa-se nos cumes verticais do círculo:aos 90 graus (que equivale a π/2 em radianos) e, lá embaixo, aos 270 graus (que atende pela fração 3π/2). Logo, possuímos estritamente 2 ocorrências e soluções válidas que satisfazem a imposição da equação.", status:0, historico:0 },
{id:3051, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Geometria Plana", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"As medidas das projeções dos catetos de um triângulo retângulo são 4 cm e 9 cm. Nessas condições, a medida da altura desse triângulo com relação à hipotenusa é igual a:", imagem:null, alternativas:["A) √13 cm","B) 3,6 cm","C) 6 cm","D) 5 cm"], resposta_correta:2, explicacao:"A alternativa C está correta. A aplicação é cirúrgica no bojo das Relações Métricas do Triângulo Retângulo. A fórmula universal ensina que a altura relativa à hipotenusa (h) elevada ao quadrado é inegavelmente idêntica e perfeitamente equiparada ao produto cruzado das projeções dos dois catetos sobre ela (sendo as projeções carinhosamente apelidadas por 'm' e 'n'). O teorema atesta:h² = m * n. Substituindo o esqueleto pelos valores frios cedidos:h² = 4 * 9. Logo, h² = 36. Aplicando a raiz quadrada na base isolada, resulta-se cravado e seguro que h = 6 cm.", status:0, historico:0 },
{id:3052, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Geometria Plana", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"O lado do quadrado inscrito numa circunferência é igual a 8√2 cm. Nessas circunstâncias, a área dessa circunferência é igual:", imagem:null, alternativas:["A) 64 π cm²","B) 16 π cm²","C) 32 π cm²","D) 128 π cm²"], resposta_correta:0, explicacao:"A alternativa A está correta. Para calcular a área pedida, necessitamos expor o Raio (R) do círculo. Quando um quadrado atua preso dentro da redoma circular (inscrito), suas hastes diametrais cruzam inegavelmente o âmago absoluto da figura e igualam-se ao Diâmetro da circunferência. A diagonal de um quadrado padroniza-se pela base L√2 (Lado vezes raiz de 2). Lançando o lado informado de 8√2, a diagonal crava 8√2 * √2 = 8 * 2 = 16 cm. O diâmetro do círculo é 16, portanto seu raio repousa cravado em 8 cm. Alimentando a fórmula de área A = π * R², temos:A = π * 8², encerrando o laudo estático em 64π cm².", status:0, historico:0 },
{id:3053, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Geometria Espacial", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"A medida da altura de um prisma de base quadrada é igual ao dobro da medida da aresta da base. Se o perímetro da base do prisma é igual a 20 cm, então o volume do prisma é:", imagem:null, alternativas:["A) 125 cm³","B) 400 cm³","C) 500 cm³","D) 250 cm³"], resposta_correta:3, explicacao:"A alternativa D está correta. Começa-se desmembrando o perímetro inferior. Uma base quadrada possui 4 lados iguais, atestando então que Perímetro = 4 * lado. Se o perímetro atinge 20 cm, a singela e pura aresta base é de 20 / 4 = 5 cm. O regramento construtivo informa que a Altura (h) do bloco equivale ao dobro e é duplicada perante essa espessura:logo, h = 2 * 5 = 10 cm. A liturgia volumétrica do Prisma orienta o trânsito da conta para:Volume = Área da Base * Altura. Como a base é quadrada (5² = 25 cm²), injetamos no volume:V = 25 * 10, estancando a prova limítrofe inócuo no gabarito final cravado de 250 cm³.", status:0, historico:0 },
{id:3054, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Geometria Analítica", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"O coeficiente angular de uma reta é igual a 5 e o coeficiente linear é 3, então a equação da reta é descrita como:", imagem:null, alternativas:["A) 3x + y - 5 = 0","B) 5x - y + 3 = 0","C) 3x - y - 5 = 0","D) 5x + y - 3 = 0"], resposta_correta:1, explicacao:"A alternativa B está correta. A geometria estampa na forma reduzida clássica o formato matriz de (y = mx + q), ou graficamente popularizada como (y = ax + b). Nesse teatro, a letra 'm' representa o ângulo de subida (coeficiente angular, no caso, 5), enquanto a incógnita 'q' personifica o exato talho no eixo Y (coeficiente linear, no caso 3). Adornando a estrutura orgânica base resulta-se em:y = 5x + 3. Para moldar as exigências da banca e transmutar para a versão da Equação Geral exigida nas respostas igualada a zero, transportamos forçosamente o isolado 'y' para as malhas inimigas mudando de sinal magnético:5x - y + 3 = 0.", status:0, historico:0 },
{id:3055, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Geometria Analítica", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"A equação de uma circunferência é igual a (x - 3)² + (y + 2)² = 16. Nessas condições, as coordenadas do centro dessa circunferência é:", imagem:null, alternativas:["A) (-3, 2)","B) (-2, 3)","C) (2, -3)","D) (3, -2)"], resposta_correta:3, explicacao:"A alternativa D está correta. A equação cartográfica pura limítrofe nativa reduzida atrelada aos polos centrais de uma circunferência possui o engessado modelo formal clássico pátrio:(x - a)² + (y - b)² = R², onde as incógnitas cativas (a, b) compõem as cruas coordenadas vetoriais litorâneas fixas ativas pacíficas daquele cobiçado Centro (C) da figura. Comparando visualmente a lei geral e a fórmula exposta crua do teste analítico ((x - 3)² + (y + 2)²), é patente forçosamente deduzir espelhamento de que o vetor 'a' vale cravado e positivo o algarismo 3, e o vetor marginal cível pacato 'b' materializa o -2 (haja vista que a injeção mecânica do sinal negativo de fábrica da matriz sobre a fração imposta converte-o visualmente reverso num +2 visível no papel). Assim, o Centro irradia da morada exata estática do ponto (3, -2).", status:0, historico:0 },
{id:3056, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Editores de texto", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"Quanto ao aplicativo do MS-Office 2010 para criação e edição de textos, analise as afirmativas abaixo, dê valores Verdadeiro (V) ou Falso (F) e assinale a alternativa que apresenta a sequência correta (de cima para baixo):\n( ) é possível colocar uma proteção para evitar que pessoas não autorizadas possam abrir um arquivo de documento Word, ou seja, quando se criar um documento sigiloso será possível impedir que pessoas não autorizadas possam abrir o arquivo.\n( ) o Word 2010 não possibilita que um arquivo seja gravado no formato PDF.", imagem:null, alternativas:["A) V - V","B) V - F","C) F - V","D) F - F"], resposta_correta:1, explicacao:"A alternativa B está correta (V, F). A primeira afirmativa é Verdadeira:o Microsoft Word possui robustas funções de restrição nativa inseridas em seu backstage na aba de informações, permitindo o isolamento do texto pela inserção ativada de senhas para trancar puramente a abertura total do arquivo sigiloso. A segunda proposição comete crime letal e é Falsa:o MS Word 2010 já incorporou integralmente em sua caixa nativa 'Salvar Como' o suporte nativo a gravação embutida orgânica limpa pacífica isolada oca pura refratária de documentos em extensão PDF, aposentando definitivamente os lentos plugins e conversores litorâneos remotos virtuais.", status:0, historico:0 },
{id:3057, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Apresentações", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"Na guia Inserir do Microsoft PowerPoint 2010 identifique a única opção abaixo que NÃO pertence a essa guia:", imagem:null, alternativas:["A) Clip-Art","B) WordArt","C) FineArt","D) SmartArt"], resposta_correta:2, explicacao:"A alternativa C está correta. A banca recobra a literalidade engessada do reconhecimento dos nomes das ferramentas gráficas embutidas nativas nas laudas visuais do Office. Na abóboda matriz isolada de formatação e inserção vetorial paralela ativa da Guia Inserir, albergam-se legitimadas universalmente as abas tradicionais limítrofes do Clip-Art (figuras antigas), do glorioso WordArt (letras em 3D refratárias densas) e as rústicas nativas puritanas marginais ativas hierárquicas da SmartArt (fluxogramas orgânicos e organogramas). A designação intrusa alienígena fantasma imposta do 'FineArt' constitui mero trocadilho inventivo pardo oco cego elaborado e plantado exclusivamente nas raias da prova pela banca como isca para confundir a nomenclatura nativa pacífica.", status:0, historico:0 },
{id:3058, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Windows", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"No gerenciador de pastas e arquivos do Windows existe um modo de exibição dos arquivos que permite exibir informações adicionais como, por exemplo:nome e tipo do arquivo, data da última modificação e tamanho. Esse modo de exibição é definido pela Microsoft como:", imagem:null, alternativas:["A) Lista.","B) Invólucro.","C) Detalhes.","D) Lado a lado."], resposta_correta:2, explicacao:"A alternativa C está correta. O modo de exibição 'Detalhes' no Windows Explorer organiza o conteúdo em formato de tabela, listando os arquivos em linhas e apresentando atributos adicionais e personalizáveis em colunas (como tamanho, tipo de item, data de modificação, autor, etc). O modo 'Lista' apenas mostra os nomes sem os dados complementares em colunas. O modo 'Lado a lado' exibe ícones médios com informações breves ao lado. 'Invólucro' é uma alternativa puramente inventada pela banca para atuar como distrator.", status:0, historico:0 },
{id:3059, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Windows", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"No Windows XP, para ativar o Gerenciador de Tarefas mostrando aplicativos e processos em execução, desempenho (uso de CPU e memória), Rede (conexão à Internet) e usuários em execução deve-se acionar a sequência de teclas:", imagem:null, alternativas:["A) Ctrl+Alt+Del","B) Alt+Del+Tab","C) Ctrl+Shif+Alt","D) Alt+Shif+Tab"], resposta_correta:0, explicacao:"A alternativa A está correta. Em versões clássicas como o Windows XP, a famosa combinação 'Ctrl+Alt+Del' abria direta e imediatamente a janela do Gerenciador de Tarefas (Task Manager). É importante notar que em sistemas modernos (como Windows 10 e 11), essa mesma combinação abre uma tela de segurança que dá acesso ao Gerenciador de Tarefas, sendo o atalho direto atual 'Ctrl+Shift+Esc'. Como a questão especificou a versão do Windows XP, a alternativa A reflete fielmente a tecnologia da época. As demais alternativas apresentam combinações fictícias ou que apenas alternam janelas.", status:0, historico:0 },
{id:3060, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"Quanto aos conceitos e modos de utilização de ferramentas e procedimentos de internet, intranet e correio eletrônico (MS-Outlook), analise as afirmativas abaixo, dê valores Verdadeiro (V) ou Falso (F) e assinale a alternativa que apresenta a sequência correta (de cima para baixo):\n( ) no MS-Outlook é possível anexar e encaminhar qualquer tipo de arquivo pela internet.\n( ) a Intranet é somente o nome dado aos provedores de Internet para os usuários em geral.", imagem:null, alternativas:["A) V - V","B) V - F","C) F - V","D) F - F"], resposta_correta:3, explicacao:"A alternativa D está correta (F, F). A primeira afirmativa é Falsa:não é possível anexar e encaminhar 'qualquer tipo' de arquivo. O MS-Outlook e a maioria dos servidores de e-mail possuem bloqueios nativos e automáticos por questões de segurança contra arquivos executáveis e scripts (como .exe, .bat, .vbs) para prevenir a propagação de malwares. Além disso, existe restrição quanto ao peso (geralmente limitado a cerca de 20MB/25MB). A segunda afirmativa também é Falsa:a Intranet não é um nome dado a provedores. Intranet é uma rede privada e corporativa que utiliza tecnologias da Internet, mas com acesso restrito aos funcionários de uma organização. Provedores de internet recebem a denominação de ISPs (Internet Service Providers).", status:0, historico:0 },
{id:3061, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"Para que um computador seja encontrado e possa fazer parte da rede mundial de computadores, necessita ter um endereço único denominado endereço IP (Internet Protocol Address). Assinale a alternativa que apresenta um endereço IP válido:", imagem:null, alternativas:["A) 172.31.110.10.257.18","B) 172.31.110.10","C) 172.31.110","D) 172.31.110.10.257"], resposta_correta:1, explicacao:"A alternativa B está correta. A arquitetura clássica do endereço IPv4 (à qual a questão faz referência primária) é composta por 32 bits divididos logicamente em 4 blocos numéricos (octetos) separados por pontos (x.x.x.x). Além da exigência de conter exatamente 4 blocos, cada bloco pode variar apenas e estritamente de 0 a 255. A alternativa B ('172.31.110.10') é a única que respeita integralmente essas regras. As opções A e D possuem blocos em excesso e usam números fora do limite do octeto (o algarismo 257 é inválido no IPv4). A alternativa C é incompleta por possuir apenas 3 blocos lógicos.", status:0, historico:0 },
{id:3062, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"Numa rede de computadores, do tipo estrela, existe um dispositivo que permite transmitir dados a todos computadores conectados à rede ao mesmo tempo. Esse dispositivo é denominado tecnicamente de:", imagem:null, alternativas:["A) hub.","B) modem.","C) bridge.","D) firewall."], resposta_correta:0, explicacao:"A alternativa A está correta. O Hub (ou concentrador) atua na Camada 1 (Física) e funciona como o nó central aglutinador de uma topologia de rede em estrela. Ele é classificado como um equipamento sem inteligência de rotas, pois ao receber um pacote de dados em uma de suas portas, ele o retransmite cegamente e inegavelmente para TODAS as demais portas conectadas de forma simultânea (processo de broadcast). Um Switch agiria diferente, mandando a informação apenas para a porta do destinatário. O Modem apenas modula o sinal analógico/digital. A Bridge liga redes distintas e o Firewall é voltado exclusivamente ao bloqueio de conexões na segurança.", status:0, historico:0 },
{id:3063, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Segurança Digital", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"Segundo a “Cartilha de Segurança para a Internet” da cert.br os “programas especificamente desenvolvidos para executar ações danosas e atividades maliciosas em um computador” é denominado:", imagem:null, alternativas:["A) lowware.","B) malware.","C) evilware.","D) poorware."], resposta_correta:1, explicacao:"A alternativa B está correta. O termo 'Malware' consolida a contração oficial e acadêmica das palavras inglesas 'Malicious' (Malicioso) e 'Software' (Programa). É a categorização universal adotada pela comunidade de tecnologia e pela CERT.br para designar qualquer código ou programa projetado com a intenção explícita de prejudicar, infectar ou roubar dados de um sistema informático. Essa categoria macro engloba os Vírus, Cavalos de Troia (Trojans), Ransomwares e Spywares. As alternativas 'Lowware', 'Evilware' e 'Poorware' consistem em neologismos criados intencionalmente pela banca como armadilhas.", status:0, historico:0 },
{id:3064, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Sistemas Operacionais", cargo:"Agente Fiscal da Vigilância Sanitária", ano:"2016", banca:"IBFC", concurso:"Prefeitura do Município de Jandira", enunciado:"Na Tecnologia de Informação definimos como sendo uma estrutura utilizada para organizar arquivos em um computador ou um arquivo que contém referências a outros arquivos:", imagem:null, alternativas:["A) programa.","B) decretório.","C) ficheiro.","D) diretório."], resposta_correta:3, explicacao:"A alternativa D está correta. Nos sistemas operacionais, o termo técnico 'Diretório' (conhecido pelo público de Windows sob a denominação visual de 'Pasta') define perfeitamente o catálogo ou contêiner de estruturação lógica usado para armazenar, hierarquizar e organizar as referências dos arquivos ou mesmo de outros subdiretórios no disco rígido. 'Programa' é sinônimo de software de execução. 'Ficheiro' é a tradução corriqueira em Portugal para um arquivo qualquer solto, e não a estrutura que os organiza. E 'decretório' é um substantivo nulo no dicionário digital.", status:0, historico:0 },
{id:3065, categoria:"Conhecimentos Específicos", materia:"Vigilância Epidemiológica", assunto:"Indicadores de Saúde", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"Nas Variáveis/ Indicadores de Saúde mais usados pela vigilância a saúde temos para uma delas a seguinte definição:“ É a variável característica das comunidades de seres vivos, refere-se ao conjunto dos indivíduos que adquirem doenças (ou determinadas doenças) num dado intervalo de tempo em uma determinada população”. Marque a opção que corresponde a essa variável.", imagem:null, alternativas:["A) Incidência.","B) Prevalência.","C) Mortalidade.","D) Morbidade.","E) Letalidade."], resposta_correta:0, explicacao:"A alternativa A está correta. A chave matriz para resolver as equações lexicais em epidemiologia orbita na dinâmica de casos. Quando a definição alude à contagem e ao surgimento isolado puro estático dinâmico de PESSOAS QUE ADQUIREM uma doença e adoecem subitamente num estrito período temporal demarcado litorâneo inócuo de risco, o conceito refere-se à taxa de NOVOS CASOS. A mensuração técnica que computa apenas a velocidade do surgimento de casos novos no bojo do tecido humano chama-se Incidência. (Prevalência mescla o volume estático empilhado de casos novos cruzado aglutinado aos velhos remanescentes crônicos).", status:0, historico:0 },
{id:3066, categoria:"Conhecimentos Específicos", materia:"Vigilância Epidemiológica", assunto:"Síndrome da Rubéola Congênita", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"Sobre a Síndrome da Rubéola Congênita, marque a opção CORRETA:\nI. Maior complicação da infecção pelo vírus da rubéola durante a gestação, .principalmente no 3º trimestre gestacional.\nII. Pode comprometer o desenvolvimento do feto e causar abortamento, morte fetal ou anomalias congênitas.\nIII. Transmissão pela via transplacentária, após a viremia materna.\nIV. As crianças com SRC frequentemente apresentam mais de um sinal ou sintoma, mas podem ter apenas uma má-formação, sendo a deficiência auditiva a mais comum e exantema crônico.", imagem:null, alternativas:["A) Somente a afirmativa I está incorreta.","B) As afirmativas I, II e III estão corretas.","C) As afirmativas I, II e IV estão corretas.","D) As afirmativas I e IV estão corretas.","E) Todas as afirmativas estão incorretas."], resposta_correta:0, explicacao:"A alternativa A está correta. A Síndrome da Rubéola Congênita (SRC) representa um risco devastador na linha de formação morfológica do feto. Seu espectro destrutivo gera o maior volume de teratogenia e má-formações sistêmicas (surdez, cegueira por catarata e cardiopatias) quando o contato agressivo do vírus com a gestante ocorre justamente nos primeiros meses de formação embrionária crítica. O erro letal cravado pela banca repousa apenas na afirmativa I, que estipula falaciosamente que as maiores complicações residem na faixa do 3º trimestre.", status:0, historico:0 },
//Criadas pelo Gemini
{id:3067, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O cenário macroeconômico brasileiro pós-pandemia tem sido marcado por debates em torno do novo Arcabouço Fiscal, criado para substituir o antigo 'Teto de Gastos'. Esse novo regramento busca equilibrar a responsabilidade fiscal com a necessidade de investimentos públicos. Em relação aos fundamentos estruturais da nova política econômica do Brasil e as discussões sobre a taxa de juros (Selic), analise o contexto e marque a constatação correta:", imagem:null, alternativas:["A) O novo arcabouço fiscal eliminou a cobrança de impostos sobre grandes fortunas, congelando o salário mínimo por dez anos para atrair capital estrangeiro.","B) A política monetária do Banco Central atua em total subordinação aos desejos imediatos do Poder Executivo, reduzindo forçadamente a Selic para 2% ao ano para estimular o crédito habitacional popular.","C) O Arcabouço Fiscal instituiu um piso e um teto para o crescimento das despesas públicas, atrelando esse crescimento à arrecadação de receitas do governo, enquanto o Banco Central, que goza de autonomia operacional, manteve-se cauteloso na redução dos juros visando controlar as pressões e a convergência da inflação.","D) O governo federal abandonou a perseguição da meta de déficit zero, adotando uma política de hiperinflação controlada para desvalorizar a moeda e baratear a exportação das commodities agrícolas do cerrado.","E) A regra fiscal recente proíbe categoricamente qualquer aumento de gastos com saúde e educação em caso de crescimento do PIB, destinando os superávits apenas para o pagamento de dividendos de estatais privatizadas."], resposta_correta:2, explicacao:"A alternativa C está correta. (70% Nível Difícil - Mistura de política e economia). A banca INETE ataca a interpretação do Arcabouço Fiscal (que não trava os gastos em zero como o teto antigo, mas atrela o aumento do gasto à alta da receita, com limites) e cobra o conhecimento sobre a Autonomia do Banco Central (o BC não é mais submisso ao presidente, o que gera os famosos atritos sobre a Selic). O distrator B inverte o fato (o BC é autônomo). Os distratores A, D e E contêm generalizações indevidas e notícias falsas ou parcialmente corretas distorcidas.", status:0, historico:0 },
{id:3068, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Julgue as sentenças abaixo sobre fatos notórios recentes na saúde pública nacional e global, marcando-as como Verdadeiras (V) ou Falsas (F), e identifique a sequência exata. \nI - O aumento exponencial dos casos de Dengue no Brasil em anos recentes está diretamente correlacionado aos efeitos do fenômeno El Niño e às mudanças climáticas, que criam condições ideais de calor e umidade para a proliferação do mosquito vetor. \nII - A vacina contra a Dengue foi incluída no SUS e imediatamente aplicada em massa para 100% da população brasileira de todas as faixas etárias, erradicando a doença em capitais costeiras. \nIII - A Organização Mundial da Saúde (OMS) declarou a varíola dos macacos (Mpox) como Emergência de Saúde Pública de Importância Internacional, exigindo vigilância global coordenada em função do surgimento de novas cepas e espalhamento geográfico. \nIV - O Brasil baniu completamente a tecnologia da bactéria Wolbachia, considerando-a um risco biológico que potencializou as epidemias urbanas nos últimos levantamentos epidemiológicos.", imagem:null, alternativas:["A) V, F, V, F.","B) F, V, F, V.","C) V, V, F, F.","D) F, F, V, V.","E) V, F, F, V."], resposta_correta:0, explicacao:"A alternativa A está correta (V, F, V, F). (30% Nível Médio). I é V (El Niño aumentou os focos). II é a pegadinha Falsa:a vacina (Qdenga) foi incluída no SUS, MAS não para 100% da população (foi focada em grupos prioritários, jovens/crianças, devido à escassez de doses). III é V (A Mpox gerou alertas globais reiterados da OMS). IV é Falsa, sendo uma inversão conceitual grave:a bactéria Wolbachia é, na verdade, uma das principais e mais bem-sucedidas ARMAS biológicas usadas pelo Brasil para INIBIR a transmissão da dengue pelo mosquito, não sendo banida, mas expandida.", status:0, historico:0 },
{id:3069, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Biossegurança", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"Analise a situação:Hong Kong, China. Um hóspede com sintomas de gripe permanece em um hotel por dois dias. Semanas depois, pessoas com a Síndrome Aguda Respiratória (Sars) são identificadas em cinco países, incluindo Canadá e Estados Unidos. A investigação mostra que os casos estavam relacionados ao paciente do hotel. Marque a opção CORRETA.\nI. A situação acima diz respeito a um conceito cada vez mais importante nos dias atuais:a biossegurança.\nII. A biossegurança está relacionada apenas a sistemas modernos de esterilização do ar de um laboratório ou câmaras de desinfecção das roupas de segurança.\nIII. Um profissional de saúde que não lava suas mãos com a frequência adequada ou o lixo hospitalar descartado de maneira errada são práticas do dia-a-dia que também trazem riscos.", imagem:null, alternativas:["A) Somente a afirmativa I está correta.","B) Somente a afirmativa II está incorreta.","C) Somente a afirmativa III está correta.","D) Somente a afirmativa II está correta.","E) Todas as afirmativas estão incorretas."], resposta_correta:1, explicacao:"A alternativa B está correta. O evento relatado comprova que vírus com grande poder de infecção escalam fronteiras em horas, tornando protocolos contínuos de Biossegurança pilares vitais e globais (I é verdadeira). O conceito de biossegurança engloba desde a faxina básica da enfermaria e a simples lavagem correta das mãos de um paramédico na UBS até o descarte do algodão fétido no lixo (III é verdadeira). Logo, a limitação perigosa imposta pela palavra 'apenas' na assertiva II, associando biossegurança exclusivamente a câmaras bilionárias de ar assépticas laboratoriais, torna a afirmação grosseiramente e irresponsavelmente falsa.", status:0, historico:0 },
{id:3070, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Brasil registrou marcos importantes na sua relação comercial global ao longo da década. A reconfiguração das cadeias de suprimentos (nearshoring) e o peso da Ásia nas exportações brasileiras redesenharam o fluxo de caixa nacional. Analisando o panorama do comércio exterior brasileiro recente, a assertiva verdadeira é:", imagem:null, alternativas:["A) Os Estados Unidos consolidaram-se como o maior parceiro comercial exclusivo do Brasil na compra de commodities brutas como soja e minério de ferro, superando folgadamente o mercado asiático.","B) A China manteve sua posição hegemônica como principal parceiro comercial e maior destino das exportações do Brasil, absorvendo maciçamente produtos primários do agronegócio e do setor extrativista mineral brasileiro.","C) O Mercosul adotou o Dólar americano como moeda oficial do bloco, abolindo a cobrança de tarifas alfandegárias para conter a invasão de produtos eletrônicos europeus nas indústrias nacionais.","D) A exportação de microchips de alta tecnologia, desenhados na zona franca de Manaus, tornou-se o principal item da balança comercial baiana, substituindo a velha matriz dependente do agronegócio de grãos.","E) O Brasil sofreu sanções do bloco BRICS após recusar o ingresso de novos membros, o que isolou as exportações de proteína animal no mercado do Oriente Médio, forçando uma dependência nociva da costa pacífica."], resposta_correta:1, explicacao:"A alternativa B está correta. (30% Nível Médio). A China é, com folga, o principal parceiro comercial do Brasil, comprando enormes volumes de soja, carne e minério de ferro (bens primários/commodities). A banca ataca esse ponto com o distrator A (colocando os EUA como principal comprador de commodities, o que é falso, já que o comércio Brasil-EUA é mais voltado para manufaturados/serviços e a China lidera em commodities). O distrator C cria uma fake news popular (Dólar no Mercosul). O distrator D inverte a matriz exportadora real (nós exportamos primários, não microchips).", status:0, historico:0 },
{id:3071, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O desastre climático ocorrido no Rio Grande do Sul não apenas devastou a infraestrutura local, mas reacendeu o alerta global sobre as 'cidades-esponja' e os protocolos de prevenção a eventos climáticos extremos. No contexto das respostas institucionais e do impacto social dessas tragédias que assolam as malhas urbanas brasileiras, conclui-se corretamente que:", imagem:null, alternativas:["A) A inoperância unânime dos sistemas de bombeamento e comportas locais evidenciou que eventos climáticos no Sul do Brasil são previsíveis apenas por satélites da agência europeia, devido à falta de radares nacionais em atuação.","B) A tragédia gaúcha estimulou a aprovação emergencial no Senado da privatização total e compulsória das defesas civis estaduais para fundos de investimento internacionais de mitigação de risco climático.","C) As enchentes e as secas severas não afetam o escoamento agrícola nacional, vez que o escoamento logístico hídrico (hidrovias) foi previamente abolido em prol das malhas ferroviárias puras nas bacias afetadas.","D) O desastre sublinhou a urgência e a falta de investimentos estruturais de longo prazo em prevenção, manutenção de diques urbanos, adaptação climática e sistemas de alerta precoce no Brasil, expondo a vulnerabilidade das cidades perante o aumento de intensidade e frequência dos eventos climáticos extremos.","E) O fenômeno provocou o resfriamento tardio das águas costeiras do Atlântico Norte, o que freou a subida das marés no litoral nordestino, impedindo que surtos similares de chuvas chegassem aos estados da região da caatinga no mesmo período."], resposta_correta:3, explicacao:"A alternativa D está correta. (70% Nível Difícil - Foco em interpretação). A INETE aborda a tragédia climática focando nas consequências sociopolíticas e estruturais. A enchente no RS mostrou que o problema maior não é só o clima (chuva forte), mas a falta de manutenção das comportas, diques e a falência dos sistemas de prevenção a desastres e adaptação climática urbana no Brasil. Os distratores usam notícias falsas absurdas camufladas de termos técnicos (B - privatização compulsória da defesa civil; C - abolição de hidrovias e impacto zero no agro; E - conexões inventadas com o Nordeste).", status:0, historico:0 },
{id:3072, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Considere um argumento cuja estrutura condicional correspondente precisa ser validada para testar a integridade de um módulo lógico. As premissas são: P1: Se o cache está íntegro, então a consulta retorna rápido. P2: Se o cache não está íntegro, então o índice é reconstruído. P3: A consulta não retorna rápido. Assinale a alternativa que apresenta uma conclusão que torna o argumento válido e cuja conjunção das premissas com a negação dessa conclusão gera uma contradição:", imagem:null, alternativas:["A) O cache está íntegro.","B) O índice não é reconstruído.","C) O índice é reconstruído e o cache não está íntegro.","D) A consulta retorna rápido se, e somente se, o índice é reconstruído.","E) Ou o cache está íntegro ou o índice não é reconstruído."], resposta_correta:2, explicacao:"Estrutura formal: P1: C -> R; P2: ~C -> I; P3: ~R. Passo 1: Aplicando Modus Tollens entre P1 (C -> R) e P3 (~R), obtemos ~C (o cache não está íntegro). Passo 2: Aplicando Modus Ponens entre P2 (~C -> I) e ~C, obtemos I (o índice é reconstruído). Passo 3: Pela regra da Conjunção entre I e ~C, temos (I ^ ~C): o índice é reconstruído e o cache não está íntegro. Negar essa conclusão junto às premissas fecha todos os ramos do tableau analítico (contradição). Distratores: A e B negam os resultados obtidos; D e E são falsos na valoração encontrada.", status:0, historico:0 },
{id:3073, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"No gerenciamento de incidentes da rede UFBA, considere as afirmações acerca de três servidores (Alfa, Beta e Gama): P1: Se Alfa está sobrecarregado, então Beta está ativo ou Gama está em espera. P2: Se Beta está ativo, então Alfa não está sobrecarregado. P3: Alfa está sobrecarregado. A partir dessas premissas, conclui-se de maneira formalmente válida que:", imagem:null, alternativas:["A) Beta está ativo e Gama está em espera.","B) Beta está ativo e Gama não está em espera.","C) Beta não está ativo e Gama está em espera.","D) Beta não está ativo e Gama não está em espera.","E) Gama está em espera apenas se Beta estiver ativo."], resposta_correta:2, explicacao:"Estrutura formal: P1: A -> (B v G); P2: B -> ~A; P3: A. Passo 1: Aplicando Modus Ponens entre P1 e P3 (A), obtemos a disjunção (B v G). Passo 2: Como temos A (que equivale a ~~A), aplicamos Modus Tollens em P2 (B -> ~A), obtendo ~B (Beta não está ativo). Passo 3: Aplicando Silogismo Disjuntivo entre (B v G) e ~B, obtemos G (Gama está em espera). Passo 4: Pela regra da Conjunção entre ~B e G, deduz-se validamente (~B ^ G): Beta não está ativo e Gama está em espera. Distratores: A e B afirmam B; D nega G; E estabelece condição inválida.", status:0, historico:0 },
{id:3074, categoria:"Conhecimentos Específicos", materia:"Vigilância Ambiental", assunto:"Georreferenciamento", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"Na Vigilância Ambiental em Saúde, o georeferenciamento de dados é uma ferramenta usada para referenciar registros tabulares a um lugar da superfície da terra ou unidade territorial (bairro, município, localidade, etc.). Qual a finalidade desse georeferenciamento para saúde? Marque a opção CORRETA.", imagem:null, alternativas:["A) Possibilitar a elaboração de mapas de risco capazes de auxiliar a tomada de decisão nas diversas instâncias do SUS.","B) Promover o controle de bens de consumo.","C) Promover o controle de prestação de serviços. .","D) Executar ações de controle de doenças e agravos.","E) Nenhuma das respostas anteriores."], resposta_correta:0, explicacao:"A alternativa A está correta. O mapeamento georreferenciado é a espinha dorsal logística da Inteligência em Saúde Pública. Ele não fiscaliza consumo de bens diretos ou age como executor isolado, mas atua processando dados (como a coordenada exata de focos da dengue ou moradias sem saneamento) para transformá-los em Mapas de Risco. Esse mapa térmico e visual é o que subsidia e orienta as decisões dos gestores do SUS para despachar frotas de agentes ou vacinas para as zonas críticas do território.", status:0, historico:0 },
{id:3075, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Política Nacional de Resíduos Sólidos", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"Quanto ao descarte de resíduos na natureza e destinos à reciclagem ou reutilização, os resíduos do Grupo D, a sua identificação deve ser feita nos recipientes e nos abrigos de guarda de recipientes, usando código de cores e suas correspondentes nomeações, baseadas na Resolução CONAMA nº. 275/2001, e símbolos de tipo de material reciclável. Marque a opção CORRETA.\nI - Azul – Papéis.\nII- Marrom – Metais.\nIII - Verde – Vidros.\nIV - Vermelho – Plásticos.\nV - Amarelo – Resíduos orgânicos.", imagem:null, alternativas:["A) As afirmativas I e II estão corretas.","B) As afirmativas II e III estão corretas.","C) As afirmativas II e V estão incorretas.","D) As afirmativas I e IV estão incorretas","E) As afirmativas I e V estão corretas"], resposta_correta:2, explicacao:"A alternativa C está correta. A Resolução CONAMA nº 275/2001 padroniza de forma rígida as cores globais das lixeiras de reciclagem no país:Azul é exclusivo para Papel (I=V); Verde abriga o Vidro (III=V); e Vermelho recebe o Plástico (IV=V). O erro da questão (que a opção C expõe brilhantemente como incorreto) encontra-se trocado nos itens II e V:A cor oficial de classificação para a recepção dos Metais é o Amarelo (não marrom), e o Marrom destina-se aos resíduos orgânicos (não amarelo).", status:0, historico:0 },
{id:3076, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Na governança de TI, estabeleceu-se o seguinte conjunto de premissas: P1: O projeto de infraestrutura é aprovado se, e somente se, consta no Plano Diretor de TI. P2: Se o projeto consta no Plano Diretor de TI, então há dotação orçamentária prévia. P3: Não há dotação orçamentária prévia ou o comitê gestor emitiu parecer favorável. P4: O comitê gestor não emitiu parecer favorável. Com base nessas premissas, conclui-se validamente que:", imagem:null, alternativas:["A) O projeto de infraestrutura foi aprovado, mas sem dotação orçamentária.","B) O projeto consta no Plano Diretor de TI, porém o projeto não foi aprovado.","C) O projeto de infraestrutura não foi aprovado.","D) Se o projeto não foi aprovado, então o comitê gestor emitiu parecer favorável.","E) Há dotação orçamentária prévia para o projeto de infraestrutura."], resposta_correta:2, explicacao:"Estrutura formal: P1: A <-> P; P2: P -> D; P3: ~D v C; P4: ~C. Passo 1: Silogismo Disjuntivo entre P3 (~D v C) e P4 (~C) resulta em ~D. Passo 2: Modus Tollens entre P2 (P -> D) e ~D resulta em ~P. Passo 3: Como P1 é uma bicondicional (A <-> P), ela implica (A -> P) e (P -> A). Aplicando Modus Tollens em (A -> P) com ~P, obtemos ~A (o projeto de infraestrutura não foi aprovado). Distratores: A, B e E contradizem ~A, ~P e ~D; D é falsa pois o antecedente (~A) é V e o consequente (C) é F.", status:0, historico:0 },
{id:3077, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Durante a depuração de um erro de compilação, o analista formulou as premissas: P1: Se a biblioteca gráfica está ausente, então o compilador emite erro de dependência. P2: Se o compilador não emite erro de dependência, então a variável de ambiente está configurada e o arquivo binário é gerado. P3: O arquivo binário não foi gerado. A conclusão validamente deduzida dessas premissas é:", imagem:null, alternativas:["A) A biblioteca gráfica está ausente.","B) A variável de ambiente não está configurada.","C) O compilador emitiu erro de dependência.","D) A biblioteca gráfica não está ausente e o compilador emitiu erro de dependência.","E) Se o compilador emitiu erro de dependência, então a biblioteca gráfica está ausente."], resposta_correta:2, explicacao:"Estrutura formal: P1: B -> E; P2: ~E -> (V ^ A); P3: ~A. Passo 1: De P3 (~A), por adição temos (~V v ~A), que por De Morgan equivale a ~(V ^ A). Passo 2: Aplicando Modus Tollens em P2 com ~(V ^ A), obtemos ~(~E), que por Dupla Negação resulta em E (o compilador emitiu erro de dependência). Atenção à armadilha no distrator A: tendo E verdadeiro na premissa P1 (B -> E), NÃO se pode concluir B, pois isso seria a falácia da afirmação do consequente! Logo, apenas E é garantido.", status:0, historico:0 },
{id:3078, categoria:"Conhecimentos Específicos", materia:"Vigilância Sanitária", assunto:"Política Nacional de Resíduos Sólidos", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"Os princípios básicos para o uso seguro e descarte adequado dos materiais pérfuro-cortantes, como descarte de agulhas em campanhas de vacinação antirrábica fora das unidades de saúde, alguns cuidados o vacinador deve ter. Marque a opção INCORRETA.", imagem:null, alternativas:["A) As agulhas devem ser reencapadas após vacinação.","B) As agulhas usadas devem ser descartadas nos coletores de pérfuro-cortantes, no local de uso.","C) Agulhas não devem ser veiculadas diretamente de uma mão para outra e sua manipulação deve ser mínima.","D) As agulhas não devem ser entortadas ou quebradas após o uso.","E) As agulhas não devem ser desconectadas da seringa após o uso."], resposta_correta:0, explicacao:"A alternativa A está correta, pois traz um absurdo em biossegurança (e atende ao pedido de incorreta). A Norma Regulamentadora 32 (NR-32) PROÍBE rigorosamente o reencape manual de agulhas após o uso. Essa prática arcaica é a maior causadora de acidentes ocupacionais de perfuração nos dedos de profissionais de saúde, transmitindo HIV e Hepatites. A seringa com a agulha exposta deve ser descartada imediatamente na caixa coletora amarela rígida (Descarpack).", status:0, historico:0 },
{id:3079, categoria:"Conhecimentos Específicos", materia:"Saúde Pública", assunto:"Vigilância em Saúde", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"A Vigilância em saúde na Atenção Básica consiste em um conjunto de ações no âmbito individual e coletivo e em seu conceito inclui:Marque a opção INCORRETA.", imagem:null, alternativas:["A) Somente a vigilância e controle das doenças transmissíveis.","B) Vigilância das doenças e agravos não transmissíveis.","C) Vigilância da situação de saúde.","D) Vigilância ambiental em saúde e vigilância sanitária.","E) Vigilância da saúde do trabalhador."], resposta_correta:0, explicacao:"A alternativa A é a INCORRETA e, portanto, o gabarito. O erro encontra-se na palavra restritiva 'Somente'. O conceito moderno de Vigilância em Saúde é abrangente e sistêmico; ele não foca apenas nas doenças contagiosas ou virais (transmissíveis). Ele engloba a prevenção de Doenças e Agravos Não Transmissíveis (DANT - como obesidade e diabetes), acidentes de trabalho, riscos ambientais e fiscalização de alimentos (Vigilância Sanitária), conforme elencado nas opções B, C, D e E.", status:0, historico:0 },
{id:3080, categoria:"Conhecimentos Específicos", materia:"Saúde Pública", assunto:"Legislação do SUS", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"A Lei que “Dispõe sobre as condições para a promoção, proteção e recuperação da saúde, a organização e o funcionamento dos serviços correspondentes e dá outras providências”.", imagem:null, alternativas:["A) Lei 8.080/90.","B) Lei Orgânica da Saúde.","C) Lei 8.142/90.","D) Lei 8.746/90.","E) Lei 9.782/99"], resposta_correta:0, explicacao:"A alternativa A está correta. A ementa transcrita no enunciado é o texto oficial e exato que abre a histórica Lei Federal nº 8.080, de 19 de setembro de 1990. Ela é a principal lei que regulamenta todo o funcionamento e a organização do Sistema Único de Saúde (SUS) no Brasil. (Nota:Embora a opção B cite 'Lei Orgânica da Saúde', que é seu apelido, em questões de concurso prioriza-se a identificação numérica do diploma legal quando ambos estão presentes).", status:0, historico:0 },
{id:3081, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Considere o argumento a seguir sobre a segurança de aplicações web da universidade: Todo formulário desprotegido contra injeção de código é vulnerável a vazamento de dados; todo sistema vulnerável a vazamento de dados viola a política de conformidade; alguns módulos legados não violam a política de conformidade; logo, alguns módulos legados não são formulários desprotegidos contra injeção de código. A respeito da estrutura lógica desse argumento, é correto afirmar que:", imagem:null, alternativas:["A) O argumento é inválido, pois parte de duas premissas universais afirmativas para uma conclusão particular negativa.","B) O argumento é válido, podendo ser demonstrado por transitividade universal seguida de instanciação existencial e Modus Tollens.","C) O argumento é inválido, pois comete a falácia da afirmação do consequente na relação entre os módulos legados e a política de conformidade.","D) O argumento só seria válido se a terceira premissa afirmasse que nenhum módulo legado viola a política de conformidade.","E) O argumento é válido, e permite concluir adicionalmente que nenhum módulo legado é vulnerável a vazamento de dados."], resposta_correta:1, explicacao:"Formalização: P1: Para todo x (F(x) -> V(x)); P2: Para todo x (V(x) -> P(x)); P3: Existe x (L(x) ^ ~P(x)); Conclusão: Existe x (L(x) ^ ~F(x)). Demonstração: De P1 e P2, para todo x (F(x) -> P(x)). Pela instanciação existencial de P3 em uma constante 'a', temos L(a) e ~P(a). Instanciando a universal para 'a': F(a) -> P(a). Por Modus Tollens com ~P(a), obtemos ~F(a). Conjunção: L(a) ^ ~F(a). Generalização existencial: Existe x (L(x) ^ ~F(x)). O argumento é perfeitamente válido (Silogismo Baroco encadeado). Distrator E falha ao tentar generalizar uma premissa particular.", status:0, historico:0 },
{id:3082, categoria:"Conhecimentos Específicos", materia:"Saúde Pública", assunto:"Saúde do Trabalhador", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"Sobre acidentes de trabalho com exposição a material biológico e quanto ao tipo de exposição, temos as exposições ocupacionais descritas a seguir. Marque a opção CORRETA.\nI.Exposições percutâneas – lesões provocadas por instrumentos perfurantes e/ou cortantes (agulhas, bisturis, vidrarias, por exemplo).\nII. Exposições em mucosas – respingos em olhos, nariz, boca e genitália.\nIII. Exposições em pele não íntegra. Por exemplo:contato com pele com dermatite, feridas abertas, mordeduras humanas consideradas, como exposição de risco, quando envolverem a presença de sangue.\nIV. Em qualquer exposição (I, II e III), nos casos envolvidos, tanto o indivíduo que provocou a lesão quanto o lesionado, devem ser avaliados.\nV. Em qualquer exposição (I, II e III), somente o indivíduo que foi lesionado deve ser avaliado.", imagem:null, alternativas:["A) As afirmativas II e V estão corretas.","B) As afirmativas I e V estão corretas.","C) As afirmativas I, II, III e V estão corretas.","D) As afirmativas I, II, III e IV estão corretas.","E) As afirmativas I e IV estão corretas"], resposta_correta:3, explicacao:"A alternativa D está correta. As diretrizes do Ministério da Saúde classificam as vias de contaminação biológica em percutânea (pele perfurada), mucosas e pele não íntegra (cortes prévios). Em um cenário de acidente com sangue, a conduta imperativa é testar clinicamente AMBAS as partes:o profissional ferido (lesionado) para profilaxia, e o paciente/indivíduo matriz do material perfurocortante (para rastrear sorologia de HIV/Hepatites). Isso invalida automaticamente a afirmativa V, tornando corretas I, II, III e IV.", status:0, historico:0 },
{id:3083, categoria:"Conhecimentos Específicos", materia:"Vigilância Epidemiológica", assunto:"Esquistossomose", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"A esquistossomose é uma doença de preocupação da vigilância epidemiológica nos casos investigados e confirmados, nas formas graves, deve ser notificada no SINAN-NET. Marque a opção CORRETA sobre a doença.\nI. A esquistossomose é transmitida por caramujos e a fonte de infecção é o homem.\nII. Na fase crônica da doença pode ocorrer a evolução para diversas formas clínicas:intestinal, hepatointestinal e hepatoesplênica.\nIII. Na forma hepatoesplênica descompensada, há comprometimento renal em 10 a 15% dos doentes.", imagem:null, alternativas:["A) As afirmativas I e II estão corretas.","B) As afirmativas I e III estão corretas.","C) As afirmativas II e III estão corretas.","D) Somente a afirmativa I esta correta.","E) Todas as afirmativas estão corretas"], resposta_correta:4, explicacao:"A alternativa E está correta. A esquistossomose (barriga d'água) depende biologicamente do ser humano (que atua como fonte de infecção liberando ovos nas fezes em mananciais) e do caramujo planorbídeo (que atua como hospedeiro intermediário no ciclo aquático). As afirmativas II e III estão plenamente validadas na literatura médica:a fase crônica da infecção é sistêmica e atinge gravemente o fígado, baço, e em casos severos induz complicações associadas ao aparelho renal (glomerulopatia).", status:0, historico:0 },
{id:3084, categoria:"Conhecimentos Específicos", materia:"Saúde Pública", assunto:"Vigilância em Saúde", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"Quanto ao processo saúde-doença e a intervenção sanitária, temos algumas abaixo relacionadas. Marque a opção CORRETA.\nI. Atividades de Malacologia, para reduzir a população de caramujo.\nII. Carro fumacê para controle do ovo do mosquito.\nIII. Imunização para todas as doenças sexualmente transmissíveis.\nIV. Eutanázia dos animais saudáveis nos centros de zoonose.", imagem:null, alternativas:["A) A afirmativa I está relacionada à esquistossomose e é a única correta.","B) As afirmativas I, III e IV estão corretas.","C) As afirmativas I e III estão incorretas.","D) Somente a afirmativa III está correta.","E) Todas as afirmativas estão incorretas."], resposta_correta:0, explicacao:"A alternativa A está correta. A Malacologia é o ramo da zoologia que estuda os moluscos, logo, o controle da proliferação de caramujos (hospedeiros da Esquistossomose) se insere nessa atividade. As demais opções são aberrações técnicas:II - O carro UBV (fumacê) lança nuvens inseticidas que atacam unicamente o mosquito na fase alada/adulta (respiratória), e nunca os ovos submersos. III - Não existe imunologia disponível para todas as DSTs (ex:sífilis não tem vacina). IV - Zoonoses não praticam eutanásia deliberada em animais perfeitamente saudáveis.", status:0, historico:0 },
{id:3085, categoria:"Conhecimentos Específicos", materia:"Saúde Pública", assunto:"Legislação do SUS", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"A Constituição Brasileira de 1988 – Título VIII, em seu Capítulo II - Da Seguridade Social em sua Seção II - Da Saúde e Art. 198. Afirma que as ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, organizado de acordo com as seguintes diretrizes. Marque a opção CORRETA.\nI - Centralização, com direção única em cada esfera de governo.\nII - Atendimento integral, com prioridade para as atividades preventivas, sem prejuízo dos serviços assistenciais.\nIII - Participação da comunidade.", imagem:null, alternativas:["A) Somente a afirmativa I está correta.","B) Somente a afirmativa II está correta.","C) Somente a afirmativa III está correta.","D) Somente a afirmativa I está incorreta.","E) Todas as afirmativas estão corretas."], resposta_correta:3, explicacao:"A alternativa D está correta. A engenharia da questão foca nas 3 diretrizes matrizes esculpidas no Artigo 198 da Constituição Federal que regem o SUS. As afirmações II e III são cópias literais dos incisos da carta magna. O erro grosseiro mora na afirmação I:a diretriz constitucional orgânica do SUS é fundamentada na sua imediata 'DESCENTRALIZAÇÃO' (fortalecendo o município na ponta) com direção única, jamais defendendo políticas de 'Centralização'. Logo, somente o item I é falso/incorreto.", status:0, historico:0 },
{id:3086, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Um analista de redes precisa validar uma regra de firewall. Ele sabe que as seguintes premissas são verdadeiras: P1: Se a porta 22 está aberta, então o serviço SSH está rodando ou há um túnel reverso ativo. P2: Se o serviço SSH está rodando, a autenticação por chave pública é exigida. P3: Se há um túnel reverso ativo, o sistema de alerta dispara. P4: A autenticação por chave pública não é exigida e o sistema de alerta não disparou. Deduz-se validamente dessas premissas que:", imagem:null, alternativas:["A) A porta 22 está aberta, mas o serviço SSH está parado.","B) Há um túnel reverso ativo na porta 22.","C) A porta 22 não está aberta.","D) O serviço SSH está rodando sem autenticação por chave pública.","E) Se a porta 22 não está aberta, então o sistema de alerta disparou."], resposta_correta:2, explicacao:"Estrutura formal: P1: P -> (S v T); P2: S -> A; P3: T -> D; P4: ~A ^ ~D. Passo 1: De P4 temos ~A e ~D. Passo 2: Modus Tollens em P2 com ~A gera ~S. Modus Tollens em P3 com ~D gera ~T. Passo 3: Por conjunção, temos (~S ^ ~T), que por De Morgan equivale a ~(S v T). Passo 4: Aplicando Modus Tollens em P1 com ~(S v T), conclui-se necessariamente ~P (a porta 22 não está aberta). Distratores: A, B e D contradizem as deduções ~P, ~T e ~S; E cria implicação falsa.", status:0, historico:0 },
{id:3087, categoria:"Conhecimentos Gerais", materia:"Administração Geral", assunto:"Relações organizacionais", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"Dentre os valores abaixo:\nI. Confiança – É a aceitação da manifestação do outro, por palavras ou gestos.\nII. Disciplina – É a forma pela qual os membros de uma equipe aceitam e atendem às normas pré-estabelecidas, necessárias ao bom atendimento dos objetivos.\nIII. Responsabilidade – É o ato de responder pelas ações próprias ou dos outros.\nEstão corretas as definições:", imagem:null, alternativas:["A) I.","B) I e II.","C) I, II e III.","D) II e III.","E) I e III."], resposta_correta:2, explicacao:"A alternativa C está correta. No escopo da ética profissional e relações humanas no trabalho, todas as definições estão alinhadas com seus conceitos basilares. A Confiança exige a aceitação mútua e boa-fé perante o próximo (I); a Disciplina é a subordinação voluntária a um conjunto de regras visando um bem maior (II); e a Responsabilidade consiste em arcar civil e moralmente pelas próprias escolhas, omissões e tarefas delegadas (III).", status:0, historico:0 },
{id:3088, categoria:"Conhecimentos Gerais", materia:"Administração Geral", assunto:"Gestão de Pessoas", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"“Feedback”, traduzindo do inglês, significa “realimentar”. O feedback é uma poderosa ferramenta para orientar funcionários de uma organização a dar respostas ao trabalho que eles vêm exercendo.\nSobre o tema, avalie as assertivas:\nI – O feedback positivo exalta um comportamento bom, a resolução eficaz de problemas, um bom andamento da atividades desenvolvidas.\nII – O feedback negativo é desnecessário, pois evidencia os pontos que precisamos melhorar como um comportamento inadequado ou algo que afeta nosso lado profissional.\nIII – Dar feedback aos funcionários de uma organização é muito importante, pois ajuda a construir uma relação de confiança, além de promover mudanças e ajudar no desenvolvimento da empresa.", imagem:null, alternativas:["A) I.","B) I e III.","C) II e III.","D) I e II.","E) I, II e III."], resposta_correta:1, explicacao:"A alternativa B está correta. A ferramenta de Feedback é essencial na gestão de desempenho. O erro da assertiva II está na palavra 'desnecessário'. O feedback negativo (mais modernamente tratado como 'feedback construtivo') é de suma importância e totalmente NECESSÁRIO para o alinhamento corporativo, pois é através da sinalização das falhas que o profissional ganha a chance de corrigir atitudes prejudiciais e evoluir na carreira. As afirmações I e III retratam perfeitamente os benefícios da ferramenta.", status:0, historico:0 },
{id:3089, categoria:"Conhecimentos Específicos", materia:"Saúde Pública", assunto:"Legislação do SUS", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"O Sistema Único de Saúde (SUS) se baseia em alguns preceitos constitucionais, norteando-se por alguns princípios e diretrizes, que estão corretamente descritos abaixo. EXCETO:", imagem:null, alternativas:["A) Universalidade de acesso aos serviços de saúde em todos os níveis de assistência.","B) Integralidade de assistência, entendida como conjunto articulado e contínuo das ações e serviços preventivos e curativos, individuais e coletivos, exigidos para cada caso em todos os níveis de complexidade do sistema.","C) Centralização político-administrativa, com direção única em cada esfera de governo.","D) Igualdade da assistência à saúde, sem preconceitos ou privilégios de qualquer espécie.","E) Participação da comunidade."], resposta_correta:2, explicacao:"A alternativa C está correta, por apresentar o conceito falso solicitado (EXCETO). Um dos maiores e mais importantes marcos do Sistema Único de Saúde brasileiro (constante no art. 198 da CF e no art. 7º da Lei 8080) é a 'DESCENTRALIZAÇÃO político-administrativa', que transferiu a responsabilidade direta das ações de saúde para os municípios, e não a 'Centralização'. Os demais princípios (Universalidade, Integralidade, Igualdade e Participação) estão perfeitos.", status:0, historico:0 },
{id:3090, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Na verificação formal de um algoritmo de controle de concorrência, um conjunto de requisitos foi modelado pelas proposições P1, P2 e P3: P1: A thread adquire o lock ou entra em estado de espera. P2: Se a thread adquire o lock, então o recurso compartilhado é bloqueado. P3: O recurso compartilhado não é bloqueado e a thread não entra em estado de espera. A respeito do conjunto formado pelas premissas P1, P2 e P3, é correto afirmar que:", imagem:null, alternativas:["A) O conjunto de premissas é consistente e permite apenas concluir que a thread adquiriu o lock.","B) O conjunto de premissas é inconsistente, pois não existe valoração lógica que torne todas as premissas simultaneamente verdadeiras.","C) O conjunto de premissas é contingente e exige uma quarta premissa para permitir qualquer dedução válida.","D) A partir dessas premissas, é inválido deduzir qualquer proposição, pois a tabela-verdade apresenta apenas valores falsos na última coluna.","E) O conjunto de premissas comprova que o recurso compartilhado foi bloqueado por outra thread."], resposta_correta:1, explicacao:"Análise de consistência: De P3 (~B ^ ~E), simplificamos ~B e ~E. De P1 (L v E) com ~E, por Silogismo Disjuntivo, obtemos L. De P2 (L -> B) com ~B, por Modus Tollens, obtemos ~L. Temos simultaneamente L e ~L (contradição). Um conjunto de premissas que deriva uma contradição (não podem ser simultaneamente verdadeiras em nenhuma linha da tabela-verdade) é formalmente definido como inconsistente. Distrator D é falso pois de premissas inconsistentes (contradição no antecedente), qualquer conclusão torna o condicional tautológico (princípio da explosão).", status:0, historico:0 },
{id:3091, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Considere as seguintes premissas sobre o ambiente de virtualização: P1: Ou o hipervisor utiliza alocação dinâmica de memória ou utiliza memória estática reservada (disjunção exclusiva). P2: Se o hipervisor utiliza memória estática reservada, então o tempo de resposta de leitura é previsível. P3: O tempo de resposta de leitura não é previsível. Conclui-se validamente que:", imagem:null, alternativas:["A) O hipervisor utiliza memória estática reservada e não utiliza alocação dinâmica.","B) O hipervisor não utiliza alocação dinâmica de memória nem memória estática reservada.","C) O hipervisor utiliza alocação dinâmica de memória.","D) Se o hipervisor utiliza alocação dinâmica de memória, então o tempo de resposta de leitura é previsível.","E) O tempo de resposta de leitura é previsível se, e somente se, o hipervisor utiliza alocação dinâmica."], resposta_correta:2, explicacao:"Estrutura formal: P1: D xor E; P2: E -> T; P3: ~T. Passo 1: Aplicando Modus Tollens entre P2 e P3, obtemos ~E (não utiliza memória estática reservada). Passo 2: Como P1 é uma disjunção exclusiva (D xor E), exatamente uma das proposições é verdadeira. Sendo E falsa (~E), conclui-se obrigatoriamente que D é verdadeira: o hipervisor utiliza alocação dinâmica de memória. Distratores: A afirma E; B viola a disjunção exclusiva ao negar ambas; D e E criam relações não dedutíveis.", status:0, historico:0 },
{id:3092, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Em um sistema de detecção de anomalias, foram estabelecidas as premissas: P1: Se o tráfego de saída excede o limite padrão, então, se o usuário não possui credencial de administrador, a sessão é encerrada. P2: A sessão não foi encerrada. P3: O tráfego de saída excedeu o limite padrão. A conclusão logicamente válida derivada desse argumento é:", imagem:null, alternativas:["A) O usuário não possui credencial de administrador.","B) O usuário possui credencial de administrador.","C) O tráfego de saída não excedeu o limite padrão.","D) A sessão foi encerrada manualmente pelo operador.","E) O usuário possui credencial de administrador somente se a sessão for encerrada."], resposta_correta:1, explicacao:"Estrutura formal: P1: T -> (~A -> S); P2: ~S; P3: T. Passo 1: Aplicando Modus Ponens entre P1 e P3 (T), obtemos a condicional (~A -> S). Passo 2: Aplicando Modus Tollens entre (~A -> S) e P2 (~S), obtemos ~(~A). Passo 3: Pela regra da Dupla Negação, ~(~A) equivale a A: o usuário possui credencial de administrador. Distratores: A esquece de aplicar a dupla negação; C contradiz P3; D contradiz P2; E introduz condicional inválida.", status:0, historico:0 },
{id:3093, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Avalie as seguintes deduções formais na lógica proposicional e de predicados e classifique cada item em verdadeiro (V) ou falso (F): ( ) Das premissas (P -> Q) e (R -> ~Q), deduz-se validamente (P -> ~R). ( ) Das premissas Todo A é B e Algum B é C, deduz-se validamente que Algum A é C. ( ) Das premissas (P v Q) e (~P -> R), deduz-se validamente (Q -> R). ( ) Das premissas (P -> Q) e (P -> ~Q), deduz-se validamente ~P. A sequência correta, de cima para baixo, é:", imagem:null, alternativas:["A) V - F - F - V.","B) V - V - F - F.","C) F - F - V - V.","D) V - F - V - F.","E) F - V - F - V."], resposta_correta:0, explicacao:"Análise técnica: 1ª (V): Pela contrapositiva de (R -> ~Q), temos (Q -> ~R). Por Silogismo Hipotético entre (P -> Q) e (Q -> ~R), deduz-se (P -> ~R). 2ª (F): Falácia do termo médio não distribuído; o subconjunto de B que intercepta C pode ser totalmente disjunto do subconjunto A dentro de B. 3ª (F): (P v Q) equivale a (~P -> Q); de (~P -> Q) e (~P -> R) não se deduz (Q -> R). 4ª (V): Lei da Refutação por Absurdo: [(P -> Q) ^ (P -> ~Q)] <=> ~P (se P fosse V, Q seria V e F simultaneamente). Sequência: V - F - F - V.", status:0, historico:0 },
{id:3094, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"A Emenda Constitucional nº 19/1998 e a Emenda Constitucional nº 42/2003 inseriram no texto constitucional dispositivos que dialogam diretamente com os princípios da eficiência, da economicidade e da supremacia do interesse público na gestão fiscal e orçamentária. Com base nas disposições expressas dos artigos 37 e 39 da Constituição Federal, analise as proposições a seguir: I. A administração fazendária e seus servidores fiscais terão, dentro de suas áreas de competência e jurisdição, precedência sobre os demais setores administrativos, na forma da lei. II. As administrações tributárias da União, dos Estados, do Distrito Federal e dos Municípios, atividades essenciais ao funcionamento do Estado, exercidas por servidores de carreiras específicas, terão recursos prioritários para a realização de suas atividades e atuarão de forma integrada, inclusive com o compartilhamento de cadastros e de informações fiscais, na forma da lei ou convênio. III. Lei da União, dos Estados, do Distrito Federal e dos Municípios disciplinará a aplicação de recursos orçamentários provenientes da economia com despesas correntes em cada órgão, autarquia e fundação, para aplicação no desenvolvimento de programas de qualidade e produtividade, treinamento e desenvolvimento, modernização, reaparelhamento e racionalização do serviço público, sendo vedado o pagamento sob a forma de adicional ou prêmio de produtividade. Está correto o que se afirma em:", imagem:null, alternativas:["A) I e II, apenas.", "B) II e III, apenas.", "C) I e III, apenas.", "D) I, apenas.", "E) I, II e III."], resposta_correta:0, explicacao:"A alternativa A está correta. Fundamentação: O item I está correto, reproduzindo literalmente o art. 37, inciso XVIII, da CF/88. O item II está correto, reproduzindo literalmente o art. 37, inciso XXII, da CF/88 (de grande relevância para a área de TI devido ao compartilhamento de cadastros e informações fiscais). Análise das incorretas: O item III é falso no fragmento final 'sendo vedado o pagamento sob a forma de adicional ou prêmio de produtividade', pois o art. 39, § 7º, da CF/88 dispõe expressamente que tais recursos serão aplicados na modernização e racionalização do serviço público, 'inclusive sob a forma de adicional ou prêmio de produtividade'. Comentário Avalia: A banca Avalia tem o hábito de transcrever literalmente dispositivos constitucionais extensos (como o art. 39, § 7º) e trocar a palavra 'inclusive' por 'vedado' ou 'exceto' no trecho final.", status:0, historico:0},
{id:3095, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"No plano da governança pública federal (Decreto nº 9.203/2017) e da atuação administrativa cotidiana na UFBA, os princípios constitucionais expressos e implícitos desdobram-se em diretrizes práticas de tomada de decisão, prestação de contas (accountability) e integridade. Relacione as situações práticas descritas na primeira coluna com o princípio da Administração Pública preponderantemente aplicável na segunda coluna e, em seguida, assinale a alternativa que apresenta a correspondência correta: 1. O Comitê de Governança Digital da universidade publica em formato de dados abertos e legíveis por máquina os relatórios de execução do Plano Diretor de Tecnologia da Informação (PDTI), sem qualquer menção elogiosa ou autopromoção dos gestores responsáveis pelas entregas. 2. A Administração Universitária, ao constatar de ofício que um ato de concessão de gratificação de tecnologia foi editado com erro de cálculo e sem amparo legal há seis meses, instaura processo administrativo para invalidá-lo, assegurando a manifestação prévia do servidor. 3. Na elaboração do termo de referência para aquisição de computadores, o Analista de TI estabelece exigências de qualificação técnica estritamente indispensáveis à garantia do cumprimento das obrigações, abstendo-se de impor restrições excessivas ou desnecessárias ao caráter competitivo. ( ) Princípios da Razoabilidade e da Proporcionalidade. ( ) Princípio da Autotutela Administrativa. ( ) Princípios da Publicidade e da Impessoalidade. A sequência numérica correta, de cima para baixo, é:", imagem:null, alternativas:["A) 1 - 2 - 3.", "B) 3 - 2 - 1.", "C) 2 - 3 - 1.", "D) 3 - 1 - 2.", "E) 2 - 1 - 3."], resposta_correta:1, explicacao:"A alternativa B está correta (3 - 2 - 1). Fundamentação: O primeiro parêntese (Razoabilidade e Proporcionalidade) corresponde ao item 3, que trata da adequação entre meios e fins e da proibição do excesso nas exigências de qualificação técnica em licitações (art. 37, XXI, da CF/88 e art. 2º, parágrafo único, VI, da Lei 9.784/99). O segundo parêntese (Autotutela Administrativa) corresponde ao item 2, em que a própria Administração revê e anula de ofício seus atos ilegais dentro do prazo decadencial, respeitado o contraditório (Súmula 473 do STF e art. 53 da Lei 9.784/99). O terceiro parêntese (Publicidade e Impessoalidade) corresponde ao item 1, que conjuga a transparência ativa em dados abertos (publicidade) com a vedação à promoção pessoal de autoridades ou servidores (impessoalidade, art. 37, § 1º, da CF/88). Análise das incorretas: As alternativas A, C, D e E invertem a correlação lógica entre os casos práticos de TI e os respectivos princípios. Comentário Avalia: Questões de correlação de colunas ou associação de casos práticos são utilizadas pela banca para verificar a capacidade analítica de distinguir princípios correlatos.", status:0, historico:0},
{id:3096, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Na tentativa de contornar a rigidez do regime jurídico-administrativo — fenômeno doutrinariamente denominado fuga para o direito privado —, diversos entes públicos passaram a celebrar ajustes com fundações de apoio ou organizações sociais sem observar os limites constitucionais e legais. Considerando o entendimento do Tribunal de Contas da União (TCU) e a incidência dos princípios constitucionais da Administração Pública sobre o relacionamento entre universidades federais e entidades privadas de apoio, assinale a alternativa correta.", imagem:null, alternativas:["A) A celebração de contrato de gestão ou convênio com entidade privada sem fins lucrativos autoriza a universidade federal a intermediar a contratação de mão de obra terceirizada para o exercício de funções administrativas ordinárias e permanentes do quadro próprio da autarquia, dispensando o concurso público.", "B) Por ostentarem personalidade jurídica de direito privado, as fundações de apoio e as organizações sociais que gerenciam recursos financeiros oriundos do orçamento da União estão isentas do dever constitucional de prestar contas ao Tribunal de Contas da União.", "C) O princípio da eficiência administrativa justifica que fundações de apoio instituídas por servidores de universidades federais atuem como meras intermediárias na execução de atividades rotineiras da instituição, utilizando livremente bens móveis, laboratórios e servidores públicos sem ressarcimento ou previsão legal.", "D) A utilização desvirtuada de contratos de gestão ou ajustes congêneres como instrumento de contratação indireta de pessoal permanente sem processo seletivo impessoal e objetivo viola frontalmente os princípios constitucionais da legalidade, da impessoalidade, da moralidade e da publicidade.", "E) As entidades da Administração Indireta dotadas de personalidade jurídica de direito privado, tais como as empresas públicas e as sociedades de economia mista, não se submetem à regra constitucional do concurso público para a admissão de seus empregados celetistas."], resposta_correta:3, explicacao:"A alternativa D está correta. Fundamentação: Conforme a jurisprudência consolidada do TCU e a doutrina administrativa (Maria Sylvia Zanella Di Pietro / Celso Antônio Bandeira de Mello), a degeneração de contratos de gestão, termos de parceria ou convênios com fundações de apoio/organizações sociais para intermediar mão de obra permanente do órgão público configura burla ao princípio constitucional do concurso público (art. 37, II, da CF/88) e afronta os princípios da legalidade, impessoalidade, moralidade e publicidade. Análise das incorretas: A é inválida em 'autoriza a universidade federal a intermediar a contratação de mão de obra... para o exercício de funções administrativas ordinárias e permanentes' (trata-se de prática ilícita reiteradamente reprimida pelo TCU e pelo STF); B é inválida em 'estão isentas do dever constitucional de prestar contas ao Tribunal de Contas da União' (o art. 70, parágrafo único, da CF/88 obriga qualquer pessoa física ou jurídica, pública ou privada, que gerencie dinheiros, bens e valores públicos a prestar contas ao TCU); C é inválida em 'utilizando livremente bens móveis, laboratórios e servidores públicos sem ressarcimento ou previsão legal' (conduta vedada pela legislação de regência das IFES e pelo TCU); E é inválida em 'não se submetem à regra constitucional do concurso público' (o STF, desde o MS 21.322, pacificou que o art. 37, caput e II, da CF/88 obriga empresas públicas e sociedades de economia mista a realizarem concurso público). Comentário Avalia: Questão de alto nível ancorada na jurisprudência do TCU sobre 'fuga do regime publicístico' e uso indevido de entidades privadas de apoio.", status:0, historico:0},
{id:3097, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Durante a análise de logs de um cluster da UFBA, o analista estabeleceu as seguintes premissas verdadeiras: se o balanceador de carga falha, então a latência da rede aumenta; a latência da rede não aumentou. A partir dessas informações, conclui-se validamente que:", imagem:null, alternativas:["A) O balanceador de carga falhou, mas o sistema de contingência atuou.","B) Se a latência da rede aumentou, então o balanceador de carga falhou.","C) O balanceador de carga não falhou.","D) A latência da rede aumenta somente quando o balanceador de carga falha.","E) Não é possível determinar se o balanceador de carga falhou."], resposta_correta:2, explicacao:"Estrutura formal: P1: B -> L; P2: ~L. Aplicando a regra de inferência Modus Tollens (negação do consequente), deduz-se necessariamente ~B (o balanceador de carga não falhou). Distratores: A contradiz a dedução; B inverte a condicional (recíproca falaciosa); D introduz bicondicional não prevista; E ignora a validade formal do Modus Tollens.", status:0, historico:0 },
{id:3098, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Considere o seguinte argumento composto pelas premissas P1, P2 e P3: P1: Se o serviço de diretório está ativo, então a autenticação única funciona. P2: Se a autenticação única funciona, então o log de auditoria é gravado. P3: O serviço de diretório está ativo. Assinale a alternativa que apresenta uma conclusão que torna o argumento formalmente válido:", imagem:null, alternativas:["A) O log de auditoria não é gravado.","B) O log de auditoria é gravado.","C) A autenticação única funciona apenas se o log de auditoria for gravado.","D) Se o log de auditoria é gravado, então o serviço de diretório está ativo.","E) Ou o serviço de diretório está inativo ou o log de auditoria não é gravado."], resposta_correta:1, explicacao:"Estrutura formal: P1: D -> A; P2: A -> L; P3: D. Por Silogismo Hipotético entre P1 e P2, temos D -> L. Aplicando Modus Ponens com P3 (D), conclui-se validamente L (o log de auditoria é gravado). Distratores: A nega a conclusão válida; C e D invertem a direção da implicação (afirmação do consequente); E é a negação das premissas.", status:0, historico:0 },
{id:3099, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"No monitoramento da rede universitária, sabe-se que: ou o tráfego passa pelo firewall de borda ou é originado na sub-rede administrativa; verificou-se que o tráfego não é originado na sub-rede administrativa. Com base exclusiva nessas premissas, infere-se validamente que:", imagem:null, alternativas:["A) O tráfego não passa pelo firewall de borda.","B) Se o tráfego passa pelo firewall de borda, então é originado na sub-rede administrativa.","C) O tráfego passa pelo firewall de borda e é originado na sub-rede administrativa.","D) O tráfego passa pelo firewall de borda.","E) Nenhum tráfego da rede universitária passa pelo firewall de borda."], resposta_correta:3, explicacao:"Estrutura formal: P1: F v S; P2: ~S. Pela regra de inferência do Silogismo Disjuntivo, dada uma disjunção verdadeira e a negação de uma de suas componentes (~S), conclui-se necessariamente a veracidade da outra componente (F: o tráfego passa pelo firewall de borda). Distratores: A contradiz a inferência; B cria implicação inválida; C afirma conjunção falsa dado ~S; E generaliza indevidamente com quantificador universal negativo.", status:0, historico:0 },
{id:3100, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Sobre a natureza formal da validade de argumentos dedutivos na lógica proposicional, analise as proposições a seguir e classifique-as em verdadeiro (V) ou falso (F): ( ) Um argumento dedutivo é válido se, e somente se, a condicional que tem como antecedente a conjunção das premissas e como consequente a conclusão for uma tautologia. ( ) Se um argumento possui premissas verdadeiras e conclusão verdadeira, ele é obrigatoriamente válido, independentemente de sua forma lógica. ( ) A falácia da negação do antecedente ocorre quando, a partir de uma condicional e da negação de seu antecedente, conclui-se a negação de seu consequente. ( ) Um argumento válido nunca pode apresentar premissas falsas. A sequência correta de preenchimento dos parênteses, de cima para baixo, é:", imagem:null, alternativas:["A) V - F - V - F.","B) V - V - F - F.","C) F - F - V - V.","D) V - F - F - V.","E) F - V - V - F."], resposta_correta:0, explicacao:"Análise técnica: 1ª (V): Definição exata de validade via teorema da dedução ((P1 ^ P2 ^ ... ^ Pn) -> Q é tautologia). 2ª (F): A validade depende exclusivamente da forma lógica, não do valor de verdade factual isolado das proposições (ex: P->Q, Q |- P pode ter tudo V e é inválido). 3ª (V): P -> Q, ~P |- ~Q define exatamente a falácia da negação do antecedente. 4ª (F): Argumentos válidos podem ter premissas falsas; o que não pode ocorrer é premissas V e conclusão F. Sequência: V - F - V - F.", status:0, historico:0 },
{id:3101, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"No setor de banco de dados da UFBA, é verdade que todo script de migração homologado é versionado no repositório central, e que nenhum script executado sem revisão de código é versionado no repositório central. A partir dessas premissas categóricas, deduz-se logicamente que:", imagem:null, alternativas:["A) Algum script de migração homologado é executado sem revisão de código.","B) Todo script versionado no repositório central é um script de migração homologado.","C) Nenhum script de migração homologado é executado sem revisão de código.","D) Nenhum script versionado no repositório central possui revisão de código.","E) Todo script executado com revisão de código é um script de migração homologado."], resposta_correta:2, explicacao:"Estrutura em lógica de predicados/conjuntos: Conjunto H (homologados) está contido em V (versionados). Conjunto S (sem revisão) é disjunto de V (S interseção V = vazio). Como H está contido em V e V não intercepta S, conclui-se necessariamente que H não intercepta S: nenhum script de migração homologado é executado sem revisão de código (Silogismo Camestres/Cesare). Distratores: A contradiz a disjunção; B e E invertem a inclusão universal (conversão ilícita do quantificador Todo); D nega propriedade não contida nas premissas.", status:0, historico:0 },
{id:3102, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Um auditor de segurança analisou o seguinte argumento: se o pacote de rede contém assinatura maliciosa, então o sistema de prevenção de intrusão descarta o pacote; verificou-se que o sistema de prevenção de intrusão descartou o pacote; logo, o pacote de rede continha assinatura maliciosa. Sob o rigor da lógica formal, esse argumento é:", imagem:null, alternativas:["A) Válido, pois aplica corretamente a regra de inferência Modus Ponens.","B) Válido, pois a conclusão é uma decorrência necessária da afirmação do consequente.","C) Inválido, pois incorre na falácia formal da negação do antecedente.","D) Inválido, pois incorre na falácia formal da afirmação do consequente.","E) Válido, desde que o sistema de prevenção de intrusão esteja configurado sem falsos positivos."], resposta_correta:3, explicacao:"Estrutura formal: P1: M -> D; P2: D; Conclusão: M. Na condicional M -> D, M é suficiente para D, mas não necessária (o pacote poderia ser descartado por outro motivo, como excesso de banda). Afirmar o consequente (D) para deduzir o antecedente (M) constitui a clássica falácia da afirmação do consequente, tornando o argumento formalmente inválido. Distratores: A e B erram a validade; C confunde o nome da falácia; E confunde validade formal com informações externas ao argumento.", status:0, historico:0 },
{id:3103, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Considere as seguintes premissas sobre a arquitetura de microsserviços do portal acadêmico: P1: Se a API de matrículas sofre sobrecarga, então o contêiner escala horizontalmente. P2: Se o banco de dados trava, então o alerta crítico é emitido. P3: A API de matrículas sofre sobrecarga ou o banco de dados trava. A conclusão validamente derivada dessas premissas por meio de um dilema construtivo é:", imagem:null, alternativas:["A) O contêiner escala horizontalmente e o alerta crítico é emitido.","B) O contêiner escala horizontalmente ou o alerta crítico é emitido.","C) Se o contêiner escala horizontalmente, então o alerta crítico é emitido.","D) A API de matrículas não sofre sobrecarga e o banco de dados não trava.","E) Ou o contêiner não escala horizontalmente ou o alerta crítico não é emitido."], resposta_correta:1, explicacao:"Estrutura formal: P1: A -> C; P2: B -> E; P3: A v B. Pela regra de inferência do Dilema Construtivo [(A -> C) ^ (B -> E) ^ (A v B)] |- (C v E), como ao menos um dos antecedentes é verdadeiro, ao menos um dos consequentes deve ser verdadeiro: o contêiner escala horizontalmente ou o alerta crítico é emitido. Distratores: A troca a disjunção por conjunção indevida; C cria implicação inexistente entre os consequentes; D e E negam os termos sem base nas premissas.", status:0, historico:0 },
{id:3104, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Considere o sistema de premissas referente a um incidente na sala de cofres da STI: P1: Se o sensor térmico dispara ou a queda de tensão ocorre, então o nobreak assume a carga. P2: Se o nobreak assume a carga, então o gerador a diesel é acionado e a equipe de plantão recebe um chamado. P3: A equipe de plantão não recebeu um chamado. A partir da validade dedutiva desse conjunto de premissas, conclui-se necessariamente que:", imagem:null, alternativas:["A) O sensor térmico disparou, mas a queda de tensão não ocorreu.","B) O nobreak assumiu a carga, porém o gerador a diesel falhou.","C) O sensor térmico não disparou e a queda de tensão não ocorreu.","D) O sensor térmico não disparou ou a queda de tensão ocorreu.","E) Se o gerador a diesel foi acionado, então o sensor térmico disparou."], resposta_correta:2, explicacao:"Estrutura formal: P1: (S v Q) -> N; P2: N -> (G ^ C); P3: ~C. Passos dedutivos: 1) Como temos ~C, por adição/De Morgan temos ~G v ~C, que equivale a ~(G ^ C). 2) Aplicando Modus Tollens em P2 com ~(G ^ C), obtemos ~N. 3) Aplicando Modus Tollens em P1 com ~N, obtemos ~(S v Q). 4) Pela Lei de De Morgan em ~(S v Q), deduz-se ~S ^ ~Q (o sensor térmico não disparou e a queda de tensão não ocorreu). Distratores: A e B contradizem ~S e ~N; D erra a aplicação de De Morgan mantendo uma afirmativa; E inverte a cadeia condicional.", status:0, historico:0 },
{id:3105, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Em uma auditoria nos servidores Linux da universidade, constatou-se que: todo processo que consome memória excessiva é monitorado pelo daemon de controle; todo processo monitorado pelo daemon de controle possui registro de identificação; existem processos de usuário que não possuem registro de identificação. Com base nessas premissas, assinale a conclusão formalmente válida:", imagem:null, alternativas:["A) Nenhum processo de usuário consome memória excessiva.","B) Todo processo que possui registro de identificação consome memória excessiva.","C) Existem processos de usuário que não consomem memória excessiva.","D) Todo processo de usuário é monitorado pelo daemon de controle.","E) Algum processo que consome memória excessiva não é monitorado pelo daemon de controle."], resposta_correta:2, explicacao:"Estrutura em Lógica de Predicados: P1: Para todo x (M(x) -> D(x)); P2: Para todo x (D(x) -> R(x)); P3: Existe x (U(x) ^ ~R(x)). Por transitividade universal (P1 e P2), para todo x (M(x) -> R(x)). Instanciando o elemento 'a' de P3: U(a) ^ ~R(a). Como M(a) -> R(a) e temos ~R(a), por Modus Tollens obtemos ~M(a). Logo, U(a) ^ ~M(a), generalizando existencialmente: Existe x (U(x) ^ ~M(x)), ou seja, existem processos de usuário que não consomem memória excessiva. Distratores: A generaliza uma premissa particular (de 'algum' para 'nenhum'); B inverte a universal; D e E contradizem as premissas.", status:0, historico:0 },
{id:3106, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Um engenheiro de software avalia a validade do argumento composto pelas premissas: P1: Se o código passa nos testes unitários e na análise estática, então o pacote é implantado em produção. P2: O pacote não foi implantado em produção. P3: O código passou nos testes unitários. Para que o argumento seja dedutivamente válido, a conclusão deve ser:", imagem:null, alternativas:["A) O código passou na análise estática.","B) O código não passou na análise estática.","C) O código não passou nos testes unitários nem na análise estática.","D) Se o código não passou na análise estática, então não passou nos testes unitários.","E) O pacote foi implantado em ambiente de homologação."], resposta_correta:1, explicacao:"Estrutura formal: P1: (U ^ E) -> P; P2: ~P; P3: U. Passo 1: Modus Tollens entre P1 e P2 gera ~(U ^ E). Passo 2: Pela Lei de De Morgan, ~(U ^ E) equivale a ~U v ~E. Passo 3: Aplicando Silogismo Disjuntivo entre (~U v ~E) e P3 (U), conclui-se necessariamente ~E (o código não passou na análise estática). Distratores: A contradiz a dedução; C esquece de converter a conjunção em disjunção ao negar; D cria condicional falsa, pois U é verdadeiro; E extrapola o escopo formal das premissas.", status:0, historico:0 },
{id:3107, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Para provar a validade do argumento (P -> Q), (Q -> R) |- (P -> R) utilizando o método da prova condicional ou o método de refutação por redução ao absurdo (tableaux semântico), o analista deve compreender o conceito de consequência lógica. Analise as assertivas e classifique-as em verdadeiro (V) ou falso (F): ( ) Na prova por redução ao absurdo, adiciona-se a negação da conclusão ao conjunto de premissas e demonstra-se que esse novo conjunto leva a uma contradição. ( ) A negação da proposição condicional (P -> R) é logicamente equivalente à proposição (~P -> ~R). ( ) Se a conjunção das premissas com a negação da conclusão resultar em uma proposição satisfatível, então o argumento original é inválido. ( ) Pelo teorema da dedução, provar que P1, P2 |- (P -> R) equivale a provar que P1, P2, P |- R. Assinale a alternativa que apresenta a sequência correta:", imagem:null, alternativas:["A) V - V - F - V.","B) F - F - V - V.","C) V - F - V - F.","D) V - F - V - V.","E) F - V - F - V."], resposta_correta:3, explicacao:"Análise técnica: 1ª (V): Definição exata do método de redução ao absurdo (P1 ^ ... ^ Pn ^ ~Q é contradição). 2ª (F): A negação de (P -> R) é (P ^ ~R), e não (~P -> ~R), que seria a contrária. 3ª (V): Se (Premissas ^ ~Conclusão) é satisfatível, existe pelo menos uma interpretação onde as premissas são V e a conclusão é F, logo o argumento é inválido. 4ª (V): Enunciado exato do Teorema da Dedução (Prova Condicional). Sequência correta: V - F - V - V.", status:0, historico:0 },
{id:3108, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Considere as seguintes premissas sobre a topologia de servidores da universidade: P1: Se o servidor primário está em manutenção, então o servidor secundário assume o tráfego. P2: Se o servidor primário não está em manutenção, então a rotina de sincronização está ativa. P3: Se a rotina de sincronização está ativa, então o servidor secundário assume o tráfego. A partir dessas premissas, conclui-se de forma categoricamente válida que:", imagem:null, alternativas:["A) O servidor primário está em manutenção.","B) A rotina de sincronização não está ativa.","C) O servidor secundário assume o tráfego.","D) O servidor secundário não assume o tráfego.","E) O servidor primário está em manutenção se, e somente se, a rotina de sincronização está ativa."], resposta_correta:2, explicacao:"Estrutura formal: P1: M -> S; P2: ~M -> R; P3: R -> S. Passo 1: Por Silogismo Hipotético entre P2 e P3, temos ~M -> S. Passo 2: Combinando P1 (M -> S) e o resultado (~M -> S), aplica-se a Lei do Dilema (ou Silogismo de Alternância / Prova por Casos): como (M v ~M) é uma tautologia (Princípio do Terceiro Excluído), tanto M quanto ~M implicam S. Portanto, conclui-se incondicionalmente S (o servidor secundário assume o tráfego). Distratores: A e B assumem valores contingentes não garantidos; D nega a dedução; E cria bicondicional falsa.", status:0, historico:0 },
{id:3109, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Analise o conjunto de premissas de um diagnóstico de rede: P1: Se a fibra óptica rompeu, então o link principal caiu. P2: Se a configuração de BGP está incorreta, então as rotas externas somem. P3: O link principal não caiu e as rotas externas não sumiram. Com base na regra de inferência do dilema destrutivo e nas leis de equivalência, conclui-se validamente que:", imagem:null, alternativas:["A) A fibra óptica rompeu ou a configuração de BGP está incorreta.","B) A fibra óptica não rompeu e a configuração de BGP não está incorreta.","C) Se a fibra óptica não rompeu, então a configuração de BGP está incorreta.","D) A fibra óptica não rompeu, mas a configuração de BGP está incorreta.","E) O link principal caiu se, e somente se, as rotas externas sumiram."], resposta_correta:1, explicacao:"Estrutura formal: P1: F -> L; P2: B -> R; P3: ~L ^ ~R. Pela simplificação de P3, temos ~L e temos ~R. Aplicando Modus Tollens em P1 (F -> L com ~L), obtemos ~F. Aplicando Modus Tollens em P2 (B -> R com ~R), obtemos ~B. Por conjunção de ~F e ~B, deduz-se ~F ^ ~B (a fibra óptica não rompeu e a configuração de BGP não está incorreta). Distratores: A afirma as premissas negadas; C e D afirmam erro de BGP contradizendo ~B; E estabelece bicondicional sem amparo dedutivo.", status:0, historico:0 },
{id:3110, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"No gerenciamento de identidade do sistema acadêmico, sabe-se que: alguns usuários com perfil de coordenador possuem chave de assinatura digital; nenhum usuário temporário possui chave de assinatura digital; todos os bolsistas de iniciação são usuários temporários. Dessas premissas, infere-se validamente que:", imagem:null, alternativas:["A) Nenhum usuário com perfil de coordenador é bolsista de iniciação.","B) Todo usuário que possui chave de assinatura digital tem perfil de coordenador.","C) Algum bolsista de iniciação possui chave de assinatura digital.","D) Algum usuário com perfil de coordenador não é bolsista de iniciação.","E) Todo usuário com perfil de coordenador é usuário temporário."], resposta_correta:3, explicacao:"Análise de Conjuntos/Predicados: P1: Interseção entre Coordenadores (C) e Chave (K) não é vazia (existe x em C e K). P2: Temporários (T) e Chave (K) são disjuntos (T interseção K = vazio). P3: Bolsistas (B) está contido em Temporários (T). Como B está contido em T e T é disjunto de K, então B é disjunto de K (nenhum bolsista tem chave). Como existe pelo menos um elemento 'a' que está em C e está em K, esse elemento 'a' não pode estar em B. Logo, algum usuário com perfil de coordenador não é bolsista de iniciação. Distrator A é a armadilha clássica: generaliza para 'Nenhum coordenador', mas outros coordenadores (que não têm chave) poderiam formalmente pertencer a B.", status:0, historico:0 },
{id:3111, categoria:"Conhecimentos Básicos", materia:"Raciocínio Lógico", assunto:"Argumentos Lógicos", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Considere o argumento estruturado pelas seguintes premissas: P1: Se o pacote é criptografado, então, se a chave simétrica é válida, o payload é decodificado. P2: O pacote é criptografado e o payload não foi decodificado. Aplicando a lei da exportação-importação e as regras de inferência dedutiva, conclui-se validamente que:", imagem:null, alternativas:["A) A chave simétrica é válida.","B) A chave simétrica não é válida.","C) O pacote não é criptografado.","D) Se a chave simétrica não é válida, então o pacote não é criptografado.","E) O payload foi decodificado, mas gerou erro de integridade."], resposta_correta:1, explicacao:"Estrutura formal: P1: C -> (V -> D); P2: C ^ ~D. Pela Lei de Exportação-Importação, P1 equivale a (C ^ V) -> D. Por simplificação de P2, temos C e temos ~D. Aplicando Modus Tollens na forma importada [(C ^ V) -> D] com ~D, obtemos ~(C ^ V), que por De Morgan equivale a (~C v ~V). Como sabemos que C é verdadeiro (simplificação de P2), aplicamos o Silogismo Disjuntivo em (~C v ~V) com C, concluindo necessariamente ~V (a chave simétrica não é válida). Distratores: A contradiz ~V; C e E contradizem P2; D cria condicional sem suporte.", status:0, historico:0 },
//Criados pelo Gemini
{id:3112, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A expansão urbana desordenada no interior da Bahia tem gerado impactos diretos na saúde pública, alterando a dinâmica de doenças endêmicas. Sobre a relação entre meio ambiente, urbanização e arboviroses, analise as assertivas:I - A supressão de biomas originais, como a Caatinga e a Mata Atlântica, reduz os habitats de predadores naturais do Aedes aegypti, favorecendo a proliferação urbana do vetor. II - O processo de gentrificação em grandes centros sempre resulta na erradicação de focos de dengue nas periferias, devido ao deslocamento das populações vulneráveis para zonas rurais isoladas. III - O aquecimento global e as anomalias térmicas (como o El Niño) expandem geograficamente as áreas de risco para arboviroses, permitindo que os vetores sobrevivam em regiões antes inóspitas. IV - A Política Nacional de Resíduos Sólidos eliminou integralmente a incidência de leishmaniose visceral no Brasil ao erradicar os lixões a céu aberto até o ano de 2024. Assinale a sequência correta:", imagem:null, alternativas:["A) V, F, V, F.","B) V, V, F, F.","C) F, F, V, V.","D) V, F, F, V.","E) F, V, V, F."], resposta_correta:0, explicacao:"A alternativa A está correta. A INETE adora inserir falsas 'conquistas absolutas' em políticas públicas. O item II é falso porque a palavra 'sempre' invalida a premissa, além de a gentrificação agravar a vulnerabilidade nas franjas urbanas (periurbanização), e não erradicar focos. O item IV é falso, pois a erradicação dos lixões (prevista na Lei 12.305/10 e no Novo Marco do Saneamento) não foi concluída integralmente no Brasil, e a leishmaniose continua endêmica. Os itens I e III são perfeitos e refletem o consenso atual sobre determinantes socioambientais em saúde. Cuidado com termos como 'eliminou integralmente', é a típica armadilha da banca.", status:0, historico:0 },
{id:3113, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O financiamento do Sistema Único de Saúde (SUS) e a estruturação da Vigilância Epidemiológica são fundamentais para o combate a endemias nos municípios. Considerando a organização política e econômica brasileira atual, assinale a alternativa que descreve corretamente um desafio contemporâneo no combate às endemias locais:", imagem:null, alternativas:["A) A centralização irrestrita das ações de vigilância na esfera federal, retirando dos municípios a autonomia para planejar bloqueios epidemiológicos contra a dengue.","B) A aplicação do princípio da Igualdade, que obriga a União a repassar exatamente o mesmo montante de recursos financeiros para todos os municípios, independentemente de seus índices de infestação predial.","C) A dependência exclusiva de financiamento privado internacional para a aquisição de larvicidas e insumos estratégicos, gerida diretamente pelo Conselho Municipal de Saúde.","D) A limitação de investimentos públicos atrelada a regras fiscais restritivas, que exige dos municípios baianos maior eficiência na alocação de recursos próprios para garantir a continuidade dos programas de controle de vetores.","E) A total desvinculação entre as metas de saneamento básico e as verbas da saúde, comprovando que o controle do Aedes aegypti depende puramente de ações biomédicas individuais."], resposta_correta:3, explicacao:"A alternativa D está correta. A INETE explora muito a interpretação de cenário macroeconômico. A restrição fiscal (como as regras de teto de gastos ou arcabouço fiscal) afeta diretamente o orçamento da saúde, forçando os municípios a otimizarem recursos. A alternativa A erra na palavra 'centralização' (o SUS é descentralizado, a vigilância é função primordial do município). A alternativa B traz a 'pegadinha' clássica da banca:confundir 'Igualdade' com 'Equidade' (repassar o mesmo valor seria injusto para quem tem mais focos). A alternativa E ignora a transversalidade da saúde com o saneamento.", status:0, historico:0 },
{id:3114, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A implementação de inovações biotecnológicas, como o uso de mosquitos Aedes aegypti infectados com a bactéria Wolbachia, tem transformado o cenário do controle de arboviroses no Brasil. Sobre essa técnica e a resposta cultural da sociedade, é correto afirmar que:", imagem:null, alternativas:["A) Trata-se de uma modificação genética (transgenia) no DNA do mosquito, que o torna estéril e elimina a população local em até duas semanas, sendo amplamente aceita sem qualquer resistência da população rural.","B) A técnica consiste na introdução de uma bactéria que impede o desenvolvimento dos vírus da Dengue, Zika e Chikungunya dentro do inseto, enfrentando, contudo, barreiras culturais devidas à desinformação e fake news sobre os riscos à saúde humana.","C) O método substitui integralmente a necessidade da atuação in loco dos Agentes de Endemias, pois a liberação dos mosquitos é monitorada via satélite pelo Ministério do Meio Ambiente.","D) A Wolbachia é um inseticida químico de nova geração pulverizado apenas em áreas de proteção ambiental, criado para contornar a resistência genética dos mosquitos urbanos em cidades da Chapada Diamantina.","E) O sucesso absoluto do método no Brasil anulou a necessidade de campanhas de conscientização sobre descarte de resíduos sólidos nas periferias baianas a partir de 2025."], resposta_correta:1, explicacao:"A alternativa B está correta. Questão de altíssimo nível. A banca INETE adora cobrar as atualidades científicas aplicadas à saúde (Método Wolbachia) e o fenômeno sociológico das 'Fake News'. A alternativa A erra porque Wolbachia NÃO é modificação genética do mosquito, e sim uma bactéria natural inserida nele, além de afirmar erroneamente sobre a aceitação (há medo popular). A alternativa C comete o erro clássico de invalidar o trabalho do candidato (a banca nunca aprova uma alternativa que torna o cargo público obsoleto). A alternativa D é absurda (não é inseticida).", status:0, historico:0 },
{id:3115, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"No contexto das políticas públicas sociais brasileiras, a articulação intersetorial é vital. Analise a correlação entre os programas de transferência de renda e o controle de endemias:I - O repasse de benefícios assistenciais está frequentemente atrelado a condicionalidades de saúde, como o cumprimento do calendário vacinal, o que impacta positivamente o trabalho de base da vigilância em saúde. II - A vulnerabilidade social é um determinante secundário e irrelevante para a doença de Chagas, visto que a proliferação do barbeiro depende exclusivamente do clima semiárido, independente das condições de moradia (casas de taipa). III - A atuação do Agente de Endemias, ao identificar focos intra e peridomiciliares, fornece dados fundamentais para o Mapeamento de Risco e intervenções da Defesa Civil e Assistência Social. Assinale a alternativa que indica as proposições tecnicamente verdadeiras:", imagem:null, alternativas:["A) Apenas I.","B) Apenas II.","C) Apenas I e III.","D) Apenas II e III.","E) I, II e III."], resposta_correta:2, explicacao:"A alternativa C está correta. Aqui a INETE testa se você entende o conceito de 'Determinantes Sociais da Saúde'. O item II é flagrantemente falso, pois a vulnerabilidade social e as condições habitacionais (casas de pau a pique/taipa) são determinantes PRIMÁRIOS, sendo fatores essenciais para a colonização do inseto vetor da Doença de Chagas. O item I aborda as condicionalidades do Bolsa Família (corretíssimo). O item III destaca a intersetorialidade do trabalho do Agente, algo que a banca sempre valoriza positivamente.", status:0, historico:0 },
{id:3116, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Brasil tem vivenciado o fenômeno da 'Sindicemia' (sinergia entre pandemias/epidemias e condições socioeconômicas). Considerando a realidade sanitária dos municípios do interior baiano, assinale a alternativa que melhor ilustra um cenário sindêmico enfrentado pelo sistema público de saúde:", imagem:null, alternativas:["A) A redução isolada dos casos de febre amarela devido à vacinação em massa de primatas não humanos em reservas biológicas estritamente isoladas.","B) A interação biológica e social severa entre surtos concomitantes de Dengue e condições crônicas como a diabetes, agravada pela insegurança alimentar e precarização do saneamento nas periferias.","C) O aumento linear das verbas repassadas pelo Ministério da Saúde exclusivamente para a construção de hospitais de alta complexidade, em detrimento da atenção primária.","D) A substituição completa do perfil epidemiológico nacional, onde as doenças infectocontagiosas desapareceram, restando apenas o combate às doenças crônicas não transmissíveis.","E) A imunidade de rebanho alcançada organicamente pelas populações ribeirinhas baianas, o que bloqueou a transmissão da malária independentemente de fatores econômicos."], resposta_correta:1, explicacao:"A alternativa B está correta. A INETE gosta de cobrar conceitos modernos de saúde pública como 'Sindicemia' (termo cunhado pelo antropólogo médico Merrill Singer). Sindicemia não é apenas ter duas doenças ao mesmo tempo (isso é comorbidade), é quando as doenças interagem entre si E com as condições sociais adversas (pobreza, falta de saneamento), multiplicando a carga da doença. A alternativa D afirma absurdamente que doenças infectocontagiosas 'desapareceram' (transição epidemiológica no Brasil é incompleta/sobreposta).", status:0, historico:0 },
{id:3117, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Julgue as afirmativas sobre a dinâmica populacional e seus reflexos na saúde ambiental do Brasil, respondendo com Verdadeiro (V) ou Falso (F). I - O envelhecimento acelerado da população brasileira exige uma readequação das estratégias de vigilância em saúde, pois idosos apresentam maior taxa de letalidade e complicações diante de arboviroses. II - O êxodo rural contemporâneo baiano caracteriza-se pela volta massiva da população jovem para os grandes latifúndios, reduzindo a pressão demográfica e o adensamento nos bairros periféricos das capitais. III - A ocupação desordenada de encostas e áreas de preservação permanente (APPs) intensifica o risco de deslizamentos e cria microclimas favoráveis à procriação de vetores devido ao acúmulo de lixo. A sequência que responde estritamente à verdade factual sociológica é:", imagem:null, alternativas:["A) V, V, F.","B) F, V, V.","C) V, F, F.","D) V, F, V.","E) F, F, V."], resposta_correta:3, explicacao:"A alternativa D está correta. Item I:Verdadeiro, o envelhecimento demográfico altera o impacto das epidemias (idosos sofrem mais com dengue grave, por exemplo). Item II:Falso, o êxodo rural é a saída do campo para a cidade, e não o oposto (a afirmação descreve uma irreal 'volta massiva'). Item III:Verdadeiro, a favelização e ocupação de APPs formam o binômio tragédia climática + surtos endêmicos. A INETE usa inversões lógicas descabidas no meio de frases formais (item II) para testar a atenção de leitura.", status:0, historico:0 },
{id:3118, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A expansão da fronteira agrícola no bioma do Cerrado, que avança também sobre regiões da Bahia (Matopiba), tem gerado profundas alterações no equilíbrio ambiental. Do ponto de vista epidemiológico e das responsabilidades do município, essa alteração antrópica massiva:", imagem:null, alternativas:["A) esteriliza o solo, eliminando preventivamente todos os artrópodes vetores e reduzindo as demandas da vigilância sanitária local a zero.","B) provoca um desequilíbrio ecológico que facilita a aproximação de animais silvestres reservatórios de patógenos aos assentamentos humanos, favorecendo o surgimento de surtos de zoonoses como leishmaniose e febre amarela silvestre.","C) melhora exponencialmente a qualidade dos lençóis freáticos, garantindo abastecimento contínuo que impede o armazenamento domiciliar inadequado de água, o maior causador da malária.","D) afeta exclusivamente a flora nativa, não possuindo correlação científica comprovada com o perfil de morbimortalidade humana da região.","E) impõe a necessidade de pulverização aérea de agrotóxicos sobre centros urbanos para controlar os vetores fugidos da área de plantio, ação preconizada pelo SUS como primeira linha de defesa ambiental."], resposta_correta:1, explicacao:"A alternativa B está correta. Esta é uma questão clássica da INETE conectando geografia econômica (fronteira agrícola/Matopiba) com saúde (Zoonoses). O desmatamento expulsa a fauna silvestre de seu habitat, empurrando hospedeiros e vetores para o peridomicílio (como o mosquito palha e macacos). A alternativa C erra grosseiramente ao dizer que melhora lençóis freáticos (o agronegócio extensivo frequentemente os sobrecarrega ou contamina). A alternativa E inventa uma prática criminosa (pulverização urbana de agrotóxicos) como se fosse preconizada pelo SUS.", status:0, historico:0 },
{id:3119, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Agente de Combate às Endemias (ACE) realiza um papel educativo fundamental durante as visitas domiciliares. Ocorre que, frequentemente, ele se depara com a recusa de moradores em permitir a sua entrada. Sob a ótica da organização social, cultura e garantias jurídicas brasileiras em contextos epidemiológicos de risco iminente, é correto asseverar que:", imagem:null, alternativas:["A) O morador exerce seu direito absoluto e intocável à propriedade privada, sendo proibida qualquer ação do Estado, mesmo em situação de pandemia ou surto epidêmico decretado.","B) A resistência muitas vezes decorre de barreiras socioculturais e medo da criminalidade, devendo o agente acionar táticas de convencimento e mobilização comunitária, existindo, porém, amparo legal para o ingresso forçado em situações de risco à saúde pública iminente, respaldadas por autoridade sanitária local.","C) O agente de endemias deve invadir a residência de imediato, utilizando força física ou arrombamento, independentemente de notificação prévia ou mandato judicial, baseando-se no Princípio da Precaução ambiental.","D) A recusa do morador deve ser punida sumariamente pelo agente no ato da visita através de aplicação de multa tributária municipal diretamente no CPF do responsável.","E) A cultura do brasileiro favorece a delegação de limpeza intradomiciliar ao SUS, de modo que as recusas ocorrem apenas quando o agente se nega a realizar serviços braçais de limpeza doméstica para o proprietário."], resposta_correta:1, explicacao:"A alternativa B está correta. A INETE cobra o limite entre o direito individual (inviolabilidade do domicílio) e o coletivo (saúde pública). A lei federal 13.301/2016 permite o ingresso forçado em imóveis abandonados, ausência prolongada ou recusa injustificada em situação de iminente perigo (surtos), mas isso exige trâmites da autoridade sanitária, não força bruta imediata do agente (invalidando a C). A alternativa A usa a palavra 'absoluto' (nenhum direito é absoluto no Brasil frente ao risco coletivo).", status:0, historico:0 },
{id:3120, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Sobre a evolução histórica das políticas de saúde pública no Brasil, um cidadão idoso de Bonito relata ao agente que, na sua juventude, 'só quem tinha carteira assinada tinha direito a médico do governo'. Em relação aos Princípios Organizativos do SUS que romperam com esse modelo excludente do passado (INAMPS), julgue:I - O Princípio da Universalidade garantiu que a saúde passasse a ser um direito de todos e dever do Estado, extinguindo a necessidade de contribuição previdenciária prévia para o atendimento clínico. II - O Princípio da Descentralização transferiu as responsabilidades operacionais diretas de saúde primária da esfera municipal para a União, garantindo um controle único centralizado em Brasília. III - O Controle Social, materializado nos Conselhos e Conferências de Saúde, garante a participação popular na formulação das políticas, atuando como fiscalizador das verbas. Estão perfeitamente de acordo com o texto legal:", imagem:null, alternativas:["A) Apenas I e II.","B) Apenas II e III.","C) Apenas I.","D) Apenas I e III.","E) I, II e III."], resposta_correta:3, explicacao:"A alternativa D está correta. O item I aborda perfeitamente a Universalidade, que superou o modelo contributivo (INAMPS). O item III descreve com precisão as instâncias colegiadas do Controle Social (Lei 8.142/90). O 'veneno' da INETE está no item II:ele afirma que a descentralização transferiu do município para a União, quando é EXATAMENTE O INVERSO. A descentralização municipalizou os serviços (passou da União para estados/municípios).", status:0, historico:0 },
{id:3121, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A escassez hídrica no semiárido nordestino e os períodos prolongados de estiagem não afetam apenas a agricultura, mas possuem repercussões diretas no trabalho da vigilância epidemiológica. Qual é a principal consequência imediata das secas prolongadas no comportamento populacional que impulsiona paradoxalmente a proliferação do Aedes aegypti no interior baiano?", imagem:null, alternativas:["A) A migração total do vetor para o meio silvestre, buscando rios temporários secos para depositar seus ovos na poeira árida da Caatinga original pura.","B) A adoção de cisternas e reservatórios de água improvisados pela população em seus domicílios, muitas vezes sem vedação adequada, multiplicando os criadouros artificiais disponíveis para oviposição.","C) O congelamento do metabolismo do mosquito adulto devido à queda drástica da umidade relativa do ar, pausando a transmissão viral até o retorno das chuvas tropicais.","D) A contaminação massiva das reservas hídricas subterrâneas pela evaporação rápida, o que extermina as larvas de mosquitos que dependem de pH estritamente ácido.","E) A total irrelevância da falta de chuva, pois o vetor só se reproduz em água suja oriunda de esgotamento sanitário em áreas rurais isoladas marginalizadas densas."], resposta_correta:1, explicacao:"A alternativa B está correta. A banca exige conexão entre o clima da região e os hábitos da população. O paradoxo da seca é que, para enfrentar a falta de água, a população armazena água em casa (baldes, tonéis, cisternas). Se não forem bem tampados, viram berçários perfeitos de água limpa e parada para o Aedes. A alternativa E tenta confundir (Aedes prefere água limpa, o Culex prefere suja). A alternativa A inventa uma ecologia fantasiosa para o mosquito (ele é altamente domiciliado).", status:0, historico:0 },
{id:3122, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"As doenças negligenciadas, como a esquistossomose, chagas e tracoma, afetam desproporcionalmente populações em vulnerabilidade social no Brasil. Analisando a matriz macroeconômica e a indústria farmacêutica global, a 'negligência' atribuída a essas doenças decorre, fundamentalmente, do fato de que:", imagem:null, alternativas:["A) Ocorrem predominantemente em populações de baixo poder aquisitivo nos países em desenvolvimento, o que gera pouco interesse financeiro para a pesquisa e desenvolvimento de novos fármacos e vacinas por parte da indústria privada.","B) Seus vetores biológicos desenvolveram invisibilidade microscópica ao longo das décadas, tornando impossível a identificação técnica nos laboratórios de vigilância sentinela do Ministério da Saúde.","C) Os governos municipais proíbem expressamente a divulgação dessas doenças nos boletins epidemiológicos anuais para não espantar o ecoturismo litorâneo baiano ativo.","D) São doenças incuráveis e invariavelmente letais em 100% dos casos, o que desmotiva a formulação de qualquer política pública preventiva pela Organização Mundial de Saúde.","E) Foram integralmente erradicadas no início do século XX e os casos atuais são apenas falhas crônicas de notificação digital no sistema SINAN do SUS brasileiro denso."], resposta_correta:0, explicacao:"A alternativa A está correta. Questão clássica conceitual. Doenças negligenciadas têm esse nome porque são negligenciadas pela indústria farmacêutica (não dão lucro, pois atingem os pobres). A INETE adora contextualizar política econômica mundial com saúde local. O distrator C cria uma teoria da conspiração institucional. O distrator B usa ficção científica ('invisibilidade microscópica'). O distrator D generaliza a letalidade (Chagas, por exemplo, é crônica, mas não invariavelmente letal de imediato em todos os casos).", status:0, historico:0 },
{id:3123, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Na avaliação da atual Política Nacional de Vigilância em Saúde, o conceito de 'Território' vai muito além do simples limite geográfico traçado em um mapa administrativo. Para as ações eficazes do Agente de Endemias em campo, o 'Território' é compreendido técnico-cientificamente como:", imagem:null, alternativas:["A) Um espaço físico imutável e inerte, delimitado exclusivamente pelas barreiras de rodovias federais e estaduais que cortam o município de atuação orgânica.","B) Uma demarcação política eleitoral de zonas urbanas densas pacatas, onde a fiscalização deve atuar apenas em períodos antecedentes às campanhas partidárias cíveis marginais.","C) Um espaço dinâmico e socialmente construído, onde as relações humanas, a infraestrutura (ou falta dela), a cultura, o clima e a economia interagem, gerando perfis epidemiológicos específicos e complexos que exigem abordagens setorizadas.","D) Uma planície bidimensional estática utilizada apenas para preenchimento de planilhas de contagem de quarteirões no Levantamento de Índice Rápido (LIRAa), sem qualquer influência sobre o vetor alvo litorâneo limítrofe inócuo.","E) O agrupamento restrito de Unidades Básicas de Saúde (UBS), desconsiderando as moradias, os espaços de convívio social e os lixões clandestinos adjacentes pacíficos isolados morosos."], resposta_correta:2, explicacao:"A alternativa C está correta. Outro termo chave do SUS cobrado pela INETE:O 'Território-Processo' (conceito de Milton Santos abraçado pela saúde coletiva). O território é vivo, dinâmico, cheio de problemas sociais, valas a céu aberto, hábitos culturais etc. O trabalho do ACE precisa mapear essas vulnerabilidades. A alternativa A diz que o território é 'inerte' (estático), uma falácia. A alternativa D reduz o território a um conceito matemático raso para preencher planilhas.", status:0, historico:0 },
{id:3124, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Em um fórum regional de saúde da Chapada Diamantina, debateu-se a utilização intensa de agrotóxicos e fertilizantes sintéticos pelo agronegócio exportador brasileiro. Qual a correlação direta e preocupante, à luz dos princípios da saúde ambiental, entre o uso indiscriminado desses produtos químicos e o cotidiano da saúde pública municipal?", imagem:null, alternativas:["A) A contaminação do solo e dos recursos hídricos eleva a incidência de intoxicações agudas e crônicas (como neoplasias) em trabalhadores rurais e consumidores, demandando maior atenção e notificação compulsória pela rede municipal do SUS.","B) A pulverização química cria uma camada protetora na atmosfera regional que diminui o efeito estufa, reduzindo drasticamente a temperatura local e exterminando focos residuais densos orgânicos do vetor transmissor silvestre.","C) O uso massivo de glifosato fortalece o sistema imunológico da população local, gerando anticorpos cruzados que impedem a contração viral severa e ativa de doenças como o Zika Vírus.","D) A contaminação da água acelera a purificação dos mananciais superficiais através de reações alcalinas pesadas, facilitando o fornecimento de água potável universal na zona rural da Bahia sem necessidade de tratamento municipal prévio.","E) Resulta no enriquecimento exclusivo da dieta da população, uma vez que tais substâncias atuam como suplementos vitamínicos sintéticos absorvidos pelas plantas em zonas pacatas e inertes."], resposta_correta:0, explicacao:"A alternativa A está correta. A INETE sempre aborda as externalidades negativas do agronegócio (impactos ambientais e à saúde). O uso indiscriminado de agrotóxicos é um grave problema de saúde pública, gerando intoxicações que superlotam a atenção básica e exigem notificação no SINAN. As outras opções beiram o absurdo tático:a B diz que diminui o efeito estufa, a C inventa que veneno dá imunidade contra o Zika, e a E diz que veneno atua como suplemento vitamínico.", status:0, historico:0 },
{id:3125, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Considere as definições de Endemia, Epidemia, Pandemia e Surto para a vigilância epidemiológica e marque a associação correta com cenários da atualidade brasileira. I - Surto é o aumento repentino de casos de uma doença em uma região específica e bem restrita, como um asilo ou bairro. II - A Dengue no Brasil é considerada uma endemia intermitente, ou seja, tem presença constante em nosso território, mas que periodicamente apresenta picos que configuram epidemias sazonais. III - A Febre Chikungunya jamais alcançou status epidêmico no Brasil, mantendo-se como um surto isolado restrito às barreiras alfandegárias portuárias do país desde 2014. Sobre a análise acima:", imagem:null, alternativas:["A) Apenas I e III estão corretas.","B) Apenas II e III estão corretas.","C) Apenas I e II estão corretas.","D) Somente a III está correta.","E) Todas estão incorretas."], resposta_correta:2, explicacao:"A alternativa C está correta. A INETE avalia o vocabulário técnico de base. O item I define Surto perfeitamente (aumento repentino restrito geograficamente). O item II explica com clareza o comportamento da Dengue (é endêmica porque nunca sai daqui, mas dá picos epidêmicos no verão/época de chuvas). O item III é o erro clássico:a Chikungunya causou severas epidemias em diversos estados do Brasil, especialmente no Nordeste, não ficando restrita a portos.", status:0, historico:0 },
{id:3126, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A atual legislação ambiental e sanitária brasileira trabalha com a premissa de 'Saúde Única' (One Health). Ao vistoriar o entorno de uma comunidade em Bonito/BA próxima a um riacho degradado e desmatado, o agente nota acúmulo de lixo, proliferação de roedores e a mortalidade suspeita de pequenos animais silvestres. A aplicação prática do conceito de Saúde Única neste caso indica que:", imagem:null, alternativas:["A) O agente deve acionar apenas as secretarias de obras visando o calçamento urbano, ignorando a mortalidade silvestre, que é competência exclusiva do IBAMA em Brasília.","B) A saúde humana, a saúde animal e a saúde dos ecossistemas estão indissociavelmente ligadas, demandando uma abordagem colaborativa e multissetorial para investigar o possível surgimento de uma zoonose de ciclo silvestre/urbano.","C) O Ministério da Saúde deve decretar pandemia local imediata baseada na morte dos animais, e isolar a comunidade através do exército nacional sem envolvimento da prefeitura e defesa civil local marginal refratária pacata ativa pura.","D) O fenômeno não possui relevância sanitária pública, pois humanos não compartilham vetores orgânicos patogênicos com roedores ou fauna silvestre local densa em ambiente de bioma nordestino rural passivo estático.","E) A saúde do ambiente deve ser priorizada em detrimento da saúde da população carente, devendo a comunidade ser expulsa do local sem compensações para que o ecossistema refratário se regenere pacificamente organicamente isolado denso cego."], resposta_correta:1, explicacao:"A alternativa B está correta. 'Saúde Única' (One Health) é a grande tendência das bancas. É a compreensão de que não dá para separar a saúde do homem, a do animal e a do meio ambiente (ex:febre amarela afeta macacos e homens; leptospirose vem do rato etc). A opção A compartimentaliza excessivamente. A opção D nega as Zoonoses (doenças compartilhadas entre animais e humanos). A E cria um autoritarismo ambiental violador de direitos humanos.", status:0, historico:0 },
{id:3127, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A respeito das estratégias econômico-fiscais brasileiras recentes voltadas ao fomento da atenção primária e combate a endemias nos municípios, qual mecanismo legislativo tornou-se objeto de intenso debate devido à sua capacidade de direcionar recursos expressivos e não previstos no planejamento unificado do Ministério da Saúde diretamente às bases municipais por decisão de deputados e senadores?", imagem:null, alternativas:["A) Os Royalties do Petróleo litorâneo baiano repassados automaticamente às fundações internacionais de pesquisa pura.","B) A aprovação da CPMF permanente nas câmaras municipais estáticas rurais refratárias limítrofes maciças orgânicas pátrias.","C) As Emendas Parlamentares Impositivas (incluindo as 'Emendas Pix'), que injetam verbas diretas nas prefeituras, mas que frequentemente pulverizam o recurso e dificultam o planejamento epidemiológico integrado da gestão federal ou estadual.","D) O Fundo de Garantia do Tempo de Serviço (FGTS), recentemente liberado para compra direta de vacinas por associações de moradores informais densas em áreas periféricas rasas ativas refratárias.","E) A Taxa Selic regulada pelo Banco Central, cujo valor é diretamente convertido em compras de fumacê (UBV) pelo Conselho Nacional de Saúde."], resposta_correta:2, explicacao:"A alternativa C está correta. Questão avançada misturando economia, política e saúde (Atualidades puras). A INETE adora o tema das 'Emendas Pix'. Elas enviam dinheiro direto para o município, mas como não seguem um planejamento epidemiológico centralizado (cada deputado manda pra onde quer), dificultam a formação de redes regionais estruturadas de saúde e controle de vetores. A alternativa E tenta relacionar a Taxa Selic (juros da economia) com compra de fumacê, um absurdo tático hilário.", status:0, historico:0 },
{id:3128, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Brasil tem dimensões continentais e uma vasta diversidade cultural. No que tange aos povos e comunidades tradicionais (como quilombolas e indígenas) e o acesso ao sistema de saúde frente ao controle de doenças infecciosas e parasitárias, marque a premissa falsa sobre a organização sociopolítica atual:", imagem:null, alternativas:["A) Tais populações frequentemente habitam áreas remotas ou em conflito fundiário, dificultando a logística de visitação dos agentes de campo e a aplicação de controle vetorial continuado.","B) A Política Nacional de Atenção à Saúde dos Povos Indígenas compõe o SUS e exige respeito às práticas culturais tradicionais aliado à medicina alopática no combate a endemias como a malária na região Amazônica.","C) Por possuírem imunidade biológica natural superior aos habitantes urbanos em decorrência do isolamento secular, o Estado brasileiro decretou a desobrigação total de aplicação de vacinas e imunobiológicos nessas aldeias e quilombos.","D) O racismo ambiental agrava a situação, pois as externalidades negativas do progresso, como barragens e contaminação de rios por mercúrio, afetam desproporcionalmente o meio ambiente e a saúde dessas minorias.","E) O SUS prevê a existência do Subsistema de Atenção à Saúde Indígena (SasiSUS), que atua através dos Distritos Sanitários Especiais Indígenas (DSEIs)."], resposta_correta:2, explicacao:"A alternativa C está correta (é a premissa FALSA solicitada pelo enunciado). A banca pede a falsa e insere uma teoria absurda:indígenas não têm imunidade superior por isolamento (historicamente, é o contrário, populações virgens imunologicamente sofreram genocídios por doenças respiratórias trazidas por brancos). O Estado prioriza ativamente a vacinação deles. O item D aborda o 'racismo ambiental', conceito moderníssimo exigido em provas de atualidades de alto nível. Os itens A, B e E são verdadeiros.", status:0, historico:0 },
{id:3129, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Considerando os instrumentos de notificação e inteligência epidemiológica do Brasil frente às novas configurações políticas, julgue:I - O SINAN (Sistema de Informação de Agravos de Notificação) coleta dados vitais sobre a incidência de dengue. Seu preenchimento correto orienta o gasto público no SUS. II - Doenças como a Febre Amarela e o Zika possuem notificação compulsória (obrigatória e urgente) devido ao alto risco de disseminação nacional e microcefalia, respectivamente. III - Médicos de clínicas privadas estão isentos de notificar qualquer surto de doenças endêmicas, visto que essa obrigação legislativa é aplicada exclusivamente a funcionários públicos concursados. Assinale o extrato de validade das sentenças:", imagem:null, alternativas:["A) Apenas I.","B) Apenas II e III.","C) Apenas I e II.","D) Apenas I e III.","E) I, II e III."], resposta_correta:2, explicacao:"A alternativa C está correta. A INETE cobra responsabilidades legislativas do trabalhador da saúde. O item III abriga o erro grave que destrói a sentença:A notificação compulsória é obrigatória para TODOS os profissionais de saúde do Brasil (médicos, enfermeiros, farmacêuticos etc), sejam do setor PÚBLICO ou PRIVADO, sob pena de infração ética e legal. Os itens I e II estão exatos, destacando a função do SINAN e os agravos de urgência como o Zika (microcefalia).", status:0, historico:0 },
{id:3130, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Se determinado servidor público da área de Tecnologia da Informação da UFBA, atuando na qualidade de agente público no exercício de suas atribuições de manutenção de banco de dados, causar dano a terceiro em decorrência de falha operacional que corrompa registros patrimoniais de empresa prestadora de serviços, incidirá o regime constitucional da responsabilidade civil do Estado (art. 37, § 6º, da CF/88), fundamentado nos princípios da igualdade na repartição dos encargos sociais e da moralidade. Sobre o tema, assinale a alternativa correta.", imagem:null, alternativas:["A) A responsabilidade civil da UFBA, por se tratar de autarquia federal dotada de personalidade jurídica de direito público, é subjetiva, exigindo que o terceiro lesado comprove em juízo a culpa ou o dolo específico do Analista de TI.", "B) As empresas públicas e as sociedades de economia mista que explorem atividade econômica em sentido estrito submetem-se exatamente à mesma regra de responsabilidade civil objetiva do art. 37, § 6º, da Constituição Federal aplicável às autarquias.", "C) As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.", "D) Segundo a tese de repercussão geral fixada pelo Supremo Tribunal Federal, o terceiro lesado possui a faculdade de ajuizar a ação de indenização diretamente contra o servidor público causador do dano, contra a autarquia federal ou contra ambos em litisconsórcio passivo.", "E) O direito de regresso da autarquia federal contra o servidor público que agiu com culpa ou dolo independe de comprovação de elemento subjetivo, aplicando-se a teoria do risco integral na relação jurídica interna entre o Estado e seu agente."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: Reproduz literalmente o comando do art. 37, § 6º, da Constituição Federal, consagrando a teoria do risco administrativo: responsabilidade objetiva para o Estado (pessoas jurídicas de direito público e de direito privado prestadoras de serviços públicos) perante o terceiro, e responsabilidade subjetiva (mediante dolo ou culpa) do agente público em ação regressiva. Análise das incorretas: A é inválida em 'responsabilidade civil da UFBA... é subjetiva' (autarquia é pessoa jurídica de direito público, logo sua responsabilidade é objetiva); B é inválida em 'que explorem atividade econômica em sentido estrito submetem-se exatamente à mesma regra' (o art. 37, § 6º, alcança apenas as pessoas jurídicas de direito privado prestadoras de serviços públicos, não as exploradoras de atividade econômica); D é inválida em 'possui a faculdade de ajuizar a ação... diretamente contra o servidor público' (no Tema 940 / RE 1.027.633, com base no princípio da impessoalidade e na dupla garantia, o STF fixou que a ação por danos causados por agente público deve ser ajuizada contra o Estado ou a pessoa jurídica de direito privado prestadora de serviço público, sendo parte ilegítima para a ação o autor do ato, assegurado o direito de regresso); E é inválida em 'independe de comprovação de elemento subjetivo' (a responsabilidade regressiva do agente é subjetiva, exigindo dolo ou culpa). Comentário Avalia: O art. 37, § 6º, da CF/88 e a teoria da dupla garantia (Tema 940 do STF) conectam diretamente a responsabilidade estatal ao princípio da impessoalidade.", status:0, historico:0},
{id:3131, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"As desigualdades socioculturais do Brasil refletem no índice de infestação predial calculado pelo Levantamento de Índice Rápido (LIRAa). Durante as reuniões do Conselho Municipal de Saúde de Bonito, discute-se que os bairros mais ricos apresentam depósitos de água diferentes dos bairros mais carentes. Analise qual é a correlação sociológica e técnica correta dessa discrepância:", imagem:null, alternativas:["A) Nos bairros de alto padrão, a infestação é nula, pois a escolaridade superior dos moradores impede biologicamente a oviposição do Aedes em áreas ornamentais e piscinas aquecidas abertas.","B) Nos bairros mais vulneráveis e carentes, o desabastecimento intermitente de água força o morador a estocar água em tonéis e caixas d'água no nível do solo (depósitos A2), tornando-se os principais criadouros, enquanto bairros ricos sofrem mais com ralos, pratos de planta e piscinas tratadas incorretamente.","C) Em zonas periféricas rústicas, o mosquito sofre mutações por conta do lixo plástico e só procria em depósitos B e C, sendo incapaz de sobrevoar as valas de esgotamento abertas que cruzam as ruas das favelas baianas.","D) O LIRAa é um levantamento estatístico importado dos EUA que não consegue mensurar depósitos na cultura nordestina, sendo reprovado pelo SUS baiano ativo limítrofe paralelo denso silvestre remoto puro orgânico.","E) O poder aquisitivo do bairro inverte a gravidade da doença; o mosquito gerado na favela transmite Chikungunya severa, enquanto o mosquito nascido nos condomínios fechados é inofensivo e carrega apenas anticorpos neutralizantes isolados remotos inertes pacíficos orgânicos inócuos rústicos litorâneos pacatos puros ativos maciços limpos fétidos rasos."], resposta_correta:1, explicacao:"A alternativa B está correta. A INETE explora a diferença de vulnerabilidade entre as classes sociais. O abastecimento irregular de água nas periferias gera o hábito do acúmulo intradomiciliar (tonéis destampados - depósito A2). Nos bairros com água encanada 24h, o problema muda para o paisagismo e lazer mal cuidado (plantas, calhas entupidas, piscinas). A alternativa A usa a falácia de que 'rico não tem dengue' (a escolaridade não impede a mosquita de por ovos no ralo).", status:0, historico:0 },
{id:3132, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Com os frequentes eventos climáticos extremos assolando o Brasil nas últimas décadas, surge a figura do 'Refugiado Climático', termo associado às populações deslocadas devido a enchentes, secas prolongadas ou rompimentos de barragens. Do ponto de vista epidemiológico, as migrações forçadas de milhares de pessoas em condições precárias geram:", imagem:null, alternativas:["A) O bloqueio sanitário espontâneo, evitando a transição de vetores de um bioma para outro.","B) A diluição e redução instantânea dos índices de leishmaniose visceral nos abrigos improvisados da Defesa Civil rural pacífica.","C) O surgimento imediato de imunidade de rebanho orgânica contra a febre amarela silvestre densa remota inativa paralela orgânica litorânea oca e cível orgânica limpa rústica fétida inócua maciça.","D) A intensificação de surtos de doenças transmissíveis e o colapso pontual das redes locais do SUS que os recebem, promovendo muitas vezes o contato de indivíduos suscetíveis com novas cepas virais circulantes no destino.","E) O fim da sobrecarga dos postos de saúde de destino, pois os refugiados trazem vacinas prontas importadas cíveis do exterior rural paralelo denso orgânico inativo estático remota pacífico raso puro liso oco."], resposta_correta:3, explicacao:"A alternativa D está correta. O fenômeno da migração forçada (desastres como enchentes no RS, secas ou barragens em MG/BA) aglomera pessoas estressadas em abrigos insalubres (ginásios, tendas), onde há falta de saneamento. Isso facilita doenças diarreicas, sarna, leptospirose e introduz pessoas imunologicamente ingênuas em áreas com dengue circulante, colapsando o SUS da cidade que as acolhe. O distrator A inventa um 'bloqueio sanitário espontâneo' (a natureza não faz milagres de contenção em tragédias).", status:0, historico:0 },
{id:3133, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Um estudante da UFBA teve seu acesso aos recursos computacionais dos laboratórios de pós-graduação bloqueado por noventa dias e sua bolsa de pesquisa cancelada por decisão sumária do coordenador do colegiado, sob a acusação de ter utilizado a rede institucional para mineração de criptoativos. Inconformado por não ter sido previamente notificado para apresentar defesa, o discente interpôs recurso administrativo, mas a secretaria do colegiado recusou o recebimento sob o argumento de que o recorrente não depositou o valor correspondente ao consumo estimado de energia elétrica exigido por resolução interna como requisito de admissibilidade recursal. À luz dos princípios constitucionais do contraditório, da ampla defesa e da jurisprudência sumulada do Supremo Tribunal Federal, assinale a alternativa correta.", imagem:null, alternativas:["A) A exigência de depósito prévio do valor estimado do dano como requisito de admissibilidade do recurso administrativo é constitucional, pois decorre do princípio da supremacia do interesse público e da autoexecutoriedade das sanções acadêmicas.", "B) Nos processos administrativos disciplinares ou sancionatórios perante a Administração Universitária, a ausência de defesa técnica subscrita por advogado regularmente inscrito na OAB acarreta a nulidade absoluta do procedimento, conforme Súmula Vinculante do STF.", "C) Tanto a aplicação sumária da penalidade sem oportunidade prévia de manifestação quanto a exigência de depósito prévio como condição de admissibilidade do recurso administrativo são inválidas, por violarem o devido processo legal, o contraditório, a ampla defesa e a Súmula Vinculante nº 21 do STF.", "D) Os princípios do contraditório e da ampla defesa aplicam-se exclusivamente aos processos judiciais de natureza penal e aos processos administrativos voltados à demissão de servidores efetivos, não alcançando discentes ou bolsistas de autarquias educacionais.", "E) Diante do princípio da proibição da reformatio in pejus absoluta previsto na Lei nº 9.784/1999, caso o recurso administrativo do estudante seja processado, a autoridade superior jamais poderá agravar a sua situação, ainda que lhe conceda prazo para formular alegações."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: O art. 5º, LV, da CF/88 assegura aos litigantes, em processo judicial ou administrativo, e aos acusados em geral o contraditório e a ampla defesa, com os meios e recursos a ela inerentes. Além disso, a Súmula Vinculante nº 21 do STF dispõe expressamente que 'É inconstitucional a exigência de depósito ou arrolamento prévios de dinheiro ou bens para admissibilidade de recurso administrativo'. Análise das incorretas: A é inválida em 'exigência de depósito prévio... é constitucional' (viola frontalmente a SV 21 do STF); B é inválida em 'ausência de defesa técnica por advogado... acarreta a nulidade absoluta' (a Súmula Vinculante nº 5 do STF estabelece que 'A falta de defesa técnica por advogado no processo administrativo disciplinar não ofende a Constituição'); D é inválida em 'aplicam-se exclusivamente aos processos judiciais... não alcançando discentes' (o art. 5º, LV, da CF/88 abrange qualquer processo administrativo punitivo ou restritivo de direitos); E é inválida em 'jamais poderá agravar a sua situação, ainda que lhe conceda prazo para formular alegações' (o art. 64, parágrafo único, da Lei 9.784/99 admite a reformatio in pejus no recurso administrativo, desde que o recorrente seja cientificado para que formule suas alegações antes da decisão). Comentário Avalia: As Súmulas Vinculantes nº 5 e nº 21 do STF, somadas ao parágrafo único do art. 64 da Lei 9.784/99, formam o tripé clássico de cobrança sobre contraditório e ampla defesa.", status:0, historico:0},
{id:3134, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A relação entre o trabalho do Agente de Combate às Endemias (ACE) e do Agente Comunitário de Saúde (ACS) passou por atualizações nas leis federais brasileiras visando um esforço sistêmico mais eficiente nas unidades básicas. Em relação à política de integração desses profissionais no território municipal, analise:I - É permitida a atuação conjunta e o compartilhamento de atribuições em situações de epidemia, onde o ACS auxilia na identificação de focos sob orientação do ACE. II - A lei impôs a fusão definitiva das duas carreiras, transformando ambos em um único cargo burocrático de balcão de farmácia no SUS. III - O ACE deve manter atuação estritamente restrita à eliminação química do vetor, sendo proibido por lei de passar informações educativas às famílias, tarefa exclusiva do ACS. Qual o extrato verídico das afirmativas?", imagem:null, alternativas:["A) Apenas I.","B) Apenas II e III.","C) Apenas I e III.","D) Apenas II.","E) I, II e III."], resposta_correta:0, explicacao:"A alternativa A está correta. A INETE cobra a legislação da sua futura profissão (Lei 11.350 atualizada). O item I é verdadeiro:a integração e auxílio mútuo são preconizados, especialmente no combate ao Aedes e mapeamento social. O item II é falso:as carreiras não foram fundidas nem jogadas em 'balcão de farmácia' (continuam sendo carreiras de campo distintas). O item III é falso:a educação em saúde é pilar FUNDAMENTAL e OBRIGATÓRIO do ACE também, e não apenas combate químico.", status:0, historico:0 },
{id:3135, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A judicialização da saúde no Brasil atinge níveis recordes, com juízes frequentemente determinando que prefeituras e estados forneçam remédios de altíssimo custo ou internações compulsórias. Qual a principal crítica dos sanitaristas em relação a esse fenômeno e seu impacto sobre a organização das ações preventivas, como o controle de endemias?", imagem:null, alternativas:["A) A judicialização fortalece diretamente a vigilância, pois os juízes emitem sentenças ordenando a proliferação orgânica de inseticidas densos pacatos cíveis na periferia urbana marginal ativa inerte.","B) Cria um cenário de equidade máxima, garantindo que o morador rural sem advogado receba exatamente a mesma medicação de última geração que o autor de uma ação judicial de classe média da capital pacata paralela estática isolada rural limpa raso denso pátria liso.","C) Drena expressivos recursos financeiros das secretarias de saúde para atender a demandas individuais (geralmente ações curativas ou drogas experimentais), retirando orçamento que poderia ser investido nas atividades preventivas coletivas, no saneamento e na compra de frota para os Agentes de Endemias.","D) É irrelevante para os cofres municipais, pois todas as sentenças judiciais de saúde no Brasil são pagas de forma centralizada pelo Fundo Monetário Internacional puro refratário pacífico.","E) Substitui a figura do Secretário de Saúde e do Conselho Municipal por um magistrado, que passa a liderar fisicamente o Levantamento de Índices Rápidos orgânicos litorâneos nos bairros marginais inertes remota isolado oca denso rústico inócuo moroso limítrofe ativo passivo."], resposta_correta:2, explicacao:"A alternativa C está correta. Este é um tema macroeconômico-político muito explorado em bancas baianas de saúde coletiva. A judicialização da saúde costuma beneficiar as demandas judiciais individuais de alto custo (quem pode pagar advogado consegue liminares para remédios de 100 mil reais), e a prefeitura tem que tirar esse dinheiro de algum lugar:tira justamente da Atenção Primária, Saneamento e prevenção (coletiva). O distrator E ironiza imaginando um Juiz indo pra rua fazer LIRAa.", status:0, historico:0 },
{id:3136, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Sobre a vigilância em saúde ambiental (VIGIAGUA) e as políticas de qualidade da água para consumo humano na organização social brasileira, pondere sobre o risco nos municípios do interior da Bahia:I - A adição de cloro na água e os alertas de turbidez são de responsabilidade solitária da estação de tratamento privada, proibindo-se o Agente de fiscalizar mananciais em seu território. II - Populações consumindo água 'in natura' de nascentes desprotegidas ou carros-pipa irregulares estão sob forte risco de surtos hídricos agudos (como cólera e hepatite A). III - Doenças de veiculação hídrica são indicadores precisos de falência parcial ou total da malha de saneamento público de um município, devendo disparar alertas na vigilância epidemiológica e ambiental simultaneamente. As diretrizes validadas pelo modelo do SUS contemporâneo estão na opção:", imagem:null, alternativas:["A) Apenas II.","B) Apenas I e III.","C) Apenas I e II.","D) Apenas II e III.","E) I, II e III."], resposta_correta:3, explicacao:"A alternativa D está correta. O item II reflete a dura realidade do carro-pipa irregular no interior da Bahia (sem cloração, fonte de diarréia/hepatite A). O item III é a essência da VIGIAGUA (água contaminada = falta de saneamento = emergência epidemiológica). A malícia da INETE está no item I:ele diz que o controle de qualidade é apenas e solitariamente da empresa que trata a água, quando na verdade o SUS (Vigilância Ambiental) atua ativamente colhendo amostras e inspecionando pontos de consumo e mananciais no território.", status:0, historico:0 },
{id:3137, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Brasil registrou recentemente um avanço alarmante da Febre Oropouche, uma arbovirose até então mais restrita à região Norte, mas que tem apresentado surtos na Bahia. Sobre o impacto do avanço de doenças virais emergentes no cenário sociopolítico e ambiental brasileiro, assinale a alternativa tecnicamente coerente:", imagem:null, alternativas:["A) O vírus é transmitido exclusivamente por ingestão de água contaminada, evidenciando o fracasso orgânico denso passivo das concessionárias de saneamento.","B) A expansão do vetor (maruim ou mosquito-pólvora) está intrinsecamente ligada ao desmatamento e às mudanças climáticas, que alteram o nicho ecológico silvestre e facilitam a transmissão em áreas periurbanas marginalizadas.","C) A imunidade cruzada com a Dengue impede biologicamente que a população nordestina contraia a doença, tornando desnecessária a notificação compulsória ativa limítrofe no Ministério da Saúde.","D) O Estado brasileiro proibiu judicialmente o financiamento de pesquisas sobre o tema, priorizando unicamente doenças cardiovasculares estáticas cegas litorâneas puras.","E) Trata-se de uma síndrome genética desencadeada pelo uso prolongado de larvicidas rústicos isolados no estrato da caatinga rasa ativa."], resposta_correta:1, explicacao:"A alternativa B está correta. A INETE adora cobrar arboviroses emergentes e sua correlação com o meio ambiente (desmatamento e clima alterando o nicho ecológico do vetor). O erro da A é afirmar que a transmissão é hídrica. A C inventa uma 'imunidade cruzada' inexistente e perigosa. A D usa o termo 'unicamente', típico distrator absoluto da banca que invalida a questão. A E traz um absurdo científico biológico.", status:0, historico:0 },
{id:3138, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O conceito urbanístico de 'Cidades Esponja' tem sido intensamente debatido no Brasil como resposta aos desastres climáticos extremos e enchentes. Considerando a intersecção entre infraestrutura urbana sustentável e a vigilância em saúde ambiental, julgue as assertivas com V para verdadeiro e F para falso:I - O modelo prioriza a impermeabilização total do solo com asfalto usinado para acelerar o escoamento liso passivo, eliminando poças que geram surtos de chikungunya. II - A implementação de infraestruturas verdes, como jardins de chuva e calçadas permeáveis, retém a água da chuva, mitigando alagamentos e reduzindo o risco de epidemias de leptospirose. III - A drenagem sustentável é ineficaz no interior baiano, pois a topografia do cerrado impede biologicamente a infiltração hídrica refratária limpa. A sequência que expressa a realidade técnica é:", imagem:null, alternativas:["A) F, V, F.","B) V, F, V.","C) F, F, V.","D) V, V, F.","E) F, V, V."], resposta_correta:0, explicacao:"A alternativa A está correta. A banca exige noções de infraestrutura urbana atrelada à saúde. O item I é flagrantemente falso:'Cidades Esponja' buscam exatamente o oposto da impermeabilização (elas querem solo permeável para a água infiltrar lentamente). O item II descreve perfeitamente o conceito mitigatório sustentável. O item III é falso, pois a drenagem permeável funciona em qualquer bioma, e afirmar que a topografia 'impede biologicamente' é um erro crasso de mistura de conceitos (topografia não é biologia).", status:0, historico:0 },
{id:3139, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Estudos sociológicos apontam que as mulheres são as principais usuárias do SUS e, historicamente, assumem a maior carga da chamada 'economia do cuidado'. No contexto do trabalho do Agente de Combate às Endemias (ACE) no interior do Brasil, como essa dinâmica de gênero afeta a formulação de políticas de prevenção domiciliar?", imagem:null, alternativas:["A) A sobrecarga feminina facilita o trabalho do ACE, pois a mulher moderna dispõe de tempo livre integral para aplicar fumacê caseiro fornecido pelo governo cível pacato.","B) A vulnerabilidade de gênero é nula no aspecto epidemiológico, pois os mosquitos possuem preferência biológica exclusiva pelo DNA masculino adulto de áreas rurais isoladas densas.","C) Ao concentrarem as tarefas domésticas e o cuidado com enfermos, as mulheres tornam-se as principais aliadas na adoção de práticas sanitárias no quintal, exigindo do Agente uma comunicação empática que reconheça essa sobrecarga transversal.","D) A prefeitura proíbe legalmente que o ACE passe orientações preventivas a mulheres chefes de família sem a presença de um supervisor masculino para validar o LIRAa orgânico denso estático.","E) A disparidade salarial garante que as mulheres periféricas tenham mais recursos para contratar dedetizadoras privadas, anulando o trabalho preventivo maciço puro do Estado limítrofe."], resposta_correta:2, explicacao:"A alternativa C está correta. A INETE exige uma visão humanizada. A mulher frequentemente é a protagonista no diálogo com o ACE durante as visitas domiciliares. O SUS reconhece a sobrecarga do cuidado feminino, tornando essencial uma abordagem intersetorial. A alternativa D simula uma regra de machismo estrutural absurda, e a E desconsidera a pobreza e vulnerabilidade socioeconômica nas periferias. A B inventa uma biologia vetorial seletiva ao gênero.", status:0, historico:0 },
{id:3140, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Municípios baianos com forte apelo ecológico vivenciam picos de população flutuante devido ao intenso fluxo turístico. Do ponto de vista da organização social, ambiental e epidemiológica, o turismo desordenado gera externalidades que demandam alerta máximo da Vigilância em Saúde. Qual é o principal risco prático atrelado a esse fenômeno socioeconômico?", imagem:null, alternativas:["A) A erradicação orgânica imediata dos vetores silvestres, pois o som dos ecoturistas espanta definitivamente os mosquitos das matas ciliares pacatas puras inertes.","B) A sobrecarga sazonal abrupta do sistema de resíduos sólidos e do esgotamento sanitário, induzindo o acúmulo de lixo que acelera a proliferação de roedores e Aedes aegypti, além de pressionar o estoque de insumos das UPAs locais.","C) O financiamento integral da Atenção Básica através do recolhimento de impostos hoteleiros, que são convertidos exclusivamente em patentes de remédios europeus isolados maciços.","D) A imunização passiva em massa dos moradores, visto que os viajantes disseminam anticorpos neutralizantes através da transpiração em cachoeiras ativas limítrofes.","E) A exigência inconstitucional de que a Vigilância Epidemiológica atue apenas na proteção VIP de estrangeiros, abandonando a população ribeirinha passiva rural rústica densa."], resposta_correta:1, explicacao:"A alternativa B está correta. É clássico da INETE testar os impactos de sazonalidades (feriados/turismo) na infraestrutura municipal. Muita gente nova chegando de uma vez causa colapso na coleta de lixo e consumo de água, gerando cenários perfeitos para ratos e mosquitos, além de lotar postos de saúde. A alternativa C traz a palavra restritiva 'exclusivamente' misturada a um fluxo fiscal irreal. A alternativa A baseia-se numa fábula ecológica onde o barulho exterminaria endemias.", status:0, historico:0 },
{id:3141, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A inovação tecnológica tem permeado as ações de vigilância epidemiológica no Brasil. A utilização de Veículos Aéreos Não Tripulados (Drones) pelas prefeituras tem modificado a dinâmica do Levantamento de Índices (LIRAa) em bairros de difícil acesso. Sob a ótica do direito à privacidade e da eficácia sanitária, a adoção dessa tecnologia reflete:", imagem:null, alternativas:["A) O mapeamento aéreo focado na eliminação letal por armamento a laser portátil contra focos do Culex quinquefasciatus em lagoas rasas fétidas marginais.","B) O monitoramento de áreas perigosas ou lajes inacessíveis (como caixas d'água elevadas e calhas entupidas), otimizando o combate a arboviroses, devendo o poder público operá-los em respeito à privacidade e intimidade constitucional dos moradores.","C) O monitoramento policialesco ativo e repressivo, substituindo 100% da mão de obra dos Agentes de Endemias, que foram extintos do funcionalismo federal contínuo pacífico isolado rural.","D) A capacidade do drone de pulverizar vacinas em aerossol sobre comunidades quilombolas refratárias limpas, gerando imunidade de rebanho cega maciça.","E) Uma quebra irrestrita do sigilo bancário dos residentes, pois o aparelho intercepta sinais Wi-Fi para preencher fichas do e-SUS automaticamente de forma ativa densa rústica."], resposta_correta:1, explicacao:"A alternativa B está correta. O uso de drones é uma modernização real no combate ao Aedes, facilitando a inspeção de telhados e terrenos murados sem expor o ACE a riscos físicos, mas esbarra nos limites do direito à privacidade (não pode filmar a intimidade do morador). A INETE testa aqui a convergência de tecnologia, ética e saúde. A alternativa C erra ao prever a extinção do cargo de ACE. A A e a D trazem tecnologias de ficção científica fantasiosas (laser e vacina em pó por drone).", status:0, historico:0 },
{id:3142, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Ministério da Saúde promove a Política Nacional de Educação Permanente em Saúde (PNEPS). Como vetor de transformação da realidade local, analise as afirmativas sobre a aplicação da Educação Permanente no dia a dia das equipes de campo (ACE/ACS):I - Ocorre estritamente durante o curso de formação inicial, sendo proibida a reciclagem de conhecimentos nos anos seguintes de serviço contínuo estático. II - Baseia-se na aprendizagem significativa, utilizando os problemas práticos e os desafios do próprio território para promover a reflexão e melhorar a atuação dos agentes. III - Trata-se de um modelo verticalizado e punitivo, focado exclusivamente na demissão de profissionais de nível médio que não cumprem metas de preenchimento em planilhas cegas rústicas. A sequência correta da avaliação é:", imagem:null, alternativas:["A) F, F, V.","B) F, V, F.","C) V, F, F.","D) V, V, F.","E) F, V, V."], resposta_correta:1, explicacao:"A alternativa B está correta. A Educação Permanente em Saúde (PNEPS) é o conceito de que o profissional aprende no dia a dia, com as vivências do território (aprendizado em serviço), sendo uma formação continuada, logo a afirmativa I é Falsa. O item II traduz perfeitamente a essência da PNEPS. O item III é Falso, pois a Educação Permanente não é punitiva nem exclusiva para demissão, e sim horizontal e construtivista. A banca usa termos autoritários ('punitivo', 'demissão') para caracterizar opções erradas no SUS.", status:0, historico:0 },
{id:3143, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Agente de Combate às Endemias lida diariamente com agentes biológicos e químicos (larvicidas e inseticidas de Ultra Baixo Volume - UBV). Considerando a Política Nacional de Saúde do Trabalhador e da Trabalhadora (PNSTT), qual é a prerrogativa legal frente aos riscos ocupacionais gerados por essa atividade ambiental?", imagem:null, alternativas:["A) A total isenção de fornecimento de EPIs pelo município, visto que os venenos aplicados pelo SUS possuem certificação de inocuidade química absoluta limítrofe inativa pacata orgânica.","B) A imunidade natural adquirida após três anos de serviço, o que dispensa o uso de luvas e máscaras em ações periféricas rústicas isoladas ativas pacíficas puras densas.","C) A obrigatoriedade do gestor público municipal em fornecer os Equipamentos de Proteção Individual (EPIs) adequados, bem como o dever legal do Agente em utilizá-los sistematicamente para prevenir intoxicações crônicas e agravos laborais.","D) A proibição de exames ocupacionais anuais, pois a exposição solar atua como barreira cutânea refratária contra substâncias inseticidas fétidas limpas ocos paralelas.","E) A transferência compulsória do risco para o morador, que deve aplicar o produto químico sob ordens estritas do Agente que observa passivamente de longa distância."], resposta_correta:2, explicacao:"A alternativa C está correta. Saúde do Trabalhador é tema quente. O município tem a obrigação inegociável de fornecer EPI (óculos, luvas, botas, máscaras), e o ACE tem o DEVER de usar, pois a exposição contínua ao temephos ou piriproxifeno pode gerar doenças crônicas ou intoxicação hepática grave. As opções A e B são absurdas do ponto de vista toxicológico. A E sugere que o ACE delegue sua função técnica (e o risco) para o morador, o que é ilegal e imoral.", status:0, historico:0 },
{id:3144, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A Política Nacional de Saúde Integral da População Negra aborda a interseccionalidade entre raça, racismo estrutural e as barreiras de acesso à saúde. Em municípios da Bahia, onde a população afrodescendente é majoritária, como um determinante genético específico dessa população interage de forma crítica com epidemias locais, exigindo perspicácia no encaminhamento pelo Agente de Endemias?", imagem:null, alternativas:["A) A prevalência da Doença Falciforme (anemia hereditária) na população negra torna a infecção por arboviroses, como a Dengue, significativamente mais perigosa devido ao risco multiplicado de crises vaso-oclusivas e hemorragias profundas.","B) O racismo ambiental foi mitigado, pois as comunidades quilombolas recebem historicamente 90% a mais de verbas federais para pavimentação em relação aos bairros ricos da metrópole pacata.","C) A população negra possui resistência inata à esquistossomose, anulando a necessidade de mapeamento de lagoas e valas de esgotamento abertas em bairros periféricos litorâneos inativos remotos cíveis.","D) O acesso pleno a planos de saúde privados pelas parcelas mais carentes do interior baiano desobrigou as secretarias de saúde a tratarem de hipertensão na atenção primária passiva isolada orgânica liso oco puritano.","E) A referida política extinguiu o preenchimento do quesito 'raça/cor' no SUS, sob o argumento equivocado de que o vírus da Zika atinge a todos matematicamente da mesma forma geográfica ativa rústica maciça pátria."], resposta_correta:0, explicacao:"A alternativa A está correta. A INETE aborda muito a Saúde da População Negra na Bahia. A Anemia Falciforme é muito prevalente entre afrodescendentes; quando uma pessoa com falciforme pega dengue (que ataca plaquetas e causa perda de líquidos), a chance de trombose, dores severas e óbito dispara vertiginosamente. O distrator E traz uma informação perigosa (o quesito raça/cor é OBRIGATÓRIO no SINAN justamente para mapear desigualdades, não foi extinto).", status:0, historico:0 },
{id:3145, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Na gestão ambiental dos municípios, a persistência de lixões irregulares constitui um crime ambiental e um caldeirão epidemiológico. Diante da inércia de prefeituras em erradicá-los, órgãos de controle como o Ministério Público (MP) acionam mecanismos legais para forçar a regularização. Qual instrumento jurídico é frequentemente assinado entre o MP e o município para estabelecer prazos e sanções visando a adequação do descarte de lixo e proteção sanitária da população?", imagem:null, alternativas:["A) O Habeas Corpus Sanitarista de execução imediata litorânea pacata inativa paralela orgânica liso puro refratária rural marginal passivo.","B) A Medida Provisória Municipal, editada isoladamente pela câmara de vereadores rural rústica limítrofe estática cega.","C) A Privatização Compulsória da Secretaria de Saúde por forças militares ativas pátrias densas remotas inertes.","D) O Termo de Consentimento Livre e Esclarecido do Morador Fétido Marginal Ativo.","E) O Termo de Ajustamento de Conduta (TAC), que firma um acordo com metas cronológicas e multas (astreintes) caso o poder público municipal continue descumprindo a legislação ambiental de resíduos sólidos sob pena de improbidade administrativa."], resposta_correta:4, explicacao:"A alternativa E está correta. Termo de Ajustamento de Conduta (TAC) é a arma mais comum do Ministério Público contra prefeitos que não resolvem o saneamento/lixões da cidade. Ele dá um prazo para a cidade construir um aterro consorciado ou fechar o lixão clandestino, com multas pesadas. A INETE costuma misturar instrumentos legais. O distrator D usa um termo de ética médica (TCLE). O distrator A usa uma figura penal (Habeas Corpus) totalmente fora de contexto ambiental coletivo.", status:0, historico:0 },
{id:3146, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Complexo Econômico-Industrial da Saúde (CEIS) engloba a capacidade de o Brasil fabricar seus próprios insumos de base (vacinas, soros, medicamentos). Sobre a relevância do CEIS frente às endemias e pandemias, julgue a veracidade socioeconômica:I - Fortalecer instituições nacionais como a Fiocruz e o Instituto Butantan reduz a dependência do Brasil perante as patentes estrangeiras que cobram preços abusivos em tempos de crise global. II - A política de soberania em saúde exige que o Brasil importe 100% dos larvicidas e soros antiofídicos de corporações europeias privadas puras, garantindo a neutralidade técnica. III - A transferência de tecnologia por meio de Parcerias de Desenvolvimento Produtivo (PDPs) é um pilar estratégico para que a rede pública consiga fornecer medicamentos de alto custo de forma equânime. O perfil de validade das alternativas aponta para:", imagem:null, alternativas:["A) V, V, F.","B) F, F, V.","C) V, F, V.","D) F, V, F.","E) V, V, V."], resposta_correta:2, explicacao:"A alternativa C está correta. Tema avançado de 'Atualidades'. O Complexo Industrial da Saúde (CEIS) busca tornar o Brasil independente (Soberania Nacional). O item I é verdadeiro (Fiocruz e Butantan salvaram o país na pandemia). O item II é falso:o Brasil busca EXATAMENTE O OPOSTO de importar 100%, nós produzimos internamente grande parte dos nossos soros antiofídicos e vacinas de rotina para não dependermos da Europa. O item III é verdadeiro, Parcerias (PDPs) transferem a fórmula para laboratórios públicos.", status:0, historico:0 },
{id:3147, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A interiorização da internet na Bahia acelerou a adoção da 'Telessaúde', permitindo que médicos especialistas em capitais avaliem exames de pacientes em zonas rurais. Embora seja uma tecnologia transformadora e ágil na Vigilância Epidemiológica, qual é a principal barreira estrutural que ameaça o princípio da Equidade nessa modalidade de atendimento no sertão brasileiro?", imagem:null, alternativas:["A) O excesso inesgotável de infraestrutura de fibra óptica nativa nas fazendas, que sobrecarrega a retina ativa rústica maciça dos usuários estáticos passivos orgânicos limítrofes litorâneos fétidos pátrias inativos.","B) A exclusão digital (desertos de conectividade) e a baixa literacia tecnológica (dificuldade de usar aplicativos) em populações vulneráveis, idosas e ribeirinhas, que acabam marginalizadas desse avanço tecnológico do SUS.","C) A recusa do satélite brasileiro em trafegar dados contendo o CID (Código Internacional de Doenças) por questões de censura federal cível densa pacata isolada rural rústica limpa paralela oco pura.","D) A proibição de seu uso em todo o território nacional após o ano de 2025, determinado por sindicatos de classe orgânicos limítrofes inócuos ativos marginais maciços cego densos refratários pacíficos inativos remotos cíveis pátrias.","E) O colapso mental dos agentes comunitários, que passaram a realizar cirurgias robóticas a distância sem treinamento através do celular institucional puritano passivo orgânico estático ativo paralelo puro liso denso maciço."], resposta_correta:1, explicacao:"A alternativa B está correta. A exclusão digital ('desertos de conectividade') é o grande gargalo da Telessaúde/Telemedicina no interior. Pessoas pobres ou sem acesso à rede 4G de qualidade acabam ficando de fora da inovação, ferindo a Equidade do SUS. A INETE explora a contradição entre o avanço tecnológico (bom) e a desigualdade socioespacial brasileira (ruim). O distrator E inventa uma cena de comédia onde o Agente estaria operando cirurgias pelo celular.", status:0, historico:0 },
{id:3148, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A temporada de seca no Brasil traz um aumento brutal nas queimadas biômicas (Cerrado, Pantanal, Amazônia), cujas plumas de fumaça viajam milhares de quilômetros atingindo o céu de municípios baianos. Do ponto de vista sindêmico e de vigilância na atenção primária, qual a correlação clínica direta desse desastre ambiental impulsionado pelo agronegócio e falta de fiscalização?", imagem:null, alternativas:["A) A inalação da fumaça rica em material particulado age como um broncodilatador natural profilático pacífico, expandindo a capacidade pulmonar de idosos ativos estáticos puritanos marginais.","B) A fuligem extermina os esporos de fungos aéreos de forma letal definitiva, erradicando a tuberculose passiva inerte oca paralela remota nas cidades do interior rústico orgânico.","C) A seca e a fumaça ressecam os reservatórios domésticos de água, gerando uma mortalidade massiva nas larvas do Aedes e encerrando os surtos de Zika vírus no segundo semestre inativo cível maciço puro liso.","D) O material particulado tóxico agrava severamente as doenças respiratórias crônicas (como asma e DPOC) e interage sinergicamente com viroses sazonais, superlotando UPAs e exigindo campanhas agressivas de umidificação e restrição ao ar livre nas comunidades.","E) As queimadas promovem a limpeza térmica orgânica do solo nordestino estático, o que impede a proliferação secular secular do Trypanosoma cruzi limítrofe ativo nas aldeias cegas passivas pátrias rústicas densas."], resposta_correta:3, explicacao:"A alternativa D está correta. O fenômeno real da fuligem das queimadas da Amazônia cobrindo outras regiões do país (corredor de fumaça) exacerba internações por problemas respiratórios, sobrecarregando a emergência dos hospitais no interior. A INETE utiliza esse tema para atrelar um dano macroambiental a uma crise micro-hospitalar de uma UPA local. As opções A e B são grotescas (sugerem que respirar fumaça faz bem à saúde ou cura tuberculose).", status:0, historico:0 },
{id:3149, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Nos últimos anos, os serviços de vigilância zoosanitária no Brasil emitiram alertas sobre surtos urbanos de Esporotricose, uma micose subcutânea que tem alarmado tutores de pets. Frente ao conceito de Saúde Única e determinantes socioambientais, a proliferação expressiva dessa doença negligenciada ocorre prioritariamente por:", imagem:null, alternativas:["A) O crescimento desordenado de populações de felinos semi-domiciliados (gatos com acesso livre à rua) interagindo com material em decomposição e lixo nas periferias urbanas, o que dissemina o fungo rapidamente entre animais e, em seguida, para seus donos por meio de arranhões agudos.","B) A transmissão direta de porcos criados soltos no asfalto litorâneo inócuo cível, cujo suor fétido puritano estático pacífico repassa a bactéria por via aérea densa maciça.","C) O excesso de vacinas antirrábicas vencidas que sofreram mutação e ativaram fungos hospedeiros nos cães de raça pura das metrópoles rústicas orgânicas ativas refratárias isoladas passivas limpas marginais limítrofes.","D) A proibição governamental total da castração de gatos, medida assinada pela defesa civil para incentivar a predação de aranhas marrons ativas inertes paralelas rústicas oco cegas remotas rústicas orgânicas inativas.","E) A total ausência do fundo de participação orgânica municipal rural, que cortou as verbas para compra de chumbinho e armadilhas letais legalizadas densas de extermínio animal limpo contínuo pacato fétido pátria refratário puro liso maciço isolado inócuo ativo estático cível."], resposta_correta:0, explicacao:"A alternativa A está correta. A Esporotricose felina é uma epidemia real em avanço no Brasil (doença do gato). Gatos soltos na rua brigam e espalham o fungo 'Sporothrix', transmitindo depois para o tutor ao serem acariciados (arranhão/mordida). É um claro exemplo de Saúde Única (homem + animal + descaso com lixo). A banca tenta confundir com opções violentas (E - extermínio legalizado com chumbinho, crime ambiental federal) ou mutações fantasiosas de vacina (C).", status:0, historico:0 },
{id:3150, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A inserção domiciliar do Agente de Endemias proporciona uma leitura única das vulnerabilidades da comunidade. Caso, durante o LIRAa (Levantamento de Índice Rápido), o Agente perceba indícios claros de negligência infantil extrema ou marcas de agressão física na dona de casa (violência doméstica), o princípio da Intersetorialidade das políticas públicas orienta que ele deve:", imagem:null, alternativas:["A) Interromper a inspeção larval, algemar o agressor em flagrante delito sanitário com uso de força letal rústica pacífica estática densa oco pura cível e confiscar as chaves do imóvel refratário liso isolado limítrofe ativo inativo.","B) Ignorar deliberadamente os fatos, uma vez que sua atribuição constitucional se restringe com exclusividade militar orgânica à contagem biológica das pupas do Culex, sob pena de demissão por quebra de jurisdição ativa limpa passiva maciça.","C) Reportar o cenário, preservando o sigilo e a segurança das vítimas, para a rede de proteção social do município (como o Conselho Tutelar, CRAS/CREAS ou coordenação da UBS), demonstrando que o SUS atua de forma ampliada além do aspecto biomédico restrito do vetor.","D) Deixar uma notificação extrajudicial impressa na porta principal exigindo a pacificação familiar, sob ameaça de corte do fornecimento de água potável no bairro periférico puritano remoto marginal denso rústico.","E) Fotografar ostensivamente os hematomas com o tablet institucional e postar publicamente nas redes sociais da prefeitura para causar constrangimento pedagógico passivo cego litorâneo inócuo estático ativo paralelo fétido orgânico maciço puro."], resposta_correta:2, explicacao:"A alternativa C está correta. A banca exige que o candidato entenda a Intersetorialidade (conversa entre a Saúde, a Assistência Social e a Segurança). O agente público não deve omitir situações de crime contra vulneráveis (violência doméstica/infantil), devendo acionar a rede (CRAS/Conselho) sem se colocar em risco. A alternativa B descreve um profissional cego para os problemas sociais (omissão). A opção A transforma o ACE em polícia tática, e a E descreve um crime cibernético e quebra de sigilo por parte do agente.", status:0, historico:0 },
{id:3151, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Com os cofres estrangulados, pequenos municípios baianos muitas vezes não conseguem comprar sozinhos maquinários pesados (carros UBV fumacê) ou manter centrais logísticas regionais de epidemiologia e ambulatórios de especialidade. Para superar esse teto financeiro garantindo o pacto federativo, qual é o mecanismo jurídico associativo de gestão estratégica frequentemente adotado pelos prefeitos da mesma região?", imagem:null, alternativas:["A) A decretação do Regime Monárquico de Exceção Litorânea, que permite saques emergenciais pátrios no Fundo Monetário Internacional ativo inativo paralelo isolado denso cego orgânico liso rural.","B) A formação de Consórcios Públicos Intermunicipais de Saúde, onde municípios vizinhos somam recursos e rateiam despesas para adquirir maquinários, policlínicas ou serviços de vigilância complexos que seriam insustentáveis individualmente.","C) O financiamento isolado mediante milícias orgânicas locais pacatas densas marginais cíveis, que impõem taxas extorsivas à população refratária limpa para comprar inseticida puritano oco ativo pacífico rústico moroso.","D) A estadualização forçada e unilateral das secretarias de obras passivas densas puras maciças limítrofes inócuas, extinguindo para sempre a figura política do prefeito remoto inativo estático.","E) A terceirização irrestrita de 100% da vigilância para a rede de farmácias privadas, destruindo o princípio da equidade estática orgânica passiva ativa litorânea fétida rasa pacífica limítrofe cível orgânica densa rústica."], resposta_correta:1, explicacao:"A alternativa B está correta. Os 'Consórcios Intermunicipais de Saúde' (como as Policlínicas Regionais da Bahia) são fundamentais para baratear custos. Se a cidade de Bonito for pequena demais para manter certos equipamentos sozinha, ela se junta a outras 5 cidades, forma um Consórcio, e todos usam e pagam uma parte. A alternativa E cita destruição do SUS. As outras alternativas viajam em terminologias políticas distópicas para gerar volume falso.", status:0, historico:0 },
{id:3152, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A 'Transição Nutricional' é um dos mais graves desafios contemporâneos e atua como fator indireto de complicação para surtos de doenças transmissíveis no Brasil. Considerando o panorama alimentar brasileiro, avalie os enunciados abaixo:I - Houve uma queda vertiginosa nos índices de desnutrição clássica, mas explodiu o crescimento do sobrepeso e obesidade na população de baixa renda. II - O alto consumo subsidiado de alimentos ultraprocessados pobres em nutrientes contribui para um estado inflamatório crônico, piorando desfechos clínicos em pacientes infectados por vírus emergentes. III - A obesidade funciona como um forte fator imunoprotetor, impedindo as mortes por Covid-19 e reduzindo as hemorragias da Dengue hemorrágica clássica. A alternativa que valida a realidade nutricional do SUS é:", imagem:null, alternativas:["A) F, F, V.","B) V, F, V.","C) F, V, F.","D) V, V, F.","E) V, V, V."], resposta_correta:3, explicacao:"A alternativa D está correta. A INETE cobra a compreensão da 'Transição Nutricional':saímos do país que passava fome sistêmica na década de 80 para um país que sofre epidemia de obesidade, movida a salsicha e miojo (ultraprocessados) em populações carentes (item I e II estão corretos). O item III é escandalosamente Falso:a obesidade agrava e muito o quadro de viroses severas, gerando tempestades inflamatórias em doentes com Dengue/Covid, jamais funcionando como 'imunoprotetor'.", status:0, historico:0 },
{id:3153, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Com o advento da globalização avançada, o fluxo aéreo e marítimo no estado da Bahia ampliou as ameaças epidêmicas globais. No tocante ao papel tático de barreira contra a introdução de novos vetores e cepas patogênicas no interior, a vigilância de portos, aeroportos e fronteiras (VigiPAF) se faz indispensável porque:", imagem:null, alternativas:["A) Os aviões de carga neutralizam termicamente 100% dos microorganismos passivos durante os voos de cruzeiro pacatos litorâneos rústicos densos marginais refratários limpos.","B) A inspeção aeroportuária foca exclusivamente na tributação fiscal de cosméticos puros cíveis importados inativos paralelos rústicos marginais remotos densos ocos.","C) Garante a deportação em massa de todos os migrantes ativos refratários com febre, anulando direitos humanos em prol da saúde biológica pacífica maciça pura limítrofe estática orgânica.","D) Permite que a alfândega injete vacinas de fase de teste em todos os turistas litorâneos fétidos inócuos ativos limpos passivos densos cegos pátrias rústicas.","E) Um indivíduo infectado, ou mesmo vetores vivos acondicionados acidentalmente em contêineres e bagagens, podem viajar de um continente asiático ou africano para o Nordeste brasileiro em tempo menor do que o período de incubação da doença, deflagrando surtos silenciosos rapidamente."], resposta_correta:4, explicacao:"A alternativa E está correta. O papel da VigiPAF (Vigilância de Portos e Aeroportos) operada pela ANVISA e SUS local é exatamente conter o 'passageiro cavalo de troia':a pessoa contrai a doença lá fora e embarca no avião ainda saudável (período de incubação). Quando ela pousa e viaja para o interior, os sintomas começam e o vírus se espalha num local onde a população é vulnerável. O distrator C ataca os direitos humanos (deportação sumária).", status:0, historico:0 },
{id:3154, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A Febre Maculosa Brasileira (FMB) demonstrou casos dramáticos de letalidade recente no país. Observando o perfil espacial da doença, qual é o principal motor imobiliário e ambiental contemporâneo que tem colocado populações de alto poder aquisitivo na rota da picada do 'carrapato-estrela' hospedeiro da bactéria Rickettsia rickettsii?", imagem:null, alternativas:["A) A expansão de condomínios horizontais de luxo, clubes de golfe e resorts para dentro de áreas de mata nativa, o que intensifica o contato lúdico dos moradores com a flora silvestre e hospedeiros amplificadores urbanizados, como as capivaras.","B) A verticalização massiva (construção de prédios de 50 andares) nos grandes centros, o que atrai carrapatos refratários estáticos para o topo das coberturas fétidas orgânicas.","C) O financiamento público restrito à construção de moradias populares em encostas litorâneas puritanas rústicas marginais ativas densas isoladas limítrofes.","D) A proibição de cultivo de soja transgênica paralela inativa maciça pátria passiva, que forçou o carrapato cego a migrar para a corrente sanguínea de peixes pacatos ocos puros cegos estáticos.","E) O recuo progressivo e voluntário do agronegócio ativo pacífico limpo, devolvendo fazendas cíveis inócuas marginais densas rústicas à natureza intocada limítrofe rústica."], resposta_correta:0, explicacao:"A alternativa A está correta. Questão sobre o surto recente de Febre Maculosa (que ceifou vidas em SP e região). O problema central é a expansão imobiliária de condomínios de luxo na beira de lagos e matas. O rico vai morar na área verde, onde a capivara (cheia de carrapato-estrela) circula tranquilamente pelos gramados. A INETE mostra que surtos de zoonoses não ocorrem apenas na pobreza, mas dependem das intervenções antrópicas em áreas verdes.", status:0, historico:0 },
{id:3155, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"No rastro das fortes enchentes e desastres climáticos, o Agente de Combate às Endemias é deslocado como tropa de choque preventivo. Nas semanas subsequentes ao recuo das águas barrentas, ele inicia a distribuição intensa e instrução de uso de frascos de Hipoclorito de Sódio a 2,5% nas comunidades rurais baianas e periféricas afetadas. Essa tática urgente objetiva:", imagem:null, alternativas:["A) Clorar o ar atmosférico passivo inativo puro, erradicando a tuberculose pulmonar estática densa marginal cível através da inalação química orgânica pátria cega refratária pacata ativa limítrofe.","B) Provocar o envenenamento seletivo de anfíbios rústicos ocos densos fétidos limpos, para que não invadam as propriedades orgânicas isoladas pacíficas puritanas.","C) Garantir a desinfecção rápida e domiciliar da água turva destinada ao consumo humano e lavagem de alimentos, prevenindo surtos explosivos de doenças de veiculação hídrica (como Cólera, Hepatite A e Diarreias Agudas) causados pelo colapso do saneamento nas áreas alagadas.","D) O uso de radiação gama portátil pelo Agente em praças secas litorâneas inativas para purificar fétidos inertes puros passivos maciços cegos contínuos rústicos isolados.","E) Esterilizar o genoma do mosquito da Malária densa ativa estática paralela pura limpa rústica marginal pacata limítrofe inativa rural orgânica passiva fétida."], resposta_correta:2, explicacao:"A alternativa C está correta. Após enchentes, a rede de água rompe ou a caixa d'água enche de lama e esgoto. A pessoa precisa beber água, então o SUS envia frascos de Hipoclorito (cloro) para que as famílias pinguem na água (duas gotas por litro) antes de beber/cozinhar, matando as bactérias das fezes e evitando surtos mortais de diarreia em crianças. O distrator A inventa um pó inalável para o ar. As alternativas D e E contêm jargões disformes (radiação gama portátil) para esgotar o candidato.", status:0, historico:0 },
{id:3156, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A espinha dorsal que mantém o Agente de Endemias na rua e as UPAs funcionando provém do financiamento. O Repasse 'Fundo a Fundo' ocorre do Fundo Nacional de Saúde (FNS) diretamente para os Fundos Estaduais e Municipais. Qual é a premissa administrativa que pauta o cálculo do rateio desse valioso recurso entre os entes da federação na atual legislação do SUS?", imagem:null, alternativas:["A) A distribuição baseia-se num rateio perfeitamente igualitário matemático, onde São Paulo capital recebe exatamente a mesma quantia financeira em reais que a cidade de Bonito/BA refratária limpa pacata orgânica densa passiva ativa puro cego.","B) A alocação de valores obedece a critérios pactuados, como o perfil demográfico, o perfil epidemiológico (doenças prevalentes na região), a rede de serviços instalada e o desempenho das metas de saúde, concretizando o princípio da Equidade financeira.","C) O financiamento é definido por sorteios anuais cíveis na Loteria Federal inativa paralela isolada orgânica litorânea rústica maciça pátria marginal limítrofe remoto.","D) O rateio é ditado exclusivamente pelo Banco Mundial estático denso puro passivo inócuo, que confisca as verbas se a cidade baiana fétida ativa rústica não cobrar pelas consultas médicas oca limpa.","E) O recurso é travado em contas offshore no exterior refratário pacífico marginal denso contínuo cego rústico inativo isolado limítrofe ativo puro orgânico liso pacato denso maciço."], resposta_correta:1, explicacao:"A alternativa B está correta. A INETE cobra a diferença entre igualdade e equidade no cofre público. O Ministério da Saúde não divide o bolo fatiando pedaços idênticos para todos (isso geraria um desastre, a opção A descreve essa falácia matemática). O rateio fundo a fundo usa critérios:se a cidade tem mais velhos, recebe para tratar DCNT; se tem surto de dengue histórico, recebe mais verba de vigilância (perfil epidemiológico e demográfico).", status:0, historico:0 },
{id:3157, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Políticas de proteção e repasse financeiro, como o Programa Bolsa Família, não operam isoladas da Vigilância Sanitária. O programa possui fortes 'condicionalidades' impostas às famílias vulneráveis beneficiárias. Qual a contrapartida exigida pelo programa social que mais fortalece e auxilia as ações preventivas do SUS municipal baiano contra surtos locais?", imagem:null, alternativas:["A) A obrigação de que cada família pobre hospede agentes de pesquisa clínica internacional na própria residência cível ativa litorânea rústica densa marginal pacata orgânica remota.","B) O compromisso restrito de matricular as crianças do sexo masculino no exército ativo refratário limpo denso paralelo fétido rústico isolado puro maciço inócuo.","C) O dever de comprar medicamentos tarja preta exclusivamente nas farmácias estatais cegas passivas oco inativas densas limítrofes rústicas contínuas.","D) A exigência rigorosa de cumprimento e atualização do calendário vacinal das crianças, o acompanhamento do estado nutricional e a realização do pré-natal pelas gestantes, o que ancora a família dentro da Unidade Básica de Saúde e eleva as barreiras imunológicas da comunidade.","E) A proibição contratual de residir em casas de taipa fétidas ativas pacíficas marginais puras densas estáticas isoladas orgânicas pátrias liso refratário remoto limpo cego."], resposta_correta:3, explicacao:"A alternativa D está correta. As 'condicionalidades' em saúde do Bolsa Família obrigam as mães a pesarem e vacinarem as crianças na UBS para não perderem o benefício. Isso foi a grande jogada inteligente de políticas públicas do Brasil:atrelar a renda básica à saúde preventiva, blindando crianças de sarampo e poliomielite. A alternativa E aponta uma crueldade ilógica (proibir alguém pobre de morar no único lugar que ele consegue).", status:0, historico:0 },
{id:3158, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A transição demográfica brasileira indica um rápido envelhecimento populacional. No planejamento orçamentário e clínico da secretaria de saúde, avalie a atual coexistência de patologias através do sistema V/F:I - O aumento da expectativa de vida elevou brutalmente os gastos com Doenças Crônicas Não Transmissíveis (DCNT), como diabetes e câncer. II - Esse cenário decretou o fim definitivo e comprovado das antigas Doenças Infectocontagiosas transmissíveis por vetores no Nordeste brasileiro. III - O Brasil vive uma 'dupla carga' ou 'tripla carga' de doenças, onde o sistema simultaneamente combate infartos infartos complexos e corre para pulverizar bairros inteiros devido ao recrudescimento da Chikungunya e Dengue. A matriz gabaritada das afirmações aponta para:", imagem:null, alternativas:["A) V, F, V.","B) F, V, F.","C) V, V, F.","D) F, F, V.","E) F, V, V."], resposta_correta:0, explicacao:"A alternativa A está correta. O item I é verdadeiro (envelhecimento traz DCNT). O erro crucial está no item II:As doenças infectocontagiosas (Dengue, Malária, Tuberculose) NÃO acabaram. Pelo contrário, elas coexistem e causam surtos anuais. O item III é verdadeiro e define a tragédia clínica brasileira:o SUS tem a 'dupla carga' de atuar como país rico (câncer/infarto) e país subdesenvolvido (dengue/cólera) ao mesmo tempo, esticando o orçamento ao máximo.", status:0, historico:0 },
{id:3159, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Ao planejar um bloqueio geográfico de nebulização costal e educação ambiental na cidade, o gestor de endemias da prefeitura depara-se com conceitos norteadores. A literatura sanitarista contemporânea estabelece um claro divisor analítico entre o simples 'perigo químico' e o que efetivamente constitui o 'Risco Epidemiológico'. O que caracteriza tecnicamente o conceito de 'Risco Epidemiológico' em uma determinada localidade baiana?", imagem:null, alternativas:["A) É o pânico infundado difundido pela mídia televisiva fétida limítrofe ativa rural pacífica rústica densa puritana limpa orgânica marginal cível cega paralela.","B) É a medida estática e imutável que isenta os cidadãos de pagarem impostos pátrios inócuos ativos densos litorâneos rústicos maciços puros inertes.","C) Corresponde à probabilidade real ou chance de ocorrência de um determinado evento adverso à saúde (doença, óbito) em uma população específica num dado período, mensurada pelo cruzamento da vulnerabilidade social do bairro, clima, e da presença histórica do agente patogênico no ambiente.","D) Refere-se à blindagem espiritual refratária isolada passiva oco contínua estática remota pacata densa pura liso das comunidades carentes perante o avanço mecânico dos vírus sintéticos importados fétidos rústicos ativos limítrofes orgânicos paralelos.","E) Ocorre apenas quando um lote de vacinas apodrece ativamente no almoxarifado pacato denso rural puro inativo limpo refratário maciço orgânico passivo cego."], resposta_correta:2, explicacao:"A alternativa C está correta. A banca exige conceitos teóricos da epidemiologia. 'Risco Epidemiológico' não é apenas a presença do mosquito (perigo ambiental). O risco é a 'chance/probabilidade' matemática real daquela população adoecer, considerando seus determinantes sociais (ex:falta saneamento? O morador entende de saúde? Choveu muito?). É o cruzamento de variáveis biológicas e humanas. Os demais distratores utilizam longas formações aleatórias lexicais sem sentido para cansar o candidato (tática de exaustão da INETE).", status:0, historico:0 },
{id:3160, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A atual legislação consolidou a integração das frentes de trabalho nas Unidades Básicas de Saúde, aproximando visceralmente a Estratégia Saúde da Família (ESF) da Vigilância em Saúde. No cenário de mapeamento do microterritório em um bairro irregular de Bonito/BA, como se deve dar a sinergia entre o Agente Comunitário de Saúde (ACS) e o Agente de Combate às Endemias (ACE)?", imagem:null, alternativas:["A) O ACE deve assumir o papel de médico prescritor refratário rústico denso, emitindo receitas de antibióticos ativos fétidos orgânicos pacatos isolados paralelos puros.","B) O território de atuação deve ser compartilhado e reconhecido por ambos; enquanto o ACE foca no combate e identificação de vetores ambientais, ele troca dados diários com o ACS, alertando-o sobre áreas de lixão de risco ou imóveis com foco de endemias onde residem grupos vulneráveis identificados pelo ACS (como gestantes ou idosos acamados).","C) A legislação proíbe a comunicação verbal entre as categorias durante o horário de expediente pacífico litorâneo limítrofe rural estático cego inócuo marginal passivo maciço orgânico denso.","D) O ACS deve realizar as medições geológicas rasas ativas rústicas limpas fétidas puritanas inativas, deixando a vacinação de pets para o engenheiro civil pátrio remoto inativo oco liso.","E) Ambos foram fusionados legalmente em uma única pessoa que realiza cirurgias estéticas cíveis isoladas pacatas refratárias densas ativas orgânicas marginais limítrofes puras no quintal barrento."], resposta_correta:1, explicacao:"A alternativa B está correta. A integração ACE/ACS é o coração da atenção primária atual. Eles andam juntos no mesmo território. O ACE olha para o ambiente (caixa d'água, ralo, terreno baldio) e o ACS olha para o indivíduo (grávida, hipertenso, diabético). Eles trocam dados para proteger os mais fracos de infecções graves em áreas infestadas. As alternativas A, D e E descrevem exercícios ilegais de profissão ou desvio brutal de função.", status:0, historico:0 },
{id:3161, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Durante o desenvolvimento de um sistema informatizado de tramitação de processos administrativos na UFBA, a equipe de Analistas de TI precisa parametrizar o fluxo de abertura e movimentação processual em conformidade com os princípios da oficialidade (ou impulso oficial), do formalismo moderado e da verdade material, previstos na Lei nº 9.784/1999. Acerca da aplicação desses princípios no processo administrativo federal, assinale a alternativa correta.", imagem:null, alternativas:["A) Pelo princípio da inércia processual aplicável à Administração Pública, o processo administrativo somente pode ser instaurado mediante provocação formal do interessado, embora a sua impulsão posterior ocorra de ofício pelo sistema.", "B) O princípio do formalismo moderado impõe a adoção de formas simples, suficientes para propiciar adequado grau de certeza, segurança e respeito aos direitos dos administrados, vedada a exigência de reconhecimento de firma, salvo imposição legal ou dúvida de autenticidade.", "C) Em decorrência do princípio da verdade formal estrita, a autoridade julgadora no processo administrativo está adstrita unicamente às provas documentais juntadas pelo requerente no momento do protocolo inicial, sendo ilícita a produção de provas de ofício.", "D) Caso o interessado desista expressamente de seu pedido ou renuncie a direito disponível no sistema eletrônico, o princípio da oficialidade impede a extinção do processo, obrigando a Administração a prosseguir no feito em toda e qualquer hipótese.", "E) A cobrança de taxas processuais e de caução prévia como condição para o protocolo eletrônico de recursos administrativos encontra amparo no princípio da eficiência arrecadatória e da oficialidade."], resposta_correta:1, explicacao:"A alternativa B está correta. Fundamentação: O princípio do formalismo moderado (ou informalismo em favor do administrado) está positivado no art. 2º, parágrafo único, incisos VIII e IX, e no art. 22, caput e § 2º, da Lei nº 9.784/1999, determinando a observância das formalidades essenciais à garantia dos direitos dos administrados e a adoção de formas simples, dispensando reconhecimento de firma salvo imposição legal ou dúvida de autenticidade. Análise das incorretas: A é inválida em 'somente pode ser instaurado mediante provocação formal do interessado' (pelo princípio da oficialidade, art. 5º e art. 2º, parágrafo único, XII, da Lei 9.784/99, o processo administrativo pode iniciar-se de ofício ou a pedido de interessado, sem prejuízo da atuação de ofício na impulsão); C é inválida em 'verdade formal estrita' e 'sendo ilícita a produção de provas de ofício' (no processo administrativo vigora o princípio da verdade material/real, podendo a Administração determinar diligências e provas de ofício); D é inválida em 'impede a extinção do processo, obrigando a Administração a prosseguir... em toda e qualquer hipótese' (segundo o art. 51, § 2º, da Lei 9.784/99, o prosseguimento de ofício após desistência só ocorre se a Administração considerar que o interesse público assim o exige); E é inválida em 'cobrança de taxas processuais e de caução prévia como condição para o protocolo eletrônico de recursos' (viola o princípio da gratuidade, art. 2º, parágrafo único, XI, da Lei 9.784/99, e a Súmula Vinculante nº 21 do STF). Comentário Avalia: Excelente conexão entre a parametrização de sistemas eletrônicos de processo (SEI/SIPAC) e os princípios da Lei nº 9.784/1999.", status:0, historico:0},
{id:3162, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O debate sobre a tese do Marco Temporal tem mobilizado os poderes da República e acirrado disputas territoriais no campo brasileiro. Essa tese jurídica, que opõe ruralistas e povos originários, fundamenta-se na premissa de que a demarcação de terras indígenas deve ser restrita às áreas que:", imagem:null, alternativas:["A) comprovadamente já eram habitadas e reivindicadas por essas populações na data da promulgação da Constituição de 1988.","B) foram historicamente mapeadas pela Coroa Portuguesa durante o período colonial como de posse imemorial das tribos isoladas.","C) sofreram algum tipo de impacto ambiental irreversível provocado pela expansão do agronegócio na década de noventa.","D) abrigam recursos minerais estratégicos para a união, independentemente do período de ocupação tradicional atestado pelos órgãos.","E) tiveram seus processos de homologação concluídos antes do estabelecimento do regime militar no território nacional."], resposta_correta:0, explicacao:"A alternativa A está correta. A tese do Marco Temporal estabelece o dia 5 de outubro de 1988 como data limite para a comprovação da ocupação indígena, prejudicando etnias que foram expulsas antes dessa data. A INETE costuma cobrar a compreensão exata do conceito jurídico por trás das disputas atuais. O distrator B inverte o recorte temporal para o período colonial, enquanto o distrator E restringe ao período anterior ao regime militar, criando marcos temporais fictícios e inválidos.", status:0, historico:0 },
{id:3163, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"A violação aos princípios da Administração Pública e a prática de atos de improbidade administrativa atraem severas consequências no plano constitucional e legal. Considerando o disposto no art. 37, §§ 4º e 5º, da Constituição Federal e a jurisprudência do Supremo Tribunal Federal acerca da prescrição das ações de ressarcimento ao erário, assinale a alternativa correta.", imagem:null, alternativas:["A) Os atos de improbidade administrativa importarão a cassação definitiva dos direitos políticos, a perda da função pública, o confisco geral de bens e o ressarcimento ao erário, na forma e gradação previstas em lei, prejudicando a propositura de ação penal pelos mesmos fatos.", "B) As sanções constitucionais por ato de improbidade administrativa restringem-se exclusivamente aos servidores públicos estatutários ocupantes de cargo efetivo, não alcançando particulares que concorram para a prática do ilícito ou dele se beneficiem.", "C) Segundo o Supremo Tribunal Federal, são imprescritíveis as ações de ressarcimento ao erário fundadas na prática de ato doloso tipificado na Lei de Improbidade Administrativa, ao passo que é prescritível a ação de reparação de danos à Fazenda Pública decorrente de ilícito civil.", "D) O princípio da moralidade administrativa, quando violado de forma meramente culposa por um Analista de TI que comete erro técnico escusável na configuração de um servidor, configura ato de improbidade administrativa que atenta contra os princípios da Administração Pública.", "E) A perda da função pública e a suspensão dos direitos políticos decorrentes de condenação por improbidade administrativa são autoaplicáveis pela autoridade administrativa superior ao término de sindicância sumária, independentemente de processo judicial."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: Interpretando o art. 37, § 5º, da CF/88, o STF fixou no Tema 897 da Repercussão Geral (RE 852.475) que 'São imprescritíveis as ações de ressarcimento ao erário fundadas na prática de ato doloso tipificado na Lei de Improbidade Administrativa', e no Tema 666 (RE 669.069) que 'É prescritível a ação de reparação de danos à Fazenda Pública decorrente de ilícito civil'. Análise das incorretas: A é inválida em 'cassação definitiva dos direitos políticos', 'confisco geral de bens' e 'prejudicando a propositura de ação penal' (o art. 37, § 4º, da CF/88 prevê suspensão dos direitos políticos, indisponibilidade dos bens e ressarcimento ao erário, sem prejuízo da ação penal cabível, sendo vedada a cassação de direitos políticos pelo art. 15 da CF/88); B é inválida em 'restringem-se exclusivamente aos servidores públicos estatutários' (o art. 3º da Lei 8.429/92 alcança particulares que induzam ou concorram dolosamente para o ato); D é inválida em 'violado de forma meramente culposa... configura ato de improbidade' (com as alterações da Lei 14.230/2021 na Lei 8.429/92 e a jurisprudência do STF, todo ato de improbidade exige dolo, não mais existindo improbidade culposa); E é inválida em 'autoaplicáveis pela autoridade administrativa... independentemente de processo judicial' (a suspensão dos direitos políticos e as sanções da LIA dependem de trânsito em julgado de sentença judicial). Comentário Avalia: Trocar 'suspensão' por 'cassação' dos direitos políticos no art. 37, § 4º, da CF/88 e cobrar o Tema 897 do STF são marcas registradas em provas de Direito Administrativo.", status:0, historico:0},
{id:3164, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O conflito bélico no leste europeu gerou ondas de choque na balança comercial brasileira, evidenciando vulnerabilidades estratégicas da economia. Julgue a validade das proposições a seguir sobre os reflexos dessa crise geopolítica no Brasil. () A alta dependência estrutural do agronegócio brasileiro em relação aos fertilizantes importados, sobretudo os nitrogenados e potássicos, tornou o setor altamente vulnerável ao cenário militar russo. () Como retaliação diplomática imediata, o governo brasileiro suspendeu integralmente as exportações de commodities agrícolas para os membros da União Europeia. () A instabilidade energética global desencadeada pelo conflito favoreceu temporariamente o Brasil ao atrair investimentos externos para matrizes renováveis alternativas. O julgamento técnico preciso estabelece a sequência:", imagem:null, alternativas:["A) F, F, V.","B) V, V, F.","C) F, V, V.","D) V, F, F.","E) V, F, V."], resposta_correta:4, explicacao:"A alternativa E está correta. O primeiro item é verdadeiro, pois o Brasil importa a vasta maioria de seus fertilizantes, sendo a Rússia um parceiro central da cadeia. O segundo item é falso, o erro reside na suspensão integral das exportações, pois o Brasil adotou postura de neutralidade e não aplicou sanções aos europeus. O terceiro item é verdadeiro, a crise acelerou a busca global por energia verde. A banca explora o princípio de causa e efeito das commodities na diplomacia.", status:0, historico:0 },
{id:3165, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"A Emenda Constitucional nº 19/1998 introduziu importantes mecanismos voltados à concretização dos princípios da eficiência, da publicidade e do controle social, disciplinando no art. 37, § 3º, da Constituição Federal a participação do usuário na administração pública direta e indireta. Considerando o referido dispositivo constitucional e os princípios aplicáveis aos serviços públicos, analise os itens a seguir: I. A lei disciplinará as formas de participação do usuário na administração pública direta e indireta, regulando especialmente as reclamações relativas à prestação dos serviços públicos em geral, asseguradas a manutenção de serviços de atendimento ao usuário e a avaliação periódica, externa e interna, da qualidade dos serviços. II. A participação do usuário abrange a regulamentação do acesso a registros administrativos e a informações sobre atos de governo, respeitados a intimidade, a vida privada, a honra e a imagem das pessoas, bem como as informações cujo sigilo seja imprescindível à segurança da sociedade e do Estado. III. Compete à lei regular a disciplina da representação contra o exercício negligente ou abusivo de cargo, emprego ou função na administração pública, fortalecendo o controle social sob a égide dos princípios da moralidade e da eficiência. Está correto o que se afirma em:", imagem:null, alternativas:["A) I e II, apenas.", "B) II e III, apenas.", "C) I e III, apenas.", "D) I, apenas.", "E) I, II e III."], resposta_correta:4, explicacao:"A alternativa E está correta. Fundamentação: Os itens I, II e III reproduzem com exatidão conceitual e normativa o caput e os incisos I, II e III do § 3º do art. 37 da CF/88 (com remissão aos incisos X e XXXIII do art. 5º da CF/88), regulamentados no plano infraconstitucional pela Lei de Acesso à Informação (Lei nº 12.527/2011) e pelo Código de Defesa dos Usuários de Serviços Públicos (Lei nº 13.460/2017). Análise das incorretas: As alternativas A, B, C e D são incorretas por excluírem pelo menos uma das assertivas inteiramente verdadeiras. Comentário Avalia: A banca costuma cobrar a literalidade estruturada do art. 37, § 3º, da CF/88 em questões de proposições múltiplas (I, II e III), onde todas as afirmativas estão corretas.", status:0, historico:0},
{id:3166, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O posicionamento diplomático brasileiro frente ao recrudescimento do conflito no Oriente Médio reflete sua tradição nos fóruns multilaterais. Assumindo a presidência rotativa do Conselho de Segurança da ONU durante a crise no final de 2023, o esforço diplomático imediato do Brasil caracterizou-se pela:", imagem:null, alternativas:["A) submissão formal aos vetos prévios das potências ocidentais para assegurar a manutenção de acordos comerciais bilaterais de livre trânsito marítimo no mediterrâneo.","B) proposição de resoluções focadas na abertura de corredores humanitários, condenação de ataques a civis e reiteração da defesa histórica da solução de dois estados soberanos.","C) ruptura imediata das relações diplomáticas e consulares com as nações envolvidas no confronto armado como forma de pressionar por um cessar-fogo unilateral monitorado.","D) liderança na formação de uma coalizão militar de paz composta exclusivamente por forças da América do Sul para intervir de forma presencial nas áreas de fronteira disputadas.","E) adoção de um protocolo de isolacionismo radical fundamentado no princípio da não intervenção, retirando seus embaixadores da sede central da organização das nações unidas."], resposta_correta:1, explicacao:"A alternativa B está correta. O Itamaraty pautou-se pela tradição:priorizou a proteção de civis (corredores humanitários) e reforçou o apoio à criação do Estado Palestino coexistindo pacificamente com Israel. O erro da alternativa C é a 'ruptura', pois o Brasil mantém embaixadas ativas para não perder o canal de diálogo. A alternativa E confunde isolacionismo alienado com a diplomacia ativa de não-intervenção militar do Estado brasileiro.", status:0, historico:0 },
{id:3167, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O estado da Bahia tem figurado no epicentro dos debates sobre segurança pública devido ao avanço dos índices de criminalidade violenta. Sobre a interiorização das dinâmicas criminais e a guerra de facções no território baiano, avalie as afirmativas. I - A fragmentação de grupos locais e a fixação de facções de atuação nacional originárias do sudeste acirraram as disputas territoriais e rotas de escoamento logístico. II - A letalidade nas intervenções das forças de segurança estaduais apresentou uma redução estrutural drástica decorrente da implementação massiva de câmeras corporais em toda a tropa de choque. III - A capilaridade das grandes organizações criminosas alcançou áreas rurais e municípios de pequeno porte que anteriormente não registravam homicídios ligados à disputa pelo controle do tráfico de narcóticos. A precisão conjuntural verifica-se em:", imagem:null, alternativas:["A) I e II.","B) I e III.","C) II e III.","D) Apenas I.","E) I, II e III."], resposta_correta:1, explicacao:"A alternativa B está correta. As afirmativas I e III expõem o atual conflito:as megafacções desceram para a Bahia, dividiram o estado e empurraram a violência para municípios pacatos do interior. O erro fatal do item II está em atestar uma redução na letalidade e o uso pleno de câmeras corporais, fatos que contradizem violentamente os relatórios do Fórum Brasileiro de Segurança Pública, que posicionam a corporação local entre as mais letais e com atrasos na adoção das câmeras.", status:0, historico:0 },
{id:3168, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A explosão de casos de dengue no cenário nacional consolida-se como um complexo conflito socioambiental. Julgue as correlações técnicas entre as variações do clima, a estrutura da sociedade e a proliferação do vetor patogênico. () A intensificação de eventos climáticos extremos e o aumento anômalo das temperaturas decorrentes do fenômeno El Niño encurtam ativamente o ciclo reprodutivo do mosquito vetor. () A deficiência crônica na cobertura de saneamento básico em periferias inviabiliza o controle endêmico governamental ao manter reservatórios de armazenamento de água propícios à oviposição indiscriminada. () A transição demográfica estabilizou as taxas de infecção eliminando o risco de mortes severas ao garantir a imunidade de rebanho definitiva das populações adultas pelas variantes circulantes da última década. A avaliação analítica manifesta-se em:", imagem:null, alternativas:["A) V, F, V.","B) F, V, V.","C) V, V, F.","D) V, V, V.","E) F, F, V."], resposta_correta:2, explicacao:"A alternativa C está correta. A primeira afirmação é um fato ecológico:o calor encurta o tempo que o ovo do mosquito leva para virar adulto. A segunda expõe o drama estrutural:sem água na torneira, o cidadão estoca em baldes, criando o foco. A terceira afirmativa está radicalmente errada ao utilizar o termo 'eliminando', pois existem quatro sorotipos do vírus da dengue; a infecção por um sorotipo não confere imunidade contra os outros três, o que inviabiliza qualquer imunidade de rebanho permanente.", status:0, historico:0 },
{id:3169, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A cúpula que validou a expansão oficial do bloco BRICS reconfigurou a geometria do poder econômico e do atrito diplomático internacional. A inclusão estratégica de novos parceiros no fórum liderado por nações em desenvolvimento possui como um de seus objetivos estruturais primordiais:", imagem:null, alternativas:["A) dissolver estruturalmente a assembleia geral das Nações Unidas para criar um parlamento global único sediado em Pequim.","B) padronizar as legislações trabalhistas do hemisfério sul para evitar penalidades severas nos tribunais europeus de concorrência orgânica comercial internacional fechada.","C) instituir uma zona de livre comércio irrestrita abolindo todas as tarifas alfandegárias vigentes entre os membros originais e agregados logo na primeira fase de adaptação aduaneira pacífica.","D) promover ações voltadas à desdolarização progressiva das transações comerciais bilaterais e fortalecer canais de financiamento não subordinados a Washington.","E) consolidar legalmente uma aliança militar defensiva coesa nos mesmos moldes operacionais orgânicos da OTAN para garantir a integridade dos estreitos petrolíferos do Golfo Pérsico."], resposta_correta:3, explicacao:"A alternativa D está correta. O eixo expansionista do BRICS concentra-se no fortalecimento econômico, na busca por alternativas transacionais que reduzam o peso do Dólar (desdolarização) e no protagonismo do Novo Banco de Desenvolvimento. O distrator C confunde o bloco com uma união aduaneira ou mercado comum, ignorando que os países membros mantêm barreiras tarifárias ativas entre si. O distrator E projeta um cenário bélico fictício para um bloco focado estritamente em cooperação econômica.", status:0, historico:0 },
{id:3170, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A sequência de catástrofes climáticas que assolaram o Rio Grande do Sul escancarou o grave conflito entre o planejamento urbano engessado e as variações atmosféricas imprevisíveis. Analise as assertivas atreladas aos determinantes de vazão e contenção do desastre. I - O aquecimento anômalo das águas do oceano pacífico equatorial bloqueou o fluxo das frentes frias, estacionando volumes pluviométricos severos sobre as calhas dos rios do estado sulista. II - A supressão irrestrita de matas ciliares aliada à impermeabilização crônica do solo urbano acelerou o escoamento superficial impedindo a infiltração da água no lençol freático e suprimindo o escoamento gradual hídrico. É imperativo concluir que as dinâmicas ambientais apontam que:", imagem:null, alternativas:["A) ambas são verdadeiras e ilustram a sinergia destrutiva entre alterações climáticas globais atuando em conjunto com a degradação e o ordenamento urbano falho em escala regional.","B) apenas a I é verdadeira indicando de forma pragmática que o impacto do desastre independe estruturalmente das ações de ocupação do solo implementadas pela gestão municipal.","C) apenas a II é verdadeira uma vez que os eventos meteorológicos sazonais não guardam qualquer correlação científica provada com as oscilações térmicas das correntes marítimas periféricas.","D) ambas são falsas pois a topografia acidentada da região serrana bloqueia fisicamente a ocorrência de inundações estacionárias impedindo os alagamentos contínuos registrados nos meios de comunicação.","E) as afirmações se contradizem pois a supressão florestal descrita no item secundário atua como fator redutor de impacto nas bacias de várzea natural ao facilitar o trânsito da lâmina de água rápida."], resposta_correta:0, explicacao:"A alternativa A está correta. O desastre é multicausal:a macrocausa climática (El Niño prendendo a umidade) uniu-se à microcausa antrópica (cidades asfaltadas, matas ciliares destruídas e diques sem manutenção). Bancas complexas como a INETE cobram a correlação entre o desastre natural e a falha de mitigação governamental. A alternativa E constrói um conceito geográfico absurdamente falso, afirmando que a supressão da mata ciliar ajuda a conter inundações.", status:0, historico:0 },
{id:3171, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O conceito de 'narco-garimpo' emergiu contundentemente nos relatórios de inteligência como a nova face da criminalidade organizada embrenhada na Amazônia Legal. Esse fenômeno sociológico e logístico de usurpação ambiental define-se com acurácia na literatura de segurança por englobar a:", imagem:null, alternativas:["A) legalização progressiva de pequenas minas terrestres pelas prefeituras locais visando recolher impostos diretamente das lideranças das facções urbanas transferidas cautelarmente para o interior da zona rural limítrofe.","B) exclusão completa da atividade mineral nativa em favor do cultivo intensivo de plantas ilícitas adaptadas em áreas de floresta densa previamente derrubadas e preparadas por madeireiros irregulares rústicos da reserva agrícola passiva.","C) migração compulsória de populações ribeirinhas indígenas para atuar como mulas logísticas no tráfico internacional devido à escassez severa de ouro de aluvião nas bacias assoreadas durante longos períodos de secas provocadas.","D) associação operacional perversa onde o capital financeiro oriundo do tráfico de entorpecentes financia a infraestrutura pesada para a mineração clandestina, convertendo a terra invadida em base logística e o ouro em lastro limpo para a lavagem de dinheiro.","E) substituição padronizada do transporte fluvial silencioso de narcóticos por rotas aéreas fretadas compostas exclusivamente por aeronaves militares sucateadas adquiridas legalmente pelos consórcios rurais atrelados à federação de agricultura regional."], resposta_correta:3, explicacao:"A alternativa D está correta. O 'narco-garimpo' não significa a extinção do garimpo, mas a sua capitalização e aparelhamento pelo tráfico (PCC e Comando Vermelho). O tráfico injeta dinheiro em maquinários (escavadeiras PC) que os garimpeiros comuns não poderiam comprar e utiliza a atividade e o escoamento do ouro como mecanismo blindado de lavagem de capitais ilícitos. O distrator B suprime a mineração da definição da palavra e os demais distratores inventam mecanismos de legalização ilusórios.", status:0, historico:0 },
{id:3172, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A aprovação legislativa da Reforma Tributária propôs a resolução de um conflito federativo corrosivo travado pelas unidades da federação. Avalie as premissas estruturais atreladas à contenção da chamada Guerra Fiscal. I - A unificação contábil de impostos pulverizados nas três esferas de poder em um Imposto sobre Valor Agregado (IVA Dual) tenciona extinguir o grave efeito em cascata ou cumulatividade tributária vigente. II - O deslocamento central da cobrança do tributo que incide sobre a produção saindo do estado de origem e passando a vigorar no estado de destino anula a vantagem dos governadores em ofertar renúncias fiscais extremas para roubar parques fabris vizinhos. III - A reformulação institucional isentou de forma integral o complexo setor de serviços e consumo digital para mitigar o êxodo corporativo e compensar as prefeituras pela inevitável perda marginal de autonomia na arrecadação do ISS clássico. O esqueleto jurídico realçado conforma-se em:", imagem:null, alternativas:["A) I, II e III.","B) Apenas II e III.","C) I e II.","D) Apenas I.","E) Apenas I e III."], resposta_correta:2, explicacao:"A alternativa C está correta. Os itens I e II retratam os pilares cruciais da reforma:combater o imposto sobre imposto (I) e travar a Guerra Fiscal repassando a arrecadação para o local onde a mercadoria é consumida (destino), secando o benefício das isenções de origem. O erro do item III encontra-se no termo 'isentou de forma integral', já que o setor de serviços (advogados, escolas, planos de saúde) teve suas alíquotas debatidas, e em alguns cenários sofrerá aumento de carga em comparação ao velho regime, inexistindo isenção total garantida no texto.", status:0, historico:0 },
{id:3173, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A continuidade estrutural do colapso governamental venezuelano impõe severas tensões imigratórias à fronteira física do extremo norte do Brasil. Julgue o ordenamento prático e os impactos sociais relativos à Operação Acolhida executada nas zonas restritas limítrofes do estado de Roraima. () O processo de interiorização desenhado pela Força Tarefa Logística busca dissipar estrategicamente o fluxo migratório enviando venezuelanos para inserção trabalhista em outros estados evitando a pane imediata dos abrigos concentrados de Boa Vista. () A lei de migração brasileira pautada nos interesses mercadológicos condiciona a regularização do refugiado à exigência da apresentação e validação de diplomas de nível superior técnico estrito para bloquear as vagas periféricas primárias do mercado de trabalho baiano nacional. () Os picos crônicos de xenofobia nos municípios que absorvem a primeira onda de deslocados alimentam-se do discurso inflamatório embasado na saturação drástica da rede estrutural precarizada do SUS e das escolas municipais locais sem repasse federal extraordinário compensatório. A validação pericial confere a ordem:", imagem:null, alternativas:["A) F, F, V.","B) V, V, F.","C) V, F, V.","D) F, V, F.","E) V, F, F."], resposta_correta:2, explicacao:"A alternativa C está correta. O primeiro item é a política oficial de desafogamento das cidades fronteiriças. O segundo item é falso, posto que o Brasil não condiciona a acolhida humanitária de refugiados à capacidade acadêmica ou exigência de diploma de nível superior. O terceiro item captura a essência do conflito civil no chão de fábrica do SUS:a população local culpa a entrada desordenada de migrantes pela escassez de remédios e falta de vagas, retroalimentando tensões de aversão ao estrangeiro. A INETE sempre exige a empatia lógica das leis.", status:0, historico:0 },
{id:3174, categoria:"Conhecimentos Específicos", materia:"Vigilância Epidemiológica", assunto:"Hepatites Virais", cargo:"Agente Fiscal Vigilância Sanitária", ano:"2015", banca:"Desconhecida", concurso:"Prefeitura Municipal de Itaitinga/CE", enunciado:"A Hepatite D é uma doença infecciosa viral, contagiosa, causada pelo vírus da hepatite delta ou HDV (é um vírus RNA, podendo apresentar-se como uma infecção assintomática ou sintomática e, nesses casos, até mesmo com formas graves de hepatite), mas, que precisa do vírus de outra hepatite para que ocorra a infecção. Marque a opção CORRETA para esse vírus.", imagem:null, alternativas:["A) Vírus da Hepatite A.","B) Vírus da hepatite B.","C) Vírus da Hepatite C.","D) Vírus da hepatite E.","E) A Hepatite A não precisa de outro vírus para que ocorra."], resposta_correta:1, explicacao:"A alternativa B está correta. A engenharia virológica isolada maciça puritana do vírus da Hepatite D (Delta) carrega uma deficiência nativa peculiar crônica. Ele é um agente patógeno satélite (incompleto e defeituoso). Para conseguir invadir com sucesso litorâneo as células nobras hepáticas e reproduzir seus invólucros vitais mortais, ele atrela-se organicamente e furta invariavelmente e inegociávelmente a cápsula protetora ativada cega (antígeno de superfície HBsAg) produzida única e estritamente pelo 'Vírus da Hepatite B' para completar a replicação letal conjunta.", status:0, historico:0 },
{id:3175, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Considere que um dirigente de órgão público federal pretenda nomear o seu próprio sobrinho, engenheiro de computação com doutorado em segurança cibernética por instituição estrangeira de renome, para ocupar cargo em comissão de direção e assessoramento superior na área de Tecnologia da Informação da entidade. Considerando a Súmula Vinculante nº 13 do Supremo Tribunal Federal e os princípios constitucionais da Administração Pública, assinale a alternativa correta.", imagem:null, alternativas:["A) A elevada qualificação técnica do nomeado afasta a incidência da vedação ao nepotismo, visto que o princípio da eficiência sobrepõe-se aos princípios da impessoalidade e da moralidade nos cargos de natureza estritamente técnica.", "B) A vedação ao nepotismo na Administração Pública decorre diretamente dos princípios expressos no caput do art. 37 da Constituição Federal, prescindindo da edição de lei formal específica para coibir a nomeação de parentes até o terceiro grau.", "C) O parentesco colateral de terceiro grau, como o existente entre tio e sobrinho, não é alcançado pela Súmula Vinculante nº 13, que limita a proibição de nomeação aos parentes em linha reta e aos colaterais até o segundo grau.", "D) A proibição de nepotismo cruzado, caracterizado mediante designações recíprocas entre autoridades de órgãos distintos, exige prévia tipificação em lei complementar federal para que possa invalidar o ato de provimento.", "E) Caso a nomeação recaia sobre função de confiança, e não sobre cargo em comissão de livre provimento, deixa de incidir a vedação sumular, mesmo que o parente seja subordinado diretamente à autoridade nomeante."], resposta_correta:1, explicacao:"A alternativa B está correta. Fundamentação: Segundo o STF (RE 579.951 e Súmula Vinculante nº 13), a vedação ao nepotismo decorre diretamente dos princípios constitucionais da impessoalidade, moralidade, eficiência e isonomia (art. 37, caput, da CF/88), sendo autoaplicável e dispensando lei formal específica. O tio e o sobrinho são parentes colaterais de 3º grau, expressamente alcançados pela vedação. Análise das incorretas: A é inválida em 'afasta a incidência da vedação ao nepotismo' (a competência acadêmica do parente não convalida o nepotismo em cargos administrativos); C é inválida em 'não é alcançado pela Súmula Vinculante nº 13' (a súmula abrange parentes em linha reta, colateral ou por afinidade, até o terceiro grau, inclusive); D é inválida em 'exige prévia tipificação em lei complementar federal' (o nepotismo cruzado também é vedado diretamente pela SV 13); E é inválida em 'deixa de incidir a vedação sumular' (a SV 13 veda expressamente o exercício de cargo em comissão ou de função gratificada). Comentário Avalia: A banca testa se o candidato sabe que o parentesco entre tio e sobrinho é de 3º grau e que a SV 13 independe de lei formal.", status:0, historico:0},
{id:3176, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"No âmbito da gestão de contratos de soluções de Tecnologia da Informação na Administração Pública Federal, o princípio da publicidade cumpre dupla função: viabilizar o controle social e administrativo sobre a conduta dos gestores (transparência) e funcionar como condição de eficácia dos atos administrativos que produzem efeitos externos ou oneram o patrimônio público. Com base nesse entendimento e nas normas constitucionais sobre publicidade e sigilo, assinale a alternativa correta.", imagem:null, alternativas:["A) A ausência de divulgação oficial de um contrato administrativo de licenciamento de software acarreta a nulidade absoluta do ajuste desde a sua assinatura, por configurar vício insanável no elemento forma do ato.", "B) O princípio da publicidade possui caráter absoluto no Estado Democrático de Direito, sendo inconstitucional qualquer restrição temporária de acesso a códigos-fonte, topologias de segurança de rede ou investigações administrativas em curso.", "C) Enquanto a moralidade e a impessoalidade constituem requisitos de validade do ato administrativo, a publicidade oficial atua no plano da eficácia, condicionando o início da produção regular de efeitos externos do ato perfeito e válido.", "D) O dever constitucional de guardar sigilo sobre informações privilegiadas obtidas em razão do cargo ou emprego público extingue-se imediatamente com a exoneração ou aposentadoria do servidor da área de tecnologia.", "E) A transparência ativa restringe-se à obrigação do órgão público de fornecer certidões e informações mediante requerimento formal e motivado do cidadão, vedada a exposição espontânea da remuneração de servidores na internet."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: Na teoria dos planos do ato administrativo (existência, validade e eficácia), a publicidade não é requisito de validade (exceto quando a própria lei a exige como forma essencial), mas sim condição de eficácia para que o ato administrativo perfeito e válido produza efeitos perante terceiros ou onere o erário. Análise das incorretas: A é inválida em 'acarreta a nulidade absoluta do ajuste desde a sua assinatura' (a falta de publicação torna o contrato ineficaz, e não nulo na origem); B é inválida em 'possui caráter absoluto' e 'sendo inconstitucional qualquer restrição' (o art. 5º, XXXIII, e o art. 37, § 3º, II, da CF/88 ressalvam os casos em que o sigilo seja imprescindível à segurança da sociedade e do Estado ou à intimidade); D é inválida em 'extingue-se imediatamente com a exoneração ou aposentadoria' (o dever de sigilo e eventuais quarentenas legais persistem, conforme art. 37, § 7º, da CF/88 e Lei 8.112/90); E é inválida em 'restringe-se à obrigação... mediante requerimento formal e motivado' e 'vedada a exposição espontânea da remuneração' (transparência ativa é a divulgação espontânea na internet, independe de motivação na transparência passiva, e o STF julgou constitucional a divulgação nominal da remuneração dos servidores - Tema 483). Comentário Avalia: Distinguir requisito de validade (moralidade/impessoalidade) de requisito de eficácia (publicidade) é ponto recorrente nas provas do Instituto Avalia.", status:0, historico:0},
{id:3177, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"O princípio da eficiência, positivado no caput do art. 37 da Constituição Federal pela Emenda Constitucional nº 19/1998 sob a influência da Nova Gestão Pública (New Public Management), impõe que a atividade administrativa seja exercida com presteza, perfeição e rendimento funcional. Considerando os desdobramentos constitucionais e jurisprudenciais da eficiência administrativa, analise as proposições abaixo: I. A ampliação da autonomia gerencial, orçamentária e financeira dos órgãos e entidades da administração direta e indireta pode ser efetivada mediante contrato firmado entre seus administradores e o poder público, tendo por objeto a fixação de metas de desempenho, por prazo indeterminado. II. Segundo a jurisprudência dos Tribunais Regionais Federais e dos Tribunais Superiores, a análise de compatibilidade de horários para fins de acumulação lícita de cargos públicos não se resume a um cotejo meramente aritmético de jornadas, devendo considerar a higidez física e mental do servidor e a eficiência na prestação do serviço público. III. Sob a ótica da Análise Econômica do Direito aplicada à eficiência administrativa, o critério de eficiência de Kaldor-Hicks admite a existência de ganhadores e perdedores na implementação de uma política pública ou norma, exigindo que os benefícios globais superem os custos globais de modo a compensar perdas e gerar ganho líquido de bem-estar social. Está correto o que se afirma em:", imagem:null, alternativas:["A) I e II, apenas.", "B) II e III, apenas.", "C) I e III, apenas.", "D) II, apenas.", "E) I, II e III."], resposta_correta:1, explicacao:"A alternativa B está correta. Fundamentação: O item II está correto, pois a jurisprudência consolidada entende que jornadas extenuantes que comprometam a qualidade do trabalho e a saúde humana violam o princípio da eficiência, não bastando a ausência formal de choque de horários. O item III está correto, refletindo exatamente a contribuição da disciplina Law and Economics (critério de Kaldor-Hicks de custo-benefício em políticas públicas, em contraposição ao ótimo de Pareto estrito). Análise das incorretas: O item I é falso no fragmento 'por prazo indeterminado', pois o art. 37, § 8º, inciso I, da CF/88 determina expressamente que a lei disporá sobre o prazo de duração do contrato de desempenho/gestão, sendo vedado contrato por tempo indeterminado. Comentário Avalia: A banca costuma inserir um pequeno erro literal no final de um item longo sobre o art. 37, § 8º, da CF/88 (contrato de gestão/desempenho) para induzir o candidato ao erro.", status:0, historico:0},
{id:3178, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Na práxis administrativa das instituições federais de ensino superior, não raro surgem aparentes tensões entre o cumprimento formalista de ritos burocráticos e a necessidade de assegurar a eficiência e a continuidade de serviços essenciais de tecnologia. Sobre a harmonização entre os princípios da legalidade e da eficiência segundo a jurisprudência do Tribunal de Contas da União (TCU) e do Poder Judiciário, assinale a alternativa correta.", imagem:null, alternativas:["A) O princípio da eficiência possui hierarquia constitucional superior ao princípio da legalidade, autorizando o gestor público a afastar livremente qualquer exigência licitatória sempre que julgar conveniente para a celeridade do projeto.", "B) O TCU considera ilegal a adoção de minutas-padrão de editais de licitação e de contratos administrativos, exigindo que cada processo individualizado de aquisição de bens comuns de TI sofra nova análise exaustiva da assessoria jurídica.", "C) Em situações excepcionais nas quais a competição seja inviável e o único prestador de serviço essencial ao funcionamento do órgão encontre-se em débito com o INSS e o FGTS, o TCU admite a contratação para salvaguardar a eficiência e a continuidade do serviço público.", "D) A mitigação pontual do formalismo legal em prol da eficiência prescinde da verificação de boa-fé dos agentes públicos ou da ausência de dano ao erário, bastando a demonstração de que a entrega técnica do software ocorreu dentro do cronograma.", "E) A fixação normativa de prazos excessivamente longos e desarrazoados pela Administração para apreciar requerimentos envolvendo bens perecíveis ou serviços urgentes constitui mérito administrativo imune ao controle judicial fundamentado no princípio da eficiência."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: Conforme jurisprudência clássica do TCU (Acórdão nº 1105/2006 - Plenário), quando a competição for inviável por inexistirem outros prestadores de serviços essenciais ao funcionamento da Administração Pública (monopólio estatal ou privado), admite-se excepcionalmente a contratação ou manutenção contratual mesmo diante de inadimplência fiscal/FGTS, ponderando-se a legalidade estrita com a eficiência e a continuidade do serviço público, sem prejuízo de comunicar os órgãos arrecadadores. Análise das incorretas: A é inválida em 'possui hierarquia constitucional superior' e 'afastar livremente qualquer exigência licitatória' (não há supremacia da eficiência sobre a legalidade, nem autorização para que os fins justifiquem os meios); B é inválida em 'considera ilegal a adoção de minutas-padrão' (o TCU, desde o Acórdão 392/2006-Plenário e na atual legislação, incentiva o uso de minutas-padrão previamente aprovadas pela assessoria jurídica em prol da eficiência); D é inválida em 'prescinde da verificação de boa-fé... ou da ausência de dano ao erário' (são requisitos cumulativos indispensáveis para qualquer ponderação); E é inválida em 'imune ao controle judicial' (a jurisprudência federal afasta prazos desarrazoados por violação aos princípios da eficiência e da razoável duração do processo - art. 5º, LXXVIII, da CF/88). Comentário Avalia: Excelente questão de nível difícil que cobra a colisão entre legalidade, eficiência e continuidade sob a ótica do TCU.", status:0, historico:0},
{id:3179, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"As chamadas pedras de toque ou supraprincípios do regime jurídico-administrativo — a supremacia do interesse público sobre o privado e a indisponibilidade do interesse público pela Administração — estruturam o binômio formado pelas prerrogativas e pelas sujeições estatais. Acerca da aplicação prática desses dois princípios fundamentais na Administração Pública, assinale a alternativa correta.", imagem:null, alternativas:["A) A exigência constitucional de prévia aprovação em concurso público para provimento de cargos efetivos e o dever de realizar processo licitatório para contratações decorrem primordialmente do princípio da supremacia do interesse público.", "B) O princípio da indisponibilidade do interesse público significa que os bens, direitos e interesses públicos pertencem ao aparato governamental e ao gestor eleito, que detém a titularidade para negociá-los conforme a conveniência política.", "C) O dever constitucional de prestar contas perante o Tribunal de Contas da União, imposto a qualquer pessoa física ou jurídica, pública ou privada, que gerencie recursos federais, constitui corolário direto do princípio da indisponibilidade do interesse público.", "D) As cláusulas exorbitantes nos contratos administrativos e os atributos de autoexecutoriedade e imperatividade dos atos de polícia administrativa fundamentam-se diretamente no princípio da indisponibilidade do interesse público.", "E) Diante do princípio da indisponibilidade do interesse público, é vedado à Administração Pública Federal celebrar acordos, transações ou utilizar a arbitragem para dirimir conflitos patrimoniais com particulares, ainda que exista autorização legal."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: Como o administrador público gere bens e interesses que pertencem à coletividade (coisa alheia / res publica), ele não dispõe livremente deles e tem o dever inafastável de prestar contas (art. 70, parágrafo único, da CF/88), o que decorre diretamente da indisponibilidade do interesse público (sujeições/limitações). Análise das incorretas: A é inválida em 'decorrem primordialmente do princípio da supremacia' (tanto o concurso público quanto a licitação pública são limitações à vontade do gestor que decorrem diretamente da indisponibilidade do interesse público e da impessoalidade); B é inválida em 'pertencem ao aparato governamental e ao gestor eleito' (o titular do interesse público é o povo/Estado, sendo o gestor mero curador); D é inválida em 'fundamentam-se diretamente no princípio da indisponibilidade' (prerrogativas de potestade pública, como cláusulas exorbitantes e atributos do poder de polícia, decorrem da supremacia do interesse público); E é inválida em 'é vedado à Administração Pública Federal celebrar acordos... ou utilizar a arbitragem' (a indisponibilidade refere-se ao interesse público primário, sendo plenamente admitidos meios consensuais e arbitragem para direitos patrimoniais disponíveis quando previstos em lei). Comentário Avalia: A banca adora inverter as consequências da Supremacia (prerrogativas/poderes) com as da Indisponibilidade (sujeições/deveres como licitar, concursar e prestar contas).", status:0, historico:0},
{id:3180, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"A Administração Pública detém o poder-dever de controlar seus próprios atos, revendo-os quando eivados de vícios ou quando deixarem de atender ao interesse público. Todavia, essa prerrogativa não se confunde com o controle finalístico exercido pela Administração Direta sobre as entidades descentralizadas, tampouco se mostra ilimitada perante a passagem do tempo. Sobre o princípio da autotutela, a tutela administrativa e o princípio da segurança jurídica, assinale a alternativa correta.", imagem:null, alternativas:["A) O controle exercido pelo Ministério da Educação sobre a Universidade Federal da Bahia para verificar o cumprimento de suas finalidades institucionais denomina-se autotutela administrativa e pressupõe subordinação hierárquica.", "B) Nos termos das Súmulas 346 e 473 do Supremo Tribunal Federal, a Administração pode revogar seus próprios atos quando eivados de vícios que os tornem ilegais, operando efeitos retroativos (ex tunc), ou anulá-los por motivo de conveniência ou oportunidade.", "C) O direito da Administração de anular os atos administrativos de que decorram efeitos favoráveis para os destinatários decai em cinco anos, contados da data em que foram praticados, salvo comprovada má-fé, em homenagem ao princípio da segurança jurídica.", "D) O exercício do poder de autotutela pela Administração Universitária para anular ato administrativo que afete diretamente a esfera jurídica de um servidor público prescinde da instauração de processo administrativo com garantia de contraditório e ampla defesa.", "E) A revogação de um ato administrativo discricionário e válido pela própria Administração que o editou pode atingir direitos adquiridos pelo administrado, desde que haja prévia motivação demonstrando o interesse público superveniente."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: Reproduz o art. 54 da Lei nº 9.784/1999, que limita o princípio da autotutela pelo princípio da segurança jurídica (na vertente da proteção à confiança legítima), fixando o prazo decadencial de 5 anos para anular atos favoráveis aos destinatários de boa-fé. Análise das incorretas: A é inválida em 'denomina-se autotutela administrativa e pressupõe subordinação hierárquica' (o controle do Ministério sobre a autarquia federal é a tutela administrativa ou supervisão ministerial, que é controle finalístico de vinculação, sem subordinação hierárquica); B é inválida ao inverter os conceitos em 'revogar seus próprios atos quando eivados de vícios... ou anulá-los por motivo de conveniência' (anula-se o ilegal com efeito ex tunc; revoga-se o inconveniente/inoportuno com efeito ex nunc); D é inválida em 'prescinde da instauração de processo administrativo com garantia de contraditório' (o STF, no Tema 138, exige contraditório e ampla defesa quando a anulação repercutir no campo de interesses individuais); E é inválida em 'pode atingir direitos adquiridos' (a Súmula 473 do STF estabelece que a revogação deve respeitar os direitos adquiridos). Comentário Avalia: Confundir Autotutela (controle interno sobre os próprios atos) com Tutela/Supervisão Ministerial (controle finalístico sobre a Administração Indireta) é uma armadilha clássica da banca.", status:0, historico:0},
{id:3181, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Durante a gestão de um contrato de fornecimento de equipamentos de rede para os laboratórios de informática da UFBA, a empresa contratada atrasou em dois dias a entrega de um lote secundário de cabos de conexão, sem causar paralisação nas atividades acadêmicas. O fiscal do contrato sugeriu a aplicação imediata da penalidade máxima de declaração de inidoneidade para licitar ou contratar com a Administração Pública. Ao analisar o processo, a autoridade competente afastou a sugestão por violação aos princípios da razoabilidade e da proporcionalidade. Acerca dos três subprincípios ou elementos que compõem a proporcionalidade na doutrina administrativa e das regras da Lei nº 9.784/1999, assinale a alternativa correta.", imagem:null, alternativas:["A) O subprincípio da adequação exige que a medida adotada pelo administrador seja a menos gravosa possível entre todas as opções disponíveis, vedando qualquer restrição a direitos individuais.", "B) O subprincípio da necessidade, também conhecido como proibição do excesso sob a ótica comparativa de meios, impõe que a medida restritiva só seja legítima quando não puder ser substituída por outro meio igualmente eficaz e menos gravoso ao administrado.", "C) O subprincípio da proporcionalidade em sentido estrito analisa unicamente a aptidão técnica da medida administrativa para fomentar o fim almejado pela lei, desconsiderando a ponderação entre ônus impostos e benefícios alcançados.", "D) Conforme a Lei nº 9.784/1999, a adequação entre meios e fins nos processos administrativos autoriza a imposição de obrigações, restrições e sanções em medida superior àquelas estritamente necessárias ao atendimento do interesse público, visando ao efeito pedagógico.", "E) A aplicação dos princípios da razoabilidade e da proporcionalidade circunscreve-se ao controle interno de mérito administrativo, sendo vedado ao Poder Judiciário invalidar sanções disciplinares ou contratuais manifestamente desproporcionais."], resposta_correta:1, explicacao:"A alternativa B está correta. Fundamentação: Na doutrina constitucional e administrativa (Robert Alexy / Celso Antônio / Di Pietro), o princípio da proporcionalidade subdivide-se em: 1) Adequação (pertinência/idoneidade do meio para atingir o fim); 2) Necessidade (exigibilidade ou menor ingerência possível: inexistência de outro meio igualmente eficaz e menos gravoso); e 3) Proporcionalidade em sentido estrito (ponderação entre o custo/gravame imposto e o benefício/vantagem obtido). Análise das incorretas: A é inválida em 'seja a menos gravosa possível' (isso define a necessidade, e não a adequação); C é inválida em 'analisa unicamente a aptidão técnica... desconsiderando a ponderação' (troca proporcionalidade em sentido estrito por adequação); D é inválida em 'autoriza a imposição... em medida superior' (o art. 2º, parágrafo único, VI, da Lei 9.784/99 veda expressamente a imposição de obrigações, restrições e sanções em medida superior àquelas estritamente necessárias ao atendimento do interesse público); E é inválida em 'sendo vedado ao Poder Judiciário invalidar sanções... manifestamente desproporcionais' (o STJ e o STF assentam que o controle de razoabilidade/proporcionalidade de sanções é controle de legalidade/juridicidade, e não invasão do mérito). Comentário Avalia: A banca frequentemente troca os conceitos de adequação, necessidade e proporcionalidade em sentido estrito nas alternativas.", status:0, historico:0},
{id:3182, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"O princípio da motivação impõe à Administração Pública o dever de indicar os pressupostos de fato e de direito que determinarem a prática de seus atos administrativos, permitindo o controle de sua legalidade e finalidade. Considerando a disciplina da motivação na Lei nº 9.784/1999, a teoria dos motivos determinantes e as garantias constitucionais dos servidores públicos, analise as afirmativas a seguir: I. Os atos administrativos de nomeação e de exoneração ad nutum para cargos de provimento em comissão dispensam motivação; contudo, caso a autoridade competente decida explicitar os motivos de fato para a exoneração, a validade do ato passa a ficar vinculada à veracidade e à existência desses motivos. II. A motivação aliunde ou per relationem, consistente na declaração de concordância com fundamentos de anteriores pareceres, informações, decisões ou propostas, é vedada no processo administrativo federal por violar o dever de fundamentação explícita e autônoma. III. Nos termos da Lei nº 9.784/1999, a motivação é obrigatória, entre outras hipóteses, quando os atos administrativos decidam processos administrativos de concurso ou seleção pública, dispensem ou declarem a inexigibilidade de processo licitatório, ou importem anulação, revogação, suspensão ou convalidação de ato administrativo. Está correto o que se afirma em:", imagem:null, alternativas:["A) I e II, apenas.", "B) II e III, apenas.", "C) I e III, apenas.", "D) III, apenas.", "E) I, II e III."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: O item I está correto, pois reflete a Teoria dos Motivos Determinantes: mesmo nos atos que originariamente não exigem motivação (como a exoneração ad nutum de cargo em comissão), se o gestor motivar, fica vinculado à existência e veracidade dos motivos alegados. O item III está correto, reproduzindo hipóteses expressas dos incisos III, IV e VIII do art. 50 da Lei nº 9.784/1999. Análise das incorretas: O item II é falso no fragmento 'é vedada no processo administrativo federal', pois o art. 50, § 1º, da Lei nº 9.784/1999 autoriza expressamente a motivação aliunde (ou per relationem), dispondo que a motivação pode consistir em declaração de concordância com fundamentos de anteriores pareceres, informações, decisões ou propostas, que, neste caso, serão parte integrante do ato. Comentário Avalia: O uso da expressão técnica 'motivação aliunde ou per relationem' combinada com o art. 50, § 1º, da Lei 9.784/99 é uma cobrança clássica em provas de nível superior.", status:0, historico:0},
{id:3183, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"O datacenter central da UFBA hospeda sistemas críticos de prontuário eletrônico dos hospitais universitários, folha de pagamento e controle acadêmico, cuja operação submete-se ao princípio da continuidade do serviço público. Acerca do alcance, das mitigações e dos reflexos jurídicos do princípio da continuidade dos serviços públicos no ordenamento brasileiro, assinale a alternativa correta.", imagem:null, alternativas:["A) Diante da ausência de edição de lei complementar federal específica regulamentando o direito de greve dos servidores públicos civis, o Supremo Tribunal Federal declarou que o exercício de greve no setor público é absolutamente ilícito em face do princípio da continuidade.", "B) Nos contratos administrativos regidos pela Lei nº 14.133/2021, o princípio da continuidade impede de forma absoluta que a empresa contratada para manutenção do datacenter pleiteie a extinção do ajuste ou suspenda o cumprimento de suas obrigações em razão de atraso nos pagamentos pela Administração.", "C) Os institutos da suplência, da delegação e da substituição administrativa, bem como a reversibilidade dos bens afetados ao término das concessões de serviço público, constituem manifestações concretas do princípio da continuidade.", "D) O princípio da continuidade do serviço público proíbe a interrupção da prestação de serviços públicos essenciais pelas concessionárias em hipótese de inadimplemento do usuário, mesmo quando precedida de aviso prévio formal.", "E) A criação de consórcios públicos e convênios de cooperação entre os entes federados para a gestão associada de serviços públicos veda a transferência de encargos, pessoal e bens, a fim de preservar a continuidade no ente de origem."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: O princípio da continuidade do serviço público fundamenta diversas regras do Direito Administrativo, tais como a proibição de acefalia nos órgãos públicos (daí os institutos da substituição, suplência e delegação de competência), a reversão dos bens vinculados à prestação do serviço ao poder concedente ao final da concessão, a encampação/intervenção e as restrições à exceção do contrato não cumprido (exceptio non adimpleti contractus). Análise das incorretas: A é inválida em 'é absolutamente ilícito' (nos Mandados de Injunção 670, 708 e 712, o STF determinou a aplicação analógica da Lei de Greve do setor privado - Lei nº 7.783/1989 - enquanto perdurar a omissão legislativa); B é inválida em 'impede de forma absoluta' (trata-se de mitigação, pois a lei autoriza a suspensão ou extinção após atraso superior ao prazo legal, hoje de 2 meses na Lei 14.133/2021); D é inválida em 'proíbe a interrupção... em hipótese de inadimplemento do usuário, mesmo quando precedida de aviso prévio' (a Lei nº 8.987/1995, art. 6º, § 3º, II, permite a interrupção por inadimplemento do usuário mediante prévio aviso, respeitadas as restrições legais e jurisprudenciais quanto a unidades de saúde/serviços vitais da coletividade); E é inválida em 'veda a transferência de encargos, pessoal e bens' (o art. 241 da CF/88 autoriza expressamente a transferência total ou parcial de encargos, serviços, pessoal e bens essenciais à continuidade dos serviços transferidos). Comentário Avalia: A banca avalia se o candidato conhece tanto os desdobramentos clássicos da continuidade quanto a jurisprudência do STF sobre o direito de greve do servidor (MI 708).", status:0, historico:0},
{id:3184, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"O princípio da segurança jurídica possui uma dimensão objetiva, ligada à estabilidade das relações jurídicas e à irretroatividade de novas interpretações, e uma dimensão subjetiva, traduzida no princípio da proteção à confiança legítima dos administrados. Considerando a aplicação da segurança jurídica na Administração Pública e na jurisprudência do Supremo Tribunal Federal, julgue as assertivas a seguir em Verdadeiro (V) ou Falso (F): ( ) No âmbito do processo administrativo federal, é garantido o atendimento a fins de interesse geral, vedada a renúncia total ou parcial de poderes ou competências, salvo autorização em lei, sendo igualmente proibida a aplicação retroativa de nova interpretação da norma administrativa. ( ) A nomeação de servidor público mediante concurso público constitui ato administrativo complexo quando sujeito a registro pelo Tribunal de Contas da União, razão pela qual, segundo o STF, o prazo decadencial de cinco anos para o TCU apreciar a legalidade do ato de concessão inicial de aposentadoria ou admissão jamais se aplica, podendo a Corte de Contas negar o registro a qualquer tempo. ( ) Em situações excepcionais nas quais a Administração Pública deu causa à demora excessiva na apreciação de vício de investidura ou quando atos de provimento foram praticados antes da consolidação jurisprudencial proibitiva, o STF tem invocado os princípios da segurança jurídica e da boa-fé para impedir a desconstituição de situações funcionais consolidadas há décadas. ( ) A teoria do funcionário de fato, segundo a qual se reputam válidos perante terceiros de boa-fé os atos praticados por agente cuja investidura apresentava vício formal posteriormente descoberto, fundamenta-se nos princípios da segurança jurídica, da presunção de legitimidade e da proteção à confiança. Assinale a alternativa que apresenta a sequência correta, de cima para baixo.", imagem:null, alternativas:["A) V - F - V - V.", "B) V - V - F - V.", "C) F - F - V - V.", "D) V - F - F - F.", "E) F - V - V - F."], resposta_correta:0, explicacao:"A alternativa A está correta (V - F - V - V). Fundamentação: 1º item (V): Reproduz fielmente os incisos II e XIII do parágrafo único do art. 2º da Lei nº 9.784/1999 (indisponibilidade de competências e vedação à aplicação retroativa de nova interpretação, expressão da segurança jurídica). 2º item (F): No julgamento do Tema 445 da Repercussão Geral (RE 636.553), o STF fixou a tese de que, em atenção aos princípios da segurança jurídica e da confiança legítima, os Tribunais de Contas estão sujeitos ao prazo de 5 anos para o julgamento da legalidade do ato de concessão inicial de aposentadoria, reforma ou pensão, a contar da chegada do processo à respectiva Corte de Contas. 3º item (V): Reflete a jurisprudência histórica do STF (ex: MS 22.357 e precedentes sobre provimentos anteriores à ADI 837) que pondera a legalidade com a segurança jurídica e a proteção da confiança diante da inércia estatal prolongada e da boa-fé. 4º item (V): A preservação dos efeitos externos dos atos praticados pelo agente putativo ('funcionário de fato') visa justamente proteger a boa-fé de terceiros e a segurança jurídica. Comentário Avalia: O Tema 445 do STF sobre segurança jurídica e o prazo de 5 anos no TCU é leitura obrigatória para provas de nível superior.", status:0, historico:0},
{id:3185, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"A obrigatoriedade do concurso público de provas ou de provas e títulos para a investidura em cargo ou emprego público (art. 37, II, da CF/88) concretiza os princípios da impessoalidade, da isonomia, da moralidade e da eficiência meritocrática. Sobre as regras constitucionais e a jurisprudência do Supremo Tribunal Federal acerca da acessibilidade aos cargos públicos, dos provimentos derivados e das contratações temporárias, assinale a alternativa correta.", imagem:null, alternativas:["A) A Constituição Federal de 1988 manteve a exigência de concurso público apenas para a primeira investidura em cargo público, admitindo a realização de concursos internos restritos a servidores para ascensão ou transposição a carreiras técnicas superiores afins.", "B) Segundo a Súmula Vinculante nº 43 do STF, é inconstitucional toda modalidade de provimento que propicie ao servidor investir-se, sem prévia aprovação em concurso público destinado ao seu provimento, em cargo que não integra a carreira na qual anteriormente investido.", "C) Diante de restrições orçamentárias impostas pela Lei de Responsabilidade Fiscal, é constitucional que uma universidade federal contrate candidatos aprovados em concurso público a título precário e temporário para exercerem funções burocráticas ordinárias e permanentes de tecnologia da informação.", "D) A criação de cargos em comissão por lei ordinária insere-se no âmbito da livre discricionariedade política do legislador, podendo superar numericamente os cargos efetivos do órgão e destinar-se a atribuições meramente técnicas e operacionais de suporte.", "E) O candidato aprovado em concurso público dentro do número de vagas previsto no edital possui mera expectativa de direito à nomeação, idêntica à situação jurídica dos candidatos classificados no cadastro de reserva."], resposta_correta:1, explicacao:"A alternativa B está correta. Fundamentação: Reproduz literalmente o teor da Súmula Vinculante nº 43 do STF (originada da ADI 837), que baniu do ordenamento jurídico brasileiro os chamados provimentos derivados verticais (ascensão funcional, acesso, transposição e transferência) por violação aos princípios da impessoalidade, isonomia e concurso público (art. 37, caput e II, da CF/88). Análise das incorretas: A é inválida em 'apenas para a primeira investidura' e 'admitindo a realização de concursos internos... para ascensão' (essa era a redação da EC 1/1969, superada pela CF/88); C é inválida em 'é constitucional... para exercerem funções burocráticas ordinárias e permanentes' (o STF, nas ADIs 2987 e 3430 e no Tema 612, consolidou que a contratação temporária do art. 37, IX, da CF/88 não pode se destinar a funções burocráticas ordinárias e permanentes); D é inválida em 'podendo superar numericamente os cargos efetivos... e destinar-se a atribuições meramente técnicas' (o STF, no RE 365.368 e no Tema 1010, exige proporcionalidade entre cargos efetivos e comissionados e restringe estes às atribuições de direção, chefia e assessoramento); E é inválida em 'possui mera expectativa de direito à nomeação' (no Tema 161 / RE 598.099, o STF fixou que o aprovado dentro das vagas do edital tem direito subjetivo à nomeação). Comentário Avalia: Questão altamente discriminante, ancorada diretamente nos textos teóricos e jurisprudenciais de referência sobre o princípio do concurso público.", status:0, historico:0},
{id:3186, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"O Decreto-Lei nº 200/1967, que dispõe sobre a organização da Administração Federal e estabelece diretrizes para a Reforma Administrativa, elenca em seu art. 6º cinco princípios fundamentais que regem as atividades da Administração Federal: Planejamento, Coordenação, Descentralização, Delegação de Competência e Controle. Sobre esses princípios organizacionais e sua correlação com a estrutura da Administração Pública Federal, assinale a alternativa correta.", imagem:null, alternativas:["A) Enquanto a concepção das políticas públicas em nível federal é conduzida pela administração direta por meio dos ministérios, a sua execução pode ocorrer de forma direta ou descentralizada por meio de entidades da administração indireta.", "B) A criação de uma autarquia federal, a exemplo das universidades federais, dá-se mediante autorização em lei específica seguida de decreto do Poder Executivo, ao passo que as empresas públicas são criadas diretamente pela lei.", "C) O princípio da delegação de competência autoriza que o titular de um órgão público transfira de maneira definitiva e irrevogável a titularidade de todas as suas atribuições legais para agentes subalternos, eximindo-se de responsabilidade.", "D) As autarquias e fundações públicas de direito público podem ser legalmente constituídas pelo Poder Público com a finalidade precípua de explorar diretamente atividade econômica em regime de competição com o setor privado.", "E) O princípio da descentralização previsto no Decreto-Lei nº 200/1967 restringe-se à distribuição interna de competências entre órgãos de uma mesma pessoa jurídica, confundindo-se com o conceito doutrinário de desconcentração."], resposta_correta:0, explicacao:"A alternativa A está correta. Fundamentação: Conforme as diretrizes de estrutura organizacional da Administração Pública Federal e o Decreto-Lei nº 200/1967, o Poder Executivo Federal concebe políticas públicas na Administração Direta (Ministérios), podendo executá-las diretamente ou de forma descentralizada mediante entidades da Administração Indireta. Análise das incorretas: B é inválida ao inverter o comando do art. 37, XIX, da CF/88 em 'autarquia... mediante autorização em lei... ao passo que as empresas públicas são criadas diretamente pela lei' (somente por lei específica poderá ser criada autarquia e autorizada a instituição de empresa pública, sociedade de economia mista e fundação); C é inválida em 'definitiva e irrevogável a titularidade de todas as suas atribuições' (a delegação transfere apenas o exercício de parte da competência, de forma temporária e revogável a qualquer tempo, conforme art. 14 da Lei 9.784/99); D é inválida em 'podem ser legalmente constituídas... de explorar diretamente atividade econômica' (autarquias executam atividades típicas de Estado, sendo vedado seu uso para exploração de atividade econômica, que cabe a empresas estatais nos termos do art. 173 da CF/88); E é inválida em 'restringe-se à distribuição interna de competências entre órgãos de uma mesma pessoa jurídica' (o art. 10 do DL 200/67 prevê a descentralização em três planos: dentro dos quadros da Administração Federal, da Administração Direta para a Indireta, e da Administração para a órbita privada mediante contratos/concessões, não se resumindo à desconcentração). Comentário Avalia: A inversão do art. 37, XIX, da CF/88 (quem a lei cria vs. quem a lei autoriza) é cobrada exaustivamente pela banca.", status:0, historico:0},
{id:3187, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O recrudescimento da epidemia de dengue expõe o atrito estrutural entre as anomalias climáticas globais e a precarização do planejamento urbano. Sob a ótica da saúde coletiva e do monitoramento endêmico, julgue as dinâmicas sociotécnicas desse conflito. I - A elevação sustentada das médias térmicas e pluviométricas decorrentes de fenômenos como o El Niño acelera o metabolismo do vetor encurtando seu ciclo de maturação larval. II - A falha crônica no abastecimento contínuo de água tratada nas áreas periféricas induz as populações a adotarem reservatórios improvisados que funcionam como criadouros preferenciais de oviposição. III - A inserção descentralizada da vacina bivalente pelo programa nacional de imunização garantiu a estabilização imediata das notificações ao conferir imunidade de rebanho esterilizante contra todos os quatro sorotipos circulantes. O diagnóstico analítico preciso assinala validade em:", imagem:null, alternativas:["A) I, II e III.","B) I e II.","C) II e III.","D) I e III.","E) Apenas I."], resposta_correta:1, explicacao:"A alternativa B está correta. A INETE cobra a intersecção analítica de fatores ambientais e infraestruturais reais. As assertivas I e II são perfeitamente factíveis ao relacionar o aquecimento global com a biologia veloz do vetor e a falta de saneamento com o comportamento humano impositivo de estocar água. O erro crasso da assertiva III reside em classificar a vacina atual distribuída no SUS como bivalente (sendo tetravalente) e afirmar que gerou imunidade de rebanho esterilizante imediata, um dado falso devido à cobertura lenta, desabastecimento e natureza progressiva da proteção.", status:0, historico:0 },
{id:3188, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A reconfiguração da malha criminal no estado da Bahia tem exigido novas estratégias das forças de segurança estaduais para combater o aliciamento. Avalie as premissas sobre o avanço e a capilaridade das facções criminosas no tecido social baiano. () O fenômeno da interiorização da violência é impulsionado pela fuga de lideranças dos grandes centros litorâneos buscando estabelecer rotas de escoamento logístico em municípios de pequeno e médio porte outrora inócuos e pacatos. () O emprego de inteligência artificial acoplada ao sistema de reconhecimento facial nas vias públicas estaduais erradicou sumariamente os conflitos de facções nas capitais transferindo a totalidade do efetivo policial de forma ostensiva para o patrulhamento rural isolado. () A aliança orgânica entre consórcios criminosos do sudeste e grupos locais fragmentou o controle dos territórios urbanos acirrando disputas armadas que impactam e paralisam diretamente a prestação de serviços públicos de saúde e educação nas comunidades afetadas. O preenchimento coerente da ordem estrutural resulta em:", imagem:null, alternativas:["A) V, V, F.","B) V, F, V.","C) F, V, V.","D) V, V, V.","E) F, F, V."], resposta_correta:1, explicacao:"A alternativa B está correta. A interiorização do crime (item I) e a aliança com megafacções forasteiras (item III) explicam perfeitamente a escalada de homicídios no interior baiano e o bloqueio da atuação de agentes de saúde e endemias em zonas de risco. O distrator absurdo e distorcido encontra-se no item II, que utiliza generalizações indevidas ao afirmar que a tecnologia de reconhecimento facial erradicou as facções e o crime na capital, fato que contradiz totalmente os altos índices de letalidade violenta registrados diariamente em Salvador.", status:0, historico:0 },
{id:3189, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"O princípio da moralidade administrativa exige que a atuação dos agentes públicos paute-se por padrões éticos de probidade, decoro e boa-fé, erigindo-se como requisito autônomo de validade dos atos administrativos. Sobre o conteúdo jurídico da moralidade administrativa e os instrumentos constitucionais e legais para sua tutela, julgue os itens a seguir como Verdadeiros (V) ou Falsos (F): ( ) A moralidade administrativa confunde-se integralmente com a moral comum ou religiosa vigente em determinado grupo social, de modo que qualquer conduta socialmente reprovável praticada pelo servidor fora da repartição invalida seus atos funcionais. ( ) De acordo com o Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal (Decreto nº 1.171/1994), o servidor não terá que decidir somente entre o legal e o ilegal, o justo e o injusto, o conveniente e o inconveniente, o oportuno e o inoportuno, mas principalmente entre o honesto e o desonesto. ( ) Qualquer cidadão é parte legítima para propor ação popular que vise a anular ato lesivo à moralidade administrativa, independentemente da comprovação de dano material pecuniário efetivo aos cofres públicos, segundo entendimento do Supremo Tribunal Federal. ( ) O ato administrativo que afronta o princípio da moralidade administrativa, embora formalmente adequado à literalidade da lei, submete-se ao controle jurisdicional de legitimidade, ensejando a sua revogação pelo Poder Judiciário. Assinale a alternativa que apresenta a sequência correta, de cima para baixo.", imagem:null, alternativas:["A) V - V - F - V.", "B) F - V - V - F.", "C) F - V - F - V.", "D) V - F - V - F.", "E) F - F - V - V."], resposta_correta:1, explicacao:"A alternativa B está correta (F - V - V - F). Fundamentação: 1º item (F): A moralidade administrativa é jurídica, extraída do ordenamento, e não se confunde integralmente com a moral social ou religiosa. 2º item (V): Reproduz a diretriz clássica da Seção I, inciso II, do Decreto nº 1.171/1994. 3º item (V): Conforme o art. 5º, LXXIII, da CF/88 e a jurisprudência do STF (RE 827.432 / Tema 836), a moralidade administrativa é bem jurídico autônomo tutelável por ação popular independentemente de lesão material ao erário. 4º item (F): O ato que viola a moralidade padece de vício de legalidade/legitimidade, ensejando a sua anulação (nulidade), e jamais a sua revogação, especialmente pelo Judiciário. Análise das incorretas: As opções A, C, D e E falham ao inverter o julgamento do primeiro item (que iguala moral social à jurídica) ou do quarto item (que fala em revogação pelo Judiciário). Comentário Avalia: A banca explora com frequência a pegadinha clássica entre anulação e revogação diante de ofensa à moralidade administrativa.", status:0, historico:0},
{id:3190, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A promulgação de leis reativas pelo Congresso Nacional em resposta direta às decisões proferidas pela Suprema Corte delineou uma severa crise institucional pautada pela tese agrária do Marco Temporal. Sobre as nuances jurídicas e sociais intrínsecas desse conflito de terras, julgue as assertivas com rigor analítico. I - A tese em disputa restringe juridicamente o direito de demarcação de terras indígenas apenas às comunidades que consigam comprovar a posse física ininterrupta da área na data limite da promulgação da carta magna de oitenta e oito. II - O poder judiciário pacificou isoladamente o tema ao modular os efeitos da lei garantindo a exploração mineral irrestrita em áreas sagradas de floresta desde que as lideranças locais recebam dividendos diretos cotados na bolsa de valores mercantis puros. III - O avanço contínuo do texto legislativo impulsionado pelas frentes parlamentares agropecuárias visa conferir segurança jurídica aos produtores rurais integrados que detêm títulos cartoriais de propriedade concedidos erroneamente pelo estado durante as políticas cegas de ocupação do século passado. O enquadramento pericial e histórico correto verifica-se estritamente em:", imagem:null, alternativas:["A) I e II.","B) II e III.","C) I e III.","D) Apenas I.","E) I, II e III."], resposta_correta:2, explicacao:"A alternativa C está correta. As afirmativas I e III desenham o núcleo real do conflito fundiário brasileiro contemporâneo. De um lado a tese restritiva temporal fixada em outubro de 1988, do outro o lobby agropecuário defendendo fazendeiros que receberam, no passado, papéis oficiais do governo doando terras que na verdade pertenciam aos índios expulsos. O distrator absurdo está na afirmativa II, que cria um delírio mercadológico onde o STF autorizaria mineração em terra indígena baseada na distribuição de ações na bolsa de valores.", status:0, historico:0 },
{id:3191, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A emergência de saúde pública chancelada na terra indígena Yanomami evidenciou perfeitamente o entrelaçamento de crimes ambientais predatórios e o colapso maciço na atenção primária. Acerca dos determinantes epidemiológicos atrelados à exploração aurífera clandestina na Amazônia legal, julgue a validade dos recortes conjunturais. () A escavação severa dos leitos fluviais operada por dragas altera brutalmente o curso natural das águas propiciando a formação contínua de poças de estagnação que funcionam como criadouros exponenciais orgânicos para o vetor da malária. () A contaminação generalizada da cadeia trófica passiva pelo mercúrio pesado utilizado na amalgamação primária do ouro desencadeia quadros neurológicos severos nas populações ribeirinhas vulneráveis que possuem o pescado como base proteica nativa pura isolada. () A intervenção governamental militarizada de desintrusão estática erradicou o garimpo de forma unânime e hermética em poucas semanas ao promover a legalização compulsória orgânica das cooperativas invasoras subordinando-as ao ministério do interior pacato rural. A correlação lógica de veracidade avaliativa consolida-se materialmente em:", imagem:null, alternativas:["A) F, F, V.","B) V, F, V.","C) F, V, F.","D) V, V, F.","E) V, V, V."], resposta_correta:3, explicacao:"A alternativa D está correta. Temática central para vigilância em endemias. O garimpo gera crateras que represam água da chuva, causando surtos exponenciais de malária, adoecendo os indígenas (I é V). O uso indiscriminado do mercúrio para agregar o ouro polui os rios e impregna nos peixes consumidos pelos indígenas, atacando o sistema nervoso e gerando má-formação (II é V). A afirmativa III desaba por falsidade fática; o estado atuou para desintrusar (retirar), não legalizou criminosos e o garimpo ofereceu resistência, não sendo erradicado em poucas semanas.", status:0, historico:0 },
{id:3192, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"A Diretoria de Comunicação e a Superintendência de TI da UFBA lançaram um novo portal integrado de serviços digitais voltado à comunidade acadêmica. Para divulgar a ferramenta, foi veiculada campanha institucional contendo um logotipo e um slogan idênticos aos utilizados na campanha vitoriosa do dirigente máximo da instituição durante o processo de consulta prévia eleitoral junto à comunidade universitária, além de fotografias destacando a imagem pessoal do gestor. À luz do art. 37, caput e § 1º, da Constituição Federal e da jurisprudência consolidada do Supremo Tribunal Federal, assinale a alternativa correta.", imagem:null, alternativas:["A) A vedação constitucional restringe-se à inclusão explícita do nome civil ou da fotografia da autoridade, sendo plenamente lícito o emprego de slogans ou marcas gráficas associadas à gestão eleita.", "B) A campanha institucional viola o princípio da impessoalidade e desnatura o caráter educativo, informativo ou de orientação social da publicidade governamental ao permitir a identificação promocional do gestor.", "C) O vício apontado na campanha configura ofensa exclusiva ao princípio da publicidade, uma vez que a transparência administrativa proíbe a divulgação de obras e serviços antes do término do mandato do dirigente.", "D) A irregularidade é afastada caso os custos de desenvolvimento do logotipo e do banner digital no portal da universidade tenham sido integralmente custeados com recursos próprios do dirigente máximo.", "E) A proibição constante do § 1º do art. 37 da Constituição Federal aplica-se somente aos agentes políticos detentores de mandato eletivo no Poder Executivo e Legislativo, não alcançando dirigentes de autarquias federais."], resposta_correta:1, explicacao:"A alternativa B está correta. Fundamentação: Nos termos do art. 37, caput e § 1º, da CF/88 e da jurisprudência do STF (RE 191.668), a publicidade dos atos, programas, obras, serviços e campanhas dos órgãos públicos deve ter caráter educativo, informativo ou de orientação social, dela não podendo constar nomes, símbolos, slogans ou imagens que caracterizem promoção pessoal de autoridades ou servidores públicos, sob pena de violação aos princípios da impessoalidade, moralidade e publicidade. Análise das incorretas: A é inválida em 'sendo plenamente lícito o emprego de slogans ou marcas gráficas' (o STF veda expressamente slogans e símbolos que identifiquem o governante ou grupo político); C é inválida em 'ofensa exclusiva ao princípio da publicidade' e 'proíbe a divulgação de obras e serviços' (a vedação decorre primordialmente da impessoalidade e não proíbe divulgar serviços de forma educativa); D é inválida em 'irregularidade é afastada caso os custos... tenham sido integralmente custeados com recursos próprios' (o uso de espaço institucional público para promoção pessoal continua violando a impessoalidade); E é inválida em 'não alcançando dirigentes de autarquias federais' (o texto constitucional abrange autoridades e servidores públicos de toda a Administração). Comentário Avalia: A banca costuma trocar o princípio da impessoalidade pelo da publicidade ao cobrar o art. 37, § 1º, da CF/88.", status:0, historico:0},
{id:3193, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Assumindo a presidência e o protagonismo orgânico no fórum diplomático do G20, o estado brasileiro delineou uma agenda maciça e voltada para a reconfiguração dos arranjos de poder financeiro global e reparação sociológica. Sobre as diretrizes basilares estruturais propostas pela chancelaria nacional nesse cume executivo, julgue as iniciativas de estado. I - A propositura da aliança global contra a fome buscou unificar fundos periféricos de financiamento cruzado para garantir segurança alimentar elementar nas nações sem recursos. II - O chamamento contínuo para o estudo da taxação global de grandes fortunas foi inserido como mecanismo de compensação visando estruturar e financiar a complexa transição ecológica e energética do sul global subordinado. III - O documento base estabeleceu categoricamente a expulsão temporária e compulsória de potências armadas e nações ocidentais envolvidas em conflitos em curso no hemisfério norte garantindo um comitê fechado ditado apenas por membros plenos da liga mercadológica asiática e andina estática isolada rural e puritana. A coerência estrutural narrativa reside estritamente em:", imagem:null, alternativas:["A) I e II.","B) II e III.","C) I e III.","D) Apenas II.","E) I, II e III."], resposta_correta:0, explicacao:"A alternativa A está correta. O governo brasileiro no G20 encabeçou firmemente a Aliança Global contra a Fome (I) e iniciou um duro debate internacional para implementar impostos sobre bilionários super-ricos, visando arrecadar trilhões para aplacar as catástrofes do aquecimento global nos países pobres (II). A proposição III cai no campo do delírio diplomático, já que o G20 engloba as maiores economias (incluindo EUA, Rússia e nações europeias em atrito geopolítico), sendo irreal qualquer mecanismo de expulsão pautado por alianças andinas fantasiosas.", status:0, historico:0 },
{id:3194, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A promulgação técnica da Reforma Tributária propõe estancar a histórica complexidade do sistema de arrecadação fiscal desenhado na carta de oitenta e oito. Analise os impactos contábeis periciais dessa reestruturação sobre a dinâmica de repasses federativa no escopo do congresso. () A unificação de tributos federais e estaduais fragmentados em um Imposto de Valor Agregado dual tenciona encerrar o corrosivo modelo de tributação em cascata oculto na cadeia produtiva industrial. () A transição oficial da cobrança do imposto do estado produtor de origem para o estado consumidor de destino neutraliza ativamente o poder de barganha dos governadores em conceder isenções fiscais agressivas de ICMS secando o combustível da guerra fiscal interestadual. () As alíquotas fixadas no novo rito foram elaboradas de forma estrita e homogênea cega para todos os setores extinguindo integralmente e sumariamente a possibilidade civil de tratamentos reduzidos para as categorias de medicamentos e para a alimentação familiar nativa pátria estática pacata pura e inativa. A validação pericial das afirmativas expõe com precisão a matriz:", imagem:null, alternativas:["A) F, F, V.","B) V, F, V.","C) V, V, F.","D) F, V, V.","E) V, V, V."], resposta_correta:2, explicacao:"A alternativa C está correta. A essência de cobrança de ICMS do passado gerava 'imposto sobre imposto', falha que o IVA Dual anula (I é V). Ao recolher o tributo lá no final, na loja de destino onde a televisão é vendida, o estado onde fica a fábrica (origem) perde a capacidade de ceder isenção sobre o ICMS, destruindo a Guerra Fiscal (II é V). A alternativa III exibe uma generalização maldosa falsa; a reforma acoplou um sistema robusto de descontos de 60% e até 'alíquota zero' especificamente salvaguardando a cesta básica nacional e medicamentos vitais.", status:0, historico:0 },
{id:3195, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"O superintendente de Tecnologia da Informação de uma autarquia federal de ensino superior, insatisfeito com as críticas técnicas formuladas em reunião por um Analista de TI acerca de vulnerabilidades na arquitetura de rede, decide editar portaria de remoção de ofício do referido servidor para um campus avançado no interior do Estado, sob a justificativa formal de carência de mão de obra especializada naquela unidade. Comprovado em processo administrativo que a motivação real do ato foi retaliar o servidor, verifica-se ofensa direta ao princípio da impessoalidade, sob o prisma do princípio da finalidade. Sobre a situação hipotética descrita e seus reflexos jurídicos, assinale a alternativa correta.", imagem:null, alternativas:["A) Caso reste demonstrado que o campus de destino realmente necessitava de um Analista de TI, o ato de remoção torna-se válido, operando-se a convalidação automática do desvio de finalidade pelo atendimento oblíquo do interesse público.", "B) O ato praticado caracteriza abuso de poder na modalidade excesso de poder, uma vez que o superintendente atuou fora dos limites de sua competência legalmente atribuída para gerir o quadro de pessoal da unidade.", "C) O ato administrativo padece de vício insanável de desvio de finalidade, sendo nulo por violar tanto a finalidade geral de satisfação do interesse público quanto a finalidade específica prevista na norma para o instituto da remoção.", "D) A conduta descrita configura mera irregularidade administrativa sanável, passível de revogação pelo Poder Judiciário mediante provocação do servidor interessado em sede de controle de mérito.", "E) A violação verificada no caso concreto restringe-se ao princípio da impessoalidade, não guardando qualquer relação com o princípio da moralidade administrativa ou da legalidade, que permanecem incólumes."], resposta_correta:2, explicacao:"A alternativa C está correta. Fundamentação: O princípio da impessoalidade, na vertente da finalidade, exige que o ato atenda à finalidade geral (interesse público) e à finalidade específica (adequar a lotação de pessoal, e não punir). Utilizar remoção de ofício com caráter punitivo configura desvio de finalidade (abuso de poder), tornando o ato nulo. Análise das incorretas: A é inválida em 'torna-se válido, operando-se a convalidação automática' (mesmo que haja necessidade de pessoal no destino, o vício de finalidade é insanável e o ato é nulo); B é inválida em 'modalidade excesso de poder' e 'fora dos limites de sua competência' (trata-se de desvio de poder/finalidade, em que o agente tem competência, mas desvirtua o fim legal); D é inválida em 'mera irregularidade administrativa sanável' e 'revogação pelo Poder Judiciário' (é vício de legalidade que gera anulação, e o Judiciário não revoga atos de outro Poder); E é inválida em 'restringe-se ao princípio da impessoalidade, não guardando qualquer relação com o princípio da moralidade' (a perseguição fere simultaneamente a impessoalidade, a moralidade e a legalidade). Comentário Avalia: O uso da remoção como punição velada é o caso clássico mais cobrado para testar a dupla finalidade (geral e específica) atrelada à impessoalidade.", status:0, historico:0},
{id:3196, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A contínua expansão institucional do agrupamento BRICS alterou vertiginosamente a balança do poder diplomático global ao incorporar nações repletas de vasto poderio energético. Sobre as novas diretrizes comerciais e orgânicas dessa aliança heterogênea no panorama sul global avalie minuciosamente as assertivas de macroeconomia. I - O convite oficial de adesão aos países detentores de gigantescas bacias petroleiras no oriente médio impulsiona o lastro político do bloco nas tratativas incipientes buscando a lenta desdolarização do fluxo mercantil de hidrocarbonetos. II - A arquitetura autônoma centralizada e moldada pelo Novo Banco de Desenvolvimento tenciona funcionar como válvula de escape diplomática ao oferecer financiamento massivo sem amarras ou bloqueios pautados na austeridade neoliberal do fundo monetário ocidental ativo e remanescente isolado rústico pacato e absoluto isolado cível. III - O documento de expansão formalizou paralelamente e juridicamente um tratado contínuo incondicional de defesa mútua bélica obrigando a constituição brasileira a decretar envio de tropas costeiras ativas perante invasões na área da península e Golfo estático passivo litorâneo inócuo. A coerência dos fatos expõe veracidade orgânica pautada em:", imagem:null, alternativas:["A) I, II e III.","B) Apenas II e III.","C) Apenas I e II.","D) I e III.","E) Apenas I."], resposta_correta:2, explicacao:"A alternativa C está correta. As diretrizes I e II expressam a musculatura central do 'BRICS Expandido':aglutinar gigantes do petróleo (Arábia Saudita, Irã, EAU) para reduzir o peso de Washington na balança transacional comercial, além de financiar estradas e pontes sem a asfixia das regras fiscais ditadas pela agenda da Casa Branca (I e II). A afirmativa III desaba fragorosamente ao forçar o candidato a engolir o BRICS como um pacto de cooperação e proteção militar blindado igual à OTAN, fato impossível visto que as próprias nações filiadas mantêm exércitos autônomos e focam primariamente na economia civil.", status:0, historico:0 },
{id:3197, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"No âmbito da Administração Pública Federal, a distinção conceitual e normativa entre os princípios expressos no caput do art. 37 da Constituição Federal de 1988 e os princípios reconhecidos pela doutrina e pela legislação infraconstitucional revela importantes desdobramentos para a governança de Tecnologia da Informação em universidades federais. Considerando o regime jurídico-administrativo e as disposições da Lei nº 9.784/1999, assinale a alternativa correta.", imagem:null, alternativas:["A) O princípio da finalidade está expressamente elencado no caput do art. 37 da Constituição Federal, confundindo-se com a eficiência administrativa na busca pelo melhor resultado operacional.", "B) Os princípios da razoabilidade, da proporcionalidade e da motivação, embora implícitos no texto constitucional, encontram-se expressamente positivados no caput do art. 2º da Lei nº 9.784/1999.", "C) O princípio da eficiência figurou no texto originário da Constituição de 1988 ao lado da legalidade, impessoalidade, moralidade e publicidade, orientando desde então a administração burocrática.", "D) Os princípios implícitos possuem hierarquia normativa inferior aos princípios expressos no art. 37 da Constituição Federal, devendo ceder integralmente diante de qualquer colisão no caso concreto.", "E) A obediência aos princípios expressos no caput do art. 37 da Constituição Federal restringe-se às pessoas jurídicas de direito público da Administração Direta e Indireta, excluindo as empresas estatais."], resposta_correta:1, explicacao:"A alternativa B está correta. Fundamentação: Conforme o art. 37, caput, da CF/88, os princípios expressos são Legalidade, Impessoalidade, Moralidade, Publicidade e Eficiência (LIMPE). Já os princípios da razoabilidade, proporcionalidade e motivação são implícitos na CF/88, mas estão expressamente previstos no art. 2º, caput, da Lei nº 9.784/1999. Análise das incorretas: A é inválida no fragmento 'expressamente elencado no caput do art. 37' e 'confundindo-se com a eficiência' (finalidade relaciona-se à impessoalidade e é expressa na Lei 9.784/99, não no caput do art. 37); C é inválida em 'texto originário da Constituição de 1988' (a eficiência foi inserida pela EC nº 19/1998, voltada à administração gerencial); D é inválida em 'hierarquia normativa inferior' (não há hierarquia prévia entre princípios constitucionais expressos e implícitos); E é inválida em 'restringe-se às pessoas jurídicas de direito público' e 'excluindo as empresas estatais' (o caput do art. 37 abrange toda a Administração Direta e Indireta de qualquer dos Poderes). Comentário Avalia: A banca Avalia frequentemente cobra a diferença entre estar expresso na CF/88 (LIMPE) e estar expresso na Lei nº 9.784/1999.", status:0, historico:0},
{id:3198, categoria:"Conhecimentos Específicos", materia:"Administração Pública", assunto:"Princípios da Administração Pública", cargo:"Analista de Tecnologia da Informação", ano:"2026", banca:"Avalia", concurso:"UFBA", enunciado:"Durante uma auditoria interna nos sistemas de gestão acadêmica da Universidade Federal da Bahia (UFBA), um Analista de Tecnologia da Informação depara-se com uma lacuna regulamentar específica quanto ao procedimento de ressarcimento de danos sofridos por equipamento pessoal de servidor que fora formalmente autorizado a utilizá-lo em atividade crítica de suporte remoto. À luz da evolução doutrinária e jurisprudencial acerca do princípio da legalidade na Administração Pública, analise as afirmativas a seguir: I. Diferentemente da esfera privada, na qual vigora o princípio da autonomia da vontade sob a premissa da liberdade, a legalidade administrativa submete a atuação estatal à lei, mesmo nos espaços de exercício do poder discricionário. II. A concepção contemporânea do bloco de legalidade, também denominada princípio da juridicidade, vincula o administrador público não apenas à literalidade da lei formal, mas à integralidade do Direito, abrangendo princípios constitucionais e gerais, como a vedação ao enriquecimento sem causa da Administração. III. Diante da inexistência de regra regulamentar casuística prevendo a hipótese exata de indenização ao servidor, o princípio da legalidade estrita impõe a omissão absoluta da Administração Universitária, sendo juridicamente impossível fundamentar o ato administrativo diretamente em princípios gerais do Direito. Está correto o que se afirma em:", imagem:null, alternativas:["A) I, apenas.", "B) I e II, apenas.", "C) I e III, apenas.", "D) II e III, apenas.", "E) I, II e III."], resposta_correta:1, explicacao:"A alternativa B está correta. Fundamentação: O item I está correto, pois contrapõe a legalidade privada (art. 5º, II, CF/88 - autonomia da vontade) à legalidade pública (art. 37, caput, CF/88), em que até a discricionariedade navega dentro das margens fixadas pela lei. O item II está correto, retratando a concepção moderna de juridicidade (bloco de legalidade), segundo a qual a atuação administrativa vincula-se à lei e aos princípios do ordenamento jurídico (art. 2º, parágrafo único, I, da Lei 9.784/99). Análise das incorretas: O item III é falso nos fragmentos 'impõe a omissão absoluta' e 'juridicamente impossível fundamentar o ato administrativo diretamente em princípios', pois a doutrina e a jurisprudência vedam que a Administração se esconda atrás de omissões regulamentares para causar prejuízo ou enriquecer ilicitamente, devendo decidir com base no bloco de legalidade. Comentário Avalia: Em provas de nível superior, a banca explora a transição da visão meramente positivista/formalista para o conceito de juridicidade.", status:0, historico:0},
{id:3199, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2024", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A transposição e sobreposição de rotas operacionais de escoamento no leito denso amazônico forjou o complexo conceito estrutural de narco-garimpo nos documentos da polícia civil e agências investigativas. Sobre as sinergias sombrias dessa simbiose de ilícitos, avalie analiticamente as afirmações táticas atreladas. I - A maciça injeção de capital limpo oriundo das remessas de entorpecentes viabiliza aos coordenadores da extração ilícita a compra à vista de maquinário logístico avançado como retroescavadeiras e hidroaviões dinamizando a supressão florestal. II - A malha difusa de pistas de pouso clandestinas cravadas no miolo das savanas desmatadas para suprir a demanda da lavra aurífera compartilha infraestrutura crucial servindo como hub reabastecedor ideal ininterrupto para pequenos aviões das facções regionais isoladas pátrias nativas pacatas puras. III - A lavagem integral da movimentação financeira suja pauta-se sumariamente na aquisição institucional contínua de letras do tesouro do banco central em nome de cooperativas rurais que permutam os recursos atrelados em moedas digitais controladas pelos procuradores da república em acordos bilaterais limítrofes nativos pacíficos isolados rústicos puros e orgânicos estáticos inativos densos marginais absolutos contínuos limpos pacatos remanescente de paz pátria inócuos ativos isolados e isentos puritanos cíveis limpos. A fundamentação exata atesta-se rigorosamente no cenário enquadrado em:", imagem:null, alternativas:["A) I e III.","B) II e III.","C) Apenas II.","D) I e II.","E) I, II e III."], resposta_correta:3, explicacao:"A alternativa D está correta. A simbiose do narco-garimpo (mistura da droga com o ouro) atua perfeitamente nas afirmações I e II:O traficante enche de dinheiro a operação de garimpo (comprando dragas que custam milhões) e as duas quadrilhas (comando vermelho e PCC) usam as mesmas pistas abertas ilegalmente na selva para movimentar suprimentos e pasta base. A terceira assertiva é escandalosamente errada porque mistura lavagem de dinheiro com a instituição do Banco Central (que não emite título para criminosos), inserindo procuradores da república como mediadores ilusórios de criptomoedas.", status:0, historico:0 },
{id:3200, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Surgida uma controvérsia técnica e econômico-financeira a respeito do restabelecimento do equilíbrio contratual em uma obra de engenharia da UFBA, a empresa contratada propôs a adoção de um meio alternativo de resolução de controvérsias. Com base nos arts. 151 a 154 da Lei nº 14.133/2021, assinale a alternativa correta:", imagem:null, alternativas:["A) A Lei nº 14.133/2021 veda expressamente o uso da arbitragem, da mediação e do comitê de resolução de disputas em contratos celebrados por autarquias federais.","B) Nas contratações regidas pela Lei nº 14.133/2021, poderão ser utilizados meios alternativos de prevenção e resolução de controvérsias, notadamente a conciliação, a mediação, o comitê de resolução de disputas e a arbitragem, sendo que o processo de escolha dos árbitros, dos colegiados arbitrais e dos comitês observará critérios isonômicos, técnicos e transparentes.","C) A arbitragem poderá ser realizada de forma sigilosa e julgada exclusivamente por equidade, abrangendo inclusive direitos indisponíveis como a anulação de multas penais.","D) Os contratos já em vigor na data de publicação da lei não podem ser aditados para permitir a adoção dos meios alternativos de resolução de controvérsias.","E) A escolha dos membros do comitê de resolução de disputas compete unilateralmente à empresa privada contratada, sem participação da Administração Pública."], resposta_correta:1, explicacao:"A alternativa B está correta, pois une literalmente os comandos do art. 151, caput, e do art. 154 da Lei nº 14.133/2021. A alternativa A está incorreta porque o art. 151 autoriza expressamente a conciliação, a mediação, o comitê de resolução de disputas e a arbitragem. A alternativa C está incorreta pois, segundo o art. 151, parágrafo único, e o art. 152, tais meios aplicam-se a direitos patrimoniais disponíveis e a arbitragem será sempre de direito (e não por equidade) e observará o princípio da publicidade. A alternativa D contraria o art. 153 (os contratos poderão ser aditados para permitir a adoção dos meios alternativos). A alternativa E viola o art. 154 (critérios isonômicos, técnicos e transparentes).", status:0, historico:0 },
{id:3201, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"O fiscal de um contrato de fornecimento de reagentes químicos para a UFBA, ao realizar a conferência física dos produtos entregues no almoxarifado, constatou que a metade dos frascos apresentava validade vencida e concentração química inferior à especificada no termo de referência. Diante dessa constatação, considerando o disposto nos arts. 117, 119 e 140 da Lei nº 14.133/2021, a conduta correta do fiscal do contrato consiste em:", imagem:null, alternativas:["A) Receber definitivamente todo o lote para não atrasar o cronograma de pagamento financeiro e solicitar verbalmente ao motorista da transportadora que envie novos produtos no mês seguinte.","B) Anotar a ocorrência em registro próprio, rejeitar no todo ou em parte o objeto que estiver em desacordo com o contrato, determinar que o contratado substitua a suas expensas os materiais com defeitos ou incorreções e informar a seus superiores em tempo hábil caso a situação demande providência sancionatória que ultrapasse sua competência.","C) Aceitar os produtos com validade vencida mediante concessão de desconto de cinco por cento diretamente na nota fiscal, lavrando termo de aditamento simplificado no ato da entrega.","D) Apreender definitivamente os produtos defeituosos em favor da UFBA e aplicar, de próprio punho e sem processo administrativo, multa de 30% sobre o valor global do contrato.","E) Encaminhar os frascos diretamente ao Tribunal de Contas da União, que é o órgão responsável por realizar o recebimento definitivo das compras nas autarquias federais."], resposta_correta:1, explicacao:"A alternativa B está correta, pois articula perfeitamente as atribuições legais do fiscal previstas no art. 117, § 1º (anotar em registro próprio todas as ocorrências e determinar o necessário para regularização), art. 140, § 1º (rejeitar no todo ou em parte o objeto em desacordo com o contrato), art. 119 (obrigação do contratado de substituir, a suas expensas, o objeto com vícios ou incorreções) e art. 117, § 2º (informar aos superiores o que ultrapassar sua competência). As demais alternativas propõem condutas ilegais, como recebimento de produto impróprio, aplicação direta de sanção sem processo pelo fiscal ou envio ao TCU para ato de gestão ordinária.", status:0, historico:0 },
{id:3202, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Ao iniciar a instrução de uma nova contratação de serviços na UFBA, um gestor solicita ao setor financeiro a emissão da nota de empenho, mas o Assistente Administrativo alerta que o processo ainda não possui a indicação dos créditos orçamentários para pagamento das parcelas vincendas no exercício nem a caracterização adequada do objeto. Nos termos do art. 150 da Lei nº 14.133/2021, a realização de contratação sem esses dois requisitos acarreta:", imagem:null, alternativas:["A) Mera irregularidade formal sanável mediante apostilamento no exercício financeiro subsequente, sem responsabilização do agente.","B) A suspensão temporária do contrato pelo prazo de 60 (sessenta) dias até que o Ministério da Educação suplemente a dotação da universidade.","C) A nulidade do ato e a responsabilização de quem lhe tiver dado causa.","D) A conversão automática do contrato em convênio de cooperação mútua sem repasse financeiro.","E) A validade plena do contrato, recaindo sobre a empresa contratada a obrigação de financiar a obra até a aprovação da lei orçamentária do ano seguinte."], resposta_correta:2, explicacao:"A alternativa C está correta, reproduzindo literalmente a parte final do art. 150 da Lei nº 14.133/2021: nenhuma contratação será feita sem a caracterização adequada de seu objeto e sem a indicação dos créditos orçamentários para pagamento das parcelas contratuais vincendas no exercício em que for realizada a contratação, sob pena de nulidade do ato e de responsabilização de quem lhe tiver dado causa. As demais alternativas suavizam ou ignoram a cominação expressa de nulidade e responsabilização.", status:0, historico:0 },
{id:3203, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Em um contrato de grande complexidade para modernização tecnológica dos laboratórios da UFBA, foi prevista cláusula de matriz de alocação de riscos entre contratante e contratado. Conforme dispõem os arts. 6º, inciso XXVII, e 103, caput e § 1º, da Lei nº 14.133/2021, a respeito da alocação de riscos e sua gestão contratual, julgue os itens a seguir com V (Verdadeiro) ou F (Falso): ( ) O contrato poderá identificar os riscos contratuais previstos e presumíveis e prever matriz de alocação de riscos, alocando-os entre contratante e contratado, mediante indicação daqueles a serem assumidos pelo setor público ou pelo setor privado ou daqueles a serem compartilhados. ( ) A alocação de riscos considerará, em compatibilidade com as obrigações e os encargos atribuídos às partes no contrato, a natureza do risco, o beneficiário das prestações a que se vincula e a capacidade de cada setor para melhor gerenciá-lo. ( ) A matriz de riscos caracteriza o equilíbrio econômico-financeiro inicial do contrato em termos de ônus financeiro decorrente de eventos supervenientes à contratação. Assinale a alternativa que apresenta a sequência correta:", imagem:null, alternativas:["A) V - V - V.","B) V - F - V.","C) F - V - V.","D) V - V - F.","E) F - F - V."], resposta_correta:0, explicacao:"A alternativa A está correta (V - V - V). A primeira assertiva é verdadeira, reproduzindo literalmente o art. 103, caput, da Lei nº 14.133/2021. A segunda assertiva é verdadeira, transcrevendo na íntegra o art. 103, § 1º, da referida lei. A terceira assertiva é verdadeira, correspondendo à definição legal de matriz de riscos constante do art. 6º, inciso XXVII, da Lei nº 14.133/2021.", status:0, historico:0 },
{id:3204, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Durante o acompanhamento de um contrato de prestação de serviços de apoio operacional na UFBA, o fiscal do contrato identificou que o preposto designado pela empresa contratada vinha mantendo comportamento hostil com os servidores da universidade e recusando-se a receber comunicados oficiais de fiscalização. Diante do disposto no art. 118 da Lei nº 14.133/2021, segundo o qual o contratado deverá manter preposto aceito pela Administração no local da obra ou do serviço para representá-lo na execução do contrato, é correto afirmar que:", imagem:null, alternativas:["A) A indicação do preposto é ato unilateral soberano da empresa contratada, sendo vedado à Administração recusá-lo ou exigir sua substituição sob qualquer pretexto.","B) Como o preposto deve ser 'aceito pela Administração', a UFBA pode recusar motivadamente o preposto inadequado e exigir que a contratada indique outro representante para o local do serviço.","C) O próprio Assistente Administrativo da UFBA deverá assumir cumulativamente a função de preposto da empresa privada até o final do contrato.","D) A recusa do preposto pela Administração acarreta a nulidade retroativa da licitação e a devolução de todos os valores já pagos pelos serviços prestados.","E) A presença de preposto somente é exigível em obras de engenharia de grande vulto acima de duzentos milhões de reais, sendo facultativa nos contratos de prestação de serviços."], resposta_correta:1, explicacao:"A alternativa B está correta. O art. 118 da Lei nº 14.133/2021 estatui expressamente que 'o contratado deverá manter preposto aceito pela Administração no local da obra ou do serviço para representá-lo na execução do contrato'. O requisito legal de aceitação pela Administração confere ao contratante público a prerrogativa de recusar, de forma motivada, o preposto que se mostre inapto ou inconveniente ao regular relacionamento contratual, exigindo sua substituição pela contratada. A alternativa A ignora a expressão 'aceito pela Administração'. A alternativa C viola frontalmente a segregação público-privada (servidor não pode ser representante da contratada). As alternativas D e E não possuem amparo no art. 118.", status:0, historico:0 },
{id:3205, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Concluída a execução de um contrato na UFBA, o setor de gestão contratual elabora a documentação de encerramento e avaliação de resultados para divulgação no Portal Nacional de Contratações Públicas (PNCP). Nos termos do art. 174, § 3º, inciso VI, alínea 'd', da Lei nº 14.133/2021, o PNCP conterá, entre outras informações, a divulgação, na forma de regulamento, de:", imagem:null, alternativas:["A) Relatório final com informações sobre a consecução dos objetivos que tenham justificado a contratação e eventuais condutas a serem adotadas para o aprimoramento das atividades da Administração.","B) Declaração sigilosa de conformidade emitida exclusivamente pela empresa contratada, vedado o acesso público aos dados de execução.","C) Extrato bancário pessoal dos fiscais e gestores que atuaram no acompanhamento do contrato durante todo o exercício financeiro.","D) Termo de quitação irrestrita que impede os órgãos de controle interno e externo de auditarem o contrato nos cinco anos subsequentes.","E) Parecer do Ministério das Relações Exteriores atestando o cumprimento das metas fiscais do contrato encerrado."], resposta_correta:0, explicacao:"A alternativa A está correta, reproduzindo literalmente o disposto no art. 174, § 3º, inciso VI, alínea 'd', da Lei nº 14.133/2021. Esse relatório final de gestão contratual consolida o ciclo de governança e aprendizado organizacional das contratações públicas. As alternativas B, C, D e E descrevem documentos esdrúxulos ou ilegais, incompatíveis com o formato de dados abertos e com a Lei de Acesso à Informação (art. 174, § 4º).", status:0, historico:0 },
{id:3206, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Ao assumir a fiscalização de um contrato de fornecimento de equipamentos médicos para o complexo hospitalar da UFBA, o Assistente Administrativo depara-se com uma cláusula ambígua acerca dos critérios de medição de uma etapa intermediária e teme que uma interpretação equivocada gere risco de dano ao erário. De acordo com o art. 117, § 3º, da Lei nº 14.133/2021, para prevenir riscos na execução contratual, o fiscal do contrato:", imagem:null, alternativas:["A) Deverá decidir isoladamente por intuição, visto que os órgãos jurídicos e de controle interno são proibidos de se manifestar antes da instauração de tomada de contas especial.","B) Será auxiliado pelos órgãos de assessoramento jurídico e de controle interno da Administração, que deverão dirimir dúvidas e subsidiá-lo com informações relevantes para prevenir riscos na execução contratual.","C) Deverá suspender imediatamente o contrato por prazo indeterminado e remeter os autos ao Poder Judiciário para ação declaratória de interpretação de cláusula.","D) Submeterá a dúvida ao preposto da empresa contratada, cuja interpretação técnica terá efeito vinculante para a Administração Pública.","E) Ficará eximido de realizar a medição da etapa, autorizando o pagamento integral sem conferência física sob o argumento de obscuridade editalícia."], resposta_correta:1, explicacao:"A alternativa B está correta, pois transcreve na íntegra o comando protetivo e colaborativo do art. 117, § 3º, da Lei nº 14.133/2021: o fiscal do contrato será auxiliado pelos órgãos de assessoramento jurídico e de controle interno da Administração, que deverão dirimir dúvidas e subsidiá-lo com informações relevantes para prevenir riscos na execução contratual. As demais alternativas contrariam diretamente o dever de auxílio preventivo prestado pela segunda linha de defesa ao fiscal do contrato.", status:0, historico:0 },
{id:3207, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Compare os procedimentos de recebimento provisório e definitivo nas contratações de 'obras e serviços' (art. 140, inciso I) e nas contratações de 'compras' (art. 140, inciso II) na Lei nº 14.133/2021. Assinale a alternativa que aponta corretamente a diferença procedimental estabelecida pelo legislador quanto ao recebimento provisório entre essas duas categorias:", imagem:null, alternativas:["A) Nas compras, o recebimento provisório exige termo detalhado assinado por comissão de três servidores; nas obras e serviços, o recebimento provisório é feito de forma sumária pelo almoxarife.","B) Nas obras e serviços, o recebimento provisório é feito pelo responsável por seu acompanhamento e fiscalização, mediante termo detalhado, quando verificado o cumprimento das exigências de caráter técnico; nas compras, o recebimento provisório é feito de forma sumária, pelo responsável por seu acompanhamento e fiscalização, com verificação posterior da conformidade do material com as exigências contratuais.","C) Nas compras, não existe a etapa de recebimento provisório, ocorrendo apenas o recebimento definitivo no ato da descarga do caminhão pelo motorista.","D) Nas obras e serviços, o recebimento provisório compete exclusivamente ao Tribunal de Contas da União; nas compras, compete ao agente de contratação que conduziu o pregão.","E) Em ambas as categorias o recebimento provisório é idêntico e dispensa qualquer registro escrito, bastando o carimbo no canhoto da nota fiscal pelo porteiro terceirizado."], resposta_correta:1, explicacao:"A alternativa B está correta, pois evidencia com precisão a sutil e importantíssima diferença textual entre a alínea 'a' do inciso I e a alínea 'a' do inciso II do art. 140 da Lei nº 14.133/2021. Em obras e serviços (inciso I, 'a'), o recebimento provisório dá-se 'mediante termo detalhado, quando verificado o cumprimento das exigências de caráter técnico'. Já em compras (inciso II, 'a'), o recebimento provisório ocorre 'de forma sumária, pelo responsável por seu acompanhamento e fiscalização, com verificação posterior da conformidade do material com as exigências contratuais'. A alternativa A inverte exatamente esses dois conceitos. As alternativas C, D e E contrariam frontalmente o art. 140.", status:0, historico:0 },
{id:3208, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"A estrutura de governança e controle das contratações públicas na UFBA organiza-se segundo o modelo das três linhas de defesa consagrado no art. 169 da Lei nº 14.133/2021. Considerando a composição legal de cada linha de defesa, assinale a alternativa correta:", imagem:null, alternativas:["A) A primeira linha de defesa é integrada pelas unidades de assessoramento jurídico e de controle interno do próprio órgão ou entidade.","B) A segunda linha de defesa é integrada pelo órgão central de controle interno da Administração (CGU) e pelo Tribunal de Contas da União (TCU).","C) A primeira linha de defesa é integrada por servidores e empregados públicos, agentes de licitação e autoridades que atuam na estrutura de governança do órgão ou entidade.","D) A terceira linha de defesa é integrada exclusivamente pelo Ministério Público Federal e pela Polícia Federal.","E) O controle social exercido pelos cidadãos substitui a segunda linha de defesa nas autarquias universitárias que possuem conselho curador."], resposta_correta:2, explicacao:"A alternativa C está correta, reproduzindo literalmente o art. 169, inciso I, da Lei nº 14.133/2021. As alternativas A e B estão incorretas porque invertem as linhas: as unidades de assessoramento jurídico e de controle interno do próprio órgão ou entidade integram a segunda linha de defesa (inciso II), enquanto o órgão central de controle interno da Administração e o tribunal de contas integram a terceira linha de defesa (inciso III). As alternativas D e E inventam composições estranhas ao texto do art. 169.", status:0, historico:0 },
{id:3209, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Ao estudar o sistema de controle das contratações na Lei nº 14.133/2021 (art. 169), o Assistente Administrativo da UFBA verifica onde se situam a Procuradoria Federal junto à universidade (unidade de assessoramento jurídico) e a Auditoria Interna da própria autarquia, bem como onde se posicionam a Controladoria-Geral da União (órgão central de controle interno) e o Tribunal de Contas da União. Assinale a alternativa que indica a alocação correta desses órgãos nas linhas de defesa:", imagem:null, alternativas:["A) As unidades de assessoramento jurídico e de controle interno do próprio órgão ou entidade integram a segunda linha de defesa; o órgão central de controle interno da Administração e o tribunal de contas integram a terceira linha de defesa.","B) As unidades de assessoramento jurídico integram a primeira linha de defesa; a auditoria interna, a CGU e o TCU integram conjuntamente a segunda linha de defesa.","C) O controle interno do próprio órgão integra a terceira linha de defesa; o tribunal de contas atua fora das linhas de defesa por pertencer ao Poder Judiciário.","D) Todos os órgãos citados integram a primeira linha de defesa, ficando a segunda e a terceira linhas restritas às empresas de auditoria independente contratadas no mercado.","E) A unidade de assessoramento jurídico integra a terceira linha de defesa; o órgão central de controle interno integra a primeira linha de defesa."], resposta_correta:0, explicacao:"A alternativa A está correta, em estrita conformidade com os incisos II e III do caput do art. 169 da Lei nº 14.133/2021: a segunda linha de defesa é integrada pelas unidades de assessoramento jurídico e de controle interno do próprio órgão ou entidade (inciso II); e a terceira linha de defesa é integrada pelo órgão central de controle interno da Administração e pelo tribunal de contas (inciso III). As demais alternativas embaralham as linhas de defesa na tentativa de confundir o controle interno setorial/próprio (2ª linha) com o órgão central de controle interno e o controle externo (3ª linha).", status:0, historico:0 },
{id:3210, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"As contratações públicas na UFBA submetem-se a práticas contínuas e permanentes de gestão de riscos e de controle preventivo, inclusive mediante adoção de recursos de tecnologia da informação. De acordo com o art. 169, § 1º, combinado com o art. 11, parágrafo único, da Lei nº 14.133/2021, a responsabilidade pela implementação dessas práticas e pela governança das contratações cabe:", imagem:null, alternativas:["A) Exclusivamente aos servidores ocupantes do cargo de Assistente Administrativo que atuam na primeira linha de defesa operacional.","B) À alta administração do órgão ou entidade, que levará em consideração os custos e os benefícios decorrentes de sua implementação, optando-se pelas medidas que promovam relações íntegras e confiáveis, com segurança jurídica para todos os envolvidos, e que produzam o resultado mais vantajoso para a Administração, com eficiência, eficácia e efetividade nas contratações públicas.","C) Ao Tribunal de Contas da União, que deve redigir e aprovar o plano anual de contratações de cada universidade federal.","D) Às empresas privadas contratadas, que assumem por delegação legal a governança interna da autarquia durante a vigência dos contratos.","E) Exclusivamente ao pregoeiro, que responde pessoalmente pela ausência de estrutura de gestão de riscos na universidade."], resposta_correta:1, explicacao:"A alternativa B está correta, reproduzindo literalmente o art. 169, § 1º, em harmonia com o art. 11, parágrafo único, da Lei nº 14.133/2021. A responsabilidade pela governança das contratações e pela implementação das práticas contínuas e permanentes de gestão de riscos e de controle preventivo é da alta administração do órgão ou entidade. As alternativas A, C, D e E transferem indevidamente uma atribuição estratégica da alta administração para agentes operacionais, órgãos externos ou particulares.", status:0, historico:0 },
{id:3211, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Durante uma ação de supervisão nos contratos da UFBA, integrantes das linhas de defesa identificaram uma impropriedade formal na instrução de um processo licitatório que não configurou dano ao erário nem decorreu de dolo ou fraude. Acerca da atuação dos agentes de controle diante de impropriedades formais e para assegurar o acesso a informações, julgue os itens a seguir à luz dos §§ 2º e 3º do art. 169 da Lei nº 14.133/2021: I. Para a realização de suas atividades, os órgãos de controle deverão ter acesso irrestrito aos documentos e às informações necessárias à realização dos trabalhos, inclusive aos documentos classificados pelo órgão ou entidade nos termos da Lei nº 12.527/2011 (Lei de Acesso à Informação). II. O órgão de controle com o qual foi compartilhada eventual informação sigilosa tornar-se-á corresponsável pela manutenção do seu sigilo. III. Quando constatarem impropriedade formal, os integrantes das linhas de defesa deverão determinar a anulação imediata do contrato e a demissão sumária do servidor, sendo vedada a adoção de medidas de orientação e treinamento. Está correto o que se afirma em:", imagem:null, alternativas:["A) I, apenas.","B) I e II, apenas.","C) II e III, apenas.","D) I e III, apenas.","E) I, II e III."], resposta_correta:1, explicacao:"A alternativa B está correta (I e II, apenas). Os itens I e II reproduzem fielmente o disposto no art. 169, § 2º, da Lei nº 14.133/2021 (acesso irrestrito aos documentos, inclusive classificados pela LAI, tornando-se o órgão de controle corresponsável pela manutenção do sigilo). O item III está incorreto, pois o art. 169, § 3º, inciso I, estabelece um controle pedagógico e proporcional: diante de impropriedade formal, os integrantes das linhas de defesa adotarão medidas para o saneamento do ato e para a mitigação de riscos de sua nova ocorrência, preferencialmente com o aperfeiçoamento dos controles preventivos e com a capacitação dos agentes públicos responsáveis (somente adotando a apuração de responsabilidade do inciso II quando a irregularidade configurar dano à Administração).", status:0, historico:0 },
{id:3212, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Na fiscalização dos atos previstos na Lei nº 14.133/2021, os órgãos de controle não atuam de forma aleatória, mas pautados por parâmetros técnicos e processuais definidos no art. 170 da referida lei. Sobre os critérios de fiscalização e o trâmite de informações perante os órgãos de controle, assinale a alternativa correta:", imagem:null, alternativas:["A) Os órgãos de controle adotarão, na fiscalização dos atos previstos na Lei, critérios de oportunidade, materialidade, relevância e risco e considerarão as razões apresentadas pelos órgãos e entidades responsáveis e os resultados obtidos com a contratação.","B) As razões apresentadas pelos órgãos e entidades responsáveis poderão ser encaminhadas a qualquer tempo, inclusive após o julgamento definitivo pelo plenário do tribunal de contas, podendo ser livremente desentranhadas dos autos a pedido do gestor.","C) A omissão da UFBA na prestação das informações solicitadas suspenderá automaticamente as deliberações dos órgãos de controle e interromperá seus prazos de tramitação até que o reitor se manifeste.","D) Os órgãos de controle são obrigados a analisar exaustivamente todos os documentos juntados pelas partes, ainda que sejam manifestamente impertinentes, meramente protelatórios ou de nenhum interesse para o esclarecimento dos fatos.","E) Apenas os licitantes habilitados no certame possuem legitimidade para representar aos órgãos de controle interno ou ao tribunal de contas contra irregularidades na aplicação da Lei nº 14.133/2021, sendo vedada a representação por pessoa física."], resposta_correta:0, explicacao:"A alternativa A está correta, transcrevendo literalmente o caput do art. 170 da Lei nº 14.133/2021. A alternativa B está incorreta porque o art. 170, § 1º, determina que as razões deverão ser encaminhadas até a conclusão da fase de instrução do processo e não poderão ser desentranhadas dos autos. A alternativa C está incorreta pois o art. 170, § 2º, dispõe que a omissão na prestação das informações não impedirá as deliberações dos órgãos de controle nem retardará a aplicação de qualquer de seus prazos de tramitação e de deliberação. A alternativa D está incorreta porque o art. 170, § 3º, estabelece que os órgãos de controle desconsiderarão os documentos impertinentes, meramente protelatórios ou de nenhum interesse para o esclarecimento dos fatos. A alternativa E está incorreta pois o art. 170, § 4º, garante que qualquer licitante, contratado ou pessoa física ou jurídica poderá representar aos órgãos de controle interno ou ao tribunal de contas competente.", status:0, historico:0 },
{id:3213, categoria:"Conhecimentos Específicos", materia:"Licitações e contratos adm", assunto:"Infrações, sanções e controle", cargo:"Assistente Administrativo", ano:"2026", banca:"Avalia", concurso:"UFBA 2026", enunciado:"Durante uma auditoria de conformidade nas rotinas do setor de compras da UFBA, a equipe de fiscalização de controle pretende formular propostas de encaminhamento que alterarão significativamente os fluxos de trabalho da autarquia. Conforme o art. 171, incisos I e II, da Lei nº 14.133/2021, na fiscalização de controle será observado o seguinte:", imagem:null, alternativas:["A) É vedado dar conhecimento prévio aos gestores sobre possíveis propostas de encaminhamento antes da publicação do acórdão final, a fim de preservar o elemento surpresa da auditoria.","B) Deverá haver viabilização de oportunidade de manifestação aos gestores sobre possíveis propostas de encaminhamento que terão impacto significativo nas rotinas de trabalho dos órgãos e entidades fiscalizados, a fim de que eles disponibilizem subsídios para avaliação prévia da relação entre custo e benefício dessas possíveis proposições.","C) Os relatórios de auditoria poderão basear-se em impressões subjetivas dos auditores e denúncias anônimas não verificadas, dispensando evidências documentais quando houver suspeita de sobrepreço.","D) A manifestação dos gestores sobre a relação custo-benefício das propostas de encaminhamento vincula obrigatoriamente o tribunal de contas, que não poderá manter a recomendação caso o reitor discorde.","E) Os procedimentos de auditoria nas autarquias universitárias dispensam fundamentação técnica, regendo-se pelo livre convencimento íntimo da primeira linha de defesa."], resposta_correta:1, explicacao:"A alternativa B está correta, reproduzindo literalmente o art. 171, inciso I, da Lei nº 14.133/2021. A alternativa A está incorreta porque o inciso I exige justamente a oportunidade de manifestação prévia dos gestores sobre propostas com impacto significativo nas rotinas de trabalho. As alternativas C e E estão incorretas porque o art. 171, inciso II, exige a adoção de procedimentos objetivos e imparciais e elaboração de relatórios tecnicamente fundamentados, baseados exclusivamente nas evidências obtidas e organizados de acordo com as normas de auditoria do respectivo órgão de controle, evitando que interesses pessoais e interpretações tendenciosas interfiram. A alternativa D está incorreta pois os gestores fornecem subsídios para avaliação prévia, mas não detêm poder de veto sobre a deliberação final do órgão de controle.", status:0, historico:0 },
{id:3214, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Em meados de 2024, o Brasil enfrentou uma epidemia histórica de dengue impulsionada por fatores climáticos e pela circulação simultânea de múltiplos sorotipos do vírus. Como resposta, o Sistema Único de Saúde (SUS) incorporou a vacina Qdenga. Sobre a estratégia de vacinação e o contexto epidemiológico inicial, assinale a alternativa correta.", imagem:null, alternativas:["A) A imunização foi inicialmente direcionada de forma universal a todos os brasileiros acima de 60 anos por representarem o grupo de maior letalidade.","B) A vacina foi desenvolvida integralmente pelo Instituto Butantan em parceria com a Fiocruz, garantindo autossuficiência nacional desde o primeiro lote.","C) O Ministério da Saúde limitou as primeiras doses a faixas etárias específicas de crianças e adolescentes em municípios com alta transmissão, devido à escassez global do imunizante no laboratório fabricante.","D) A incorporação da Qdenga substituiu as ações de combate vetorial em campo, uma vez que a vacina bloqueia a transmissão do vírus pelo mosquito Aedes aegypti independentemente de criadouros.","E) O avanço da vacinação suspendeu a estratégia do uso de mosquitos infectados com a bactéria Wolbachia, considerada incompatível com a nova tecnologia de mRNA da vacina."], resposta_correta:2, explicacao:"A alternativa C está correta. A vacina Qdenga (da farmacêutica japonesa Takeda) foi incorporada ao SUS em 2024. Devido à capacidade restrita de produção do laboratório, o Ministério da Saúde precisou priorizar a faixa etária de 10 a 14 anos em municípios com alta endemicidade. A alternativa A erra ao afirmar vacinação universal para idosos. A B erra a origem (a vacina é da Takeda, não do Butantan). A alternativa D altera as consequências reais da vacina, que protege o indivíduo, mas não substitui o controle vetorial do Agente de Endemias. A E mistura conceitos errôneos sobre Wolbachia e mRNA.", status:0, historico:0 },
{id:3215, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Em 2024, o Brasil registrou um aumento expressivo e a expansão territorial de casos da Febre do Oropouche, doença que historicamente se concentrava na Região Norte e passou a afetar outros estados brasileiros. Considerando as características dessa emergência em saúde pública, é correto afirmar que a Febre do Oropouche é transmitida prioritariamente:", imagem:null, alternativas:["A) pela picada de mosquitos do gênero Culicoides, popularmente conhecidos como maruim ou mosquito-pólvora, causando sintomas clinicamente semelhantes aos da dengue.","B) pelo mesmo vetor vetor biológico da malária, o mosquito Anopheles, exigindo que os agentes de endemias apliquem os mesmos protocolos de bloqueio hídrico usados em garimpos.","C) exclusivamente por contato direto com gotículas respiratórias de primatas não humanos infectados em áreas de desmatamento da Mata Atlântica.","D) pela ingestão de água contaminada pelas fezes do mosquito Aedes aegypti durante períodos de intensas enchentes urbanas.","E) pela mordedura de carrapatos do gênero Amblyomma, que migraram das capivaras para áreas residenciais devido às secas no Pantanal."], resposta_correta:0, explicacao:"A alternativa A está correta. A Febre do Oropouche é uma arbovirose cujo principal vetor urbano e periurbano é o Culicoides paraensis (maruim). Em 2024, a doença espalhou-se para fora da bacia amazônica, causando preocupação devido aos sintomas muito similares aos da dengue (febre, mialgia, cefaleia), o que dificulta o diagnóstico clínico inicial. O distrator B aponta o vetor da malária. O C sugere via respiratória (falso, é vetorial). O D inventa uma via de transmissão hídrica para o Aedes. O E descreve a Febre Maculosa, não o Oropouche.", status:0, historico:0 },
{id:3216, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"No primeiro semestre de 2024, o estado do Rio Grande do Sul foi assolado pela maior tragédia climática de sua história, com enchentes devastando dezenas de municípios. Após o recuo das águas, as autoridades de saúde pública emitiram alertas máximos para o aumento exponencial de uma doença infecciosa específica, intimamente ligada ao contato com a água das inundações. Trata-se da:", imagem:null, alternativas:["A) Leishmaniose Visceral, cujos reservatórios caninos foram amplamente deslocados pelas correntezas urbanas.","B) Leptospirose, causada por uma bactéria presente na urina de roedores infectados que se mistura facilmente às águas de enchentes e lama.","C) Febre Amarela urbana, desencadeada pela proliferação maciça de mosquitos em poças d'água contaminadas com material orgânico e resíduos químicos.","D) Doença de Chagas, ocasionada pelo contato da pele ferida da população com as fezes do inseto barbeiro arrastado pela enchente.","E) Malária, cujos índices dispararam nas áreas metropolitanas alagadas devido à alteração drástica da salinidade dos rios da bacia do Guaíba."], resposta_correta:1, explicacao:"A alternativa B está correta. A Leptospirose é a principal doença epidêmica pós-enchentes no Brasil. A bactéria do gênero Leptospira, presente na urina de ratos (reservatórios), contamina a água e a lama das inundações, penetrando na pele humana, especialmente através de arranhões ou permanência prolongada na água. Os distratores apontam doenças cujos ciclos de transmissão não são diretamente impulsionados pelo simples contato com a água de alagamento (Leishmaniose é por mosquito palha; Febre Amarela e Malária por mosquitos específicos; Chagas por barbeiro/ingestão).", status:0, historico:0 },
{id:3217, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Avaliando as atualizações recentes no Calendário Nacional de Vacinação elaboradas pelo Programa Nacional de Imunizações (PNI), julgue as afirmativas a seguir sobre as mudanças no esquema contra a Poliomielite.\nI - O Ministério da Saúde determinou a substituição definitiva da Vacina Oral Poliomielite (VOP), as famosas gotinhas, pela Vacina Inativada Poliomielite (VIP), de aplicação injetável, nas doses de reforço.\nII - A transição tecnológica para a vacina inativada atende a recomendações da Organização Mundial da Saúde (OMS) para mitigar o risco, ainda que raríssimo, da poliomielite derivada da própria vacina atenuada.\nIII - A mudança ocorreu em virtude da identificação de um grande surto de poliomielite selvagem na região Nordeste em 2024, que tornou as gotinhas ineficazes.\nA análise atesta que estão corretas:", imagem:null, alternativas:["A) I, II e III.","B) Apenas I e III.","C) Apenas II e III.","D) Apenas I e II.","E) Apenas III."], resposta_correta:3, explicacao:"A alternativa D está correta. As afirmativas I e II são verdadeiras. Em 2024, o Brasil iniciou a substituição das doses de reforço da poliomielite (que eram feitas com a VOP bivalente - gotinha) pela VIP (injetável e inativada). Como o vírus selvagem está erradicado no Brasil há décadas, a OMS recomenda usar vacinas inativadas para zerar o risco de pólio derivada do vírus vivo enfraquecido presente nas gotinhas. A afirmativa III é falsa pois não houve surto de vírus selvagem no Brasil recente; o país segue com certificado de erradicação, embora as taxas de cobertura tenham gerado alertas anteriores.", status:0, historico:0 },
{id:3218, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Nos últimos anos, a Terra Indígena Yanomami, localizada entre os estados de Roraima e Amazonas, tornou-se o epicentro de uma profunda crise humanitária e de saúde pública, demandando ações contínuas do governo federal. O vetor principal que desencadeou os alarmantes índices de desnutrição severa e o descontrole de doenças endêmicas, notadamente a malária, nesse território foi:", imagem:null, alternativas:["A) o avanço da fronteira agrícola de monocultura de soja que eliminou os predadores naturais do mosquito palha na floresta tropical.","B) a construção de complexos hidrelétricos no rio Uraricoera, que gerou reservatórios de água estagnada e deslocou as comunidades de suas rotas de caça.","C) a migração de milhares de refugiados venezuelanos que se fixaram no território indígena, sobrecarregando os polos base do Distrito Sanitário Especial Indígena.","D) a mutação natural do vírus da febre amarela nos primatas da região, que impossibilitou o acesso das equipes de saúde às aldeias isoladas por questões de biossegurança.","E) a invasão massiva de garimpeiros ilegais, cujas atividades causaram o desmatamento, a contaminação dos rios por mercúrio e a multiplicação desenfreada de criadouros do mosquito transmissor da malária nas cavas abertas."], resposta_correta:4, explicacao:"A alternativa E está correta. A tragédia na TI Yanomami está visceralmente ligada à invasão do garimpo ilegal. O processo de extração de ouro cria gigantescas cavas de água parada (criadouros perfeitos para o Anopheles, transmissor da malária), afugenta a caça, destrói as roças e contamina os rios com mercúrio, o que resulta na explosão simultânea de malária e desnutrição. O distrator A fala de soja; B de hidrelétricas; C culpa refugiados; D inventa uma mutação viral, ocultando a raiz estrutural do problema que é o crime ambiental do garimpo.", status:0, historico:0 },
{id:3219, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Durante os meses de agosto e setembro de 2024, grande parte do território brasileiro registrou péssimos índices de qualidade do ar, com o céu de diversas capitais tomado por uma densa cortina de fumaça, gerando alertas de saúde por problemas respiratórios. Esse fenômeno meteorológico e ambiental de escala continental foi causado diretamente:", imagem:null, alternativas:["A) pela erupção em cadeia de complexos vulcânicos na cordilheira dos Andes, cujas cinzas foram empurradas para o Brasil por frentes frias.","B) pela combinação de uma seca extrema com a proliferação de focos de incêndio descontrolados na Amazônia, no Pantanal e em países vizinhos como a Bolívia, cujos ventos transportaram a fuligem pelo corredor de umidade.","C) pelo colapso das barragens de rejeitos químicos no interior de Minas Gerais, que evaporaram compostos tóxicos na atmosfera ao longo da bacia do rio São Francisco.","D) pela intensificação abrupta do fenômeno El Niño, que transformou a umidade natural do Sudeste em névoas secas de poeira saariana vindas pelo Oceano Atlântico.","E) pelo aumento repentino da queima de carvão mineral nas termoelétricas da região Sul para suprir o apagão nacional do Sistema Interligado Nacional no mesmo período."], resposta_correta:1, explicacao:"A alternativa B está correta. O evento marcante de 2024 foi a densa camada de fumaça que cobriu cerca de 60% do Brasil (e países vizinhos). Foi resultado de queimadas recordes na Amazônia, no Pantanal e em partes da Bolívia e Paraguai, agravadas pela estiagem severa. Os ventos chamados 'Rios Voadores', que normalmente trazem chuva da Amazônia para o Sul/Sudeste, transportaram enormes corredores de fumaça. Os distratores inventam causas absurdas como vulcões (A), rompimento químico gasoso (C) ou poeira do Saara (D).", status:0, historico:0 },
{id:3220, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A Organização Mundial da Saúde (OMS) declarou em 2024, pela segunda vez em pouco tempo, Emergência de Saúde Pública de Importância Internacional devido à explosão de casos de Mpox. Sobre o cenário epidemiológico que fundamentou essa recente declaração e seus reflexos no Brasil, é válido afirmar que o alerta global ocorreu devido:", imagem:null, alternativas:["A) à comprovação de que o vírus sofreu mutação para transmissão aérea a longas distâncias, com letalidade superior à da Covid-19 no continente europeu.","B) à constatação de que o mosquito Aedes aegypti tornou-se capaz de inocular o vírus durante o repasto sanguíneo nas regiões endêmicas brasileiras.","C) ao surgimento e rápida disseminação de uma nova cepa (Clado Ib) em países da África, que se mostrou mais transmissível inclusive por contatos não sexuais, gerando risco de importação para as Américas.","D) ao fim do estoque mundial de retrovirais, o que impediu o controle dos casos autóctones que nasceram exclusivamente nas comunidades isoladas do cerrado brasileiro.","E) à decisão política de bloquear a produção das vacinas tradicionais de varíola, deixando a população mundial imediatamente suscetível às cepas de laboratório do vírus."], resposta_correta:2, explicacao:"A alternativa C está correta. A OMS decretou emergência global para a Mpox (antiga varíola dos macacos) novamente em meados de 2024 devido à expansão acelerada de uma variante mais agressiva, o Clado Ib, concentrado na República Democrática do Congo e países vizinhos na África, com transmissão sustentada e maior contágio intrafamiliar (inclusive crianças). O distrator A exagera afirmando transmissão aérea tipo Covid. O B cria uma transmissão vetorial irreal. O D e o E trazem teorias conspiratórias e dados falsos sobre origem e bloqueios de produção.", status:0, historico:0 },
{id:3221, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Na seara política e econômica, a aprovação da Emenda Constitucional da Reforma Tributária (EC 132/2023) e sua subsequente regulamentação pautaram os noticiários em todo o país. O principal pilar estrutural dessa reforma voltado ao consumo consiste na:", imagem:null, alternativas:["A) unificação de cinco tributos atuais (PIS, Cofins, IPI, ICMS e ISS) na forma de um Imposto sobre Valor Adicionado (IVA) Dual, dividido em CBS federal e IBS para estados e municípios.","B) extinção absoluta do Imposto de Renda da Pessoa Física para trabalhadores que ganham até dez salários mínimos, compensada pela criação do imposto sobre grandes fortunas estaduais.","C) substituição do modelo de arrecadação descentralizado por uma alíquota única de contribuição sobre transações financeiras (nos moldes da antiga CPMF), abolindo impostos estaduais.","D) isenção total de impostos de importação sobre produtos asiáticos vendidos em plataformas digitais, com o objetivo de frear a inflação no varejo local de pequenas cidades.","E) transferência da competência de cobrança de todos os impostos sobre serviços e mercadorias exclusivamente para a esfera dos municípios, descentralizando a Receita Federal."], resposta_correta:0, explicacao:"A alternativa A está correta. A Reforma Tributária do Consumo aprovada criou o modelo de IVA Dual. PIS, Cofins e IPI (federais) transformam-se na CBS (Contribuição sobre Bens e Serviços); ICMS (estadual) e ISS (municipal) formam o IBS (Imposto sobre Bens e Serviços). O distrator B trata de imposto de renda, que é o foco da segunda fase, não a aprovada. O C remete à recriação de CPMF, refutada. O D inverte a realidade (houve taxação das compras internacionais, a 'taxa das blusinhas'). O E distorce a lógica federativa do IBS.", status:0, historico:0 },
{id:3222, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Um dos maiores debates ambientais e energéticos do Brasil recente envolve a exploração de petróleo na chamada 'Margem Equatorial'. Analise as afirmativas referentes a esse conflito de interesses governamentais.\nI - A Petrobras busca obter licença para perfurar blocos de exploração na bacia da Foz do Amazonas, visando encontrar novas reservas e repor o declínio futuro do Pré-sal.\nII - O IBAMA (Instituto Brasileiro do Meio Ambiente e dos Recursos Naturais Renováveis) tem negado repetidamente as licenças ambientais para essa exploração, apontando inconsistências e riscos à biodiversidade costeira.\nIII - A área disputada da Margem Equatorial localiza-se na bacia de Campos, no litoral sul do Rio de Janeiro, sendo o maior polo turístico submerso do país.\nEstão corretas as afirmativas:", imagem:null, alternativas:["A) I, II e III.","B) Apenas I e III.","C) Apenas I e II.","D) Apenas II e III.","E) Apenas II."], resposta_correta:2, explicacao:"A alternativa C está correta. As afirmativas I e II espelham exatamente o impasse interno no governo:de um lado o Ministério de Minas e Energia e a Petrobras buscando viabilidade econômica na Foz do Amazonas; do outro, o Ministério do Meio Ambiente e o Ibama aplicando o rigor técnico e negando as licenças por falta de garantias ambientais sólidas. A afirmativa III é grosseiramente falsa, a Margem Equatorial estende-se do Amapá ao Rio Grande do Norte (costa norte e nordeste), e não no litoral fluminense (onde fica o atual Pré-sal/Campos).", status:0, historico:0 },
{id:3223, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Brasil assumiu a presidência do G20 em 2024, culminando com a Cúpula de Líderes realizada no Rio de Janeiro. No exercício de sua liderança diplomática no bloco, o governo brasileiro priorizou como principal marca estrutural da sua gestão o lançamento global da iniciativa:", imagem:null, alternativas:["A) Tratado de Defesa Nuclear e Restrição Balística do Atlântico Sul, que expulsa nações em conflito da bacia amazônica.","B) Fundo Monetário de Transição do Brics, que estipula a adoção compulsória de uma moeda unificada para todas as transações comerciais do Mercosul com a União Europeia.","C) Agenda de Privatização Hídrica Mundial, visando criar um mercado livre de negociação de bacias hidrográficas entre países em desenvolvimento para quitar dívidas públicas.","D) Aliança Global contra a Fome e a Pobreza, que busca angariar recursos e unificar políticas públicas internacionais baseadas em evidências para erradicar essas mazelas socioeconômicas.","E) Moratória de Imigração Climática, que fecha juridicamente as fronteiras terrestres sul-americanas para refugiados afetados por secas nos próximos cinco anos."], resposta_correta:3, explicacao:"A alternativa D está correta. A grande bandeira da presidência brasileira no G20 (grupo das maiores economias do mundo) em 2024 foi a criação e o lançamento da Aliança Global contra a Fome e a Pobreza, puxando os holofotes internacionais para o financiamento de políticas sociais e de transferência de renda sustentáveis. O Brasil também pautou transição ecológica e reforma da governança global. Os distratores A, B, C e E citam propostas fictícias, agressivas ou diametralmente opostas aos princípios da diplomacia brasileira atual.", status:0, historico:0 },
{id:3224, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Sobre as recentes reformulações na estrutura do Programa Mais Médicos para o Brasil, julgue as afirmativas como Verdadeiras (V) ou Falsas (F).\n( ) O programa retomou as atividades assegurando a prioridade absoluta de vagas para médicos formados no Brasil ou com diploma revalidado (registro no CRM).\n( ) A nova lei que recriou o programa proibiu de maneira definitiva a participação de profissionais brasileiros formados no exterior sem o Revalida.\n( ) Foram instituídos novos incentivos financeiros para promover a fixação de profissionais em áreas de extrema vulnerabilidade e periferias, incluindo bônus para pagamento de dívidas do FIES.\n( ) O controle operacional e financeiro do Mais Médicos foi transferido integralmente para os governos estaduais, eximindo o Ministério da Saúde do pagamento das bolsas.\nA sequência correta, de cima para baixo, é:", imagem:null, alternativas:["A) V, F, V, F.","B) V, V, F, F.","C) F, F, V, V.","D) F, V, V, F.","E) V, F, F, V."], resposta_correta:0, explicacao:"A alternativa A está correta (V, F, V, F). Primeira é Verdadeira:a prioridade legal das chamadas é sempre para profissionais brasileiros/formados no Brasil com CRM. Segunda é Falsa:o programa não proibiu brasileiros (e até estrangeiros) sem Revalida; eles atuam através de registros provisórios do Ministério da Saúde caso as vagas não sejam preenchidas na prioridade. Terceira é Verdadeira:o novo formato apostou pesado em indenizações adicionais e auxílio para pagar o FIES para atrair médicos para locais de difícil provimento. Quarta é Falsa:o programa continua sendo cofinanciado fortemente pelo Ministério da Saúde (União).", status:0, historico:0 },
{id:3225, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"No contexto do avanço científico no combate às arboviroses, a Agência Nacional de Vigilância Sanitária (Anvisa) aprovou o registro de uma vacina inédita contra o vírus causador da febre Chikungunya, a vacina Ixchiq. Considerando o perfil epidemiológico dessa doença que afeta drasticamente a saúde ocupacional e a qualidade de vida dos pacientes, a referida vacina caracteriza-se como:", imagem:null, alternativas:["A) um imunizante de tecnologia de RNA mensageiro voltado à população pediátrica, visando erradicar a transmissão transovariana do vírus nos ovos do Aedes aegypti em água parada.","B) a primeira vacina aprovada no país para prevenção da doença, sendo inicialmente indicada para adultos, administrada em dose única e desenvolvida utilizando o vírus vivo atenuado.","C) uma formulação combinada que protege simultaneamente contra os quatro sorotipos da dengue, Zika e Chikungunya, sendo produzida em larga escala pelo governo federal.","D) um produto químico voltado à fumigação (Fumacê) nas residências, e não de uso humano, servindo como barreira sanitária para matar os mosquitos adultos no ar.","E) um antiviral de uso contínuo distribuído de forma universal e gratuita em farmácias populares para eliminar as sequelas crônicas nas articulações após a infecção."], resposta_correta:1, explicacao:"A alternativa B está correta. A vacina Ixchiq (da empresa francesa Valneva, que firmou acordo com o Butantan) foi aprovada pela Anvisa. É o primeiro imunizante contra Chikungunya no mundo/Brasil, é de vírus vivo atenuado, dose única, e a aprovação inicial foca em maiores de 18 anos. O distrator A fala de mRNA e bloqueio vetorial (incorreto). O C cria uma vacina tríplice que não existe comercialmente ainda. O D confunde vacina com larvicida/adulticida. O E confunde vacina (prevenção) com tratamento medicamentoso para sequelas articulares crônicas típicas da doença.", status:0, historico:0 },
{id:3226, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Em 2024, o Brasil testemunhou um embate jurídico de repercussão internacional que culminou na suspensão temporária do acesso à rede social X (antigo Twitter) em todo o território nacional. A decisão monocrática de bloqueio proferida pelo Supremo Tribunal Federal (STF) fundamentou-se legalmente:", imagem:null, alternativas:["A) na exigência do Ministério da Fazenda pela taxação direta de postagens políticas, que a plataforma se recusou a recolher durante o período eleitoral.","B) na quebra do monopólio econômico das big techs de comunicação pelo Conselho Administrativo de Defesa Econômica (CADE) para favorecer redes sociais desenvolvidas por empresas estatais.","C) no descumprimento reiterado de ordens judiciais de bloqueio de perfis investigados e na recusa da empresa em indicar um representante legal no Brasil, conforme exige o Marco Civil da Internet.","D) na publicação de um decreto presidencial visando silenciar canais de oposição nas redes sob a justificativa de segurança cibernética durante a cúpula do G20.","E) na constatação técnica de que os servidores da empresa estavam fisicamente hospedados em paraísos fiscais, violando a Lei Geral de Proteção de Dados de forma irreversível."], resposta_correta:2, explicacao:"A alternativa C está correta. A suspensão do 'X' ocorreu após o empresário Elon Musk anunciar o fechamento do escritório no Brasil e recusar-se a indicar um representante legal no país (exigência básica para empresas operarem no Brasil) e não cumprir ordens de bloqueio de contas investigadas por crimes no STF (Alexandre de Moraes). Os distratores A e E tentam aplicar fundos tributários ou da LGPD; o distrator D aponta um falso autoritarismo presidencial (foi ato do judiciário); o B inventa intervenção do CADE.", status:0, historico:0 },
{id:3227, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A Organização das Nações Unidas (ONU) confirmou a cidade brasileira de Belém, capital do Pará, como sede oficial da 30ª Conferência das Partes da Convenção-Quadro das Nações Unidas sobre Mudança do Clima (COP 30), a realizar-se em 2025. A escolha inédita dessa cidade insere-se numa estratégia diplomática para:", imagem:null, alternativas:["A) pressionar as indústrias petroquímicas do sudeste a financiarem a recuperação das áreas afetadas pelo desastre de Mariana, realocando o evento para longe dos centros decisórios de Brasília.","B) focar os debates ambientais exclusivamente na exploração dos oceanos e combate ao plástico marinho, marginalizando as pautas sobre emissão de gases de efeito estufa.","C) promover a construção de usinas nucleares flutuantes na bacia amazônica para compensar a crise hídrica do Centro-Oeste durante a transição climática.","D) debater a crise climática e a transição ecológica exatamente no coração da Amazônia, visando demonstrar ao mundo o compromisso com a bioeconomia, freio do desmatamento e inclusão dos povos originários.","E) transferir as sedes da ONU e do Banco Central do Brasil definitivamente para a Região Norte, com vistas a descentralizar a arrecadação de créditos de carbono do polo industrial de Manaus."], resposta_correta:3, explicacao:"A alternativa D está correta. Sancionar a COP 30 em Belém foi um ato político e diplomático para colocar a Floresta Amazônica no centro dos debates reais da cúpula do clima, obrigando os líderes mundiais a vivenciarem a realidade da região, além de pautar soluções baseadas na natureza (bioeconomia, povos indígenas e redução do desmatamento). Os distratores apontam teses absurdas de energia nuclear na Amazônia (C), foco exclusivo no mar (B) ou mudanças institucionais irreais do Banco Central (E).", status:0, historico:0 },
{id:3228, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A intensa popularização e posterior regulamentação governamental das plataformas de apostas esportivas online ('Bets') no Brasil levantaram alertas não apenas na economia, mas também na área de saúde e assistência social, sendo objeto de portarias do Ministério da Saúde. O principal argumento de saúde pública utilizado para a regulação do setor é:", imagem:null, alternativas:["A) o crescimento vertiginoso da 'ludomania' (vício compulsivo em jogos de azar) gerando adoecimento mental, endividamento das famílias mais pobres e impactos no orçamento doméstico de programas sociais.","B) o alto índice de sedentarismo e obesidade causado pelo uso prolongado dos aplicativos por parte de atletas amadores, gerando sobrecarga nas filas cirúrgicas do SUS.","C) a contaminação de jovens por infecções sexualmente transmissíveis durante eventos presenciais patrocinados pelas casas de apostas nos grandes centros urbanos.","D) a proibição imediata da operação de qualquer casa de apostas na América do Sul, a pedido da Organização Mundial da Saúde, por estimular esquemas de lavagem de dinheiro das milícias.","E) a constatação de que os algoritmos dos jogos emitem frequências sonoras subliminares causadoras de surtos epilépticos contínuos em crianças não vacinadas."], resposta_correta:0, explicacao:"A alternativa A está correta. A regulamentação das 'Bets' (Lei 14.790/2023 e ações de 2024) exigiu ferramentas de controle de tempo, perdas e propaganda, pois o vício em jogos (ludomania) foi alçado a problema gravíssimo de saúde pública. Famílias beneficiárias do Bolsa Família e cidadãos vulneráveis passaram a comprometer renda básica em apostas, gerando adoecimento mental (ansiedade, depressão) e desestruturação social. Os distratores criam causas médicas irreais para o contexto (sedentarismo, epilepsia por som, infecções).", status:0, historico:0 },
{id:3229, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A publicação detalhada dos resultados do Censo Demográfico de 2022 do IBGE trouxe uma importante alteração técnica na nomenclatura utilizada para classificar áreas urbanas caracterizadas pela ocupação informal e carência de serviços públicos. Atendendo a demandas de movimentos sociais e buscando remover estigmas, o IBGE substituiu o termo 'Aglomerados Subnormais' por:", imagem:null, alternativas:["A) Zonas de Sacrifício Ambiental.","B) Periferias em Situação de Rua.","C) Loteamentos Rústicos Informais.","D) Bairros em Desenvolvimento Pleno.","E) Favelas e Comunidades Urbanas."], resposta_correta:4, explicacao:"A alternativa E está correta. Após décadas utilizando a nomenclatura 'Aglomerados Subnormais' (que carregava um peso pejorativo, indicando algo fora da normalidade e estigmatizando moradores), o IBGE, em diálogo intenso com líderes comunitários e acadêmicos, adotou no Censo 2022 o termo 'Favelas e Comunidades Urbanas'. Esse termo resgata o pertencimento cultural e identitário desses territórios, além de melhorar a acurácia no mapeamento demográfico essencial para planejamento de saneamento e saúde preventiva. As demais opções são fictícias.", status:0, historico:0 },
{id:3230, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O conhecimento técnico dos vetores e das características da doença é essencial ao Agente de Endemias. Acerca do complexo cenário da epidemia de Dengue que assolou o país a partir de 2024, julgue os itens.\nI - As mudanças climáticas e o fenômeno El Niño favoreceram altas temperaturas e chuvas atípicas, acelerando o ciclo reprodutivo do mosquito.\nII - Houve a reintrodução e forte circulação do sorotipo DENV-3 em vários estados, o qual não circulava com intensidade havia mais de 15 anos, encontrando uma vasta população suscetível.\nIII - O Ministério da Saúde determinou que a pulverização costal seja abolida das ações de bloqueio, pois o Aedes albopictus tornou-se o único vetor transmissor no ambiente intradomiciliar urbano.\nÉ tecnicamente correto o que se afirma em:", imagem:null, alternativas:["A) I, II e III.","B) Apenas I e II.","C) Apenas II e III.","D) Apenas I e III.","E) Apenas II."], resposta_correta:1, explicacao:"A alternativa B está correta. A afirmação I é precisa:o calor extremo provocado pelo El Niño diminui o tempo de eclosão dos ovos, gerando mais mosquitos adultos em menos tempo. A afirmação II é cirúrgica:a epidemia agravou-se pois o Brasil vinha sendo atingido pelo DENV-1 e DENV-2, mas o DENV-3 (e pontualmente o 4) ressurgiu, pegando crianças e jovens que nunca tiveram contato com ele. A afirmação III é falsa:o Aedes aegypti continua sendo o vetor urbano principal absoluto da doença; o Aedes albopictus é mais restrito a áreas rurais/silvestres; e o bloqueio químico não foi abolido como ferramenta de contingência.", status:0, historico:0 },
{id:3231, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Em decisão histórica com amplos reflexos na segurança pública e nas políticas de saúde relacionadas ao uso de entorpecentes, o Supremo Tribunal Federal (STF) concluiu um julgamento em 2024 que pacificou critérios de diferenciação no âmbito da Lei de Drogas. O teor central da decisão estabeleceu:", imagem:null, alternativas:["A) a legalização irrestrita do comércio, plantio e publicidade de todas as drogas ilícitas naturais, revogando totalmente a lei federal vigente a partir de uma decisão do Tribunal Superior Eleitoral.","B) que os governos estaduais têm autonomia para criar impostos próprios sobre o tráfico de cocaína apreendida, repassando os fundos diretamente para o Sistema Único de Saúde.","C) a descriminalização do porte de maconha (Cannabis) para uso pessoal, fixando o parâmetro objetivo presuntivo de até 40 gramas ou seis plantas fêmeas para diferenciar o usuário do traficante.","D) o Congresso Nacional como único órgão capaz de interpretar prisões em flagrante, impedindo que juízes soltem dependentes químicos flagrados com grandes remessas internacionais na fronteira.","E) a internação psiquiátrica compulsória de imediato, em nível federal, de qualquer indivíduo abordado portando medicamentos controlados sem receita, independentemente da quantidade."], resposta_correta:2, explicacao:"A alternativa C está correta. O STF julgou o Recurso Extraordinário e fixou tese de repercussão geral descriminalizando (não legalizando) o porte de maconha estritamente para consumo pessoal. O STF fixou a quantia de 40g ou 6 plantas fêmeas como limite para presunção de usuário (salvo provas de comércio em contrário), no intuito de evitar o encarceramento massivo de usuários pobres pretos tratados erroneamente como traficantes. As outras alternativas inventam cenários irreais de 'legalização total', inclusão de cocaína ou internações compulsórias automáticas.", status:0, historico:0 },
{id:3232, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Novo Marco Legal do Saneamento Básico possui total intersecção com a prevenção contínua de doenças endêmicas e parasitárias nas cidades. Analise as premissas deste Marco Legal aplicáveis ao cenário brasileiro, classificando-as como Verdadeiras (V) ou Falsas (F).\n( ) A lei estipulou metas audaciosas de universalização, prevendo que 99% da população tenha acesso à água potável e 90% à coleta e tratamento de esgoto até o final de 2033.\n( ) As metas proíbem que empresas privadas participem das licitações e concessões de serviços de água e esgoto, protegendo as estatais endividadas do setor.\n( ) Foi estabelecido que os municípios estão dispensados de estruturar sistemas de drenagem de águas pluviais, pois as inundações são consideradas desastres naturais imprevisíveis fora do Marco.\n( ) Incentivou-se a regionalização dos serviços, agrupando municípios rentáveis e deficitários em um mesmo bloco para garantir que pequenas cidades também recebam investimentos de infraestrutura.\nA sequência correta, de cima para baixo, é:", imagem:null, alternativas:["A) V, V, F, V.","B) F, V, V, F.","C) V, F, V, F.","D) V, F, F, V.","E) F, F, V, V."], resposta_correta:3, explicacao:"A alternativa D está correta (V, F, F, V). A primeira é Verdadeira:são as metas centrais cravadas na lei até 2033 (com possibilidade de prorrogação até 2040 em casos específicos). A segunda é Falsa:a grande novidade do Marco foi justamente acabar com os contratos de programa sem licitação, forçando a abertura do mercado à iniciativa privada para acelerar os investimentos. A terceira é Falsa:o saneamento básico compreende água, esgoto, manejo de resíduos sólidos (lixo) E drenagem urbana de águas pluviais. A quarta é Verdadeira:o modelo de blocos regionais força o subsídio cruzado para que cidades pequenas e pobres não fiquem sem esgoto.", status:0, historico:0 },
{id:3233, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Em meados de 2024, o Congresso Nacional aprovou e o Executivo sancionou o retorno da cobrança obrigatória anual voltada a acidentes de trânsito, modelo que substitui o antigo DPVAT (extinto em 2020 por esgotamento de fundos). A nova roupagem deste seguro social, gerido pela Caixa Econômica Federal, passou a ser denominada oficialmente como:", imagem:null, alternativas:["A) Seguro Obrigatório para Proteção de Vítimas de Acidentes de Trânsito (SPVAT), que garante indenizações por morte e invalidez para todas as vítimas, sejam elas pedestres, motoristas ou passageiros.","B) Fundo Nacional de Multas e Acidentes (FNMA), que destina integralmente sua arrecadação para recuperar a malha asfáltica federal sob gestão militar rodoviária.","C) Seguro Privado Exclusivo Automotor (SPEA), transferindo a obrigatoriedade da gestão securitária unicamente para corretoras privadas ligadas a montadoras de veículos.","D) Imposto sobre Propriedade de Veículos Acidentados (IPVA-S), cobrando tarifas extras de motoristas embriagados com base em exames toxicológicos obrigatórios no licenciamento.","E) Auxílio-Trânsito Contínuo, um benefício voltado apenas a motoristas de aplicativo que sofrerem furtos de seus veículos nos grandes centros urbanos."], resposta_correta:0, explicacao:"A alternativa A está correta. A lei complementar de 2024 criou o SPVAT (Seguro Obrigatório para Proteção de Vítimas de Acidentes de Trânsito), mantendo o caráter social de indenizar vítimas de trânsito em território nacional por morte ou invalidez, além de reembolsar despesas médicas e funerárias (se não cobertas pelo SUS). Ele volta a ser cobrado dos donos de veículos. O distrator C inverte para bancos privados. O B aponta para asfalto, fugindo da proteção à vida. As demais opções são criações sem conexão com a lei aprovada.", status:0, historico:0 },
{id:3234, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O setor do agronegócio e a saúde pública brasileira conviveram com estado de emergência zoossanitária motivada por focos do vírus H5N1 (Influenza Aviária de Alta Patogenicidade). Sobre esse cenário de biossegurança de relevância nacional, analise e aponte a afirmação que retrata com fidedignidade o controle da doença no país:", imagem:null, alternativas:["A) Houve transmissão pandêmica sustentada entre humanos nas granjas do sul do país, forçando o fechamento preventivo de escolas nas áreas rurais e rurbana.","B) Os casos foram circunscritos principalmente a aves silvestres migratórias e mamíferos marinhos, preservando o status do Brasil de país livre da doença em granjas comerciais para garantir as exportações de frango.","C) A Organização Mundial da Saúde vetou permanentemente a exportação de carne de frango brasileira após detectar que o vírus H5N1 sobrevive a temperaturas extremas de cozimento em larga escala.","D) O governo brasileiro utilizou o extermínio de todas as aves silvestres da Mata Atlântica como principal estratégia química para suprimir os focos de contato litorâneo.","E) A disseminação ocorreu pelo contato com morcegos hematófagos na Amazônia, provocando o abandono total da produção avícola no estado de São Paulo, o maior produtor do Brasil."], resposta_correta:1, explicacao:"A alternativa B está correta. O Brasil enfrentou a Influenza Aviária de Alta Patogenicidade (H5N1) encontrando casos em aves silvestres migratórias e em mamíferos (como leões-marinhos) nas costas litorâneas (especialmente no Sul e Sudeste), o que acionou emergência de saúde animal. A grande vitória da vigilância sanitária foi evitar que o vírus chegasse aos criatórios comerciais (granjas). Assim, o Brasil manteve seu status de livre da doença na avicultura comercial, mantendo as multibilionárias exportações intactas. Os distratores criam pandemias humanas (A) e vetos da OMS mentirosos (C).", status:0, historico:0 },
{id:3235, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Na geopolítica internacional, o bloco original do BRICS (Brasil, Rússia, Índia, China e África do Sul) passou por uma formal e ampla expansão de seus membros plenos. Com a adesão efetivada das novas nações, o grupo consolidou sua estratégia de maior controle energético global e liderança no chamado Sul Global. Assinale o grupo de países que, de fato, ingressou plenamente no bloco:", imagem:null, alternativas:["A) Argentina, Estados Unidos da América, Japão e Nigéria.","B) México, Turquia, Indonésia e Alemanha.","C) Egito, Etiópia, Irã e Emirados Árabes Unidos.","D) Colômbia, Venezuela, Cuba e Espanha.","E) Arábia Saudita, Canadá, França e Austrália."], resposta_correta:2, explicacao:"A alternativa C está correta. Na cúpula de expansão, foram convidados e ingressaram (a partir de 1º de janeiro de 2024) Egito, Etiópia, Irã e Emirados Árabes Unidos. A Arábia Saudita também foi convidada, mas manteve postura ambígua/pendente sobre adesão plena formal até então. A Argentina foi convidada, mas a eleição de Javier Milei fez o país retirar o pedido de adesão (por motivos ideológicos, não aderiu). Estados Unidos, países da União Europeia e Japão (potências ocidentais do G7) obviamente não fazem parte dessa articulação multipolar e figuram como distratores lógicos nas opções.", status:0, historico:0 },
{id:3236, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"No âmbito das políticas públicas de transferência de renda e sua interface com o Ministério da Saúde, o redesenho do programa Bolsa Família retomou fortemente as condicionalidades para a manutenção do benefício às famílias vulneráveis. Leia os itens abaixo relacionados ao cruzamento de dados com a área de saúde.\nI - É obrigatório o cumprimento do calendário nacional de vacinação para as crianças da família, resgatando a cobrança das cadernetas de imunização como passaporte para o benefício.\nII - Acompanhamento contínuo do estado nutricional (peso e altura) das crianças menores de 7 anos e a realização rigorosa de pré-natal para gestantes cadastradas.\nIII - Exigência de comprovação de adesão da família a planos privados de saúde de coparticipação para aliviar a demanda sobre as Unidades Básicas de Saúde locais.\nSobre as condicionalidades impostas ao recebimento da renda familiar, estão corretos:", imagem:null, alternativas:["A) Apenas I e II.","B) Apenas II e III.","C) Apenas I e III.","D) I, II e III.","E) Apenas I."], resposta_correta:0, explicacao:"A alternativa A está correta. A relançamento do Bolsa Família (pós-período do Auxílio Brasil) recriou rigidamente a cobrança das contrapartidas na saúde e educação, visando quebrar o ciclo intergeracional de miséria e evitar o retorno de doenças evitáveis. As afirmações I e II são as pilastras sanitárias da lei (vacinação e acompanhamento de saúde da mulher/criança e nutrição). A afirmação III é absurda:exigir plano de saúde privado do cidadão em extrema pobreza seria um contrassenso absoluto que anularia a natureza do SUS e do próprio programa social.", status:0, historico:0 },
{id:3237, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Agente de Endemias atua intrinsecamente ligado à climatologia, pois o regime de chuvas e secas dita o ritmo dos criadouros de doenças tropicais. O período entre o final de 2023 e meados de 2024 marcou o pico do aquecimento do Pacífico Equatorial e sua posterior dissipação. Na linguagem meteorológica global, o Brasil vivenciou:", imagem:null, alternativas:["A) a consolidação prolongada da La Niña por dez anos consecutivos, responsável pela seca histórica e inédita no litoral paranaense e enchentes no nordeste seco.","B) um longo inverno polar ártico bloqueando massas de ar na faixa equatorial, gerando neve crônica nas capitais nordestinas e ausência de proliferação de vetores alados.","C) os efeitos brutais dos furacões atlânticos de categoria 5 atingindo diretamente a costa brasileira devido ao congelamento precoce da bacia do rio Amazonas e seus afluentes.","D) a transição da Zona de Convergência Intertropical para o Hemisfério Norte, causando a antecipação crônica das cheias do Pantanal sul-mato-grossense durante a primavera e verão inteiro.","E) a atuação severa do fenômeno El Niño, que induziu secas extremas na bacia amazônica e chuvas anômalas na Região Sul, seguida de um alerta mundial de transição posterior para o esfriamento com a chegada da La Niña."], resposta_correta:4, explicacao:"A alternativa E está correta. O evento climático que marcou violentamente o biênio 2023-2024 foi o Super El Niño, que aqueceu as águas do Pacífico, bloqueou frentes frias, causou uma seca arrasadora e recorde nos rios da Amazônia e tempestades torrenciais no Sul (agravando a tragédia do RS). No segundo semestre de 2024, a meteorologia previu a virada da chave para a fase de resfriamento, a La Niña (que tende a inverter os polos de seca e chuva no país). Os distratores trazem inverdades geográficas e fenômenos fantasiosos para a costa brasileira (como furacão no Amazonas ou neve no Nordeste).", status:0, historico:0 },
{id:3238, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Nas eleições municipais, a taxa de sucesso de prefeitos que buscaram a reeleição atingiu índices muito altos no interior do Brasil, fenômeno atrelado a modificações estruturais no orçamento da União que deram forte capilaridade de obras e recursos na base dos municípios. O fator central apontado por cientistas políticos que impulsionou essa retenção do poder local das gestões incumbentes foi:", imagem:null, alternativas:["A) a proibição legal imposta pelo Tribunal Superior Eleitoral da candidatura de empresários do setor privado, restringindo o pleito apenas a funcionários públicos concursados.","B) o volume recorde e o controle bilionário repassado aos municípios via emendas parlamentares federais (inclusive as conhecidas como 'emendas Pix'), irrigando as prefeituras com recursos diretos para pavimentação, saúde e festividades perto das urnas.","C) o retorno do sistema de voto impresso auditável e cédulas manuais nas pequenas cidades rurais baianas, o que facilitou a comunicação com eleitores idosos nas urnas sem o suporte dos mesários federais e estaduais.","D) a imposição do financiamento puramente corporativo e privado pelas grandes mineradoras nas cidades afetadas pela exploração do Pré-sal nordestino nos meses eleitorais vigentes em 2024.","E) o cancelamento das dívidas previdenciárias das prefeituras sob a condição única de que os gestores adotassem o piso salarial do Agente de Endemias como base fiscal imutável ao longo da gestão anterior."], resposta_correta:1, explicacao:"A alternativa B está correta. O fenômeno político nas eleições de 2024 foi a altíssima taxa de reeleição (a maior desde que a reeleição foi instituída no Brasil), puxada pelo poder e força da máquina pública irrigada pelas chamadas 'emendas Pix' (Transferências Especiais) e emendas de comissão e relator (antigo Orçamento Secreto). Prefeitos no cargo receberam aportes milionários dos deputados, permitindo inaugurações e gastos sociais que desequilibraram a disputa em favor de quem estava na cadeira. Os distratores apontam voto impresso (nunca retornou), financiamento empresarial (proibido pelo STF desde 2015) e perdões fiscais inexistentes.", status:0, historico:0 },
{id:3239, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Para mitigar o gargalo e o forte desabastecimento de cuidados gerados no ápice da pandemia de coronavírus, o Ministério da Saúde implementou e refinanciou um dos maiores eixos emergenciais do SUS por meio do Programa Nacional de Redução das Filas (PNRF). O cerne dos robustos repasses financeiros aos estados e municípios direcionou-se maciçamente à viabilização de:", imagem:null, alternativas:["A) cirurgias eletivas represadas (como cataratas, hérnias e retirada de vesícula), consultas ambulatoriais especializadas e mutirões de exames que sofreram forte paralisação por priorização da rede aos quadros virais.","B) tratamentos estéticos plásticos pós-operatórios para redução de medidas, visto que as medidas restritivas de convívio social engatilharam epidemias absolutas de obesidade mórbida entre atletas.","C) repatriação compulsória de centenas de médicos estrangeiros formados no programa Mais Médicos devido à suspensão inconstitucional das revalidações estudantis.","D) aquisição massiva de oxigênio líquido para ser distribuído domesticamente a pacientes que optaram por internação domiciliar em detrimento das unidades de triagem e UPAs das capitais.","E) construção relâmpago de mil novos hospitais de campanha provisórios em lonas infláveis ao longo da planície costeira e central voltados puramente ao tratamento das complicações secundárias da vacinação."], resposta_correta:0, explicacao:"A alternativa A está correta. O Programa Nacional de Redução das Filas (PNRF) foi a medida do SUS para 'correr atrás do prejuízo'. Durante os picos da pandemia de Covid-19, os leitos e centros cirúrgicos foram focados em salvar as vítimas do vírus, paralisando praticamente todas as cirurgias eletivas (aquelas que podem ser agendadas, mas que reduzem a qualidade de vida, como hérnias ou catarata) e os exames preventivos complexos. Os mutirões, cirurgias em fim de semana e metas do programa injetaram verba extra para zerar esse gargalo invisível. O distrator B aponta cirurgia plástica estética. O E tenta criar fake news vacinais num programa cirúrgico logístico.", status:0, historico:0 },
{id:3240, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Instituto Butantan avançou decisivamente no desenvolvimento de uma vacina nacional contra a dengue, a Butantan-DV, que apresentou resultados promissores em ensaios clínicos visando a aprovação da Anvisa. Comparada a outros imunizantes estrangeiros, a principal inovação estrutural e logística esperada com o imunizante brasileiro para a saúde pública é:", imagem:null, alternativas:["A) a exigência de três doses anuais obrigatórias para garantir imunidade cruzada imediata com o vírus da febre amarela.","B) o fato de ser desenvolvida com tecnologia de RNA mensageiro, idêntica à vacina contra a Covid-19, dispensando refrigeração na rede de frio do SUS.","C) a capacidade de proteção contra os quatro sorotipos do vírus em esquema de dose única, facilitando a adesão populacional e a vacinação em massa.","D) sua aplicação restrita a pessoas idosas acima de 65 anos, por comporem o público alvo singular com risco de desenvolver formas hemorrágicas severas.","E) a capacidade de imunizar diretamente o mosquito Aedes aegypti quando este pica um humano recém-vacinado, quebrando o ciclo vetorial ambiental."], resposta_correta:2, explicacao:"A alternativa C está correta. A grande revolução logística da vacina Butantan-DV é ter sido concebida como tetravalente (protege contra os 4 sorotipos) e administrada em dose única, o que barateia e agiliza campanhas públicas. O distrator B erra a tecnologia (ela usa vírus vivo atenuado, não mRNA). O A erra as doses e cruza com febre amarela. O D restringe falsamente o público. O E descreve uma ficção científica biológica, pois vacinas imunizam o hospedeiro, não o vetor.", status:0, historico:0 },
{id:3241, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A repavimentação do trecho do meio da rodovia BR-319, que liga as capitais Manaus (AM) e Porto Velho (RO), concentra tensos debates sobre infraestrutura e meio ambiente no Brasil. Analise os fatores dessa controvérsia:I - Políticos da região argumentam que a obra é vital para tirar o Amazonas do isolamento terrestre e baratear o escoamento de insumos. II - Ambientalistas alertam que o asfaltamento sem forte fiscalização estatal causará um salto no desmatamento e na grilagem de terras no eixo da rodovia. III - A obra foi suspensa por decisão internacional da ONU, pois cruza reservas indígenas isoladas determinando o embargo do agronegócio nacional. Estão corretas:", imagem:null, alternativas:["A) Apenas I e II.","B) Apenas II e III.","C) Apenas I e III.","D) I, II e III.","E) Apenas I."], resposta_correta:0, explicacao:"A alternativa A está correta. Os itens I e II resumem perfeitamente o impasse crônico da BR-319:a necessidade real de conexão terrestre do estado do Amazonas (I) versus o iminente risco de explosão do desmatamento (efeito espinha de peixe) em áreas antes intocadas (II). O item III é totalmente falso, pois a ONU não tem jurisdição para embargar obras internas brasileiras e a área não paralisa todo o agronegócio nacional.", status:0, historico:0 },
{id:3242, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Os dados consolidados do Censo Demográfico do IBGE confirmaram uma transição estrutural na sociedade brasileira, exigindo forte adaptação do planejamento do Sistema Único de Saúde (SUS). O fenômeno populacional apontado pelo levantamento que afeta as políticas públicas é:", imagem:null, alternativas:["A) a explosão atípica da taxa de fecundidade juvenil, demandando a construção emergencial de maternidades federais em todos os estados nordestinos.","B) o envelhecimento acelerado da população aliado à queda da taxa de natalidade, o que desloca o peso das demandas de saúde para o tratamento de doenças crônicas e degenerativas.","C) a queda abrupta da expectativa de vida provocada pelas secas no Centro-Oeste, reduzindo drasticamente a necessidade de médicos especialistas em geriatria.","D) a migração em massa de idosos rurais para países do Mercosul, esvaziando o contingente a ser atendido pelos agentes comunitários de saúde.","E) o crescimento populacional recorde e imprevisto que ultrapassou a marca de 350 milhões de habitantes, colapsando a expansão das redes de esgoto."], resposta_correta:1, explicacao:"A alternativa B está correta. O Censo de 2022 confirmou que os brasileiros estão tendo menos filhos (queda de natalidade) e vivendo mais, resultando em um envelhecimento rápido da base demográfica (foram contabilizados cerca de 203 milhões de habitantes, não 350 milhões como aponta o erro da E). Isso impacta o SUS, que precisa lidar crescentemente com Doenças Crônicas Não Transmissíveis (diabetes, câncer, hipertensão) em detrimento de antigas doenças prevalentes em jovens. Os distratores A e C invertem completamente a realidade estatística.", status:0, historico:0 },
{id:3243, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"As frequentes e intensas 'ondas de calor' que atingiram o Brasil passaram a ser enquadradas como risco iminente nos alertas da Defesa Civil e do Ministério da Saúde. Do ponto de vista epidemiológico e ambiental diário, esse fenômeno climático adverso afeta a saúde coletiva porque:", imagem:null, alternativas:["A) encurta o ciclo de vida aquático do mosquito Aedes aegypti e acelera a replicação viral no interior do inseto, aumentando o risco de explosão de casos de arboviroses em menor tempo.","B) provoca a morte em massa dos mosquitos urbanos em sua fase adulta, que biologicamente não sobrevivem sob nenhuma hipótese a temperaturas acima de 30 graus no verão.","C) está associado diretamente e de forma isolada ao buraco na camada de ozônio sobre a bacia amazônica, causando exclusivamente danos estéticos na derme.","D) induz surtos secundários de doenças transmitidas por roedores, já que os ratos buscam o resfriamento de córregos e rios limpos no interior dos imóveis.","E) extingue a evaporação superficial das lagoas e poças de água, eliminando naturalmente os criadouros dos vetores da malária no ciclo silvestre sazonal."], resposta_correta:0, explicacao:"A alternativa A está correta. Para o Agente de Endemias, o calor extremo é um sinal de alerta vermelho. Temperaturas altas aceleram tanto a eclosão das larvas quanto o 'período de incubação extrínseca' (o tempo que o vírus leva para se multiplicar dentro do mosquito até ele poder transmitir). Logo, há mais mosquitos e eles se tornam infectantes mais rápido. O distrator B inverte a resistência do vetor. O C associa erroneamente à camada de ozônio. O E diz que o calor para a evaporação (o que desafia a física básica).", status:0, historico:0 },
{id:3244, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Historicamente, o controle da Leishmaniose Visceral Canina no Brasil envolvia protocolos rígidos que resultavam na eutanásia dos cães soropositivos. Uma mudança de paradigma e de regulamentação recente por parte das autoridades de saúde e de veterinária estabeleceu que:", imagem:null, alternativas:["A) o tratamento de cães infectados com medicamentos específicos aprovados passou a ser permitido, retirando a obrigatoriedade de sacrificar o animal, desde que acompanhado por médico veterinário e com medidas de repulsão do vetor.","B) a vacinação gratuita de cães de rua foi incorporada aos postos do SUS para curar a doença nos estágios avançados de comprometimento renal.","C) a eutanásia passou a ser aplicada de forma compulsória também aos proprietários rurais que não limparem os criadouros de caramujos transmissores da doença.","D) o vetor flebotomíneo (mosquito-palha) foi declarado oficialmente extinto no Nordeste devido ao uso extensivo de inseticidas biológicos.","E) a transmissão da leishmaniose animal passou a ser reconhecida como doença exclusiva de gatos domésticos, isentando os caninos de testagem pelo Centro de Zoonoses."], resposta_correta:0, explicacao:"A alternativa A está correta. Antigamente, o sacrifício do cão positivo para Leishmaniose Visceral (calazar) era regra incontestável no Ministério da Saúde. Porém, novas portarias e aprovações de medicamentos (como o Milteforan) permitiram que os tutores tratassem os cães doentes, visando reduzir a carga parasitária para que não sirvam de reservatório para o mosquito palha. O tratamento não traz cura parasitológica total, mas impede a transmissão se associado a coleiras repelentes. O distrator B diz que a vacina cura a doença (vacina previne, e não há vacina curativa gratuita no SUS). O C insere caramujos (vetor da esquistossomose). O E culpa os felinos.", status:0, historico:0 },
{id:3245, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O aguardado acordo de livre comércio entre o Mercosul e a União Europeia, cujas bases foram desenhadas ao longo de décadas, enfrentou novos reveses geopolíticos e paralisações significativas nos últimos dois anos. O principal entrave que tem bloqueado a assinatura definitiva e implementação do acordo reside:", imagem:null, alternativas:["A) na exigência inegociável do Mercosul de adotar o Euro como moeda única sul-americana para transações agropecuárias de base.","B) nos protestos intensos do setor agrícola de países europeus, especialmente da França, aliados a exigências de cláusulas de punição ambiental impostas pelos europeus sobre o desmatamento no Brasil.","C) no embargo comercial formal aplicado pela China, que ameaçou comprar toda a dívida externa europeia caso o acordo favorecesse o parque industrial argentino.","D) na recusa categórica do Brasil em exportar etanol e minério de ferro, sob a justificativa de risco de desabastecimento das matrizes energéticas das capitais costeiras.","E) na constatação de que o tratado proibiria as indústrias farmacêuticas da Europa de venderem vacinas contra arboviroses ao sistema público de saúde sul-americano."], resposta_correta:1, explicacao:"A alternativa B está correta. A finalização do acordo Mercosul-UE tem batido constantemente na barreira do protecionismo agrícola europeu (fazendeiros franceses temem não conseguir competir com o agronegócio sul-americano) somado à pauta ambiental (a UE quer impor punições severas se houver produtos oriundos de áreas desmatadas). Os distratores criam cenários irreais:adoção do Euro no Mercosul (A), intervenção chinesa (C), proibição de exportar minério que é a base das exportações do Brasil (D) ou restrições de vacinas (E).", status:0, historico:0 },
{id:3246, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Em Maceió (AL), bairros inteiros precisaram ser esvaziados em um dos maiores desastres socioambientais em área urbana do mundo, resultando na realocação de dezenas de milhares de pessoas e no afundamento progressivo do solo. Esse colapso geológico foi provocado diretamente pela:", imagem:null, alternativas:["A) perfuração descontrolada de poços de petróleo na zona costeira para abastecimento da bacia petrolífera do Pré-sal nordestino.","B) construção de linhas subterrâneas de metrô pesado sem estudos prévios de impacto de lençóis freáticos na lagoa Mundaú.","C) falha na barragem de rejeitos tóxicos pertencente a empresas de siderurgia, cujo lodo corroeu a fundação das residências populares.","D) atividade de mineração prolongada e falha na estabilização das cavernas subterrâneas de extração de sal-gema conduzida pela empresa Braskem.","E) movimentação repentina de falhas tectônicas passivas no Atlântico Sul gerando pequenos abalos sísmicos rotineiros na camada superficial da capital."], resposta_correta:3, explicacao:"A alternativa D está correta. O colapso do solo que destruiu bairros como o Mutange e Pinheiro em Maceió deveu-se à mineração de sal-gema feita pela Braskem. A extração deixou enormes cavidades subterrâneas que começaram a desmoronar, causando tremores e o afundamento da superfície. O distrator A fala de petróleo; o B inventa metrô; o C aponta barragens de rejeitos (Brumadinho/Mariana); o E aponta causas sísmicas naturais, retirando a culpa ambiental corporativa real do desastre.", status:0, historico:0 },
{id:3247, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Com o avanço meteórico da tecnologia e seus reflexos nos direitos dos cidadãos, o Congresso Nacional brasileiro pautou a criação do Marco Legal da Inteligência Artificial. Acerca desse contexto regulatório em tramitação e suas premissas, julgue (V) para verdadeiro ou (F) para falso. ( ) O texto base adota o sistema de gradação de risco, impondo regras e auditorias muito mais severas para sistemas de IA que atuem em setores críticos como saúde e segurança. ( ) O projeto visa proibir definitivamente as pesquisas acadêmicas sobre redes neurais e algoritmos generativos no Brasil para evitar plágios em massa. ( ) A legislação tenta estabelecer balizas para que as plataformas respeitem os direitos autorais e protejam dados sensíveis em conformidade com a LGPD. ( ) Uma das cláusulas aprovadas impõe que julgamentos de primeira instância na justiça comum passem a ser realizados autonomamente por inteligências artificiais. A ordem correta é:", imagem:null, alternativas:["A) F, F, V, V.","B) V, V, F, F.","C) V, F, V, F.","D) F, V, F, V.","E) V, F, F, V."], resposta_correta:2, explicacao:"A alternativa C (V, F, V, F) está correta. A primeira é Verdadeira:o modelo brasileiro inspira-se na regulação europeia, focando no risco da aplicação (alto risco exige muita transparência). A segunda é Falsa:não há proibição de pesquisa científica (o objetivo é fomento ético, não banimento). A terceira é Verdadeira:o uso de obras com direitos autorais para treinar IA é o grande debate global. A quarta é Falsa:o judiciário não será substituído integralmente e autonomamente por robôs (isso contraria garantias constitucionais do juiz natural e devido processo legal).", status:0, historico:0 },
{id:3248, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Nas políticas de vigilância epidemiológica, o Brasil busca intensamente recuperar um certificado internacional concedido pela Organização Pan-Americana da Saúde (OPAS/OMS), o qual foi perdido no ano de 2019 em decorrência de surtos sustentados causados por baixas coberturas vacinais. Esse esforço contínuo do Programa Nacional de Imunizações foca em reaver o status de país livre da circulação endêmica do:", imagem:null, alternativas:["A) Zika vírus, que foi contido mediante a distribuição nacional de vacinas importadas.","B) Rotavírus, que causa desidratação infantil fatal nas regiões norte e nordeste.","C) Vírus da Raiva, erradicado de cães e gatos, mas reintroduzido pelos grandes primatas silvestres.","D) Sarampo, doença viral altamente contagiosa cujas taxas de vacinação caíram, abrindo brecha para a reintrodução do patógeno pelas fronteiras.","E) Hantavírus, cuja disseminação respiratória se dá exclusivamente no ar condicionado de edifícios urbanos comerciais."], resposta_correta:3, explicacao:"A alternativa D está correta. O Brasil havia recebido o certificado de eliminação do Sarampo em 2016. Contudo, a queda livre da cobertura vacinal (Tríplice Viral) aliada ao fluxo de casos importados de países vizinhos fez o vírus voltar a circular intensamente em 2018 e 2019, o que levou à perda do certificado. O Ministério da Saúde realiza busca ativa de vacinação para demonstrar ausência de transmissão e reaver o status. O distrator A sugere vacina para Zika (não disponível rotineiramente/comercialmente). As demais opções citam vírus com ciclos biológicos e status imunológicos distintos.", status:0, historico:0 },
{id:3249, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Diversas publicações científicas de relevância global nos últimos dois anos soaram o alarme para uma contaminação silenciosa do corpo humano, associada diretamente ao descarte inadequado de resíduos sólidos e à poluição de rios e oceanos. Cientistas detectaram, em amostras de sangue humano e placentas, concentrações preocupantes de:", imagem:null, alternativas:["A) isótopos radioativos resultantes de usinas nucleares soviéticas naufragadas na costa tropical atlântica.","B) microplásticos, partículas minúsculas resultantes da degradação de polímeros que entram na cadeia alimentar e na água ingerida pela população.","C) bactérias termófilas provenientes das lavas vulcânicas recém-descobertas no fundo da bacia do Rio São Francisco.","D) chumbo gasoso concentrado advindo exclusivamente da queima da palha da cana-de-açúcar na Amazônia legal.","E) amianto líquido injetado clandestinamente na produção de vacinas de matrizes virais atenuadas de origem europeia."], resposta_correta:1, explicacao:"A alternativa B está correta. Um dos grandes temas de saúde ambiental contemporânea é a detecção de microplásticos (fragmentos menores que 5 milímetros) permeando os tecidos humanos (sangue, pulmões, placenta). Esse plástico oriundo de garrafas, roupas e lixo mal gerido quebra-se na natureza, é consumido por peixes/animais ou contamina a água potável, parando dentro do organismo humano. Os distratores são ficcionais:lixo radioativo soviético no Atlântico (A), vulcões no São Francisco (C) ou teorias absurdas sobre vacinas e chumbo (D e E).", status:0, historico:0 },
{id:3250, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O governo federal relançou o Programa de Aceleração do Crescimento (Novo PAC), desenhando investimentos robustos para vários eixos da sociedade. No eixo focado na Saúde e nas melhorias de vigilância sanitária e atendimento básico aos cidadãos, o programa previu prioridade orçamentária para:", imagem:null, alternativas:["A) o financiamento exclusivo da rede privada filantrópica de hospitais de alta complexidade para cirurgias bariátricas com tecnologia robótica.","B) a construção de Unidades Básicas de Saúde (UBS), Policlínicas, ampliação da frota do SAMU e expansão das obras de esgotamento sanitário essenciais para prevenção de endemias.","C) a privatização imediata da Fiocruz e do Instituto Butantan como forma de terceirizar a pesquisa de soros antiofídicos e vacinas de malária.","D) a suspensão total de repasses financeiros fundo a fundo para os estados, obrigando governadores a assumirem 100% da compra de ambulâncias.","E) o fechamento gradual do Programa Farmácia Popular, transferindo os subsídios de medicamentos para convênios médicos empresariais."], resposta_correta:1, explicacao:"A alternativa B está correta. O Novo PAC da Saúde voltou-se fortemente para a Atenção Primária e Especializada (com promessas de milhares de novas UBS, centenas de Policlínicas regionais e renovação do SAMU), reconhecendo que fortalecer a base do SUS e integrar obras de saneamento são o motor real da prevenção em saúde pública. O distrator A erra ao focar recursos do PAC em robótica privada bariátrica. O C fala da venda criminosa dos patrimônios da ciência nacional. O D inverte a lógica do cofinanciamento do SUS. O E contraria o fortalecimento atual do Farmácia Popular.", status:0, historico:0 },
{id:3251, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"No rescaldo das lições deixadas pela pandemia de Covid-19, a Organização Mundial da Saúde (OMS) tem pautado a diplomacia na elaboração do chamado 'Tratado Global das Pandemias'. Analise os eixos de tensão das rodadas de negociação:I - Países em desenvolvimento pleitearam mecanismos ágeis para a transferência de tecnologia e repartição justa de vacinas e terapias em emergências. II - Países ricos e pólos farmacêuticos demonstraram grande resistência em flexibilizar a propriedade intelectual (patentes) das descobertas biotecnológicas. III - O tratado consolidou uma cláusula que confere à OMS o poder soberano de intervir militarmente nas fronteiras sanitárias do país que falhar em conter um vírus transmissível. Está demonstrada a verdade técnica em:", imagem:null, alternativas:["A) Apenas I e II.","B) Apenas II e III.","C) Apenas I e III.","D) I, II e III.","E) Apenas I."], resposta_correta:0, explicacao:"A alternativa A está correta. Os incisos I e II retratam precisamente a briga geopolítica na OMS:o Sul Global (que sofreu no fim da fila para vacinas em 2021) lutou por garantias de equidade, enquanto os EUA e Europa defenderam ferozmente o modelo de negócios de suas indústrias farmacêuticas (Big Pharma). A afirmativa III é uma das 'fake news' mais famosas sobre esse tratado; não há e nunca haverá perda de soberania nacional ou intervenção armada por parte da OMS, que é apenas uma entidade coordenadora e recomendadora.", status:0, historico:0 },
{id:3252, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Brasil tem implementado mudanças progressivas na recomendação da vacina contra a Febre Amarela. No cenário epidemiológico contemporâneo, a principal diretriz governamental para esta imunização consistiu na:", imagem:null, alternativas:["A) proibição da dose para residentes da Região Norte, face ao desaparecimento definitivo do ciclo silvestre na bacia amazônica.","B) substituição da vacina de vírus atenuado por pílulas preventivas de ingestão oral antes de viagens turísticas ecológicas.","C) expansão da vacinação como recomendação de rotina para todo o território nacional, não se restringindo mais apenas aos estados antes classificados como áreas endêmicas de risco.","D) limitação do uso da vacina apenas para indivíduos que comprovem ter sido picados pelo carrapato-estrela na zona rural.","E) imposição legal de que a vacina seja aplicada de seis em seis meses devido à mutação rápida do vírus em ambiente exclusivamente urbano mantido pelo Culex."], resposta_correta:2, explicacao:"A alternativa C está correta. Historicamente, a vacina de Febre Amarela era indicada quase que apenas para o Norte, Centro-Oeste e partes do Sudeste. Após surtos alarmantes migrarem para o sudeste e sul nos últimos anos, o Ministério da Saúde decidiu gradativamente tornar o Brasil inteiro 'Área com Recomendação de Vacina' (ACRV), inserindo-a no calendário de rotina em nível nacional, dada a dispersão do vírus nos corredores ecológicos. O distrator D cita o carrapato (vetor da Febre Maculosa). A E cita o Culex urbano e repetição semestral (errado, uma dose confere proteção vitalícia).", status:0, historico:0 },
{id:3253, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O avanço da frota de veículos elétricos e híbridos provocou reações econômicas e medidas de Estado no Brasil, culminando na sanção do Programa Mover (Mobilidade Verde e Inovação). A espinha dorsal das medidas desse programa que impactou a importação internacional de veículos consiste na:", imagem:null, alternativas:["A) eliminação retroativa de todas as multas de trânsito dos motoristas de aplicativo que compraram carros elétricos produzidos na Argentina.","B) proibição permanente de venda de carros a combustão no Brasil a partir de 2025, forçando o sucateamento de toda a frota a diesel agrícola do país.","C) retomada gradual da cobrança do imposto de importação para carros elétricos asiáticos e estrangeiros, visando estimular que as montadoras passem a fabricar esses veículos e suas baterias dentro do Brasil.","D) concessão de isenção integral de pedágios nas rodovias federais para qualquer tipo de veículo utilitário fabricado na Europa sob padrões de hidrogênio líquido.","E) taxação duplicada sobre bicicletas elétricas e patinetes, enquadrando-os como veículos emissores de carbono pesado sujeitos ao imposto ecológico de Manaus."], resposta_correta:2, explicacao:"A alternativa C está correta. O governo federal encerrou a isenção de imposto de importação para carros elétricos e eletrificados, taxando gradualmente os veículos (notadamente as fabricantes chinesas como BYD e GWM que inundaram o mercado). O objetivo da política nacional (Mover) é não apenas ser um mercado consumidor, mas obrigar as empresas a instalarem suas fábricas (produção de tecnologia verde e emprego) em solo brasileiro para evitar os impostos. As opções B, D e E trazem cenários extremistas, irreais ou contraditórios com as diretrizes do programa.", status:0, historico:0 },
{id:3254, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O debate sobre segurança pública e o sistema penitenciário brasileiro aqueceu com a aprovação da nova Lei de Execução Penal restritiva, popularmente associada ao benefício da 'saidinha'. Sobre o tortuoso caminho desse projeto de lei, julgue:( ) O Congresso Nacional aprovou a abolição das saídas temporárias de presos do semiaberto para visitação familiar em feriados. ( ) A lei aboliu integralmente a progressão de regime prisional, forçando presos sem gravidade a ficarem eternamente no regime fechado. ( ) O Executivo vetou a proibição das visitas familiares visando a ressocialização, mas o Legislativo derrubou o veto do presidente, mantendo a restrição. ( ) O direito do detento do regime semiaberto de sair do presídio para frequentar cursos supletivos ou profissionalizantes foi preservado no texto final. A avaliação resulta na sequência:", imagem:null, alternativas:["A) V, F, V, F.","B) V, F, V, V.","C) F, F, V, V.","D) F, V, F, V.","E) V, V, F, F."], resposta_correta:1, explicacao:"A alternativa B (V, F, V, V) está correta. 1ª é Verdadeira:o cerne da lei foi proibir as saídas em feriados (Natal, Dia das Mães) para ver a família. 2ª é Falsa:a lei de Execução Penal continua permitindo a progressão de regime (fechado para semiaberto), a alteração incidiu apenas sobre o benefício de saídas. 3ª é Verdadeira:houve o veto de Lula a pedido do Ministério da Justiça, e o Congresso impôs sua força e derrubou o veto. 4ª é Verdadeira:a saída temporária puramente para trabalho e estudo técnico/supletivo não foi extinta e continuou amparada para evitar ócio carcerário absoluto.", status:0, historico:0 },
{id:3255, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Completando-se uma década do pico da emergência em saúde pública decretada no Brasil pelo avanço do vírus Zika, o SUS ainda lida com as pesadas sequelas sociossanitárias daquele evento que surpreendeu a medicina global. Do ponto de vista epidemiológico e assistencial atual, a principal política remanescente para as vítimas oriundas dessa crise vincula-se:", imagem:null, alternativas:["A) à prestação de assistência continuada e interdisciplinar (fisioterapia, fonoaudiologia) e pagamento de pensões vitalícias para a geração de crianças nascidas com microcefalia e a chamada Síndrome Congênita do Zika.","B) à castração química compulsória de todos os homens diagnosticados com a doença, tendo em vista a disseminação genética do vírus aos gametas.","C) ao extermínio e interdição das lagoas e mananciais onde ocorre o ciclo aquático predominante do barbeiro vetor do vírus letal.","D) à restrição da circulação nacional de fêmeas do mosquito Anopheles por meio do congelamento aéreo com nitrogênio na região nordeste.","E) à vacinação obrigatória e decenal de gestantes utilizando imunizantes recombinantes importados de Cuba que curam malformações cranianas intraútero."], resposta_correta:0, explicacao:"A alternativa A está correta. A grande herança da crise da Zika de 2015/2016 é a geração de crianças com a Síndrome Congênita do Zika Vírus (SCZV), marcadamente a microcefalia. O desafio do Estado brasileiro (através do SUS e da Seguridade Social) é garantir acesso a terapias multidisciplinares vitais para o desenvolvimento dessas crianças e a pensão especial vitalícia destinada às mães e famílias vulneráveis. O distrator B é hediondo. O C e D confundem vetores (Zika é pelo Aedes). O E fala de uma vacina que ainda não existe comercialmente e promete reversão absurda de malformações cerebrais anatômicas.", status:0, historico:0 },
{id:3256, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A bacia hidrográfica amazônica enfrentou severas anomalias hidrológicas entre o final de 2023 e o ano de 2024, culminando em registros de marcas históricas em pontos de medição como o Porto de Manaus. As notícias atrelaram o contexto à emergência climática somada a fenômenos oceânicos. O impacto socioeconômico e sanitário direto dessa dinâmica expressou-se pela:", imagem:null, alternativas:["A) elevação extraordinária do nível das águas causando tsunamis fluviais que arrasaram a infraestrutura de saúde das aldeias yanomamis.","B) abertura forçada e emergencial das comportas da Usina de Itaipu para inundar os igarapés secos do Pará.","C) seca extrema e baixas recordes na calha de grandes rios como o rio Negro, isolando centenas de comunidades ribeirinhas que perderam acesso a suprimentos alimentares, água potável e remoção médica de urgência.","D) solidificação da superfície do rio Solimões desencadeada por frentes polares extremas (friagens) que bloquearam a reprodução térmica das larvas de anofelinos.","E) formação de um tornado categoria 4 acima do bioma, o qual arrancou e disseminou estoques inteiros de vacinas da Fundação Nacional dos Povos Indígenas nos rios peruanos."], resposta_correta:2, explicacao:"A alternativa C está correta. O evento marcante na Amazônia recentemente foi a seca histórica. O nível do Rio Negro atingiu a cota mais baixa em mais de um século de medições. Como os rios são as estradas e artérias da Amazônia, a seca isolou comunidades, encalhou barcos, matou toneladas de botos e peixes (água hiperaquecida) e dificultou o envio de médicos e de água mineral para os ribeirinhos. Os distratores usam fenômenos falsos para a região (tsunamis, congelamentos e tornados) ou erros crassos de geografia (Itaipu fica na bacia do rio Paraná, Sul do país).", status:0, historico:0 },
{id:3257, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A inovação tecnológica tem amparado gradualmente o cotidiano das vigilâncias em saúde municipais. Muitos gestores têm incorporado a utilização tática de 'Drones' (veículos aéreos não tripulados) nas rotinas de combate às arboviroses, com a finalidade de otimizar o trabalho do Agente de Endemias no campo. A principal utilidade dessa ferramenta no controle do vetor baseia-se:", imagem:null, alternativas:["A) na substituição do agente humano em 100% das visitas, pois o drone adentra a sala das residências mapeando recipientes sob os móveis por sensor de raios-x.","B) na emissão de raios laser de precisão acoplados no aparelho que carbonizam os mosquitos adultos voando no quintal do morador.","C) na aplicação restrita de bombas de gás lacrimogêneo veterinário para esterilizar as fêmeas hematófagas nos parques ambientais com alta densidade de árvores.","D) no mapeamento aéreo fotográfico para inspecionar criadouros de difícil acesso, como calhas entupidas, marquises, telhados e caixas d'água elevadas e destampadas em prédios sem acesso e imóveis abandonados.","E) na criação de correntes de vento simuladas acima de favelas para dispersar as nuvens biológicas do produto larvicida BTI lançado por aviões cargueiros do exército."], resposta_correta:3, explicacao:"A alternativa D está correta. A grande sacada do uso de drones na saúde endêmica é transpor a barreira física:visualizar calhas sujas, caixas d'água sem tampa, depósitos de lixo em terrenos murados ou ferros-velhos de alto risco que o agente não conseguiria ver da calçada ou que estão fechados/abandonados. Assim, a ação se torna direcionada. Os distratores são ficcionais:drones entrando dentro das salas com raio-x ou atirando laser são absurdos absolutos; gás lacrimogêneo (C) é artefato de contenção humana policial e não tem utilidade veterinária ou endêmica.", status:0, historico:0 },
{id:3258, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A infraestrutura hídrica nordestina vive um grande marco com a projeção e início das instalações de uma das maiores Usinas de Dessalinização de água do mar da América Latina, situada na Praia do Futuro, no Ceará. Contudo, o projeto esbarrou em intensa preocupação e entraves de licenciamento com empresas multinacionais devido ao conflito envolvendo:I - A enorme quantidade de cabos de fibra óptica submarinos de telecomunicações que aportam no Brasil exatamente na mesma praia, temendo-se apagões de internet. II - A possibilidade de a sucção da água e os dutos da usina causarem o rompimento dessa teia física responsável pelo tráfego de dados do país com o exterior. III - O uso exclusivo de usinas termonucleares poluentes ao lado da praia para evaporar a água marinha. Pode-se cravar que o diagnóstico correto está nas afirmações:", imagem:null, alternativas:["A) Apenas II e III.","B) Apenas I e II.","C) Apenas I e III.","D) I, II e III.","E) Apenas I."], resposta_correta:1, explicacao:"A alternativa B está correta. A polêmica da Usina no Ceará (SPE Águas de Fortaleza) deu-se porque a Praia do Futuro é o grande hub de cabos de internet do Atlântico. O setor de telecomunicações (operadoras) alegou que as escavações e a instalação dos tubos captadores de água do mar da usina colocariam as fibras sob alto risco de rompimento (I e II são reais). A afirmação III é falsa, a tecnologia utilizada costuma ser a osmose reversa, não evaporação termo-nuclear radiativa, que sequer existe no Nordeste nessas premissas.", status:0, historico:0 },
{id:3259, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A economia brasileira tem atravessado momentos de fricção institucional entre a Presidência da República e a diretoria do Banco Central do Brasil. O cerne deste conflito, que influencia do controle da inflação até a geração de empregos, apoia-se legal e economicamente na:", imagem:null, alternativas:["A) privatização sumária e irrevogável do Banco Central, cujas ações majoritárias foram compradas pelo mercado financeiro suíço ditando os juros do país.","B) vigência da lei de autonomia do Banco Central, que conferiu mandatos fixos aos diretores, permitindo que a instituição mantenha a taxa básica de juros (Selic) em patamares restritivos a despeito das pressões políticas do Executivo por cortes rápidos.","C) suspensão completa do curso legal da moeda Real, substituída temporariamente por criptoativos lastreados no minério de ferro das estatais por decreto do próprio Banco.","D) manutenção abusiva e anticonstitucional de taxas de juros negativas (abaixo de zero), o que obriga os bancos a pagarem empresas para que tomem empréstimos estatais vultosos.","E) exigência do presidente da República de que a taxa Selic passe a ser definida e votada trimestralmente através de plebiscito popular nas urnas, esvaziando o comitê técnico."], resposta_correta:1, explicacao:"A alternativa B está correta. A grande celeuma econômica atual reside no fato de o Banco Central (BACEN) ter ganhado independência formal em 2021 (mandatos desvinculados do mandato do Presidente da República). O presidente Lula passou o mandato criticando duramente o presidente do BC (Roberto Campos Neto) pela manutenção da taxa de juros (Selic) alta para conter a inflação, o que, por outro lado, encarece o crédito e esfria o crescimento econômico e consumo. As outras opções relatam situações irrealistas (Bancos privatizados, criptomoeda estatal, juros nominais negativos ou plebiscitos inflacionários).", status:0, historico:0 },
{id:3260, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"As tensões geopolíticas prolongadas no leste europeu e as sanções oriundas dos conflitos geraram sobressaltos e dependência crítica no agronegócio nacional e na balança comercial. A vulnerabilidade do Brasil nesse xadrez internacional fica escancarada devido:", imagem:null, alternativas:["A) à dependência aguda que a agricultura brasileira tem da importação de fertilizantes e adubos (potássio e fosfato) vindos diretamente da Rússia e seus vizinhos, insumos essenciais para garantir as colheitas recordes de grãos no país.","B) à exportação massiva e obrigatória da força de trabalho de militares brasileiros para patrulhar os portos agrícolas do Mar Negro sob ordens diretas das Nações Unidas.","C) ao fechamento total da importação de carne bovina por parte dos Estados Unidos, que temiam a espionagem biológica através dos rebanhos vacinados em áreas de litígio russa.","D) à proibição do uso das rotas marítimas atlânticas impostas aos graneleiros brasileiros, o que forçou o Ministério da Agricultura a transportar a soja apenas por vias terrestres até a Ásia.","E) ao bloqueio que o Brasil impôs à China, rompendo laços comerciais com Pequim após os mesmos recusarem financiar o corredor transoceânico do agronegócio."], resposta_correta:0, explicacao:"A alternativa A está correta. O calcanhar de Aquiles do agronegócio brasileiro ficou evidente com a guerra da Ucrânia/Rússia. O Brasil é uma potência agropecuária, mas precisa importar vastas quantidades de fertilizantes (NPK - nitrogênio, fósforo e potássio) para corrigir e enriquecer seus solos; a Rússia e Bielorrússia são grandes fornecedores vitais. Ameaças a essa cadeia geram risco inflacionário nos alimentos no Brasil e ameaçam safras. Os distratores misturam fatos isolados com ficções logísticas ou acordos diplomáticos surreais (como bloqueios à China ou fechamento naval total do oceano atlântico).", status:0, historico:0 },
{id:3261, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"A visibilidade, o debate na mídia e o diagnóstico precoce do Transtorno do Espectro Autista (TEA) cresceram vertiginosamente no Brasil, o que motivou a promulgação de leis específicas (como a Lei Berenice Piana e criação da CIPTEA - Carteira de Identificação) e demandou novos fluxos de atendimento. Do ponto de vista das pressões na formulação de políticas públicas do SUS e da assistência social, essa realidade se traduz na:", imagem:null, alternativas:["A) restrição drástica da matrícula de crianças atípicas nas redes regulares de ensino, confinando-as às instituições asilares da esfera federal isoladas do convívio.","B) necessidade impreterível de ampliar a oferta de terapias multidisciplinares (psicologia, terapia ocupacional e fonoaudiologia especializada em abordagens baseadas em evidências) para evitar judicializações em massa buscando o custeio pelo Estado.","C) prescrição obrigatória de antibióticos de amplo espectro logo nos primeiros meses de vida para curar o transtorno nos casos atestados nos testes do pezinho biológicos.","D) limitação do diagnóstico apenas às capitais costeiras, dado que o aumento dos casos foi cientificamente e comprovadamente atrelado à poluição e salinidade do litoral.","E) constatação acadêmica de que as campanhas de vacinação pediátricas do sarampo originaram o espectro, devendo-se suspender o calendário da primeira infância."], resposta_correta:1, explicacao:"A alternativa B está correta. O salto no número de diagnósticos e na conscientização sobre o Autismo (TEA) expôs a carência do SUS e dos planos de saúde em oferecer intervenções precoces eficientes (como terapias focadas em métodos científicos, ABA etc.). Sem o serviço público adequado, famílias passaram a acionar a justiça para obrigar o Estado ou convênios a pagar as terapias (judicialização). O distrator A fala em segregação asilar (crime contra a inclusão educacional garantida em lei). O C sugere cura com antibióticos. O D aponta fator litorâneo absurdo. E o E endossa um mito covarde e desmentido cientificamente (vacina não causa autismo).", status:0, historico:0 },
{id:3262, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"O Agente de Endemias atua intensamente no controle das Doenças Tropicais Negligenciadas (DTNs), moléstias que afetam predominantemente populações empobrecidas. Sobre as metas mundiais e o plano de ação nacional frente ao pacto da OMS voltado a controlar e eliminar tais agravos até 2030, julgue com (V) ou (F):( ) O roteiro oficial foca estruturalmente na melhoria do saneamento básico, fortalecimento do controle vetorial nos municípios e ampliação do acesso ao tratamento primário. ( ) A doença de Chagas e a Esquistossomose são exemplos vitais de morbidades endêmicas no país enquadradas nestas metas de controle de transmissão. ( ) O governo brasileiro se recusou a aderir ao roteiro da OMS alegando que o país já erradicou 100% de qualquer vetor silvestre ou urbano ao longo da última década. ( ) A hanseníase foi retirada da lista de atenção, pois o desenvolvimento de uma vacina estrangeira de dose única proporcionou imunidade profilática e cura biológica global definitiva. A composição que assinala corretamente é:", imagem:null, alternativas:["A) F, F, V, V.","B) V, V, F, F.","C) V, F, V, F.","D) F, V, F, V.","E) V, F, F, V."], resposta_correta:1, explicacao:"A alternativa B (V, V, F, F) está correta. A 1ª é Verdadeira:o documento da OMS para 2030, reforçado pelo programa 'Brasil Saudável', aponta que saneamento e controle vetorial integrado são a base real de combate. A 2ª é Verdadeira:Chagas (barbeiro) e Esquistossomose (caramujo) são o retrato duro das DTNs prevalentes que castigam a parcela mais carente do país. A 3ª é Falsa:o Brasil não só aderiu como é país-chave para bater as metas, estando muito longe de erradicar a transmissão de grande parte delas. A 4ª é Falsa:o Brasil amarga o segundo lugar mundial em casos de Hanseníase e a doença não tem uma vacina mágica resolutiva comercial de dose única, exigindo meses prolongados de poliquimioterapia (PQT).", status:0, historico:0 },
{id:3263, categoria:"Conhecimentos Gerais", materia:"Atualidades do Brasil e do Mundo", assunto:"Atualidades Brasileira", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Prefeitura de Bonito/BA", enunciado:"Em novembro de 2024, no cenário da COP29 realizada no Azerbaijão e visando pavimentar sua diplomacia ambiental para sediar a subsequente COP30 (em Belém do Pará), o governo brasileiro oficializou perante a ONU uma audaciosa atualização de suas metas de contribuição climática (NDCs). O compromisso assumido pelo país na redução da emissão de gases de efeito estufa vincula-se maciçamente ao sucesso interno de qual pauta ambiental?", imagem:null, alternativas:["A) Substituição compulsória de 100% das termoelétricas nacionais por grandes usinas nucleares alocadas especificamente no interior da caatinga nordestina.","B) Cessação absoluta da produção agropecuária bovina, induzindo por força de lei uma transição da matriz alimentar exclusivamente para vegetais e sintéticos nas metrópoles.","C) Desmobilização das forças armadas e do sistema penitenciário brasileiro a fim de converter os fundos estatais de defesa e segurança na compra de cotas de carbono da União Europeia.","D) Cumprimento da meta de atingir o desmatamento ilegal zero em todos os biomas brasileiros, o que impacta profundamente a curva de emissões gasosas e garante a credibilidade verde pátria.","E) Retirada e denúncia formal do Brasil do Acordo de Paris, buscando isenção diplomática para perfurar reservas fósseis na calha do rio Amazonas em águas doces rasas sem restrições globais."], resposta_correta:3, explicacao:"A alternativa D está correta. A Contribuição Nacionalmente Determinada (NDC) que o Brasil propõe (redução entre 59% e 67% das emissões até 2035) é um pilar ancorado em zerar o desmatamento ilegal, pois as queimadas e o desmate da vegetação primária (especialmente na Amazônia e no Cerrado) são a maior fonte estatística nacional de emissões de CO2, suplantando os gases dos escapes de carros ou queima de carvão industrial. Cumprir a meta de desmatamento é vital para fazer a COP30 no Brasil ter brilho global. O resto das alternativas flerta com medidas radicais extremistas irreais:fim das carnes (B), abolição prisional (C), ou até sair do Acordo de Paris para perfurar o interior da Amazônia livremente (E).", status:0, historico:0 },
{id:3264, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"Editores de texto", cargo:"Agente de Endemias", ano:"2026", banca:"INETE", concurso:"Saúde/BA", enunciado:"Durante a confecção de um panfleto educativo, o Agente de Endemias precisou converter um texto corrido contendo nomes de doenças (separados por vírgula) diretamente em uma tabela estruturada, sem precisar copiar e colar célula por célula. Qual a ferramenta nativa do Word utilizada para esta ação e em qual guia ela se localiza?", imagem:null, alternativas:["A) 'Texto em Colunas', localizada na guia 'Layout'.", "B) 'Converter Texto em Tabela', localizada no botão 'Tabela' da guia 'Inserir'.", "C) 'Inserir Planilha do Excel', localizada na guia 'Inserir'.", "D) 'Desenhar Tabela', localizada na guia 'Design de Tabela'.", "E) 'Mala Direta', localizada na guia 'Correspondências'."], resposta_correta:1, explicacao:"A alternativa B está correta. O Word possui a excelente ferramenta 'Converter Texto em Tabela', que fica escondida dentro do menu do botão 'Tabela', na guia 'Inserir'. Ela lê os separadores (como vírgulas ou tabulações) do texto selecionado e monta a grade automaticamente. A banca INETE adora o distrator A ('Texto em Colunas', que fica no Excel, na guia Dados, ou no Word apenas para colunas de página, não tabelas).", status:0, historico:0 },
{id:3265, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Para a sincronização segura dos dados coletados pelos Dispositivos Móveis de Coleta (DMCs), o IBGE utiliza uma Intranet corporativa rigorosa interligando os postos de coleta à sede. Sobre as características intrínsecas que diferenciam a Intranet da Internet pública, é correto afirmar que a Intranet do IBGE:", imagem:null, alternativas:["A) opera utilizando um conjunto de protocolos de comunicação proprietários e exclusivos de circuito fechado, rechaçando a pilha TCP/IP por ser de natureza pública e vulnerável.","B) compartilha exatamente a mesma pilha de protocolos padrão da Internet (TCP/IP), diferenciando-se fundamentalmente pela restrição de acesso lógico aos usuários autorizados da corporação, geralmente isolada por firewalls.","C) exige que sua topologia física seja unicamente local (LAN), sendo tecnicamente impossível estender uma Intranet por conexões geograficamente distantes (WAN) entre os estados.","D) anula a necessidade de endereçamento IP interno para os tablets dos recenseadores, substituindo-o pelo uso exclusivo do endereço MAC para garantir a invisibilidade externa.","E) é caracterizada pelo uso do protocolo UDP em substituição ao TCP em todas as suas camadas de transporte, visando acelerar a transmissão dos microdados censitários."], resposta_correta:1, explicacao:"A alternativa B está correta. A banca Avalia adora testar a falsa premissa de que a Intranet usa tecnologia diferente da Internet. A verdade é que ambas usam a mesma base (TCP/IP, HTTP, FTP, etc.). A diferença é puramente política/acesso (restrito vs. público). O distrator A explora a falsa ideia de protocolos proprietários; o C mente ao dizer que Intranet não pode ser WAN (uma intranet de empresa nacional é uma WAN privada); o D cria a falácia de que rede local não usa IP.", status:0, historico:0 },
{id:3266, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Ao montar a infraestrutura de um novo posto de coleta regional, o Agente de Informática recebe dois equipamentos distintos:um Switch e um Roteador. Considerando as funções fundamentais desses hardwares no modelo de referência de redes, qual deve ser a destinação técnica e a configuração correta empregada pelo Agente?", imagem:null, alternativas:["A) O Switch deve ser utilizado para interligar redes distintas e definir as melhores rotas de saída para a Internet baseando-se em endereços IP, enquanto o Roteador servirá para conectar os computadores locais dentro da mesma sala baseando-se no endereço MAC.","B) O Roteador operará na camada de Enlace com a função de espelhar o sinal elétrico recebido em uma porta para todas as outras portas simultaneamente, caracterizando o domínio de colisão unificado.","C) O Switch, operando primariamente na camada 2 (Enlace), será usado para conectar os computadores locais da agência, encaminhando os quadros de dados especificamente para a porta de destino com base no endereço físico (MAC Address) da máquina.","D) Ambos os equipamentos são classificados como repetidores de camada 1 (Física), sendo o Roteador superior apenas por possuir antenas de rádio frequência blindadas contra interferência de cabos UTP.","E) O Switch criará uma tabela de roteamento estático global analisando os IPs de destino dos formulários censitários, isolando o tráfego da rede LAN local contra ataques externos de injeção de pacotes."], resposta_correta:2, explicacao:"A alternativa C está correta. Este é o modelo de 'inversão de hardware' favorito da banca Avalia. Switch = Camada 2 (Enlace), conecta máquinas na mesma rede usando o endereço MAC (cria tabela MAC). Roteador = Camada 3 (Rede), conecta redes diferentes e traça rotas usando o endereço IP. O distrator A inverte perfeitamente as funções do Switch e do Roteador. O distrator B descreve o comportamento burro de um HUB antigo (repetidor de portas). O distrator E atribui falsamente funções de roteamento IP de camada 3 a um Switch padrão.", status:0, historico:0 },
{id:3267, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Durante a transmissão de um bloco massivo de dados consolidados do Censo para o data center central, o sistema acusa perda de pacotes devido a instabilidade no link estadual. Contudo, o sistema garante que nenhum pacote recebido será montado fora de ordem ou corrompido, e que os pacotes perdidos serão retransmitidos automaticamente. Essa confiabilidade vital para os dados estatísticos do IBGE é garantida porque o software de coleta utiliza, na camada de transporte, o protocolo:", imagem:null, alternativas:["A) UDP, pois sua arquitetura orientada à conexão assegura o controle de fluxo e de congestionamento sem onerar o cabeçalho.","B) ICMP, que atua estabelecendo um túnel de checagem contínua de erros matemáticos entre os nós de roteamento passivo.","C) TCP, que é um protocolo orientado à conexão, provendo entrega confiável, verificação de erros e retransmissão de pacotes perdidos através do mecanismo de 'three-way handshake'.","D) FTP, que atua na camada de transporte criando uma via blindada e criptografada, imune a quedas de sinal no roteador de borda.","E) DHCP, responsável por gerenciar a ordem sequencial de pacotes distribuindo números lógicos para cada fragmento transmitido."], resposta_correta:2, explicacao:"A alternativa C está correta. A banca Avalia exige a distinção visceral entre TCP e UDP. O TCP (Transmission Control Protocol) garante entrega, verifica erros, retransmite perdas e ordena pacotes (orientado à conexão, confiável). O UDP (User Datagram Protocol) envia pacotes sem checar se chegaram, sendo mais rápido, porém não confiável (usado em streaming/VoIP). O distrator A comete o erro letal de classificar o UDP como orientado à conexão. Os distratores D e E citam protocolos de aplicação (FTP, DHCP) atuando de forma fictícia na camada de transporte.", status:0, historico:0 },
{id:3268, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"A topologia física de uma rede determina o layout dos cabos e dispositivos. Em um determinado posto do IBGE, os 15 computadores dos recenseadores estão conectados por cabos individuais diretamente a um único Switch central localizado no rack da sala técnica. Caso o cabo de um dos recenseadores seja rompido, apenas aquele computador perde a rede. Contudo, caso o Switch central sofra uma pane elétrica fatal, todos os 15 computadores ficarão inoperantes e isolados. Esse cenário descreve de forma clássica a topologia de:", imagem:null, alternativas:["A) Anel (Ring).","B) Barramento (Bus).","C) Malha (Mesh).","D) Estrela (Star).","E) Árvore (Tree)."], resposta_correta:3, explicacao:"A alternativa D está correta. O conceito central da topologia em Estrela é a dependência de um nó central (Switch ou Hub). A quebra de um cabo periférico afeta só aquela máquina, mas a quebra do nó central derruba toda a rede. A banca usa o cenário prático para testar o reconhecimento da topologia. No distrator B (Barramento), o rompimento do cabo central (backbone) também derruba todos, mas não há um 'Switch central'. No distrator C (Malha), a quebra de um equipamento central não derrubaria a rede, pois existem múltiplos caminhos redundantes.", status:0, historico:0 },
{id:3269, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Um recenseador utiliza a internet pública de uma lanchonete para sincronizar seus dados diários. Para garantir que as informações trafeguem em um túnel criptografado e seguro por dentro dessa rede pública insegura, simulando que o dispositivo móvel está fisicamente dentro da rede local matriz do IBGE, o agente de informática instruiu o uso obrigatório de:", imagem:null, alternativas:["A) uma VPN (Virtual Private Network), que encapsula os pacotes de dados protegendo-os de interceptação externa.","B) um servidor DNS dinâmico, que mascarará o endereço físico da lanchonete trocando o IP interno.","C) uma Extranet limpa, que bloqueia o acesso de outros clientes da lanchonete ao modem sem fio.","D) um Proxy reverso, que limpa o cache de navegação do dispositivo antes de transmitir a carga de formulários.","E) uma VLAN perimetral, criando um cabo virtual de rádio frequência livre de colisões CSMA/CD."], resposta_correta:0, explicacao:"A alternativa A está correta. O conceito de VPN é fortemente cobrado como solução de segurança sobre redes públicas. A VPN cria um túnel criptografado (encapsulamento), permitindo tráfego seguro de dados corporativos via internet comum. O distrator B (DNS) apenas traduz nomes; o distrator C (Extranet) é um conceito de acesso restrito a parceiros, mas não descreve o 'túnel seguro' em si; o distrator E (VLAN) divide redes locais internamente, não criptografa conexões externas via internet.", status:0, historico:0 },
{id:3270, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Sobre os serviços de infraestrutura de redes cruciais para o funcionamento dos laboratórios do IBGE, analise as proposições a seguir e julgue-as:\\nI - O protocolo DNS (Domain Name System) tem a função precípua de traduzir os nomes de domínio amigáveis (como ibge.gov.br) para endereços IP numéricos, dispensando o usuário de memorizar sequências lógicas complexas. \\nII - O protocolo DHCP (Dynamic Host Configuration Protocol) atua automatizando a configuração das placas de rede, distribuindo dinamicamente endereços IP, máscaras de sub-rede e gateways para os tablets que se conectam ao Wi-Fi do posto. \\nIII - Quando o DHCP falha globalmente, o DNS assume a contingência alocando endereços MAC secundários aos dispositivos móveis para manter a navegação ativa. \\nÉ correto o que se afirma em:", imagem:null, alternativas:["A) Apenas I.","B) Apenas II.","C) Apenas I e II.","D) Apenas II e III.","E) I, II e III."], resposta_correta:2, explicacao:"A alternativa C está correta. A afirmação I define perfeitamente o DNS (tradutor de nomes para IP). A afirmação II define com precisão cirúrgica o DHCP (distribuidor de IPs dinâmicos). A afirmação III é absurdamente falsa e típica pegadinha da Avalia:DNS não aloca endereços MAC (que vêm de fábrica na placa física) nem atua como contingência de DHCP. Misturar serviços de rede de camadas distintas é o método preferido do examinador para confundir candidatos medianos.", status:0, historico:0 },
{id:3271, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Devido ao esgotamento matemático dos endereços lógicos mundiais, o provedor de internet do polo regional migrou a conexão do IBGE para o padrão IPv6. Sobre as distinções arquitetônicas e conceituais do IPv4 em relação ao IPv6, o analista deve ter ciência inegável de que:", imagem:null, alternativas:["A) O IPv4 utiliza um formato de 32 bits representado nativamente por notação decimal separada por pontos, enquanto o IPv6 expande a capacidade para 128 bits, sendo representado por notação hexadecimal separada por dois pontos.","B) O IPv6 foi desenvolvido para substituir o IPv4 com o atrativo principal de eliminar o uso das placas de rede físicas (MAC Addresses), unificando hardware e software em uma numeração decimal de 64 bits.","C) O IPv4 provê segurança nativa através do IPSec embutido em seu cabeçalho matriz, recurso que foi removido do IPv6 para focar estritamente em velocidade de broadcast.","D) O IPv6, por ser hexadecimal, possui a exata mesma quantidade de endereços disponíveis que o IPv4, mas os organiza em blocos mais eficientes de 32 bits paralelos.","E) A migração para IPv6 dispensa a utilização do DNS na internet, vez que os endereços hexadecimais de 128 bits já são semanticamente compreensíveis e legíveis ao cérebro humano sem auxílio de tradutores."], resposta_correta:0, explicacao:"A alternativa A está correta. Aborda a diferença morfológica clássica das gerações IP. IPv4 = 32 bits (divididos em 4 octetos decimais, ex:192.168.1.1). IPv6 = 128 bits (divididos em 8 blocos hexadecimais, ex:fe80::1a2b). A Avalia elabora distratores por meio de generalizações indevidas:o IPv6 NÃO elimina o MAC Address (B é falsa); o IPv6 é que traz suporte nativo aprimorado ao IPSec, não o inverso (C é falsa); a quantidade de endereços do IPv6 é astronomicamente maior (D é falsa); e o ser humano obviamente não memoriza cadeias hexadecimais de 128 bits facilmente, o que torna o DNS ainda mais vital (E é falsa).", status:0, historico:0 },
{id:3272, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Um recenseador que utiliza o portal da transparência percebe que, após limpar completamente os dados do seu navegador web, a página demorou muito mais tempo para carregar na primeira visita, mas perdeu o preenchimento automático do seu login e os itens de navegação da sessão. Na teoria de infraestrutura e navegação web, a lentidão no carregamento das imagens e a perda da sessão de login devem-se, respectivamente, à exclusão prévia do(a):", imagem:null, alternativas:["A) Cache local e dos Cookies.","B) Histórico de URLs e do Servidor Proxy.","C) Cookies de sessão e do Cache DNS.","D) Favoritos salvos e da Zona Intranet.","E) Cache local e do IP dinâmico da máquina."], resposta_correta:0, explicacao:"A alternativa A está correta. A banca exige a separação exata entre Cache e Cookies, frequentemente confundidos pelos candidatos. CACHE:armazena pedaços estáticos das páginas (imagens, scripts) no HD do usuário; se apagado, o site demora a carregar pois baixa tudo de novo. COOKIES:armazenam dados de navegação, sessão de login e preferências do usuário; se apagados, o usuário é 'deslogado' e perde itens do carrinho ou preferências. O distrator C inverte as funções maliciosamente e os demais inventam remoções irreais (não se exclui um IP dinâmico limpando dados do navegador).", status:0, historico:0 },
{id:3273, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Os equipamentos de rede operam processando dados em camadas distintas do modelo OSI para garantir a comunicação padronizada do IBGE. Analise os ativos de rede abaixo e marque (V) para Verdadeiro e (F) para Falso:\\n( ) O Hub é um dispositivo de camada 1 (Física) que não possui inteligência para ler endereços MAC, operando por broadcast (replicando o sinal recebido para todas as demais portas). \\n( ) O Switch opera na camada 2 (Enlace de Dados) e segmenta domínios de colisão, direcionando o tráfego apenas para a porta do dispositivo de destino através da análise de seu endereço IP. \\n( ) O Roteador é um dispositivo de camada 3 (Rede) capaz de interligar redes com arquiteturas diferentes, encaminhando os pacotes baseando-se em endereços IP. \\nA sequência correta imposta pelos preceitos de redes é:", imagem:null, alternativas:["A) V, F, V.","B) F, V, V.","C) V, V, F.","D) F, F, V.","E) V, V, V."], resposta_correta:0, explicacao:"A alternativa A está correta (V, F, V). A afirmação I é verdadeira (Hubs são repetidores burros de camada 1). A afirmação II é a armadilha central da Avalia:É Falsa. Embora o Switch opere na camada 2 e segmente domínio de colisão (correto até aqui), ele direciona o tráfego baseado no endereço MAC físico, e NÃO no endereço IP (que é matéria da camada 3 do roteador). O examinador planta uma mentira no final de uma frase cheia de verdades técnicas. A afirmação III é verdadeira (definição clássica do Roteador atuando na camada de Rede com IPs).", status:0, historico:0 },
{id:3274, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Para otimizar o uso da banda larga no posto censitário e garantir diretrizes de acesso, a TI instalou um servidor Proxy na rede. Durante uma auditoria, constatou-se que o consumo de internet reduziu significativamente mesmo com muitos usuários acessando a mesma portaria da prefeitura diariamente. Qual comportamento essencial de um Servidor Proxy justifica inequivocamente essa redução no consumo de banda externa?", imagem:null, alternativas:["A) Ele bloqueia os protocolos TCP, forçando a rede a operar via UDP, o que elimina o tamanho excessivo dos cabeçalhos na banda larga externa.","B) Ele atua como um intermediário que criptografa os dados usando túneis VPN de ponta a ponta, comprimindo as fotos em arquivos binários opacos.","C) Ele atua retendo uma cópia local (cache) das páginas web mais acessadas pelos recenseadores; quando um novo agente solicita a mesma página, o Proxy a entrega localmente sem precisar baixar tudo da internet novamente.","D) Ele modifica ativamente os endereços IP públicos do IBGE para IPs privados, reduzindo a conta de tarifação da operadora de telecomunicação na conversão do NAT.","E) Ele intercepta pacotes maliciosos na camada de aplicação, transformando-se em um switch passivo que converte dados em fibras ópticas."], resposta_correta:2, explicacao:"A alternativa C está correta. A função primária de um servidor Proxy (além de filtrar/bloquear acesso) é o 'Web Caching'. Quando 50 funcionários acessam o site do IBGE, o Proxy baixa o site na primeira vez e guarda uma cópia. Para os outros 49, ele entrega a cópia local, não consumindo internet externa de fato. O distrator A inverte lógicas de camada de transporte; o B descreve uma mescla de VPN com compressão irreal; o D confunde Proxy com NAT (Network Address Translation).", status:0, historico:0 },
{id:3275, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"As redes de computadores são classificadas segundo a sua abrangência geográfica. O parque computacional situado internamente no andar do prédio do IBGE em Salvador e a conexão dedicada e roteada dessa base de Salvador com o mega Data Center localizado na cidade do Rio de Janeiro configuram, técnica e respectivamente, as escalas de rede denominadas:", imagem:null, alternativas:["A) MAN e PAN.","B) LAN e WAN.","C) PAN e WLAN.","D) WAN e LAN.","E) LAN e MAN."], resposta_correta:1, explicacao:"A alternativa B está correta. Conceito direto exaustivamente cobrado:Uma rede restrita a um prédio, sala ou andar é uma LAN (Local Area Network). Uma rede de longa distância que cruza limites estaduais, países ou continentes, como conectar Bahia ao Rio de Janeiro, é categoricamente uma WAN (Wide Area Network). O distrator A fala em MAN (Metropolitana) e PAN (Pessoal, como Bluetooth). O distrator D inverte cruelmente as posições das redes exigidas no enunciado.", status:0, historico:0 },
{id:3276, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Um coordenador relata ao suporte técnico que não consegue despachar os relatórios finais via e-mail do seu cliente de correio eletrônico (como o Outlook), embora consiga receber as mensagens das demais filiais normalmente. O técnico constata que há um bloqueio restritivo em um protocolo específico na porta do provedor de acesso. Qual protocolo da camada de aplicação do modelo TCP/IP está sofrendo falha ou bloqueio, impedindo exclusivamente o envio (saída) das mensagens do cliente para o servidor?", imagem:null, alternativas:["A) IMAP (Internet Message Access Protocol).","B) POP3 (Post Office Protocol version 3).","C) SMTP (Simple Mail Transfer Protocol).","D) FTP (File Transfer Protocol).","E) SNMP (Simple Network Management Protocol)."], resposta_correta:2, explicacao:"A alternativa C está correta. A banca foca na mnemônica clássica de e-mails. O SMTP é o protocolo responsável pelo ENVIO/SAÍDA (Sua Mensagem Tá Partindo) dos e-mails a partir do cliente. Se o usuário recebe mas não envia, a falha é no SMTP. O POP3 (baixa e remove do servidor) e o IMAP (sincroniza leitura nas nuvens) são protocolos exclusivos de RECEBIMENTO (distratores A e B). O distrator D (FTP) é para transferência de arquivos gerais, e o distrator E (SNMP) é para gerenciamento de rede (muito parecido com SMTP visualmente, feito para punir leitura desatenta).", status:0, historico:0 },
{id:3277, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Quando o tablet do setor acusa falha geral de conexão com a base de dados central (ibge.gov.br), o Agente de Informática abre a interface de comando (Prompt) e digita utilitários nativos para investigar o engarrafamento. Se ele deseja medir o tempo de resposta simples para saber se o servidor está alcançável e vivo, e logo após deseja ver a lista completa de todos os roteadores intermediários (saltos) pelos quais o pacote passa até chegar no Rio de Janeiro, ele utilizará correta e sequencialmente os comandos:", imagem:null, alternativas:["A) Tracert e Nslookup.","B) Ping e Netstat.","C) Ipconfig e Ping.","D) Ping e Tracert (ou Traceroute).","E) Arp e Route."], resposta_correta:3, explicacao:"A alternativa D está correta. Questão técnica operacional de rede via prompt de comando. O PING envia pacotes de 'echo request' do protocolo ICMP para testar a conectividade básica (saber se o site/IP responde). O TRACERT (ou Traceroute em Linux/Unix) mapeia o caminho, mostrando todos os nós e roteadores intermediários ('hops' ou saltos) até o destino final, ajudando a achar onde o gargalo ocorre. O distrator C confunde com o Ipconfig (que só mostra o IP da própria máquina local). O distrator B usa o Netstat (que exibe portas abertas e conexões ativas na máquina local, não mapeia rota).", status:0, historico:0 },
{id:3278, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Sobre os meios físicos de transmissão cabeada empregados na topologia das subseções do censo, pondere sobre as tecnologias de par trançado e fibra óptica. I - O cabo UTP (Par Trançado Sem Blindagem) tem seus fios internos trançados unicamente por questões estéticas de fabricação, não exercendo efeito sobre o sinal elétrico. II - A fibra óptica transmite dados por pulsos de luz no interior de um núcleo de vidro ou polímero, tornando-a integralmente imune a Interferências Eletromagnéticas (EMI) externas. III - O cabo UTP categoria 6 (Cat6) possui maior taxa de transmissão que as antigas redes co-axiais rústicas do passado, porém ainda está sujeito a atenuação do sinal elétrico se esticado por distâncias desproporcionais sem uso de repetidores. A verdade técnica reside em:", imagem:null, alternativas:["A) Apenas I e II.","B) Apenas II e III.","C) Apenas I e III.","D) I, II e III.","E) Apenas III."], resposta_correta:1, explicacao:"A alternativa B está correta. A afirmação I abriga o erro grave (falácia de generalização indevida):o trançamento dos pares no cabo UTP não é estético, mas um fenômeno da física para anular ativamente o 'crosstalk' (linha cruzada) e reduzir o ruído eletromagnético dos pares vizinhos. A afirmação II é a premissa de ouro da fibra óptica:como transporta fótons (luz) e não elétrons, motores ou raios magnéticos não a interferem. A afirmação III é verdadeira, o cabo de cobre UTP (seja Cat5 ou Cat6) sofre atenuação elétrica (sinal enfraquece) após a marca média de 100 metros lógicos e precisa de switch ou repetidor.", status:0, historico:0 },
{id:3279, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Buscando realizar uma pesquisa de preços de hospedagem sem que o algoritmo dos sites de busca memorize suas preferências, um agente adota o uso do 'Modo de Navegação Anônima' (InPrivate ou Incognito) em seu navegador padrão. Frente aos mecanismos reais de proteção de rede e privacidade do modo anônimo, é tecnicamente incontestável que essa aba obscura:", imagem:null, alternativas:["A) mascara o endereço IP público da máquina, tornando as buscas invisíveis para as operadoras de telecomunicações do estado.","B) apaga automaticamente o histórico de navegação, cookies e formulários preenchidos apenas localmente (no seu próprio computador) após o fechamento da janela, mas não oculta a sua navegação do Provedor de Internet (ISP) nem do administrador da rede do IBGE.","C) cria um túnel VPN direto para o site buscado, criptografando a visualização para impedir o rastreio cego do provedor.","D) imuniza ativamente o sistema contra o download de arquivos maliciosos ou keyloggers passivos da web orgânica.","E) impede que o provedor de e-mail remoto rastreie a digitação nativa ao converter as URLs do cabeçalho HTTPS em pacotes isolados."], resposta_correta:1, explicacao:"A alternativa B está correta. O Instituto Avalia sempre cobra o 'mito' do modo anônimo. O modo anônimo protege a privacidade do usuário APENAS contra quem usa o mesmo computador físico (esposa, colega de mesa). Ele limpa o rastro local (cache, histórico) quando fecha a janela. Contudo, seu chefe, o administrador de TI do IBGE ou a Vivo/Claro continuam vendo todos os sites que você acessa normalmente. O distrator A explora a falsa crença de que ele esconde o IP ou age como VPN, o que é um conceito atroz.", status:0, historico:0 },
{id:3280, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Ao configurar estaticamente a placa de rede de um computador novo no polo estadual do censo, o técnico preenche os campos:Endereço IP (192.168.1.15), Máscara de Sub-rede (255.255.255.0) e o Gateway Padrão (Default Gateway). Qual a função técnica vital do 'Gateway Padrão' configurado nesse contexto arquitetônico de redes TCP/IP?", imagem:null, alternativas:["A) Definir qual é o endereço MAC físico da placa de rede local para evitar conflito de domínio interno em colisões.","B) Traduzir de forma passiva os endereços amigáveis da web em endereços lógicos atrelados à máquina.","C) Informar à máquina qual é o endereço IP do roteador local que fará a saída; ou seja, apontar a porta de escape para onde os pacotes devem ser enviados quando o destino pertencer a uma rede externa diferente da sua (como a Internet ou o servidor no RJ).","D) Interceptar pacotes de broadcast da própria rede local para impedir o espelhamento massivo do Switch de borda periférica.","E) Funcionar como uma senha de sub-rede estática, garantindo a criptografia AES da camada de enlace na malha corporativa baiana."], resposta_correta:2, explicacao:"A alternativa C está correta. O Gateway Padrão (Portão de Saída) é essencialmente o endereço IP da interface do Roteador mais próximo de você. O computador pensa:'Esse arquivo vai para a máquina do lado? Entrego via Switch. Esse arquivo vai para o Rio de Janeiro? Não está na minha rede, então vou mandar pro Gateway Padrão (Roteador), pois ele sabe o caminho pra fora'. A alternativa B tenta confundir Gateway com o servidor DNS; a alternativa A confunde com conceitos físicos da camada 2 (MAC Address).", status:0, historico:0 },
{id:3281, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Os 50 tablets operando no IBGE regional estão acessando a internet comumente. Contudo, todos eles possuem endereços IP privados (iniciados com 10.x.x.x ou 192.168.x.x), os quais são inviáveis e não roteáveis na rede global pública da Internet. Qual é o serviço ou protocolo implementado no roteador de borda do IBGE que possibilita que esses 50 tablets consigam navegar simultaneamente na internet utilizando um único endereço IP público válido perante a operadora?", imagem:null, alternativas:["A) ARP (Address Resolution Protocol).","B) NAT (Network Address Translation).","C) SSH (Secure Shell).","D) DNS (Domain Name System).","E) FTP passivo (File Transfer Protocol)."], resposta_correta:1, explicacao:"A alternativa B está correta. O NAT (Tradução de Endereços de Rede) é a tecnologia salvadora que converte pacotes contendo IP privado em um IP público único do roteador para conversar com o mundo externo, guardando uma tabela interna para devolver a resposta correta ao tablet certo que fez a requisição. Sem o NAT, o esgotamento do IPv4 teria ocorrido na década de 90. O distrator D (DNS) tenta pegar os apressados que associam 'Tradução' a qualquer serviço do router; o DNS traduz NOMES para IP, o NAT traduz IP PRIVADO para IP PÚBLICO. ARP (A) converte IP em MAC internamente.", status:0, historico:0 },
{id:3282, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Para estabelecer um novo link de dados sem fio (Wi-Fi) no alojamento dos cadastradores agrários, o técnico precisa blindar a conexão contra a quebra de senha via força bruta. Evitando protocolos obsoletos falhos, ele deve acionar na interface do roteador wireless qual conjunto padronizado e contemporâneo focado na alta criptografia avançada da rede sem fio baseada no esquema AES?", imagem:null, alternativas:["A) WEP, que permanece inegavelmente como a cifra de base estática passiva irrompível nos padrões modulares IEEE 802.11 b/g/n puros.","B) CSMA/CD, por ser a trava magnética e elétrica primária da colisão ativa litorânea dos pacotes de ar rústicos orgânicos e seguros.","C) WPA2 ou WPA3, pois são os padrões de segurança atualizados que oferecem proteção robusta (como a criptografia CCMP/AES), em oposição ao defasado, falho e frágil WEP.","D) SSL, visto que roteadores wireless dependem obrigatoriamente do encapsulamento de certificados de correio puro local rústico para emitir o sinal SSID público passivo da base.","E) IPSec 802.3, cravando a ponte maciça criptográfica de enlace na frequência de 5 GHz raso litorâneo da rede em anel mudo contínuo livre pardo."], resposta_correta:2, explicacao:"A alternativa C está correta. Na hierarquia de segurança Wi-Fi, o WEP é jurássico e facilmente hackeado. O WPA foi o substituto provisório. O WPA2 (que usa AES) e o moderníssimo WPA3 são as escolhas corretas de segurança exigidas pelas políticas do governo. O distrator A elogia grotescamente o falido WEP. O distrator B usa a técnica de controle de meio CSMA/CD (que nem sequer é usada no Wi-Fi, onde se usa CSMA/CA, e de qualquer forma não é protocolo de criptografia).", status:0, historico:0 },
{id:3283, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Para que o firewall institucional seja ajustado perfeitamente no acesso remoto aos serviços web, o Agente de Informática mapeia as portas lógicas da camada de transporte do protocolo TCP e UDP inerentes a cada serviço. Julgue as associações técnicas de portas e serviços a seguir:\\nI - O protocolo HTTP, responsável pela transferência em texto claro das páginas de hipertexto convencionais, atua primordialmente e ativamente associado à porta padrão 80 do protocolo TCP. \\nII - O protocolo HTTPS, portador do escudo criptográfico SSL/TLS nativo sobre a web puritana, flui organicamente bloqueado e associado à porta 443 do protocolo TCP. \\nIII - A transferência brutal de arquivos grandes e binários isolados (via FTP nativo) utiliza habitualmente o par de portas TCP 20 (para dados) e 21 (para o controle de comando do painel). \\nA correlação exata de portas que se mostra perfeitamente imaculada encontra-se na assertiva:", imagem:null, alternativas:["A) Apenas I.","B) Apenas II e III.","C) Apenas I e III.","D) Apenas I e II.","E) I, II e III."], resposta_correta:4, explicacao:"A alternativa E está correta. A banca exige memorização da IANA para portas vitais de concursos públicos. A afirmação I aponta acertadamente a porta 80 para o HTTP comum. A II afirma corretamente que o HTTPS seguro trafega na porta 443. E a III descreve perfeitamente a dinâmica peculiar do FTP, que é um dos poucos protocolos que consome 2 portas distintas por padrão (20 transfere a carga/arquivo bruto; 21 gerencia os comandos de autenticação/pausa/reinício). Todas são verdadeiras e materializam o rigor numérico da camada de transporte.", status:0, historico:0 },
{id:3284, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Ao plugar um notebook em uma rede corporativa governamental isolada sob restrições físicas de segurança, a primeira barreira do sistema no switch exige que a máquina esteja cadastrada em uma lista de aprovação de 'MAC Address' ('MAC Filtering'). Relativo à natureza material e inegociável desse endereço na estrutura da máquina física, o Endereço MAC caracteriza-se fundamentalmente por:", imagem:null, alternativas:["A) Ser atribuído dinamicamente pelo servidor DHCP assim que a máquina é religada, garantindo sua renovação constante para ludibriar sniffers na LAN.","B) Ser um endereço lógico de 32 bits utilizado primordialmente na camada de Rede do modelo OSI para encontrar o melhor caminho de salto até um provedor da nuvem externa corporativa litorânea passiva.","C) Consistir em um endereço físico estático de 48 bits, gravado nativamente em hexadecimal na ROM da própria placa de rede pelo fabricante ('burned-in address'), operando na camada de Enlace de Dados para comunicação direta na mesma rede local.","D) Corresponder ao endereço de e-mail raiz cadastrado no painel remoto Microsoft da máquina baiana isolada orgânica litorânea densa rústica ativa limítrofe inativa pura.","E) Ser uma máscara de sub-rede variável que fragmenta o domínio de broadcast puro orgânico rural em pequenas VLans amigáveis contínuas limpas pacíficas ativas maciças pátrias de base cega e paralela."], resposta_correta:2, explicacao:"A alternativa C está correta. Endereço MAC (Media Access Control) é o RG ou CPF físico da sua Placa de Rede (NIC). Ele vem queimado de fábrica (burned-in), tem 48 bits em formato Hexadecimal e atua na Camada 2 (Enlace). Diferencia-se brutalmente do IP (Endereço lógico, que muda de acordo com o lugar em que você conecta). A pegadinha da Avalia reside na afirmativa A (dizer que o MAC é dinâmico/DHCP, função que pertence ao IP) e B (tratar o MAC como ferramenta lógica de 32 bits de roteamento, roubando as características centrais operacionais exclusivas do IPv4).", status:0, historico:0 },
{id:3285, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"Os modelos de arquitetura de rede ditam as regras de requisição e fornecimento de recursos. No IBGE, o sistema em que centenas de tablets solicitam diariamente arquivos centralizados de formulários armazenados em um único mega-computador no Rio de Janeiro diferencia-se diametralmente do modelo em que os agentes trocam pequenos memorandos simultâneos diretamente uns com os outros nas máquinas do posto, sem a intervenção de um supercomputador hierárquico. As arquiteturas narradas referem-se, imperativamente e na ordem descrita, a:", imagem:null, alternativas:["A) Peer-to-Peer (P2P) e Cliente-Servidor.","B) Arquitetura em Malha orgânica e Token Ring estrutural.","C) Cliente-Servidor e Arquitetura Ponto-a-Ponto (P2P).","D) Mainframe nativo ativo e Computação em Nuvem Híbrida.","E) Thin Client paralelo pacífico e Extranet puritana litorânea ativa estática pacata."], resposta_correta:2, explicacao:"A alternativa C está correta. A arquitetura Cliente-Servidor baseia-se em uma hierarquia pesada:um Servidor central poderoso e altamente disponível atende às solicitações passivas de centenas de Clientes marginais subordinados (modelo do mega-computador do RJ). Já a troca direta entre os próprios tablets, onde não existe 'rei' e todos são simultaneamente clientes e fornecedores, perfaz o modelo Ponto-a-Ponto (P2P ou Peer-to-Peer), característico de Torrent ou pequenas redes domésticas ad-hoc sem gerência central. O distrator A inverte a ordem de forma letal, e os demais misturam topologias (anel, malha) que não dizem respeito à lógica do software do sistema.", status:0, historico:0 },
{id:3286, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"A visualização de um cadeado fechado ao lado da URL ('https://') nos portais de serviço atesta ao Agente de Endemias que ele não será alvo de sniffers capturando sua senha em texto puro no percurso. Sobre o alicerce e as engrenagens de segurança que compõem o HTTPS em oposição ao obsoleto HTTP puro orgânico inerte de texto claro, consolida-se materialmente que o protocolo HTTPS:", imagem:null, alternativas:["A) blinda a máquina isoladamente contínua estática através da ação de antivírus alocados localmente e puritanos na placa mãe nativa refratária limpa pacata e isenta.","B) emprega as extensões de segurança SSL (Secure Sockets Layer) ou seu sucessor aprimorado moderno TLS (Transport Layer Security) para gerar a criptografia robusta dos pacotes do site na camada de aplicação e transporte reverso paralelo inativo nativo cego.","C) bloqueia categoricamente e passivamente que o navegador acesse sites hospedados fora da fronteira pacata litorânea limítrofe nacional, atuando como um firewall de zona geolocalizada pátria maciça puritana limpa e rural pacífica rústica densa.","D) transfere organicamente a carga refratária de dados pelo protocolo UDP puritano na porta ativa marginal rústica 80, o que confunde taticamente os hackers litorâneos inócuos marginais inertes nativos ocos cegos.","E) impede forçadamente e nativamente o carregamento do cache no disco cível local pacífico orgânico puritano isolado pacato remota inativo para não vazar históricos litorâneos fétidos rasos."], resposta_correta:1, explicacao:"A alternativa B está correta. A Avalia testa a composição química do HTTPS. Ele nada mais é do que o HTTP clássico encapsulado sobre os certificados de túnel criptográfico SSL (antigo) ou o TLS (o padrão atual seguro adotado universalmente moderno). Isso garante integridade, confidencialidade e autenticação do tráfego web entre você e o banco/site. O distrator A inventa que ele age como antivírus local (falso, ele não mata vírus da sua máquina, só esconde os dados viajando). O distrator D inverte para a porta 80 e UDP, quando o HTTPS roda sobre a porta 443 TCP.", status:0, historico:0 },
{id:3287, categoria:"Conhecimentos Básicos", materia:"Informática", assunto:"internet e redes", cargo:"Agente Censitário de Informática", ano:"2026", banca:"Avalia", concurso:"IBGE", enunciado:"As tecnologias de rede locais clássicas (Ethernet cabeada via Switch) e sem fio (Wi-Fi local) utilizam mecanismos de detecção no fundo de suas camadas para gerenciar como as máquinas decidem falar para evitar que duas enviem sinais na exata mesma fração de segundo pelo mesmo meio gerando corrupção do frame. Quais são, na respectiva e cível ordem, os protocolos de controle de acesso ao meio empregados organicamente por redes cabeadas Ethernet rústicas e redes Wi-Fi passivas aéreas?", imagem:null, alternativas:["A) Token Ring estático analítico e FDDI puritano denso passivo liso rural ativo litorâneo limítrofe oco.","B) CSMA/CA (Carrier Sense Multiple Access with Collision Avoidance) e o CSMA/CD (Collision Detection).","C) CSMA/CD (Carrier Sense Multiple Access with Collision Detection) e o CSMA/CA (Collision Avoidance).","D) OSPF litorâneo passivo marginal e o BGP ativo puro cego estático inerte rural rústico pacato denso.","E) IPv4 limpo pacato isolado denso ativo rústico puro raso e o IPv6 orgânico denso raso inócuo moroso."], resposta_correta:2, explicacao:"A alternativa C está correta. Um conhecimento de raízes densas das topologias clássicas. Ethernet cabeada utiliza o CSMA/CD (Collision Detection = Detecção de colisão):ele 'escuta' o cabo de cobre elétrico; se dois falam e a voltagem sobe colidindo, ele detecta a batida e manda as máquinas esperarem. Wi-Fi (rádio, ar) usa o CSMA/CA (Collision Avoidance = Evitar Colisão):como no ar os rádios não conseguem 'detectar' a colisão perfeitamente enquanto enviam (pois as antenas escutam e enviam em potências desiguais), eles pedem autorização prévia ao roteador (RTS/CTS) para EVITAR o choque aéreo antecipadamente. O distrator B inverte malignamente a ordem imposta no texto e o D mescla protocolos de roteamento (OSPF/BGP) absurdos.", status:0, historico:0 },
//Extraído de Provas
{id:3288, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Semântica", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"CULTIVAR PARA FLORESCER:COMO AS PLANTAS TRANSFORMAM O CORPO E A MENTE\n\nCuidar de plantas vai muito além da estética:é um ato de bem-estar. Do toque na terra ao florescer das folhas, o cultivo estimula os sentidos, fortalece o corpo e acalma a mente. Ao cultivar hortaliças, plantas ornamentais e medicinais em casa, nos aproximamos da natureza e paramos de pensar nos problemas. A atividade é um cultivo de paciência, criatividade e autodesenvolvimento. Vamos ter para nós que o cultivo de plantas em casa beneficia em três diferentes planos:ambiental, físico e mental.\n\nNo ambiental, não é novidade que as plantas têm um papel essencial na manutenção de ecossistemas. No físico, as atividades de plantar, podar, regar e colher ajudam nos sentidos, como visão, tato e olfato – além do constante exercício físico de baixo impacto. E, para a mente, o ato de cultivar estimula a concentração, promove a redução de estresse e incentiva aprendizado e criatividade. Cultivar também envolve decisões como escolha do local, do que e como plantar. Assim, a pessoa se sente fundamental no processo de execução, o que torna a atividade mais prazerosa e relaxante. Mas se o seu problema é espaço – ou a falta dele –, saiba que você não precisa ter um jardim enorme para sentir os efeitos positivos. Afinal, vale de tudo:hortaliças, plantas ornamentais e medicinais. Também não há restrições de idade para o cultivo, mas é importante adaptar a atividade de acordo com a faixa etária. A botânica Flávia Cartaxo Ramalho Vilar explica:“Crianças devem realizar o plantio em vasos ou jardineiras, enquanto jovens e adultos podem usar uma área maior e instalar hortas ou jardins. Já para os idosos, o melhor é realizar o cultivo em vasos instalados em uma altura adequada, de fácil acesso e corredores livres, para evitar quedas”. Especificamente para os idosos, Flávia aponta que a prática de jardinagem proporciona efeitos notáveis na saúde, que dão suporte para a coordenação motora e a motricidade fina (movimentos pequenos e precisos), além de auxiliar na distração de pensamentos relacionados à perda de vigor e saúde.\n\nOs benefícios são tantos que o cultivo de plantas até é utilizado como prática de terapia ocupacional, chamada de hortoterapia, com foco no desenvolvimento físico e mental dos praticantes. Docente do IF Sertão Pernambuco, Flávia estudou os benefícios da prática e conta que “a formação de um ambiente de cultivo das plantas permite que a pessoa tenha um contato direto com a terra e o prazer de se sentir útil a si mesmo e às pessoas de seu convívio. A horta é um espaço de desenvolvimento, manifestação, criatividade, transformação, humanização, experimentação, interação social e convivência”, diz. Segundo ela, essa terapia, em conjunto com tratamento médico, pode estimular os sentidos e a mente, com resultados em questões sociais, cognitivas, físicas e psicológicas, auxiliando no alívio do estresse e agregando saberes.\n\nAlém de muitos benefícios físicos e mentais, as plantas podem nos ensinar sobre resiliência, cooperação e eficiência. [...]\n\nQUESTÃO 02\nNa passagem do texto “No ambiental, não é novidade que as plantas têm um papel essencial na manutenção de ecossistemas.”, a palavra “ecossistemas” foi usada no sentido", imagem:null, alternativas:["A) ambíguo.", "B) conotativo.", "C) denotativo.", "D) irônico.", "E) pejorativo."], resposta_correta:2, explicacao:"A alternativa C está correta. A palavra 'ecossistemas' foi empregada em seu sentido estrito, literal e objetivo do dicionário, referindo-se ao meio ambiente biológico. O uso literal das palavras é o que chamamos de sentido 'Denotativo' (lembre-se do 'D' de Dicionário). Não há duplo sentido (ambíguo), sentido figurado/poético (conotativo), tom de deboche (irônico) ou tentativa de ofensa (pejorativo).", status:0, historico:0 },
{id:3289, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Tipologia, Gênero e Discurso", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"CULTIVAR PARA FLORESCER:COMO AS PLANTAS TRANSFORMAM O CORPO E A MENTE\n\nCuidar de plantas vai muito além da estética:é um ato de bem-estar. Do toque na terra ao florescer das folhas, o cultivo estimula os sentidos, fortalece o corpo e acalma a mente. Ao cultivar hortaliças, plantas ornamentais e medicinais em casa, nos aproximamos da natureza e paramos de pensar nos problemas. A atividade é um cultivo de paciência, criatividade e autodesenvolvimento. Vamos ter para nós que o cultivo de plantas em casa beneficia em três diferentes planos:ambiental, físico e mental.\n\nNo ambiental, não é novidade que as plantas têm um papel essencial na manutenção de ecossistemas. No físico, as atividades de plantar, podar, regar e colher ajudam nos sentidos, como visão, tato e olfato – além do constante exercício físico de baixo impacto. E, para a mente, o ato de cultivar estimula a concentração, promove a redução de estresse e incentiva aprendizado e criatividade. Cultivar também envolve decisões como escolha do local, do que e como plantar. Assim, a pessoa se sente fundamental no processo de execução, o que torna a atividade mais prazerosa e relaxante. Mas se o seu problema é espaço – ou a falta dele –, saiba que você não precisa ter um jardim enorme para sentir os efeitos positivos. Afinal, vale de tudo:hortaliças, plantas ornamentais e medicinais. Também não há restrições de idade para o cultivo, mas é importante adaptar a atividade de acordo com a faixa etária. A botânica Flávia Cartaxo Ramalho Vilar explica:“Crianças devem realizar o plantio em vasos ou jardineiras, enquanto jovens e adultos podem usar uma área maior e instalar hortas ou jardins. Já para os idosos, o melhor é realizar o cultivo em vasos instalados em uma altura adequada, de fácil acesso e corredores livres, para evitar quedas”. Especificamente para os idosos, Flávia aponta que a prática de jardinagem proporciona efeitos notáveis na saúde, que dão suporte para a coordenação motora e a motricidade fina (movimentos pequenos e precisos), além de auxiliar na distração de pensamentos relacionados à perda de vigor e saúde.\n\nOs benefícios são tantos que o cultivo de plantas até é utilizado como prática de terapia ocupacional, chamada de hortoterapia, com foco no desenvolvimento físico e mental dos praticantes. Docente do IF Sertão Pernambuco, Flávia estudou os benefícios da prática e conta que “a formação de um ambiente de cultivo das plantas permite que a pessoa tenha um contato direto com a terra e o prazer de se sentir útil a si mesmo e às pessoas de seu convívio. A horta é um espaço de desenvolvimento, manifestação, criatividade, transformação, humanização, experimentação, interação social e convivência”, diz. Segundo ela, essa terapia, em conjunto com tratamento médico, pode estimular os sentidos e a mente, com resultados em questões sociais, cognitivas, físicas e psicológicas, auxiliando no alívio do estresse e agregando saberes.\n\nAlém de muitos benefícios físicos e mentais, as plantas podem nos ensinar sobre resiliência, cooperação e eficiência. [...]\n\nQUESTÃO 03\nTendo em vista a estrutura de composição do texto 01, verifica-se a presença de\nI- citação direta.\nII- citação indireta.\nIII- subjetividade.\nIV- objetividade.\nV- conotação.\nEstão CORRETOS os itens", imagem:null, alternativas:["A) I, II e III, apenas.", "B) I, II, III e V, apenas.", "C) II, III e IV, apenas.", "D) III, IV e V, apenas.", "E) I, II, III, IV e V."], resposta_correta:4, explicacao:"A alternativa E está correta. Todos os elementos estão presentes no texto. I - Há citação direta reproduzindo fielmente as palavras da botânica Flávia entre aspas ('Crianças devem realizar...'). II - Há citação indireta, quando o autor descreve o pensamento dela com suas palavras ('Flávia aponta que a prática de jardinagem proporciona...'). III - Há subjetividade em frases que expressam percepções e sentimentos ('é um ato de bem-estar', 'Vamos ter para nós...'). IV - Há objetividade ao relatar informações concretas e baseadas na ciência (os benefícios físicos, o papel no ecossistema). V - Há conotação (sentido figurado), visível desde o título ('Cultivar para florescer', usando florescer no sentido de crescimento pessoal/mental).", status:0, historico:0 },
{id:3290, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Formação de Palavras", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"CULTIVAR PARA FLORESCER:COMO AS PLANTAS TRANSFORMAM O CORPO E A MENTE\n\nCuidar de plantas vai muito além da estética:é um ato de bem-estar. Do toque na terra ao florescer das folhas, o cultivo estimula os sentidos, fortalece o corpo e acalma a mente. Ao cultivar hortaliças, plantas ornamentais e medicinais em casa, nos aproximamos da natureza e paramos de pensar nos problemas. A atividade é um cultivo de paciência, criatividade e autodesenvolvimento. Vamos ter para nós que o cultivo de plantas em casa beneficia em três diferentes planos:ambiental, físico e mental.\n\nNo ambiental, não é novidade que as plantas têm um papel essencial na manutenção de ecossistemas. No físico, as atividades de plantar, podar, regar e colher ajudam nos sentidos, como visão, tato e olfato – além do constante exercício físico de baixo impacto. E, para a mente, o ato de cultivar estimula a concentração, promove a redução de estresse e incentiva aprendizado e criatividade. Cultivar também envolve decisões como escolha do local, do que e como plantar. Assim, a pessoa se sente fundamental no processo de execução, o que torna a atividade mais prazerosa e relaxante. Mas se o seu problema é espaço – ou a falta dele –, saiba que você não precisa ter um jardim enorme para sentir os efeitos positivos. Afinal, vale de tudo:hortaliças, plantas ornamentais e medicinais. Também não há restrições de idade para o cultivo, mas é importante adaptar a atividade de acordo com a faixa etária. A botânica Flávia Cartaxo Ramalho Vilar explica:“Crianças devem realizar o plantio em vasos ou jardineiras, enquanto jovens e adultos podem usar uma área maior e instalar hortas ou jardins. Já para os idosos, o melhor é realizar o cultivo em vasos instalados em uma altura adequada, de fácil acesso e corredores livres, para evitar quedas”. Especificamente para os idosos, Flávia aponta que a prática de jardinagem proporciona efeitos notáveis na saúde, que dão suporte para a coordenação motora e a motricidade fina (movimentos pequenos e precisos), além de auxiliar na distração de pensamentos relacionados à perda de vigor e saúde.\n\nOs benefícios são tantos que o cultivo de plantas até é utilizado como prática de terapia ocupacional, chamada de hortoterapia, com foco no desenvolvimento físico e mental dos praticantes. Docente do IF Sertão Pernambuco, Flávia estudou os benefícios da prática e conta que “a formação de um ambiente de cultivo das plantas permite que a pessoa tenha um contato direto com a terra e o prazer de se sentir útil a si mesmo e às pessoas de seu convívio. A horta é um espaço de desenvolvimento, manifestação, criatividade, transformação, humanização, experimentação, interação social e convivência”, diz. Segundo ela, essa terapia, em conjunto com tratamento médico, pode estimular os sentidos e a mente, com resultados em questões sociais, cognitivas, físicas e psicológicas, auxiliando no alívio do estresse e agregando saberes.\n\nAlém de muitos benefícios físicos e mentais, as plantas podem nos ensinar sobre resiliência, cooperação e eficiência. [...]\n\nQUESTÃO 04\nSobre a palavra “hortoterapia” usada no texto, é CORRETO afirmar que é", imagem:null, alternativas:["A) formada pelo processo de justaposição de dois radicais.", "B) formada pelo processo de composição de três radicais.", "C) formada pelo processo de aglutinação de dois radicais.", "D) formada por um único radical com anteposição de afixos.", "E) formada por um único radical, sendo, portanto, primitiva."], resposta_correta:0, explicacao:"A alternativa A está correta. A palavra 'hortoterapia' é um neologismo formado pela união de duas bases/palavras distintas:'horto' (ou horta) + 'terapia'. Como a junção dessas duas palavras não causou nenhuma perda ou alteração fonética e gráfica nelas originais (ambas mantêm sua integridade), trata-se do processo de composição por Justaposição. Se houvesse perda (como em plano+alto = planalto), seria aglutinação. Como são duas palavras-base, trata-se de composição de dois radicais, não derivação por afixos e nem palavra primitiva.", status:0, historico:0 },
{id:3291, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Sintaxe", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"CULTIVAR PARA FLORESCER:COMO AS PLANTAS TRANSFORMAM O CORPO E A MENTE\n\nCuidar de plantas vai muito além da estética:é um ato de bem-estar. Do toque na terra ao florescer das folhas, o cultivo estimula os sentidos, fortalece o corpo e acalma a mente. Ao cultivar hortaliças, plantas ornamentais e medicinais em casa, nos aproximamos da natureza e paramos de pensar nos problemas. A atividade é um cultivo de paciência, criatividade e autodesenvolvimento. Vamos ter para nós que o cultivo de plantas em casa beneficia em três diferentes planos:ambiental, físico e mental.\n\nNo ambiental, não é novidade que as plantas têm um papel essencial na manutenção de ecossistemas. No físico, as atividades de plantar, podar, regar e colher ajudam nos sentidos, como visão, tato e olfato – além do constante exercício físico de baixo impacto. E, para a mente, o ato de cultivar estimula a concentração, promove a redução de estresse e incentiva aprendizado e criatividade. Cultivar também envolve decisões como escolha do local, do que e como plantar. Assim, a pessoa se sente fundamental no processo de execução, o que torna a atividade mais prazerosa e relaxante. Mas se o seu problema é espaço – ou a falta dele –, saiba que você não precisa ter um jardim enorme para sentir os efeitos positivos. Afinal, vale de tudo:hortaliças, plantas ornamentais e medicinais. Também não há restrições de idade para o cultivo, mas é importante adaptar a atividade de acordo com a faixa etária. A botânica Flávia Cartaxo Ramalho Vilar explica:“Crianças devem realizar o plantio em vasos ou jardineiras, enquanto jovens e adultos podem usar uma área maior e instalar hortas ou jardins. Já para os idosos, o melhor é realizar o cultivo em vasos instalados em uma altura adequada, de fácil acesso e corredores livres, para evitar quedas”. Especificamente para os idosos, Flávia aponta que a prática de jardinagem proporciona efeitos notáveis na saúde, que dão suporte para a coordenação motora e a motricidade fina (movimentos pequenos e precisos), além de auxiliar na distração de pensamentos relacionados à perda de vigor e saúde.\n\nOs benefícios são tantos que o cultivo de plantas até é utilizado como prática de terapia ocupacional, chamada de hortoterapia, com foco no desenvolvimento físico e mental dos praticantes. Docente do IF Sertão Pernambuco, Flávia estudou os benefícios da prática e conta que “a formação de um ambiente de cultivo das plantas permite que a pessoa tenha um contato direto com a terra e o prazer de se sentir útil a si mesmo e às pessoas de seu convívio. A horta é um espaço de desenvolvimento, manifestação, criatividade, transformação, humanização, experimentação, interação social e convivência”, diz. Segundo ela, essa terapia, em conjunto com tratamento médico, pode estimular os sentidos e a mente, com resultados em questões sociais, cognitivas, físicas e psicológicas, auxiliando no alívio do estresse e agregando saberes.\n\nAlém de muitos benefícios físicos e mentais, as plantas podem nos ensinar sobre resiliência, cooperação e eficiência. [...]\n\nQUESTÃO 05\nConsidere a seguinte passagem do texto:“Cuidar de plantas vai muito além da estética:é um ato de bem-estar. Do toque na terra ao florescer das folhas, o cultivo estimula os sentidos, fortalece o corpo e acalma a mente.”\nAnalise as afirmativas a seguir, tendo em vista a estrutura linguística de composição dessa passagem.\nI- Os dois pontos poderiam ser substituídos por vírgula, sem alteração de sentido.\nII- O verbo “florescer” foi substantivado com a anteposição do artigo definido “o”.\nIII- A conjunção coordenativa “e” insere, na passagem, uma ideia de adversidade.\nIV- O segundo período da passagem é composto por três orações coordenadas.\nV- As palavras “toque” e “florescer” foram empregadas como verbos de ação.\nEstão CORRETAS as afirmativas", imagem:null, alternativas:["A) I, II e III, apenas.", "B) I, II e IV, apenas.", "C) II, III e IV, apenas.", "D) II, III e V, apenas.", "E) III, IV e V, apenas."], resposta_correta:1, explicacao:"A alternativa B está correta. Analisando as afirmativas:I - CORRETA:Os dois-pontos introduzem uma oração coordenada explicativa/justaposta, que poderia ser perfeitamente dividida por vírgula no contexto da pontuação estilística. II - CORRETA:'Florescer' naturalmente é verbo, mas ao ser precedido pela contração 'ao' (preposição 'a' + artigo definido 'o'), ele sofre derivação imprópria e passa a atuar como substantivo. III - INCORRETA:A conjunção 'e' tem valor clássico de ADIÇÃO na frase, e não de oposição (adversidade). IV - CORRETA:O segundo período possui três orações ('o cultivo estimula os sentidos', 'fortalece o corpo', 'e acalma a mente'), coordenadas entre si. V - INCORRETA:Como visto no item II, 'florescer' está como substantivo; e 'toque' também está substantivado pelo artigo na contração 'Do' (de + o).", status:0, historico:0 },
{id:3292, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Divisibilidade", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"Dado o número natural A, para testar se A é primo se fazem testes para saber se determinados números são divisíveis por A. Marque a alternativa que apresenta a menor quantidade possível de testes para afirmar que A é primo.", imagem:null, alternativas:["A) Testar se A é divisível por todos os números menores que A.", "B) Testar se A é divisível por todos os números menores que raiz quadrada de A.", "C) Testar se A é divisível por todos os números primos menores que A.", "D) Testar se A é divisível por todos os números primos menores que raiz quadrada de A.", "E) Testar se A é divisível por todos os números menores que A dividido por 2."], resposta_correta:3, explicacao:"A alternativa D está correta. O método mais eficiente (menor quantidade de testes) para descobrir se um número 'A' é primo consiste em dividi-lo apenas pelos NÚMEROS PRIMOS que sejam menores ou iguais à raiz quadrada de 'A'. A lógica matemática é simples:se um número não é primo, ele é um produto de dois fatores. Pelo menos um desses fatores obrigatoriamente tem que ser menor ou igual à sua raiz quadrada. Assim, testar os primos até o limite da raiz quadrada já é prova suficiente, poupando o trabalho de testar todos os números.", status:0, historico:0 },
{id:3293, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"aritmética", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"João precisa fazer a seguinte conta ⁷√(435)² na calculadora, porém ele percebeu que a calculadora não possui a função ⁷√x. João pode resolver esse problema fazendo o seguinte cálculo:", imagem:null, alternativas:["A) (435)^(14/1).", "B) (435)^(7/14).", "C) (435)^(7/2).", "D) (435)^(1/14).", "E) (435)^(2/7)."], resposta_correta:4, explicacao:"A alternativa E está correta. A questão exige o conhecimento da propriedade fundamental que converte raízes em potências de expoente fracionário. A regra popularmente conhecida é:'quem está no sol (índice da raiz, do lado de fora) vai para a sombra (denominador da fração), e quem está na sombra (expoente do radicando, lado de dentro) vai para o sol (numerador)'. Assim, na expressão matemática da raiz sétima de 435 elevado ao quadrado, o radicando é 435, o expoente é 2 e o índice é 7. Convertendo:(435)^(2/7).", status:0, historico:0 },
{id:3294, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Teoria dos Conjuntos", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"Considerando o intervalo (-1, 4] na reta real, pode-se afirmar que", imagem:null, alternativas:["A) -1 pertence ao intervalo.", "B) 0 não pertence ao intervalo.", "C) 1 não pertence ao intervalo.", "D) 3 pertence ao intervalo.", "E) 4 não pertence ao intervalo."], resposta_correta:3, explicacao:"A alternativa D está correta. A questão avalia a leitura de notação de intervalos na reta real. O parêntese '(-1' indica que o intervalo é ABERTO à esquerda, portanto o número -1 NÃO faz parte do conjunto (a alternativa A é falsa). Já o colchete '4]' indica que o intervalo é FECHADO à direita, ou seja, o número 4 FAZ parte do conjunto (a alternativa E é falsa). Os números englobados compreendem todos os reais maiores que -1 até o 4, o que inclui 0, 1, 2, 3 e 4. Portanto, as alternativas B e C são falsas por dizerem que o 0 e o 1 não pertencem. Resta a alternativa D, que está perfeita:o número 3 pertence ao intervalo.", status:0, historico:0 },
{id:3295, categoria:"Conhecimentos Básicos", materia:"Língua Portuguesa", assunto:"Interpretação e Produção de Textos", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"CULTIVAR PARA FLORESCER:COMO AS PLANTAS TRANSFORMAM O CORPO E A MENTE\n\nCuidar de plantas vai muito além da estética:é um ato de bem-estar. Do toque na terra ao florescer das folhas, o cultivo estimula os sentidos, fortalece o corpo e acalma a mente. Ao cultivar hortaliças, plantas ornamentais e medicinais em casa, nos aproximamos da natureza e paramos de pensar nos problemas. A atividade é um cultivo de paciência, criatividade e autodesenvolvimento. Vamos ter para nós que o cultivo de plantas em casa beneficia em três diferentes planos:ambiental, físico e mental.\n\nNo ambiental, não é novidade que as plantas têm um papel essencial na manutenção de ecossistemas. No físico, as atividades de plantar, podar, regar e colher ajudam nos sentidos, como visão, tato e olfato – além do constante exercício físico de baixo impacto. E, para a mente, o ato de cultivar estimula a concentração, promove a redução de estresse e incentiva aprendizado e criatividade. Cultivar também envolve decisões como escolha do local, do que e como plantar. Assim, a pessoa se sente fundamental no processo de execução, o que torna a atividade mais prazerosa e relaxante. Mas se o seu problema é espaço – ou a falta dele –, saiba que você não precisa ter um jardim enorme para sentir os efeitos positivos. Afinal, vale de tudo:hortaliças, plantas ornamentais e medicinais. Também não há restrições de idade para o cultivo, mas é importante adaptar a atividade de acordo com a faixa etária. A botânica Flávia Cartaxo Ramalho Vilar explica:“Crianças devem realizar o plantio em vasos ou jardineiras, enquanto jovens e adultos podem usar uma área maior e instalar hortas ou jardins. Já para os idosos, o melhor é realizar o cultivo em vasos instalados em uma altura adequada, de fácil acesso e corredores livres, para evitar quedas”. Especificamente para os idosos, Flávia aponta que a prática de jardinagem proporciona efeitos notáveis na saúde, que dão suporte para a coordenação motora e a motricidade fina (movimentos pequenos e precisos), além de auxiliar na distração de pensamentos relacionados à perda de vigor e saúde.\n\nOs benefícios são tantos que o cultivo de plantas até é utilizado como prática de terapia ocupacional, chamada de hortoterapia, com foco no desenvolvimento físico e mental dos praticantes. Docente do IF Sertão Pernambuco, Flávia estudou os benefícios da prática e conta que “a formação de um ambiente de cultivo das plantas permite que a pessoa tenha um contato direto com a terra e o prazer de se sentir útil a si mesmo e às pessoas de seu convívio. A horta é um espaço de desenvolvimento, manifestação, criatividade, transformação, humanização, experimentação, interação social e convivência”, diz. Segundo ela, essa terapia, em conjunto com tratamento médico, pode estimular os sentidos e a mente, com resultados em questões sociais, cognitivas, físicas e psicológicas, auxiliando no alívio do estresse e agregando saberes.\n\nAlém de muitos benefícios físicos e mentais, as plantas podem nos ensinar sobre resiliência, cooperação e eficiência. [...]\n\nQUESTÃO 01\nAssinale a alternativa CORRETA, tendo em vista as ideias veiculadas no texto 01.", imagem:null, alternativas:["A) A falta de espaço físico é um dos empecilhos para aqueles que querem cultivar plantas.", "B) A falta de motricidade fina impede os idosos de aproveitarem o cultivo das plantas.", "C) A terapia do cultivo de plantas dispensa a adoção de outros tratamentos médicos.", "D) O cultivo de plantas, além de proporcionar satisfação, traz ensinamentos para a vida.", "E) O cultivo de plantas, embora benéfico, não é muito aconselhável para os idosos."], resposta_correta:3, explicacao:"A alternativa D está correta. O último parágrafo do texto afirma explicitamente que, além dos benefícios, 'as plantas podem nos ensinar sobre resiliência, cooperação e eficiência', validando os ensinamentos para a vida. A alternativa A está incorreta pois o texto diz que se a falta de espaço for o problema, 'você não precisa ter um jardim enorme'. A B está incorreta porque a jardinagem ajuda a desenvolver e dar suporte à motricidade fina, e não o contrário. A C está incorreta porque a hortoterapia atua 'em conjunto com tratamento médico', e não o dispensa. A E está incorreta porque o texto aponta que há efeitos notáveis na saúde dos idosos com essa prática.", status:0, historico:0 },
{id:3296, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Sistemas Lineares", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"Considere o seguinte sistema linear {\n𝑝𝑥 + 3𝑦 = 9\n2𝑥 − 6𝑦 = 2\ne marque a alternativa CORRETA.", imagem:null, alternativas:["A) Se p=2, então o sistema tem infinitas soluções.", "B) Se p=2, então o sistema tem infinitas soluções.", "C) Se p=-1, então o sistema não tem solução.", "D) Se p=-1, então o sistema tem 1 única solução.", "E) Se p=1, então o sistema não tem solução."], resposta_correta:2, explicacao:"A alternativa C está correta. Para que um sistema linear de duas equações não tenha solução (seja impossível), as retas representadas pelas equações devem ser paralelas e distintas. Matematicamente, isso significa que a proporção entre os coeficientes de x e y deve ser igual, mas diferente da proporção dos termos independentes:p/2 = 3/(-6) ≠ 9/2. Resolvendo a primeira parte:p/2 = -1/2, logo p = -1. Verificando a segunda parte:-1/2 ≠ 9/2 (Verdadeiro). Portanto, se p = -1, o sistema não tem solução.", status:0, historico:0 },
{id:3297, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Porcentagem", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"João está negociando um carro ofertado por R$ 151.000,00. Ao final da negociação, o valor para aquisição do carro foi para R$ 143.000,00. Logo, o percentual de desconto foi", imagem:null, alternativas:["A) 5,3%.", "B) 5,9%.", "C) 6,8%.", "D) 8%.", "E) 9%."], resposta_correta:0, explicacao:"A alternativa A está correta. Para encontrar o percentual de desconto, primeiro calculamos o valor absoluto do desconto:R$ 151.000,00 - R$ 143.000,00 = R$ 8.000,00. Em seguida, dividimos o valor do desconto pelo valor original e multiplicamos por 100 para achar a porcentagem:(8.000 / 151.000) * 100 ≈ 0,05298 * 100 ≈ 5,298%. Arredondando para uma casa decimal, obtemos 5,3%.", status:0, historico:0 },
{id:3298, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Funções", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"Uma função polinomial de grau 1 possui raiz em x=5 e toca o eixo y na altura -2. Sendo assim, a lei de formação da função é", imagem:null, alternativas:["A) f(x)=(2/5)x - 2.", "B) f(x)=(2/5)x + 2.", "C) f(x)=-2x + (2/5).", "D) f(x)=2x - (2/5).", "E) f(x)=-2x - (2/5)."], resposta_correta:0, explicacao:"A alternativa A está correta. Uma função polinomial do 1º grau tem a forma f(x) = ax + b. Onde a função toca o eixo y é exatamente o valor do coeficiente linear 'b', logo b = -2 (pois f(0) = -2). A raiz da função é o valor de x quando f(x) = 0. Sabendo que a raiz é x=5, temos:f(5) = a(5) - 2 = 0. Resolvendo:5a = 2, logo a = 2/5. Substituindo os valores encontrados na forma geral, a lei de formação é f(x) = (2/5)x - 2.", status:0, historico:0 },
{id:3299, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Produtos Notáveis e Fatoração", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"Simplificando a expressão (54900² - x²), obtém-se", imagem:"null", alternativas:["A) 54900² -2(54900)x + x².", "B) 54900² +2(54900)x + x².", "C) (54900 - x)(54900 - x).", "D) (54900 + x)(54900 + x).", "E) (54900 + x)(54900 - x)."], resposta_correta:4, explicacao:"A alternativa E está correta. A expressão (54900² - x²) é um caso clássico de produto notável chamado 'Diferença de Dois Quadrados'. A regra matemática estabelece que a² - b² é fatorado como o produto da soma pela diferença de suas bases:(a + b)(a - b). Aplicando a regra à expressão, onde a = 54900 e b = x, obtemos exatamente (54900 + x)(54900 - x).", status:0, historico:0 },
{id:3300, categoria:"Conhecimentos Básicos", materia:"Matemática", assunto:"Produtos Notáveis e Fatoração", cargo:"Vários Cargos - Ensino Médio", ano:"2025", banca:"FADENOR", concurso:"Prefeitura de Morro da Garça", enunciado:"Em geral, para iniciar a resolução da equação biquadrada 𝑥⁴ + 2𝑥² + 5 = 0, faz-se uma mudança de variável e essa mudança leva a uma equação quadrática. Assinale a alternativa que apresenta a equação quadrática CORRETA.", imagem:"null", alternativas:["A) y²+2y+5=0.", "B) 2y²+y-5=0.", "C) 2y²+5y+1=0.", "D) 2y²+2y+5=0.", "E) 5y²+y+1=0."], resposta_correta:0, explicacao:"A alternativa A está correta. Para resolver uma equação biquadrada da forma ax⁴ + bx² + c = 0, o método padrão consiste em fazer uma substituição de variável, definindo x² = y. Consequentemente, x⁴ passa a ser (x²)² = y². Substituindo essas variáveis na equação original x⁴ + 2x² + 5 = 0, obtemos a nova equação quadrática:y² + 2y + 5 = 0.", status:0, historico:0 },

]